GossipText = {
    GossipLookupByNPCID = {
        [68] = {
            ["一個獵人？好的，那麼你會想跟矮人區的索爾芬·石盾談談。  哦，你一定要告訴他如果我再次介入他的寵物生意，他就可以去培訓那些監牢裡的獵人了！"] = "d9d6fc265ce7e558402d3ca53747dac5",
            ["一個裁縫是嗎？哦，如果你在這兒待的時間夠長你最後就會聽到關於喬吉奧·波利羅的談論。他現在已經領導潮流幾個月了。如果你希望跟他學習，你能在法師區的外圈找到他。"] = "9cba4dc5407b5b21f860b325ab149a86",
            ["什麼？我不認為暴風城裡有術士訓練師。  不過……在法師區的那家名叫「已宰的羔羊」的旅店中有一些與惡魔有關的活動，我想你應該去那裡看看。"] = "f6a52f523eecff532c9530eae7d0e89a",
            ["他在法師區，那兒有一間名叫煉金材料店的小商店。你會在前往法師區的沿途看到各種各樣奇怪的商店，但是如果你沿著週邊走的話，你一定會找到它的。"] = "8651024fca6f7bd42a0336d52e7d69fc",
            ["你不喜歡騎獅鷲獸，嗯。你很幸運，我們有一個替代品可以讓你穩穩地立在地上。那就是地精們的公共交通工具，礦道地鐵。那就在矮人區的後面，非常方便。"] = "b8a17986e4d6330f2e74f8f8a53c0d86",
            ["你可以去找吉爾曼·石手談談。我知道他在矮人區有一棟房子，但我不知道確切的地方。如果我是你的話，我就會去那邊看看。"] = "8f8f48c440d58b1a783b868dd9222e74",
            ["你可以在國王的覲見室中找到赫塔希姆。她能幫助你前往阿拉希盆地，阿拉索聯軍需要援助來打敗污染者。"] = "9ff1ef7f7918452a7571c3f770ab4e14",
            ["你可以在法師區的煉金材料店外面找到塔尼莎。"] = "356b1700581f2c27333ab266a26bb077",
            ["你可以在花園區的月井旁邊找到塞瑞德蘭或者瑪爾德利恩。到法師區的北邊，教堂廣場的西邊就可以找到花園區了。"] = "2c1e9110dff51f5d1d491b13523c5989",
            ["你可以在英雄谷東北邊的那個城堡平臺上找到獅鷲獸管理員。"] = "f5c1db946eb2f4fba13e922275d9fb95",
            ["你可以在貿易區的暴風城接待中心裡找到奧德文·拉弗林。"] = "53cfbdba892d116c2e03388c9fd6d5d0",
            ["你在尋找哪種專業的訓練師？"] = "ce83ae92effc9c6509cef60c5f919389",
            ["你對哪個戰場感興趣？"] = "481f209702cc74fc87fe4569d25b276b",
            ["你想要學習製皮？西蒙·坦納爾可以教你。你可以在舊城區的「護體皮甲」店裡找到他。"] = "52ef93000b10574ffb40f6f451597e26",
            ["你想要成立一個公會，對嗎？祝你好運！  和暴風城接待中心的奧德文·拉弗林談談吧。你從英雄谷進入貿易區之後就可以看到暴風城接待中心了。"] = "dbd178f951b41e05c59af921ec3b7725",
            ["你想要穿皮革對嗎？聽起來你該與舊城區的西蒙·坦納爾談談。他在那兒開了一家叫做護體皮甲的商店。"] = "02b8fd48e20c73453938adc9f4995c2c",
            ["你應該去找瑟魯姆·深爐談談，他是我見過的最好的矮人鐵匠。你可以在矮人區的中心地帶找到他。"] = "a4956fb4f50c46eaea4f68dd50ceb194",
            ["你應該和奧斯伯談談。暴風城沒有比他更擅長潛行藝術了，那傢伙就在舊城區裡。"] = "5079ccedcf83df1e6554116dbaa337bd",
            ["你知道，我可以刺穿一個獸人或是把一個食人妖切成碎片？我甚至可以把我名字的大寫字母刻在怪物的側腹上，但我卻不能忍受給動物剝皮。想一下，怎麼樣。  好的，如果你有興趣，那就到老城的護體皮甲找馬瑞斯·格蘭治。"] = "c7ce82c152a63bc669f1d309ce17f9bd",
            ["你聽說地鐵了是嗎？那可真是一樣不錯的交通工具！你會在矮人區的後部找到它。哦，一定記得在地鐵行進時把你的胳膊和腿放到地鐵裡面。"] = "98484e0cd95c72af21e16247f3eead70",
            ["你要尋找哪種職業的訓練師？"] = "7e357056bac5b73342ac2bee0458e300",
            ["你要找的一定就是塞爾曼·岩拳。你可以在暴風要塞的國王旁找到他。"] = "bcfcce27aafd9e54ef3d2fcdb27f4139",
            ["你說你不能在這兒聞到矮人煆爐的煙味？哦，如果你想學習鍛造的話就該找瑟魯姆·深爐。他就在大教堂廣場北邊的矮人區。"] = "a3a18a74f32a8ebab3109103db8d0fd5",
            ["你需要幫助嗎？"] = "2402ec9453525b4ec16e1180457c7cfb",
            ["你需要租用一隻獅鷲獸進行飛行，是嗎？杜加爾就在貿易區的城牆上，他那裡有很多獅鷲獸，記著飛行的時候要抓緊哦！"] = "7df84a254c23565acaa7fc468ead3ab2",
            ["光明大教堂是暴風城所有治療相關技能的訓練中心。你可以找珊娜·弗勒學習急救技能。"] = "fd43bf9ef9a4ea5b42ea21a6017c205b",
            ["勞瑞娜是暴風城的高階牧師，你可以在教堂廣場上的光明大教堂裡找到她。"] = "4a22a1b67aa8fe418d517ebb0e371796",
            ["去兵營或者豬和哨聲旅店逛逛吧。如果你去旅店的話，別忘了嘗嘗那裡的好酒，那些酒絕對能讓矮人的酒相形見拙。"] = "c621f0b9a4a6a6290dd5972a302122fc",
            ["吳平大師幾乎精通人類所知的所有武器用法。他的劍法尤其具有致命的攻擊力。要是你需要訓練的話就去找他吧，他大部分時間都在維勒武器店等待新武器的到來。"] = "ea46258d498568523f3fadf071cc9af0",
            ["吳平的精力真令人驚奇。我看著他連續練習了數小時技巧。他用雙手擊打練習用的假人直到他的拳頭沾滿鮮血。我想不到還有誰比他還適合訓練你的戰鬥技能。"] = "312810e5deb14cd60aa19428f7f51227",
            ["哈，你要找的是暴風城訪客中心。從英雄谷走到貿易區後左手邊的第一座建築就是了。"] = "646cbbc2bf91bdaa020beb25f4e0a678",
            ["哎，盜賊只會影響我們在暴風城的工作。我真希望能把奧斯伯和馬迪亞斯直接送到暴風城監獄去。"] = "6e24adae0babfe7f1e128960d09c55af",
            ["哦，你正在學習魔法？那沒有什麼地方會比法師區的巫師聖殿更好了。"] = "0493aff58b480f500d524b265550d281",
            ["啊，你在找杜加爾·朗德瑞克。他那裡有卡茲莫丹飛得最快的獅鷲獸！你可以在貿易區的外牆上找到他。"] = "a36856bf0646fdd5ce14e1bbdbeab7a2",
            ["啊，你是在找魯坎·考迪爾。他在魔法區外開了一家商店，你前往監獄時會經過那兒的。"] = "e3f9bcedb2188218c92b8b8fb1e8eb6a",
            ["啊，鑲金玫瑰？那柔軟的床鋪和溫水沐浴……想想這一切吧。::打哈欠::如果你要前往那兒的話，你可真幸運。旅館就在貿易區的西邊……柔軟的枕頭、溫暖的毛毯。::打哈欠::"] = "e84a11ab6b3896ecf97c8adfbc08636c",
            ["嗨，提醒我啦，我需要修理一下火箭靴。聰明人一點就通啦，不要把火箭靴和獅鷲獸混淆的。  哦，讓我為你指明方向……穿過矮人區，你就會找到利廉姆·火軸啦。"] = "bb3fee63f3293484e591674a691d3c88",
            ["嗯，嗯，我們都生活在這個世界中，是嗎？在舊城區的東南角落，你可以找到勇士大廳。如果你是官員的話，就可以直接進入大廳。如果不是的話，你也可以跟站在大廳外的埃雷恩談談。祝你好運！"] = "a0e2103ae01da9c6c1707056a504c6ae",
            ["嗯？又來一個商人？拍賣場就在貿易區那兒，離銀行不遠。"] = "3b18fc0710278c6aa12fb30a85999aaf",
            ["在暴風城銀行和貿易區的鑲金玫瑰旅店之間設有郵箱，非常便利。"] = "bb63ff9d75c7726f1d06e21fe2021b8b",
            ["在暴風城，有很多地方可供飲水休息，但是只有一處可以過夜。去貿易區的鑲金玫瑰吧。我聽說客房的費用相當合理，被單也很整潔。"] = "44af32f368e03c09b89fe9f87be3875e",
            ["如果你想要成為一名好廚師，那就去舊城區的豬和哨聲旅店，找斯蒂芬·雷百克談談。那傢伙知道怎羊才能做出與眾不同的肋排大餐來。  啊……說到他那著名的肋骨大餐，我都感到有些餓了。你可不要指望他會把那道菜的做法傳授給你！"] = "dbe19e29f297c8e1fb35a95e50f89466",
            ["如果你想變成強大的聖騎士，那麼格雷森·沙東布瑞克公爵是你最好的導師。你可以在教堂廣場上的光明大教堂中找到他。"] = "2d22a7afddcc8d88b9c1353ae28daf09",
            ["如果你要去學剝皮術，可以到舊城區的「護體皮甲」店裡看看。"] = "6f55eb7e6eebe144bc957790dae41464",
            ["如果你要學習煉金術，暴風城只有一個地方值得你去……那就是煉金材料店。你可以沿著法師區的週邊找到這家店鋪。"] = "7034523efe4bfc8203b790a1d127dca2",
            ["如果你要尋找德魯伊訓練師，那就去花園區。塞瑞德蘭或者瑪爾德利恩一般都在那裡的月井旁邊。"] = "6ca4fdf838b083f58d40a21536adeaed",
            ["如果你要找盜賊的話，就應該去舊城區。它坐落在暴風城的東北角。"] = "cd52082b0fdc76c7dded230c974a2ebf",
            ["如果你需要將寵物關在屋內，以便訓練另一隻寵物的話，就去矮人區找耶諾瓦·石盾談談。"] = "b68ea919378ae726f910e862a386d16f",
            ["它就位於貿易區市中心那裡，就在暴風城入口不遠處。"] = "568c01f3e19d99d5f41ea3aac2056ebe",
            ["想要接受訓練？我可以把你訓練成暴風城最好的戰士，但是守衛是不能這麼做的。我想你得去兵營或者豬和哨聲旅店，找些合適的人來對你進行訓練。"] = "cd7fa3fdce25e94d80b36771810f1e93",
            ["我不知道他們是怎麼做到的……這些郵箱一定是傳送門之類的東西。為什麼人們整天都聚集在銀行旁邊的郵箱那兒，從小小的郵箱中不斷地取出劍、盾牌和各種護甲！"] = "b4b551dc6175faa3e32ad05a88b10b09",
            ["我們都是大自然的孩子，所以你到花園區的月井那邊去吧。"] = "a63f0a77a472eab18caf48ea8320d27e",
            ["我建議你去教堂廣場上的光明大教堂裡找一找。"] = "7c15eb60533829779dc9fd0c60d26a6a",
            ["戰士們一般都在豬和哨聲旅店或者在舊城區的兵營裡出沒。但我建議你還是到旅店去找找比較好。"] = "9434f3b21efa2de084243d600d530ff5",
            ["教堂廣場的光明大教堂是暴風城神職人員的住所，你可以在那裡找到高階牧師勞瑞娜。"] = "bb897a746e8a30c2b211e9076b6a286d",
            ["暴風城有一個天才地精名叫利廉姆·火軸，他是這裡最好的工程學訓練師。你可以在矮人區的後面找到他。"] = "05e90b70ee82c6ab15e68fec597454c2",
            ["暴風城的暴風城會計室位於城中貿易區的前門處。當你厭煩細數你的金錢時，一定要在鑲金玫瑰喝一杯。"] = "554b8726d09d342022c5c7eaf5a9818e",
            ["暴風城銀行坐落在貿易區，就在城門的西北面。來，讓我在地圖上指給你看。"] = "8fedf8298f3edb222d5b5f4355c58675",
            ["有一名優秀的廚師在舊城區的豬與哨聲旅店工作。我曾在他身旁看他在烹飪時使用刀具，但是我可不認為他只是一名廚師。別誤會我的意思……如果你想學廚藝的話，他會是你最好的老師。"] = "af66b0b5d2d42f34571240ac0c887807",
            ["沒有什麼能比在水晶湖釣一天的魚更愜意的事情了。阿諾德·利蘭教我學會了釣魚。你可以在運河區的碼頭找到他。  哦，不要相信他告訴你的任何關於運河裡有怪物之類的故事。"] = "852f678dbc06d3601bdf168e7032735a",
            ["法師們都聚集在法師區的巫師聖殿裡，那裡有一座高塔。和它相比，我們的兵營就好像是一座農舍。"] = "338c8fab07f57033e48217d5973c15df",
            ["獅鷲獸？你是要使用空中旅行服務吧，到貿易區的城牆上去找到杜加爾·朗德瑞克就可以了。"] = "258744fe85450f544093d5fd17856341",
            ["真希望與你同行，$n。去暴風要塞吧，跟國王覲見室的塞爾曼·岩拳談一談，他會幫助你前往奧特蘭克山谷的。"] = "5da822272073a4d726872184c3421ca6",
            ["矮人區的耶諾瓦·石盾是你要找的人。在獵人接受她父親的訓練時，她幫著照看獵人的寵物。"] = "9654c77653b91d446f531295982fbec7",
            ["突然之間，你成為了「聯盟的保衛者」，是嗎？！嗯，我猜你一定是想去勇士大廳。大廳就在舊城區，但是你不是官員，守衛是不會讓你進去的，你只能跟埃雷恩談談。去吧。"] = "33278f8101e800c93fc3d2385cfed699",
            ["索爾芬·石盾從鐵爐堡而來，讓我們見識到了什麼叫真正的狩獵藝術。如果你不介意被煙燻得淚流滿面，就到矮人區去找他吧。他的屋子就在那個區域的東北部。"] = "8c8ac67be8a32d83d11e1119cbe8b9f8",
            ["聽起來你得去跟瑪姬諾·仲馬談談！你可以在法師區的巫師聖殿找到他。當然，那些法師總是來去無蹤……"] = "fa0d9c855011039c74c70b23db0b82ea",
            ["與自然的交流溝通是其他任何事情都無可比擬的……至少夜精靈是這麼告訴我的。我並不擅長跟花草樹木交談，但是我想塔尼莎能幫助你。她居住在法師區外側的煉金材料店。"] = "42747362bb8e6d2164d7e79747248058",
            ["術士，嗯。我先前並未對你提及，但是我聽說他們聚集在法師區中一間名為已宰的羔羊的酒吧中。"] = "f05de425d7bd02752037b8477cf01b53",
            ["要學急救的話，沒有比光明大教堂的珊娜·弗勒更好的老師了。  去找她吧，去有黃色屋頂的房子就是教堂樣式的房子，在那兒頂上你能俯瞰整個城市。"] = "b1be3018807cc2da500145c8c2b10794",
            ["讓矮人從鐵爐堡指派一名採礦專家來教教我們吧。使用鋤頭打碎岩石有多困難？嗯，只要他在這兒，你就只管問他好了。他名叫吉爾曼，居住在矮人區。"] = "64070f95813e914bdca6f15e390c919e",
            ["那個討厭的利蘭？他整天就在貿易區外的碼頭邊釣魚。他在釣魚上花費這許多時間，我想他的釣魚技術一定很高。如果你想學的話，為什麼不去跟他談談呢？"] = "2472ef40c4054390e47d26a2790dcef8",
            ["鄧肯雇傭了暴風城最好的裁縫，喬吉奧·波利羅。他的店就坐落在法師區裡。"] = "8706ad14fe81bd7bfe9d6986ff68ed63",
            ["銀翼哨兵部隊運用一切援助對抗戰歌偵察騎兵。$N，如果你想要幫助他們的話，就去暴風要塞找艾弗拉蘭談談。"] = "a28ad28e180fb23f6b2f30a8926dd8d3",
            ["銀翼要塞需要你的援助。跟暴風要塞覲見室的艾弗拉蘭談談。"] = "ab67b49961ce98725cccb8a6b0e8e7ef",
            ["阿拉索聯軍在阿拉希盆地所做的一切令人敬佩。可惜那些不死族的討厭鬼和他們的部落盟友擋住了去路。去暴風要塞國王的覲見室找赫塔希姆吧，她會幫助你前往阿拉希盆地。"] = "adb9b1e902dc3d39490b7c0e4c0e67cd",
            ["魯坎·考迪爾在監獄附近的運河邊上有一家小店。我相信他可以教你附魔的技巧。"] = "91e3f367dbb0e83b362a5880d1271dc4",
        },
        [197] = {
            ["你好！你看起來挺強壯的。我們這裡的衛兵數量不太夠，你願意幫忙嗎……"] = "2343fa9b01b2ca00b5bc7a390ac07935",
        },
        [198] = {
            ["你好。我是一個法師訓練師。而你不是法師！"] = "54074b0b08d3a499512ae6fba95f3115",
            ["你好啊，法師。我能在魔法知識的學習上為你提供什麼幫助嗎？"] = "3ddc082eac22c52bb34743331a694904",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [223] = {
            ["當我從墓穴中爬出來後，我本以為我的家人會熱烈地歡迎我。相反，他們把我從村裡趕了出去，用一種我聽不懂的語言高聲尖叫著。"] = "94095eb43627763b471b3b24bdf02a82",
        },
        [233] = {
            ["艱難時期，嗯，$N？誰都需要幫助，我和我妻子也不例外。"] = "9331c7d44a0e3e3352a08f93cde78162",
        },
        [277] = {
            ["暴風城最好的貨物啊，朋友，你絕對不應該錯過。看看有什麼你需要的東西嗎？"] = "0a50227fd4a79a221c5e74147031f06e",
            ["看看我賣的東西吧，有什麼你想要的嗎？"] = "a86de99ac7614f683ab7eab24b0a0b93",
        },
        [295] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "137f53b5268a04b1b5bdb21820557b14",
            ["你能在旅店裡幹什麼？$B$B當你待在旅店裡的時候，你就可以好好地休息。因此,你可以比留在野外更快地恢復到充分休息的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以通過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你綁定的旅店裡了。"] = "8fc274a3d994a2459bdce3fd3dc98705",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "206f059d0c629c5d37a5efc62769a4a3",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "d268a407b36e89a7c70ab981fb46abd7",
            ["歡迎來到我的旅店，疲憊的旅行者。我能為您做點什麼嗎？"] = "e3e01e02de026cbe5e2560a468bbdebb",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "fa856e726cbf60331453148913410f70",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "616aaf989a9683312fafbb75a48fe26b",
        },
        [328] = {
