        },
        [332] = {
            ["歡迎來到軍情七處總部，$n。"] = "f02518f56be86de855c4a5c585841f34",
        },
        [347] = {
            ["很抱歉，$c，但是在你變得更有經驗之前，我不能讓你去奧特蘭克山谷送死。"] = "b83ab9c1a9dd85b93121a8a221e21094",
            ["必須殺死雷矛衛兵！準備好要到奧特蘭克山谷了嗎，$c?"] = "81ed3ff7e3aa4663fea43677ac077dd8",
        },
        [352] = {
            ["$g先生:女士;，你想去哪裡？只需要花幾個小錢，你就可以搭乘獅鷲獸快速到達目的地。"] = "6b05ee484d45803ee175e05a07d644f4",
            ["這些巨獸比你更會尋找道路，它們能讓你更快地到達目的地，而且還可輕鬆欣賞沿途的美景。"] = "483ae8ef81d9a1fa5470403f505b2d87",
        },
        [375] = {
            ["別與聖光作對，$c，或許有一天它能拯救你。"] = "120875f188ac12780f811009b51a783b",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "768f0928588ebe52253715a9f6b21ad7",
            ["我相信聖光會與你同在，$N。我能幫忙嗎？"] = "aebf3948f2b6eeebadd9d114b8e08bba",
        },
