        },
        [384] = {
            ["多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了——今天就在這裡找到你想要的馬！"] = "0016d0ff7c43ada7e4f367d5b24e9b81",
            ["很抱歉，如果你不是暴風城中的貴族，我是不會將馬匹賣給你的。這些戰馬是最好的，我們當然不會當它們落入敵人之手。$B$B想要證明自己不是敵人，當然……你只需贏得暴風城的信任，我就可以跟你做買賣了。"] = "33c0e9087e12555f8dc52cc2a68cccb1",
        },
        [459] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "768f0928588ebe52253715a9f6b21ad7",
            ["魔法只會腐蝕那些意志薄弱的人。即便你不是術士，最好也牢記這一點。"] = "bf6b174b1213cc9fc8478d3b5f2b4971",
            ["黑暗並沒有包圍你，$c。別說廢話，從我視線中消失吧！滾！"] = "2aabd37566ced1f9550e86910bb3baf8",
        },
        [460] = {
            ["你的黑暗指數真的是低到會讓我不屑繼續與你對話。請走吧。"] = "8045db4a1a25656b86eb87b955fbe642",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "a9083a5c3e3237e00bd856dcc0fd400d",
            ["魔法只會使弱者墮落。繼續你的訓練吧，不然你的命運就跟那些傢伙相差無幾了。"] = "073492d1b775dad17b73e4495accc8b7",
        },
        [461] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "768f0928588ebe52253715a9f6b21ad7",
            ["魔法只會使那些軟弱的人墮落。繼續你的訓練吧，不然你的命運就跟那些人相差無幾了。"] = "c381816693d5bcf8cf6644c3ad7a0dea",
            ["黑暗並沒有包圍你，$c。別說廢話，從我視線中消失吧！滾！"] = "2aabd37566ced1f9550e86910bb3baf8",
        },
        [483] = {
            ["暴風城最好的貨物啊，朋友，你絕對不應該錯過。看看有什麼你需要的東西嗎？"] = "930e45368ed7dcac8e799df8fa5bc730",
            ["看看我賣的東西吧，有什麼你想要的嗎？"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
        },
        [491] = {
            ["我會儘量保證哨兵嶺物資供給的，要維持這項行動可不容易。"] = "f25d9eb86b1a32dfb1649beab901ef4c",
        },
        [514] = {
            ["很抱歉，我現在有些忙，我要為湖畔鎮的弗納·奧斯古打造馬蹄。"] = "80c8a703f2783e988393cdc3f26954dd",
        },
        [523] = {
            ["你去哪兒？如果你想快些到那裡，那就別猶豫了！"] = "a8c3fee28c1869e9b77707e11b8cd0a2",
        },
        [543] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "89218c24a0eff1fa5c10022467769ef7",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "4c9a93178a8bd81be46f856336284914",
        },
        [658] = {
            ["啊，你是個結實的傢伙。也許你能給我一些幫助。這附近除了新學徒之外沒多少人能幫忙，而且他們也有別的事情要傷腦筋。"] = "5fc097432cec6da6622815d859a41a7a",
        },
        [716] = {
            ["奈辛瓦里要出去狩獵。我發現幫助他做叢林狩獵的準備工作比做戰爭準備的工作輕鬆多了。儘管我錯過了戰場上的光輝歲月。"] = "e3a348a35882a9d1e3d9c86ff56b6bbe",
        },
        [727] = {
            ["$g小夥子:姑娘;，你可以去卡拉諾斯雷酒釀製廠外找謝爾比·石火。她會好好照顧你的寵物的。"] = "bee5611eb524aaf54dfb7c803d87d4c9",
            ["一瓶雷霆啤酒外加格雷姆羅克做的菜就足以讓你飽餐一頓。如果你想成為一名廚師的話，就該去參加他的培訓。"] = "d280277830161709ce905baf4cb22615",
            ["不，在丹莫洛是沒有煉金師的。你最好去鐵爐堡……去工匠區找地精。"] = "f7cf19aeccddff42a9a0b22c505718cc",
            ["不，這兒沒人能教你草藥學。你最好去鐵爐堡碰碰運氣。"] = "5aaf2f083eef745315ab1a2dc692fcb0",
            ["丹莫洛一帶是沒有獅鷲獸管理員的，$g小夥子:姑娘;。如果你想騎獅鷲獸去什麼地方的話，就必須去鐵爐堡。"] = "f3c8a5a8b088f61349bd467d2e1e02b1",
            ["丹莫洛這裡可沒有剝皮匠，$g小夥子:姑娘;，如果你想要學習剝皮的話，就到鐵爐堡去找找吧。"] = "6a6954aa23ff423b51b954fe09b144a8",
            ["住在雷酒釀製廠的一名法師或許能教你一些新的魔法。我想他名叫瑪濟斯·石衣。"] = "cfa572bac748ea1fa7e7c25dc2a4ae04",
            ["你在尋找霍格拉爾？那你找過旅店嗎？啊！如果你在找一個盜賊，而他同時還是一個矮人，你應該從旅店開始！先去看一下。"] = "d218e9d1194ff62a08601af71245f9b8",
            ["你在找哪個專業的訓練師？"] = "cf38911600ac02c04cb72aafa6596e66",
            ["你在找哪個職業訓練師？"] = "cf38911600ac02c04cb72aafa6596e66",
            ["你想去哪裡？"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["你想找哪類職業訓練師？"] = "dcadd0f33e63218ef70a191c145117f6",
            ["你應該去鋼架補給站找布隆克。當他不忙著修補一些奇怪裝置的時候，他通常就在跟飛行員們聊些關於他們的蒸汽坦克的事。"] = "f4fbd7429c935511c5657b11b95d1303",
            ["你肯定你不想當一名戰士？那好吧，如果你真想學習動動手指的把戲，你最好去找雷酒釀製廠的瑪濟斯·石衣談談。"] = "3361a9560236765dd4f9f954267bed44",
            ["你肯定可以在雷酒釀製廠看到馬克薩恩·安沃爾大口喝酒。為什麼你不去喝一點，順便看看他能教你點什麼新鮮東西呢？"] = "f9ef4e04eea4de713fc61313fd8a4c8e",
            ["你需要什麼方面的指引？"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["你需要找哪個職業的訓練師？"] = "dcadd0f33e63218ef70a191c145117f6",
            ["你需要接受些訓練？好吧，阿札爾·戰錘總是願意教給年輕的聖騎士一點東西。你為什麼不去雷酒釀製廠找他呢？"] = "63af3d038f4096f6bba167a9b297ef08",
            ["假如你問我的話，我想格瑞夫在動物身上花費的時間過多了。到目前為止，沒人比他更精通於獵人之道。去卡拉諾斯的鐵匠鋪外面找他吧。"] = "5d54f11c82628de5397e4af70d935d39",
            ["剝皮匠通常會把所有的獸皮豆帶到鐵爐堡去風乾。你為什麼不去那兒看看是否能找人訓練你呢？"] = "12bf423a5f31db52e9d292ceb06ece6b",
            ["哦……一個聖騎士？嗯，$g小夥子:姑娘;，你真走運！阿札爾·戰錘剛結束訓練，他現在在卡拉諾斯的雷酒釀製廠。"] = "9d8f2dd4c4db277f02b3c5d5f15c9354",
            ["哦！這可是你說的！我敢打賭格蘭尼斯·快斧會向你展示如何揮動武器的。他現在在卡拉諾斯的雷酒釀製廠。"] = "0fd2049ea24b3dbd43761a96e891bd61",
            ["哦！這是一項極有價值的技能。托格努斯以你從未見過的方式敲擊鐵砧。為什麼你不去跟他談談，看看他能教你什麼？"] = "5240f70aad5a8e58147ce8fae9c1ec57",
            ["哦，旅店是嗎？嗯，雷酒釀製廠是最棒的。你可以在那裡稍事休息，但是你一定得嘗嘗那兒的啤酒。"] = "e66a69d239e7c3f1206d7f638c44bec1",
            ["哦，是牧師嗎？要是你想接受訓練的話，就去雷酒釀製廠找馬克薩恩吧，他一定在那兒喝酒呢。"] = "9a7b6a50e57d38d1acb4f3bff531e0f2",
            ["啊，石眉這些日子不怎麼離開鐵爐堡的，如果你想要學做一名裁縫的話，就去鐵爐堡找他吧。"] = "63ec46e6d95ea9bc754d4ccb65dd8202",
            ["嗯，似乎你在尋找裁縫時並不順利。但是，有很多高明的裁縫都居住在鐵爐堡。你為什麼不去問問那裡的守衛呢？"] = "720fafcfb6472426d4149a74769fda89",
            ["好心的薩姆諾前些天在我與一個骯髒的穴居人戰鬥後替我包紮了傷口。我現在已經完全痊癒了！我敢肯定薩姆諾會很高興教你製作繃帶的。"] = "93839b8ccc68c7af9e06e65b17c1fd90",
            ["如果你一心想學附魔的話，你該到鐵爐堡看看。我記得上次我到那裡的時候曾看到獅鷲獸旁邊有一家商店。"] = "e56f9fe4500923af12e19f791a883d14",
            ["布隆克總是在敲敲打打，他擅長修理最為精密的機械。你應該到鋼架補給站拜訪他一趟。"] = "d505dd7c90c149052d96dc5021198f21",
            ["急救雖然不能代替牧師的治療，但是它在緊要關頭卻很方便。我建議你去跟雷酒釀製廠的薩姆諾談談，並力所能及地學習一些東西。"] = "a88b941bc8e164b364a0b5d642a579b5",
            ["我告訴你，掌握那種魔法可不是什麼好事。我不知道為什麼他們會允許吉姆瑞茲在雷酒釀製廠外面安營紮寨！離他遠點！"] = "f1180972db6665288081c1cfc7b5f408",
            ["我聽說鐵爐堡中有家由精通煉金術的地精所經營的商店。你該去看看。"] = "e59e7a5d5007c14bc99785f8ce315a5c",
            ["所有的官員都居住在鐵爐堡。你得去鐵爐堡訪客中心領取公會登記表。"] = "f9fd222716447c9fab43d7fdd2bdcab4",
            ["據我所知，丹莫洛是沒有附魔師的。如果你想成為一名附魔師的話，就去鐵爐堡吧。"] = "ccffed48b48def2c22f1c44f31434020",
            ["最近的獅鷲獸管理員居住在鐵爐堡的大鍛爐附近。如果你想乘坐獅鷲獸的話，就前往鐵爐堡吧。"] = "c32efb4b50768d9afd75e50dc0393a88",
            ["最近的銀行就是鐵爐堡銀行，$g小夥子:姑娘;。"] = "501c83ee292da27782fae1e60bf7c3f3",
            ["有些弱小的植物竟然能在丹莫洛的寒風中開花，這真令人驚奇……但是這兒沒有草藥師。你得去鐵爐堡接受草藥師的訓練。"] = "3fd9a5ca3019eefa0d287e45aeacd7da",
            ["格蘭尼斯·快斧能在桌下大喝也能虎虎生風的揮舞著斧頭。如果你想接受訓練的話，就去找他吧。"] = "ee5ecc14e2bf49a6990e74cae4288e7b",
            ["格雷姆羅克烹飪的手藝不一定是最好的，但他確實有些美味的食譜值得學習。到雷酒釀製廠找他聊聊，看看他能教給你什麼。"] = "812ca9ddb549b5088d51719a6d51434b",
            ["當你在卡拉諾斯的時候，你可能會聽到托格努斯在鐵砧上敲打。然而，如果你還沒有把耳朵裡的蠟清理掉，那你為什麼不到鐵匠鋪去看看呢？"] = "9f64ea1b3225a2261a71922332f8c889",
            ["礦工？你不需要問有沒有，$g小夥子:姑娘;，只需問在哪裡！亞爾就是你要找的傢伙，我想他應該在鋼架補給站那裡。"] = "4ef02a6cde5565b37e151274512c0641",
            ["術士……我可不在乎他們。就像那個在雷酒釀製廠外開設商店的吉姆瑞茲。都是他，那兒的啤酒可能都跑了氣！術士……呸！"] = "60bf6744b34a4b35ea7e3f938b4de2fd",
            ["要是你想學習製皮的話，就去鐵爐堡吧。我聽說大鍛爐附近有間商店，你可以那兒學到製皮的知識。"] = "5ca39ccf61fd158a1d527dc435d98222",
            ["要是你需要一些公會登記表的話，就前往鐵爐堡，去拜訪鐵爐堡訪客中心吧。"] = "395a422b3eb1d579d18416f0b5ef4bff",
            ["謝爾比·石火幫當地獵人看管寵物。如果你想讓她幫你照看寵物的話，就去雷酒釀製廠找她吧。"] = "5011b7376cf9fbdf9a91842132fba2e6",
            ["這周圍可不是釣魚的好地方，但是你應該去找帕克斯頓問問看。他在湧冰湖釣魚。"] = "467b47eb9a3d4006f250fad9ecb18eb0",
            ["這附近只有一名獵人，那就是格瑞夫。他就站在卡拉諾斯的鐵匠鋪外。"] = "3043df25383951a157419bf109bd7229",
            ["這附近只有幾處地方可以釣魚。帕克斯頓對此瞭若指掌，但是他不一定都會告訴你。為什麼不去湧冰湖找他談談呢？"] = "8bbfc8f6de8eca0089d8559839569436",
            ["這麼說，你以為在這個城鎮裡沒有常駐礦工，是嗎？錯！在卡拉諾斯外的鋼架補給站附近去找亞爾吧。"] = "1c9825e778eedca69936cc9dcbf549ef",
            ["那麼，似乎我們都是來找霍格拉爾·巴坎的。他是個矮人，他遲早會去 雷酒釀製廠喝酒的，沒准他現在已經在那兒了。"] = "1f4384179f7f2eff7cf1e505f549b91e",
            ["鐵爐堡是學習製皮的最佳場所。要是我沒記錯的話，你可以去大鍛爐旁的商店。"] = "712130efaf95afb9ccb5f2a5c069c0fc",
            ["鐵爐堡銀行是這一帶最近的銀行。"] = "83965dbeffe98cceda0d3e3dbf0734c2",
            ["雷酒家族在卡拉諾斯開了一家旅店，久負盛名。在那裡喝杯酒休息一下吧。"] = "0ee12bb81d2947b566609b7ba822b401",
        },
