            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [988] = {
            ["你的意志不足以操縱我們控制的軍隊$c。"] = "5a92f47cf481eb3def2615b8693c94fc",
            ["你知道的已經夠危險了，但是對我來說你看起來還需要訓練$n。"] = "f097ab331f582c2d79e805e164a7c169",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [1103] = {
            ["你想學點東西嗎？我會很樂意教你的！"] = "c9603b8eec1e5738749f40b5e7e89a19",
            ["我對裁縫業知之甚少，但你需要更多的幫助。我聽說有個夜精靈精通裁縫技術。他居住在暴風城的魔法區。"] = "c20cda58878fc7ac4e481f3bc65a3f73",
            ["我覺得你的服飾急需維修。"] = "b34aad75e8e14753d5e47ece1a2eba61",
        },
        [1154] = {
            ["你已經成為一個出色的獵手了，$N！你不但證明了你的技能，你還勝過了達瑞爾，這是你在我的名冊中得到了額外的分數！$B$B歡迎你隨時來到這裡。"] = "f5c3b81ff7aa2cea4c40a37dadb0f053",
            ["在旅行者營地，我們最推崇狩獵技能。想獲得我的賞識嗎？你得靠行動來證明。$B$B面對挑戰吧，$G小夥子:姑娘;！"] = "b9a009c23ae18be4d2beb4d5b487dd08",
        },
        [1156] = {
            ["拿到那顆頭顱肯定會讓達瑞爾大吃一驚。是他活該，這個傲慢又該死的混蛋。但是哈！我等不及想看到你把這個拿給他看時他臉上的表情。"] = "675474e0619645670f8ac5fe9a9fadbf",
            ["歡迎來到旅行者營地，$N！"] = "acbe16ea3d149deb13ccd9048db985c9",
        },
        [1215] = {
            ["你好，$g先生：女士；。我想握你的手，但是如你所見，我正忙著做事。我可以幫忙嗎？"] = "fc05789524675185326e36bb917847b7",
            ["你已經學會了我能教給你的所有東西，$n。如果你還想繼續學習的話，去找暴風城法師區的夜精靈莉琳希亞·夜風談話。我聽說她是個好老師。"] = "00ac4b235ec0f2725dd99c50a0ed9648",
            ["你有了一個好的開始，但是你要學的還有很多，$n。"] = "8d1a9653ec0ac81cbb827f31a1138bda",
        },
        [1226] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "31ab172e1a375db1c9157d594eb608d9",
            ["願聖光保佑你，$c。"] = "852369f0d2fbc11e555e75fe5a433853",
            ["願聖光與你同在，$N。我能為你做什麼嗎？"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
        },
        [1228] = {
            ["你好。我是法師訓練師，而你不是一個法師。"] = "8fd77c576e61a6ac69420c6902a2153b",
            ["你好。我是法師訓練師，而你是一個法師。"] = "ba87bd521b00c273a44207b174b44c7a",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "a9083a5c3e3237e00bd856dcc0fd400d",
        },
        [1229] = {
            ["你不是戰士……你在我的訓練課程中會連一天都堅持不下去的！$B$B認為$g他是:她是;一個戰士的$c。哈！"] = "64a04066374cb355ff1adeae11f4ae82",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "31ab172e1a375db1c9157d594eb608d9",
            ["雖然現在是和平時期，但是我們可不能荒廢了我們的戰鬥技能！"] = "ce85977b0f1b155023ca49641a927acd",
        },
        [1231] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "31ab172e1a375db1c9157d594eb608d9",
            ["我可以為你做什麼?"] = "ff4c1db50d39977890db3fe889ea21ae",
            ["我無法訓練你。你該去找$c訓練者。"] = "65ffa984c80ec793cab656acd848ac8c",
        },
        [1232] = {
            ["你可能不會像一個銀手騎士那樣追尋光之蹤跡，但是你總可以向我們尋求幫助。"] = "6d05441079c12f5737a4ae0732070946",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "31ab172e1a375db1c9157d594eb608d9",
            ["願聖光與你同在，$c。我能幫上忙嗎？"] = "0c2e5af8c299738c3e541d7e001d442e",
        },
        [1234] = {
            ["是什麼把你帶到這個地方的，$c？"] = "cdcf0443cbf0e6c89324a0d43261fbd6",
            ["沒法幫你，$n。我只訓練盜賊。"] = "fa078d44ecb0731e4c2a45f949ae67b1",
        },
        [1241] = {
            ["你好，$g小夥子:姑娘;。我可以幫你什麼忙嗎？"] = "9e8b94c1be7b802ff587b91f7fd1bd92",
            ["你學得很快，$g小夥子:姑娘;，快得我已經遠遠跟不上你了。如果你想繼續學習的話，我建議你去見見我的導師。他的名字叫洛特加斯，嗯，洛特加斯·石鬚。你可以在鐵爐堡的大鍛爐那裡找到他。"] = "b87832ee885e2c2b541409175c3036f5",
            ["你是來接受訓練的嗎？我也是剛剛開始學習這方面的知識，但是我很樂意把我所知道的教給你。"] = "5fcded33d34a5f55fd70058a5461f5ed",
        },
        [1243] = {
            ["海格納·重槍，願為你效勞！"] = "021dde6de017478913faed817d53af98",
        },
        [1246] = {
            ["$g小夥子:姑娘;，努力吧。苦幹和決心——那就是成功之道！書本知識是遠遠不夠的。"] = "94877755c9cc3beb33d35c6e3279a7f0",
            ["別被那些天真的大眼睛欺騙了。塔雷是個專家，我每天都在學習新知識。你認為我為什麼會在地精區？你看我像個工程師嗎？啊，我可不這麼想。"] = "32a5626d8140ad954652c141442fc86c",
            ["哦，我不能教給你什麼，$N。跟塔雷·漿泡談談。她幾乎夠不著桌子，但是當她在配製藥水時，你得看仔細了！"] = "39ebd1b988bad54e8ab04456d49fb6c9",
        },
        [1247] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "e76319f8e0a3393f78b709a653ebd046",
            ["你能在旅店裡幹什麼？$B$B當你待在旅店裡的時候，你就可以好好地休息。因此,你可以比留在野外更快地恢復到充分休息的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以通過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你綁定的旅店裡了。"] = "7559d6906f8128171c86805ac0f7eaac",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "e74b227d686c3a09c784a937420b00fc",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "64973aa51308c04b55be79da97ac51f1",
            ["滿上一杯啤酒，拉一張凳子過來坐坐。我們要暢飲一番，同時還要分享我們的故事。"] = "c3684d8296958c5935a2740fa7611b74",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "490f61093d0ec9e8887f5611d0dde3c6",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "a6db9e7560aabbf0956453b311a6e920",
        },
