        [1346] = {
            ["太好了！我能斷定我的努力不會白費！"] = "ddcbbdc4dca9d1bfc3f2a254cfd1dc1a",
            ["我只知道有一個人能在裁縫技能上勝過我。我最後一次聽說他在塞拉摩島。你該去找他。"] = "9485e8cef81326a7a0116e50049a19ba",
            ["我恐怕在我可以教授你知識之前你要需要更多的訓練。"] = "b35756d26207fcb3c0a6292cafad396c",
            ["是的，我現在已經經營這家店一段時間了。最近生意非常好。許多新的探險者來了……"] = "191c0730f0b850af3afce8e3beb43593",
        },
        [1347] = {
