        [1351] = {
            ["讓聖光保佑你一路平安。如果你需要需要任何幫助，就來找我吧。"] = "ce3a30336400d5979cf1804ab2617300",
        },
        [1355] = {
            ["加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。"] = "de96efe8437890d30d0aff9e01f5f7cb",
            ["去銀風避難所找珊蒂瑞亞吧。她可以賣給你「高級烹飪教材」。"] = "fe8baba790f8edd0a4e3d2f680dfe89a",
            ["我可以教你如何烹飪！"] = "8aeb96ef5db5b2d70e98dbbaca63f721",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "c4162cb7f63061b6eae39dc6b6b814dd",
        },
        [1382] = {
            ["加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。"] = "fa94f3b2a7756a7206f2d739132e099b",
            ["我可以教你如何烹飪！"] = "3c5599de03c8689a7c59e4a9c7e86daa",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "6b8ea29137624c8512925cd734b18e4f",
            ["葬影村的烏蘭可以賣給你「高級烹飪教材」。如果你想要提高烹飪技能的話，就需要這本書。"] = "178749ad5f34e7d82d4f95b09e30304c",
        },
        [1383] = {
            ["你認為自己夠資格向我學習嗎？你不過是我腳下的一名卑微的小人物罷了。但是，收納一名下屬或許能增加我對蘇米和圖米的吸引力。讓我看看你擁有什麼技能。"] = "ff39ca29b26a2bf82446bf23f9f6bdd7",
            ["再次給我帶來這種劣質貨我就把你裝在用山羊尿回過火的小鐵盒裡送回家。現在去見見那個傻瓜烏格索克，他更加適合你的需要。"] = "a5954f50750c048ad3968621a36bb8a8",
            ["我沒有什麼東西可以教你了 - 快滾！不要想接近薩魯，因為像你一樣卑微的人他只會用你們的血來煉鋼的。"] = "9a53f418dd0796c16815bebd0a53e258",
            ["要是我向薩魯證明了自己的實力，他將別無選擇，只能讓我為他的一個女兒而戰。讓我們看看誰是失敗的那個吧。"] = "892843767faa267d3c9dffac4a715fb9",
            ["離蘇米和圖米遠點。他們會……極力推銷他們的東西的。"] = "3460cf49688cf1e61bb4c182e4fe1f25",
        },
        [1385] = {
            ["你沒經過適當的訓練就來找我，說明你勇氣有餘而智慧不足。去找個接近你的技術水準的人談話，像獸人卡瑪瑞，他住在奧格瑪的暗巷區。"] = "333ced88b7c1e9498193f4e7df73a47d",
            ["現在，我們在這片大陸上只有一處立足之地，但是人類是永遠不可能打敗我們的。他們很快就會受到報復。我們會割下他們說謊的舌頭，懲戒他們的背叛行為。"] = "14c20e89440319b1fc7df3e53552a16d",
            ["要是我能的話，我會教你的，但我力所不及。去跟雷霆崖中央高地西北部的商店找牛頭人猶納談談。她擁有真正的才能。"] = "f58bf6b4db68eb60245db834b0c12194",
        },
        [1386] = {
            ["你膽敢讓我培訓你，你這可憐蟲？你期望什麼，你這個呆頭呆腦的鄉巴佬，一場關於如何正確使用銀葉的講演？滾出去！你浪費我的時間沒把你打個半死算你走運。"] = "ef707d4afe6c519b2111f0699c611d06",
            ["嗯，好吧，我看到你還懂一點做藥劑的方法。然而，你是否配做我的學生仍有待察看。我有一項任務交給你。爭取給我一個好印象。"] = "82de1081947db7e5efe700935903c696",
            ["戰爭之王索爾親自邀請我到這兒來。我感到非常榮幸，這並不困難。我不要求自己的職務高於斯通納德。我只想找些生長在這兒的草藥。"] = "6ce2c0940d0dd65750b3907022d09eee",
        },
        [1387] = {
            ["你想要飛往什麼地方？"] = "0edd3c73540d735f036ac6e027466523",
        },
        [1404] = {
            ["不要浪費我的時間。"] = "77d31ff418c404f97bed5fd865e38ebe",
            ["什麼？"] = "473178aa39ca6564bcadca7c21bbfead",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [1411] = {
            ["你看起來像是那種手腳不乾淨的人。有什麼我可以幫忙的嗎？"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["你看起來像是那種手腳不乾淨的傢伙。有什麼我可以幫忙的嗎？"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["我想你不願意向我學習吧。你最好找個$c訓練師幫助你。"] = "0fac9f50e1fb5c48f7301ce81e131b5f",
            ["我跟你沒什麼好說的，你最好找個$c訓練師來幫助你。"] = "0fac9f50e1fb5c48f7301ce81e131b5f",
        },
        [1416] = {
            ["要是你是來找世界上最富經驗的工匠，你就找對地方啦！$B$B格瑞曼德·艾爾默，願為你效勞！"] = "42e10d7c6d1c5dff59458f9ee1073107",
        },
        [1423] = {
            ["一個盜賊？嗯……我曾聽說過那個科瑞恩·塞爾留斯在那些陰暗的地方遊蕩。找她談談，看看你能學到點什麼。"] = "8e11642ef78ecb20aeb15e5bd3d4ac1d",
            ["一個術士？好吧，如果我是一個術士，我可能會待在這附近最黑暗的地方……那就是獅王之傲旅店的地下室。你應該先到那裡去看看。"] = "325caa33bcef35efcdd544756cf14f0f",
            ["不，我不認為在艾爾文森林中有附魔師。但是，在暴風城中有個名叫魯坎的傢伙，他開了一家商店。你可以去找他，看他是否能訓練你。"] = "e821d7ca53f505264e3c4d486d01a7b4",
            ["你一定是在尋找鐵匠阿古斯。如果你需要接受訓練的話，他通常在閃金鎮監督鑄造工作。"] = "43662cd560b3472be8503d8f103e25ee",
            ["你在找什麼？"] = "ed1b18176e479fb1e0c5d47c9f1dd25d",
            ["你想學習成為一個裁縫？嗯……我相信在東谷伐木場有一個裁縫可以教你。"] = "9b934f8faed0473a27a58466b2ffe393",
            ["你為什麼不到獅王之傲看看呢？那裡的廚師可能會教你幾道好菜。"] = "62fe1dee3e085669493ca628f7533517",
            ["你通常可以在鐵匠鋪的後面發現威爾海姆修士和里瑞亞互相講故事。他總是很樂意向聖騎士們傳授新的技藝。"] = "8c17773e87f0ed8951a19ec2b38a564c",
            ["到閃金鎮的獅王之傲旅店去吧。那兒有啤酒和柔軟的床鋪供你盡情享用，沒有比那裡更好的休息場所了。"] = "f25229f44474299d00b3ef221972ff2e",
            ["哦……好吧，瑪克西米利安是這附近唯一一個瞭解黑暗魔法的人。你也許可以在獅王之傲旅店那陰暗的地下室裡找到他。"] = "d4cde9dec6267a8111368f29e62b71aa",
            ["哦，你一定是說暴風城會計室。走進城門之後，它就在貿易區的西南部。"] = "8d0487b1471f828e2ad08533960ce09c",
            ["嗯……這附近唯一有附魔訓練師的地方就是暴風城了。你為什麼不問一下暴風城的守衛呢？"] = "ee80e28a58b1049bafc0e9b980b7a239",
            ["在水晶湖畔居住著一名技藝高超的剝皮師。她可以教你這項專業的入門技能。"] = "7b8dd59196b08d9c2aaf28ce9395a4ab",
            ["在艾爾文森林只有少數職業的訓練師。你在找誰？"] = "a5a7622b8f8ebe5afb104225cc531868",
            ["好心的旅店老闆艾瑪，她現在已經照顧當地的動物好些年了。我敢肯定她會很高興照顧你給的任何動物。你可以在獅王之傲旅店的外面找到她。"] = "02898b1403315800a99b2c54921d2dda",
            ["如果你想乘坐獅鷲獸的話，就去找暴風城的獅鷲獸管理員吧。當你進入英雄谷時，應該就能看見右邊的獅鷲獸降落台。"] = "af3a7d00ee25555e5773f072ba9dd2b6",
            ["如果你想學習挖礦的話，最好前往暴風城的矮人區。那裡的某個矮人肯定會教給你這門技能。"] = "5b3a63364d822c6bd2559d96ec4d9317",
            ["威爾海姆修士經常在閃金鎮的鍛冶場後面培訓里瑞亞·杜拉克。你可能會從他那裡學到一些聖騎士的知識。"] = "31da6527b1db663dc6f3342620895fe3",
            ["居住在北郡和暴風城之間的山上的一位煉金師或許能幫上忙。你為什麼不去找他呢？"] = "e497836bddead8885e3007c40241502e",
            ["德魯伊？我沒看到過任何德魯伊。不過在暴風城中有一塊屬於夜精靈的區域。"] = "fb2147a6362627351b16b4e670503b33",
            ["我對魔法知之甚少，但是在獅王之傲有一個名叫札爾迪瑪的法師，他也許能幫助你。"] = "288705c766a2a8cdf112cab9b1339549",
            ["我打賭科瑞恩·塞爾留斯知道你在尋找的東西。科瑞恩的公司一點也不正直。她通常在獅王之傲旅店裡。"] = "cec94b6df353509053c932b86d356143",
            ["我敢打賭潔塞塔會很樂意教你學習新法術的。她就在獅王之傲旅店的房間內。"] = "0131cac34dfe2c78da45684a609b5c32",
            ["我最近在這裡附近遭遇過一些迪菲亞盜賊，但蜜雪兒·貝利幫我進行了治療。到獅王之傲與她商量一下，看看她能否教你。"] = "96d48bb506899c3338f1cadfcbe2c66a",
            ["我相信奧德文·拉弗林仍是暴風城的常駐公會註冊員。當你進入暴風城的貿易區後，你的左手邊就是他的居所。"] = "c01d6d61aad524ab4f569adfc154bdea",
            ["我知道有些人在這附近練習某些專業。你想要打聽哪項專業技能的訓練師？"] = "20386cfd269226043dcfdd5aa6c1fdc7",
            ["我聽說暴風城中有個矮人因狩獵技巧高超而聞名。或許你可以找他問問看。"] = "0156f92878dd7185920a393b5853d47b",
            ["我認為你在暴風城會交到好運的。去問問那兒的守衛，他們會給你指明方向。"] = "60dc358a6e2438c3c568e59ad0bce002",
            ["我通常將那種事情留給地精去做。要是你想學習這項專業的話，我想你可以在暴風城找到一些地精來訓練你。"] = "f0fa0f3fc757caa137f7f79f9bbf14be",
            ["旅店老闆艾瑪照料著這周圍的所有動物。要是你需要跟她交談的話，就去獅王之傲旅店外面找她。"] = "58e01c3573e8ec29c720f44c53d6fe5f",
            ["暴風城中的某位地精肯定能教你，而且我相信暴風城的守衛能為你指明方向。"] = "67d9b63fc15643383e2f46d266010802",
            ["有一名草藥師跟煉金師一同居住在暴風城東面的山上。完美的搭配，不是嗎？"] = "228c73c43f5dce6e402e233719bc6c1f",
            ["札爾迪瑪可能會教你一些新的法術。他最近喜歡待在獅王之傲旅店，你可以去那裡的房間看看他在不在。"] = "a8a07c07ddedc32bea4ab7fd7bf3f027",
            ["李·布朗在水晶湖中抓到過很多奇怪的東西。他說他數月前釣起過一個神秘的面具。但是照實說，我想他那晚一定在獅王之傲喝多了。"] = "17360956a7039de22d26a002b7bfcd3e",
            ["李·布朗整天都在水晶湖釣魚。或許他能給你講些故事，還能教你一些技巧。"] = "e5a3403d0988099931e0ac6f2f9d1c86",
            ["水晶湖邊居住著一位名叫艾德勒·費歐德的女士。她利用從當地剝皮師海倫尼那兒得來的皮革為當地的守衛製作補丁。如果你想要學習這項專業技能，她也許就是你要找的人。"] = "c42cc1f489ae783fa9e802f59af6a32e",
            ["海倫尼·派特斯金納有著數年的剝皮經驗，他一直為艾德勒·費歐德提供獸皮以製造皮革製品。你可以在水晶湖旁的房間裡找到她。"] = "a0fc4a75717f81994f43c0cc9dcc5a2a",
            ["湯瑪斯也許不是最好的廚師，但是他確實能做一些精美的菜肴。如果你想學習廚藝的話，就去獅王之傲旅店找他吧。"] = "99a5d490289d9bb0176d9a7556472b8e",
            ["潔塞塔經常幫助鎮子裡的守衛，她是聖光賜予我們的禮物。如果你想學習牧師技能的話，可以去獅王之傲旅店找她。"] = "d22f824b0a95fcf0e0fa1f9b6e66ee87",
            ["獅鷲獸管理員監管著飛進飛出暴風城的所有獅鷲獸。如果你想乘坐獅鷲獸的話，就去找他吧。"] = "e7b869503b0c9fc3c78fef1e53facf50",
            ["聽說那個隱士瑪洛瑞有時會為當地居民配製藥劑，他居住在暴風城和北郡之間的小山上。"] = "002edc960865a12462d524da4a9ec5c2",
            ["艾德勒·費歐德的皮革手藝在艾爾文森林已經婦孺皆知了。她的家就在水晶湖旁邊。"] = "055387f3f8f3d85f77a3586504bdb666",
            ["艾爾丁是艾爾文森林中唯一稱得上裁縫的人。要是你對這個專業感興趣，就去東谷伐木場找他吧。"] = "99116cecd296f9c7b453b0cd466c1c0c",
            ["草藥師博米洛伊為居住在北郡和暴風城之間的山上的一名煉金師收集草藥。去他的住所找草藥師博米洛伊，看她是否能對你有所指引。"] = "91eec838271e2defd97f1ef17cd50484",
            ["蜜雪兒·貝利對病患的態度令人欽佩！她也許無法教你如何對待病人，但是她可以教你一些急救技巧。她現在居住在獅王之傲旅店。"] = "e130db25d19c3095f05bb7862422afec",
            ["要是你想接受訓練的話，就去找科瑞恩。她通常在鐵匠鋪外面等著鐵匠打造武器。"] = "82b4071e4aa609b4e65e5f67ec183b71",
            ["這些日子以來，所有的官方事務都是在暴風城處理的。如果你想要組織公會的話，就去暴風城接待中心吧。"] = "74f90133248ed081dd63135606a46784",
            ["這附近很少有人像里瑞亞·杜拉克一樣精通於刀刃的使用技巧。到鐵匠鋪後面找她看一下她有沒有心情教你些新東西。"] = "0331ca902e3146c78118e62c38363c41",
            ["銀行？哦，這附近最近的銀行就是暴風城會計室。沿著暴風城大門不遠的那條路向前走就是。"] = "f92f96da1792dd89dc40428e6b0fa147",
            ["鐵匠阿古斯居住在閃金鎮。我想他能教你如何做一名鐵匠。"] = "da5177b45d44e25aa57706e08476b9f5",
            ["閃金鎮的獅王之傲旅店是這個地區中最好的旅店了。在那兒歇一歇吧，旅店老闆法雷會讓你感受到家的溫暖。"] = "0c144818f02d11af9021a5823b7427f0",
        },
        [1430] = {
            ["加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。"] = "46bd22a73f998050e4834380890f65e5",
            ["去銀風避難所找珊蒂瑞亞吧。她可以賣給你「高級烹飪教材」。"] = "6adb3f498e428354df52f9e4254cab21",
            ["我可以教你如何烹飪！"] = "165cad0ff12e810f8dff25c54b2fd744",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "65b5db40b84f65e9d8f699beb4eaf4f7",
        },
        [1432] = {
            ["嘿，$先生:小姐;。看樣子你們都對品酒有相當的鑑賞力$C。我想請你幫個忙，給你的報酬一定會好的讓你無法抗拒…算了，那真是不錯的酬勞！"] = "2849e3835de3a2c6a8aa1626f6cec474",
        },
        [1460] = {
            ["多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了——今天就在這裡找到你想要的馬！"] = "b2eb329ecae1bc16999a40f0d3b30dc8",
            ["很抱歉，如果你不是暴風城中的貴族，我是不會將馬匹賣給你的。這些戰馬是最好的，我們當然不會當它們落入敵人之手。$B$B想要證明自己不是敵人，當然……你只需贏得暴風城的信任，我就可以跟你做買賣了。"] = "3abbcc0541b691e0b8bbe9d7c11ad032",
        },
        [1464] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "e76319f8e0a3393f78b709a653ebd046",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "a4d0603824a832576cec3e3d0e01eb3a",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "970d265673ae5fad5a5c1dc628457490",
            ["你有興趣探索這些地下城中的一個嗎？"] = "036da6474362e31b5c5b8714997221d3",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "41e7446de8a99d017f4dbbef7255bc13",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "b85a4524b031030828761221440ff4cd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "0696ddb759f36db8a31b0de8dfe773e6",
            ["厄運之槌位於菲拉斯的中部。"] = "8bcc27057464ad8295116b381b58f4c4",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "adddbf128dedf6f6ca7aac8e3be5bf92",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "d0b8820f2e1f29977d61ec36fbba4c37",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "7f5e67249a1d4971841ece6127c8d749",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "387741cc6b9473695e470695f72c685c",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "dfbf5c158793a5d635b039bb99fbcd86",
            ["奧達曼位於荒蕪之地最北端。"] = "e395d0b7e6c95518344f6330e935cace",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "c7a772d767a66660e5da8715a151a796",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "e74b227d686c3a09c784a937420b00fc",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "8fb15b22af529953dc80e7257f2df256",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "252356bb3f6f7907c717b8af0e9450c5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "672d1e8529c61b7cd4745f6b33011c68",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "64973aa51308c04b55be79da97ac51f1",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "334b73436ddc4b1bda745af5eb1e4f32",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "327242bcd711775eb7720e35cac612af",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "ecab747cb61959b39b57ef0de545ae6e",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "e9e63692c2220a4c865d9adef19b35e9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "bddcb2f11ff849b592a1d76b4d46b5d1",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "0de78051c05d635c0f53d505687c9a11",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d590cc10020ce147fee1519be78c0e51",
            ["滿上一杯啤酒，拉一張凳子過來坐坐。我們要暢飲一番，同時還要分享我們的故事。"] = "c3684d8296958c5935a2740fa7611b74",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "722216dcb64e2fd4e0adfbec7f5a169e",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1c36c2f9f75af3f1994be97e3fa76600",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "490f61093d0ec9e8887f5611d0dde3c6",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "a6db9e7560aabbf0956453b311a6e920",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "09a72d48b06490f955cd61ccf3e6a038",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "be509dfb481fe127dfd82ad17e93b19e",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "e303428e45f8504ab95951e7cf3b15a5",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "3ca87dd2a1766fe3430d6ece60a54be7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "b5a78d9a4eb2335b05dc3e74b7bf93d2",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "a8a237543c2ca2b43003dda93eb3bc66",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "637ea23cab1a47898f266b7ddbe033ca",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "b1f375bae193622f365bfe78f36e26a6",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "77aa9a2034ff610f83189bb1b5922172",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "e0678027d988e76f5db5e0b28bd5fded",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "d4c8367f7e096bd61f9f2c15a639c5d5",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "b81280ccbca7aa10e3280895aec17ea5",
        },
        [1466] = {
            ["還沒準備好收拾這張皮。我希望做皮革不要花太多時間。肯定有辦法削減等待的時間。這對我身體不太好，你知道嗎？"] = "d66a2bc101b5a2594db0e958f8da478a",
        },
        [1470] = {
            ["我教不了你，$N。去找塔雷·漿泡；她是一個地精，住在鐵爐堡的地精區。哦，既然你反正要去，請把我的愛帶給卡利。"] = "921a3d184477e407e62200c891fd94f3",
            ["是我親愛的戀人卡利派你來找我的？她可是我的寶貝。"] = "ec7c4633bc5f4374a2102940fcd7c5fe",
            ["沒想到你會來這兒找我的可愛的卡利談話。很好。這是藥水。有沒有人說過你是個頭腦簡單的傢伙？"] = "888d5259091b04afd7e726170db3465b",
        },
        [1496] = {
            ["他名叫魯伯特·鮑什。我聽說他在城鎮東南角的恐懼之末旅店樓上的某間房間裡。"] = "de253e3169d9f7d6717bd3c610685772",
            ["你一定是要找舍倫尼·洛巴爾特。沿著布瑞爾東南方的道路走，然後在十字路口向東走。她就居住在路邊的某個營帳中。"] = "d527ff651e5c8f5b38b73526706b5b23",
            ["你不算太聰明吧？嗯，如果我是獸欄管理員的話，我應該是在馬廄附近吧？去那邊找莫加努斯吧。"] = "e9a287a2eb1861b87d62565cd3f9941c",
            ["你可以在布瑞爾東南邊的恐懼之末旅店的樓上的一間房間找到范斯·安德格魯姆。"] = "93cc04c8b8e24496ad60223e82204b3c",
            ["你可以在恐懼之末旅店樓上的平臺找到法師訓練師凱恩·火歌的，恐懼之末旅店就在布瑞爾的東南端。我猜你現在去的話有點晚了，他不會再登記給你房間了。"] = "fd95ca0767fb6854229c17e46878eea4",
            ["你可以在穿過城鎮的道路東南端的恐懼之末旅店裡面找到旅店老闆瑞尼。"] = "e5750cf72eef1fd9a7b8998872a7898a",
            ["你想成為一個標本剝制師？我不喜歡那些從我身上獲得材料然後運走的人，因為他們認為我死了。難道不討厭嗎？好了！到城鎮東南邊的一個營地找尋蘭德·洛巴爾特。要找到他需要走布瑞爾東南方的路，然後在十字路口左拐。"] = "b2057081f202c32ff47e8c3e643a50bf",
            ["你會在城鎮西北端發現卡羅萊·安尼斯正試圖炸掉她的房屋。為什麼你不去看看你能否幫她？"] = "de06a1722b12d439c9afc5bbb2bda105",
            ["你看我像個會施魔法的人嗎？嗯，我確實聽說 凱恩·火歌居住在城鎮東南部的恐懼之末旅店的樓上。他那樣站在格雷徹的房間之外可真奇怪。"] = "385fddd86e7c422be8f061e089433318",
            ["你要找什麼技能的訓練師？"] = "453b9c8037ce4d9e2cd70e18ad1d9620",
            ["你要找什麼？"] = "2496e7dedec4748fa10b50cbb971b275",
            ["你要找的是魯伯特·鮑什。他和他的隨從居住在布瑞爾東南角恐懼之末旅店的樓上。"] = "4d833ba2be9a9ed29ed79a621d6ebcce",
            ["你說屠夫？哦，急救訓練師！一個樣。當你看到護士妮拉站在城鎮東南面的恐懼之末旅店裡面時你就會明白為什麼。"] = "d52cdea0c5a316cd91c993435b3f0346",
            ["你需要銀行做什麼？好吧，你得穿越布瑞爾南部的羅德隆廢墟，乘坐電梯到達幽暗城。當你到達那兒後，詢問自稱為幽暗城守衛的行動緩慢的憎惡，請求它給予更詳細的指示。"] = "a3e61fd7af1b53b3d710ad8dab75a981",
            ["來福槍、炸藥、炸彈、爆炸綿羊……這些可愛的東西。要學習如何製造這些物品以及其他工具的話，就去布瑞爾以南，羅德隆廢墟下的幽暗城吧。乘坐廢墟後面的電梯，當你到達幽暗城後，向一個幽暗城守衛詢問訓練者的確切位置。"] = "f1ae7876e60c93e2336f0802cc01e837",
            ["克萊德·凱林，當地的釣鱸魚高手，有他自己最喜歡的釣魚地點，就在布瑞爾東部的澈水湖。"] = "c8c457f00ba68e930345dc9a61425874",
            ["去恐懼之末旅店的主餐廳找奧斯蒂爾·德·蒙。酒館就在布瑞爾城的東南角。"] = "026418de080205834ee64ce5d0625a46",
            ["去找法魯薩。我最後一次見到她時，她正站在馬廄和西北方向的房間之間。"] = "703653ea2b256edc8ff3ec853fb0791e",
            ["去鎮子東南角的恐懼之末旅店，你可以在旅店樓上的閱覽室中找到黑暗牧師貝里爾的。"] = "5beef90fab0c2fbc8e782f8a205f7045",
            ["哪一項專業？"] = "68b0bdb01281865de220bb8ce19e964a",
            ["啊，你是在找黑暗牧師貝里爾。他在恐懼之末旅店樓上的閱讀室。他一直在閱讀、禱告，沒人知道他在幹嘛，也誰敢去問他啊？"] = "b0d229770be3e29c722b451fae65aa8a",
            ["在幽暗城中居住著一位蝙蝠管理員。出了布瑞爾城朝南走，然後在丁字路口向西走。羅德隆廢墟就在你的右邊，穿過廢墟，然後進入幽暗城。你可以問問那兒的守衛，請求他們的幫助。"] = "7cde77346a7f6eeabaf54f17380e5d92",
            ["如果我是旅店老闆瑞尼的話，我可能在哪兒？嗯？哦，也許在恐懼之末旅店中。是的，是那兒，我敢肯定。試著去布瑞爾的東南角……你認為自己能找到他嗎？"] = "affc5a63c0a0c78d1f8e58687e0f6be0",
            ["實際上我更傾向於傳統醫學……水蛭，蛆，鋸骨……那類東西。你可以看到我們本地的草藥醫學訓練師，法魯薩，就站在布瑞爾的馬廄的附近。"] = "3b98f483b3fc975239cc1e5337fdbb2e",
            ["布瑞爾鎮沒有銀行，你得去幽暗城找找。在南方的羅德隆廢墟後面的電梯能帶你去幽暗城。你可以問問幽暗城守衛，他們會為你指明方向的。"] = "5adb08a671ae648047709221c58553c6",
            ["很抱歉，朋友，在布瑞爾沒有你想要的東西。你得前往幽暗城。幽暗城位於布瑞爾以南的羅德隆廢墟下。在廢墟後面搭乘電梯即可到達，去問問幽暗城守衛，他會為你指明方向的。"] = "1d78372b655ebdea61f7c5f24bd72002",
            ["想要當廚師？到城鎮南部的幽暗城去接受培訓。你可以到羅德隆廢墟後面找到下行的電梯。當你到達後向那些笨拙的幽暗城守衛尋求更多幫助。"] = "3f03840f6cba54c94a171fec48a1899a",
            ["想飛往某處？你得去幽暗城才行！沿著城鎮南面的道路走，然後往西南方前進，到達羅德隆廢墟。你可以乘坐廢墟後面的電梯到幽暗城，問問幽暗城守衛，獲取更詳細的指示。"] = "f080ec403b25479b3bea6d34d7e97dda",
            ["我們的煉金師名叫卡羅萊·安尼斯。她居住在布瑞爾鎮西北角的房屋中。"] = "31cbfadfd213c0536a30ef65e2da9df4",
            ["我猜想你最初的訓練就是挖掘到幽暗城。嗨，明白嗎？挖掘……沒關係。要到幽暗城，你先要到布瑞爾南面的羅德隆廢墟後方，然後乘電梯下去。向那裡的一位幽暗城守衛尋求更多的幫助。"] = "2e97c78ba8df38524753f0708f9146cd",
            ["我聽說幽暗城中有個礦工訓練師。離開城鎮往南走，穿過羅德隆廢墟，你就能到那兒了。然後乘坐電梯下到幽暗城，去詢問幽暗城守衛，你應該能獲取更多指示資訊。"] = "9e32fc29d61e78d418bf12b83291d07c",
            ["接近屍體時的感覺是獨一無二的。你可以沿著城鎮外東南方面的道路前進，到達十字路口後向東走，找到舍倫尼·洛巴爾特。她居住在離道路不遠處的小營帳中。"] = "cebb299ef2f7de153bf58659b5d8051b",
            ["既然所有東西對你來說吃起來都像是灰燼，為什麼還要做飯呢？如果你還有一樣東西不是這樣的，那很好，到布瑞爾南邊的幽暗城去問一位幽暗城的守衛，以進一步瞭解如何找到他們的烹飪培訓師。要到那裡你可以從羅德隆廢墟的後方乘電梯下去。"] = "1c6cc53cc9d4d87c2ebcb2148741091e",
            ["是的，你應該去找奧斯蒂爾·德·蒙。他總住在城鎮東南端的客棧裡。它叫做恐懼之末旅店，你不會錯過的。"] = "b7899941266bd499f36628be4b089ec3",
            ["是的，你總是能看到克萊德·凱林在布瑞爾東邊的澈水湖岸釣魚。但當你到那裡後要當心那些帶著面具的變態者。我們去年就被迫關掉了孩子們的夏令營。"] = "90cd6156af4fabbed61c7d3ef0682ad3",
            ["有消息說范斯·安德格魯姆已經在城鎮東南端的恐懼之末旅店樓上永久定下了一間房間。我想他剛剛離開了閱覽室。"] = "dc627f30c464b24dbaf5d0e40e0aa261",
            ["當人們進入城鎮東南角的恐懼之末旅店時，妮拉會向這些未來的顧客致敬。"] = "372f22b4f09e1c12985532736a35e6ef",
            ["盜賊訓練者名叫馬里恩·考爾。她在城鎮東南角的恐懼之末旅店的閱覽室中。"] = "a3706807400a87a3d36b47b32c146081",
            ["蘭德·洛巴爾特相當擅長剝夜行蝙蝠這類動物的皮。你可以在往布瑞爾東南角沿途的某個營帳中找到他。沿著城鎮東南方的道路走，然後在十字路口向東轉。"] = "e4f311ec0b21740e615d6cb30e9cb438",
            ["說也奇怪，獸欄管理員莫加努斯就在馬廄外面。"] = "b3c7473fb751209da9ccc66fa335c622",
            ["那麼你是在找博文·布里斯博埃斯了。他居住在爐灰莊園大橋另一邊，布瑞爾城鎮西南部。"] = "a05a273555c4e438987174be83fe9a2d",
            ["鐵匠？不，我們最後一名鐵匠都轉變成毫無頭腦的天譴軍團士卒啦。但是鎮子南邊的幽暗城中還居住著一名鐵匠。幽暗城在羅德隆廢墟下面，好聽的名字，是嗎？乘坐廢墟後面的電梯抵達幽暗城，去跟那兒的守衛談談，他們會為你指明方向的。"] = "6635289d43d0b38e56c4dba6cd15143a",
            ["雖然在布瑞爾沒有工程學訓練師，在幽暗城卻有一位。要到那兒，朝村子的南邊走，一直到羅德隆廢墟，然後坐電梯下去。一旦你到了那裡，向一位幽暗城守衛詢問詳細的方位。"] = "48bace730ef5ab4f593d6a3849c15245",
            ["馬里恩·考爾和黑暗牧師貝里爾一起在布瑞爾鎮東南角恐懼之末旅店樓上的閱覽室中。我只是想看看誰是這場對抗的勝利者。"] = "df502e2630a2ea2e0237408499de840a",
            ["黑色、灰色和深紫色是規定的顏色。朋友，看仔細了，可別迷失方向。博文·布里斯博埃斯可以幫助你。你可以穿過鎮子西南的橋樑，去爐灰莊園找他。"] = "d6769fe270aefb1f31493758e255cc9b",
        },
        [1569] = {
            ["艾澤拉斯中沒有哪一個種族經歷過我們的人民所受的磨難，$c。面對死亡仍安之若素已經成為我們的第二天性了。"] = "f3c13d9b72d8b59a9be9b737dae6a6b2",
        },
        [1571] = {
            ["你想要飛往什麼地方？"] = "f6ea55ad6f6344693225294350de4559",
        },
        [1572] = {
            ["記得我的話！你在東部王國是找不到比塞爾薩瑪獅鷲獸更快的獅鷲獸的！"] = "d8898d865fab410aca206ba2a1411338",
        },
        [1573] = {
            ["蠻錘城堡的矮人也許有奔跑迅速的戰馬，但是這些鷹巢山的獅鷲獸能承受大鍛爐的熱量嗎？我覺得不能！"] = "d440ae293e3b396fde51ad230c446188",
        },
        [1632] = {
            ["唉，對不起。我沒什麼新東西可以教你了。你去暴風城的老城區找西蒙·坦納爾談談怎麼樣？他是一個肌肉發達有一頭漂亮紅發的人類。"] = "3562140894e8c1f1b4cacb7b4c4bbceb",
            ["它怎麼樣了？我喜歡皮革的味道；你不喜歡嗎？"] = "099dc5a84f1e29de6a36426dd647ee2b",
            ["自從我的丈夫上了前線後，海倫尼便一直保護著我。她用善良的心腸和鋒利的寶劍幫助我度過了無數艱難歲月。沒有她，我真不知道會發生什麼事。"] = "bf01f102d5ed32f38e5e64a67baaa456",
        },
        [1651] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "43ebea4a5129c29af35af2064eb93951",
            ["我可以教你一些釣魚技能。"] = "b285645e1bdb1be37d7bfdc440534eec",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "13d2af5f294a07ae2cff1bf240fa32c1",
        },
        [1652] = {
            ["他名叫魯伯特·鮑什。我聽說他在城鎮東南角的恐懼之末旅店樓上的某間房間裡。"] = "de253e3169d9f7d6717bd3c610685772",
            ["你一定是要找舍倫尼·洛巴爾特。沿著布瑞爾東南方的道路走，然後在十字路口向東走。她就居住在路邊的某個營帳中。"] = "d527ff651e5c8f5b38b73526706b5b23",
            ["你不算太聰明吧？嗯，如果我是獸欄管理員的話，我應該是在馬廄附近吧？去那邊找莫加努斯吧。"] = "e9a287a2eb1861b87d62565cd3f9941c",
            ["你可以在布瑞爾東南邊的恐懼之末旅店的樓上的一間房間找到范斯·安德格魯姆。"] = "93cc04c8b8e24496ad60223e82204b3c",
            ["你可以在恐懼之末旅店樓上的平臺找到法師訓練師凱恩·火歌的，恐懼之末旅店就在布瑞爾的東南端。我猜你現在去的話有點晚了，他不會再登記給你房間了。"] = "fd95ca0767fb6854229c17e46878eea4",
            ["你可以在穿過城鎮的道路東南端的恐懼之末旅店裡面找到旅店老闆瑞尼。"] = "e5750cf72eef1fd9a7b8998872a7898a",
            ["你想成為一個標本剝制師？我不喜歡那些從我身上獲得材料然後運走的人，因為他們認為我死了。難道不討厭嗎？好了！到城鎮東南邊的一個營地找尋蘭德·洛巴爾特。要找到他需要走布瑞爾東南方的路，然後在十字路口左拐。"] = "b2057081f202c32ff47e8c3e643a50bf",
            ["你會在城鎮西北端發現卡羅萊·安尼斯正試圖炸掉她的房屋。為什麼你不去看看你能否幫她？"] = "de06a1722b12d439c9afc5bbb2bda105",
            ["你看我像個會施魔法的人嗎？嗯，我確實聽說 凱恩·火歌居住在城鎮東南部的恐懼之末旅店的樓上。他那樣站在格雷徹的房間之外可真奇怪。"] = "385fddd86e7c422be8f061e089433318",
            ["你要找什麼技能的訓練師？"] = "453b9c8037ce4d9e2cd70e18ad1d9620",
            ["你要找什麼？"] = "2496e7dedec4748fa10b50cbb971b275",
            ["你要找的是魯伯特·鮑什。他和他的隨從居住在布瑞爾東南角恐懼之末旅店的樓上。"] = "4d833ba2be9a9ed29ed79a621d6ebcce",
            ["你說屠夫？哦，急救訓練師！一個樣。當你看到護士妮拉站在城鎮東南面的恐懼之末旅店裡面時你就會明白為什麼。"] = "d52cdea0c5a316cd91c993435b3f0346",
            ["你需要銀行做什麼？好吧，你得穿越布瑞爾南部的羅德隆廢墟，乘坐電梯到達幽暗城。當你到達那兒後，詢問自稱為幽暗城守衛的行動緩慢的憎惡，請求它給予更詳細的指示。"] = "a3e61fd7af1b53b3d710ad8dab75a981",
            ["來福槍、炸藥、炸彈、爆炸綿羊……這些可愛的東西。要學習如何製造這些物品以及其他工具的話，就去布瑞爾以南，羅德隆廢墟下的幽暗城吧。乘坐廢墟後面的電梯，當你到達幽暗城後，向一個幽暗城守衛詢問訓練者的確切位置。"] = "f1ae7876e60c93e2336f0802cc01e837",
            ["克萊德·凱林，當地的釣鱸魚高手，有他自己最喜歡的釣魚地點，就在布瑞爾東部的澈水湖。"] = "c8c457f00ba68e930345dc9a61425874",
            ["去恐懼之末旅店的主餐廳找奧斯蒂爾·德·蒙。酒館就在布瑞爾城的東南角。"] = "026418de080205834ee64ce5d0625a46",
            ["去找法魯薩。我最後一次見到她時，她正站在馬廄和西北方向的房間之間。"] = "703653ea2b256edc8ff3ec853fb0791e",
            ["去鎮子東南角的恐懼之末旅店，你可以在旅店樓上的閱覽室中找到黑暗牧師貝里爾的。"] = "5beef90fab0c2fbc8e782f8a205f7045",
            ["哪一項專業？"] = "68b0bdb01281865de220bb8ce19e964a",
            ["啊，你是在找黑暗牧師貝里爾。他在恐懼之末旅店樓上的閱讀室。他一直在閱讀、禱告，沒人知道他在幹嘛，也誰敢去問他啊？"] = "b0d229770be3e29c722b451fae65aa8a",
            ["在幽暗城中居住著一位蝙蝠管理員。出了布瑞爾城朝南走，然後在丁字路口向西走。羅德隆廢墟就在你的右邊，穿過廢墟，然後進入幽暗城。你可以問問那兒的守衛，請求他們的幫助。"] = "7cde77346a7f6eeabaf54f17380e5d92",
            ["如果我是旅店老闆瑞尼的話，我可能在哪兒？嗯？哦，也許在恐懼之末旅店中。是的，是那兒，我敢肯定。試著去布瑞爾的東南角……你認為自己能找到他嗎？"] = "affc5a63c0a0c78d1f8e58687e0f6be0",
            ["實際上我更傾向於傳統醫學……水蛭，蛆，鋸骨……那類東西。你可以看到我們本地的草藥醫學訓練師，法魯薩，就站在布瑞爾的馬廄的附近。"] = "3b98f483b3fc975239cc1e5337fdbb2e",
            ["布瑞爾鎮沒有銀行，你得去幽暗城找找。在南方的羅德隆廢墟後面的電梯能帶你去幽暗城。你可以問問幽暗城守衛，他們會為你指明方向的。"] = "5adb08a671ae648047709221c58553c6",
            ["很抱歉，朋友，在布瑞爾沒有你想要的東西。你得前往幽暗城。幽暗城位於布瑞爾以南的羅德隆廢墟下。在廢墟後面搭乘電梯即可到達，去問問幽暗城守衛，他會為你指明方向的。"] = "1d78372b655ebdea61f7c5f24bd72002",
            ["想要當廚師？到城鎮南部的幽暗城去接受培訓。你可以到羅德隆廢墟後面找到下行的電梯。當你到達後向那些笨拙的幽暗城守衛尋求更多幫助。"] = "3f03840f6cba54c94a171fec48a1899a",
            ["想飛往某處？你得去幽暗城才行！沿著城鎮南面的道路走，然後往西南方前進，到達羅德隆廢墟。你可以乘坐廢墟後面的電梯到幽暗城，問問幽暗城守衛，獲取更詳細的指示。"] = "f080ec403b25479b3bea6d34d7e97dda",
            ["我們的煉金師名叫卡羅萊·安尼斯。她居住在布瑞爾鎮西北角的房屋中。"] = "31cbfadfd213c0536a30ef65e2da9df4",
            ["我猜想你最初的訓練就是挖掘到幽暗城。嗨，明白嗎？挖掘……沒關係。要到幽暗城，你先要到布瑞爾南面的羅德隆廢墟後方，然後乘電梯下去。向那裡的一位幽暗城守衛尋求更多的幫助。"] = "2e97c78ba8df38524753f0708f9146cd",
            ["我聽說幽暗城中有個礦工訓練師。離開城鎮往南走，穿過羅德隆廢墟，你就能到那兒了。然後乘坐電梯下到幽暗城，去詢問幽暗城守衛，你應該能獲取更多指示資訊。"] = "9e32fc29d61e78d418bf12b83291d07c",
