            ["你可以在穿過城鎮的道路東南端的恐懼之末旅店裡面找到旅店老闆瑞尼。"] = "e5750cf72eef1fd9a7b8998872a7898a",
            ["你想成為一個標本剝制師？我不喜歡那些從我身上獲得材料然後運走的人，因為他們認為我死了。難道不討厭嗎？好了！到城鎮東南邊的一個營地找尋蘭德·洛巴爾特。要找到他需要走布瑞爾東南方的路，然後在十字路口左拐。"] = "b2057081f202c32ff47e8c3e643a50bf",
            ["你會在城鎮西北端發現卡羅萊·安尼斯正試圖炸掉她的房屋。為什麼你不去看看你能否幫她？"] = "de06a1722b12d439c9afc5bbb2bda105",
            ["你看我像個會施魔法的人嗎？嗯，我確實聽說 凱恩·火歌居住在城鎮東南部的恐懼之末旅店的樓上。他那樣站在格雷徹的房間之外可真奇怪。"] = "385fddd86e7c422be8f061e089433318",
            ["你要找什麼技能的訓練師？"] = "453b9c8037ce4d9e2cd70e18ad1d9620",
            ["你要找什麼？"] = "2496e7dedec4748fa10b50cbb971b275",
            ["你要找的是魯伯特·鮑什。他和他的隨從居住在布瑞爾東南角恐懼之末旅店的樓上。"] = "4d833ba2be9a9ed29ed79a621d6ebcce",
            ["你說屠夫？哦，急救訓練師！一個樣。當你看到護士妮拉站在城鎮東南面的恐懼之末旅店裡面時你就會明白為什麼。"] = "d52cdea0c5a316cd91c993435b3f0346",
            ["你需要銀行做什麼？好吧，你得穿越布瑞爾南部的羅德隆廢墟，乘坐電梯到達幽暗城。當你到達那兒後，詢問自稱為幽暗城守衛的行動緩慢的憎惡，請求它給予更詳細的指示。"] = "a3e61fd7af1b53b3d710ad8dab75a981",
            ["來福槍、炸藥、炸彈、爆炸綿羊……這些可愛的東西。要學習如何製造這些物品以及其他工具的話，就去布瑞爾以南，羅德隆廢墟下的幽暗城吧。乘坐廢墟後面的電梯，當你到達幽暗城後，向一個幽暗城守衛詢問訓練者的確切位置。"] = "f1ae7876e60c93e2336f0802cc01e837",
            ["克萊德·凱林，當地的釣鱸魚高手，有他自己最喜歡的釣魚地點，就在布瑞爾東部的澈水湖。"] = "c8c457f00ba68e930345dc9a61425874",
            ["去恐懼之末旅店的主餐廳找奧斯蒂爾·德·蒙。酒館就在布瑞爾城的東南角。"] = "026418de080205834ee64ce5d0625a46",
            ["去找法魯薩。我最後一次見到她時，她正站在馬廄和西北方向的房間之間。"] = "703653ea2b256edc8ff3ec853fb0791e",
            ["去鎮子東南角的恐懼之末旅店，你可以在旅店樓上的閱覽室中找到黑暗牧師貝里爾的。"] = "5beef90fab0c2fbc8e782f8a205f7045",
            ["哪一項專業？"] = "68b0bdb01281865de220bb8ce19e964a",
            ["啊，你是在找黑暗牧師貝里爾。他在恐懼之末旅店樓上的閱讀室。他一直在閱讀、禱告，沒人知道他在幹嘛，也誰敢去問他啊？"] = "b0d229770be3e29c722b451fae65aa8a",
            ["在幽暗城中居住著一位蝙蝠管理員。出了布瑞爾城朝南走，然後在丁字路口向西走。羅德隆廢墟就在你的右邊，穿過廢墟，然後進入幽暗城。你可以問問那兒的守衛，請求他們的幫助。"] = "7cde77346a7f6eeabaf54f17380e5d92",
            ["如果我是旅店老闆瑞尼的話，我可能在哪兒？嗯？哦，也許在恐懼之末旅店中。是的，是那兒，我敢肯定。試著去布瑞爾的東南角……你認為自己能找到他嗎？"] = "affc5a63c0a0c78d1f8e58687e0f6be0",
            ["實際上我更傾向於傳統醫學……水蛭，蛆，鋸骨……那類東西。你可以看到我們本地的草藥醫學訓練師，法魯薩，就站在布瑞爾的馬廄的附近。"] = "3b98f483b3fc975239cc1e5337fdbb2e",
            ["布瑞爾鎮沒有銀行，你得去幽暗城找找。在南方的羅德隆廢墟後面的電梯能帶你去幽暗城。你可以問問幽暗城守衛，他們會為你指明方向的。"] = "5adb08a671ae648047709221c58553c6",
            ["很抱歉，朋友，在布瑞爾沒有你想要的東西。你得前往幽暗城。幽暗城位於布瑞爾以南的羅德隆廢墟下。在廢墟後面搭乘電梯即可到達，去問問幽暗城守衛，他會為你指明方向的。"] = "1d78372b655ebdea61f7c5f24bd72002",
            ["想要當廚師？到城鎮南部的幽暗城去接受培訓。你可以到羅德隆廢墟後面找到下行的電梯。當你到達後向那些笨拙的幽暗城守衛尋求更多幫助。"] = "3f03840f6cba54c94a171fec48a1899a",
            ["想飛往某處？你得去幽暗城才行！沿著城鎮南面的道路走，然後往西南方前進，到達羅德隆廢墟。你可以乘坐廢墟後面的電梯到幽暗城，問問幽暗城守衛，獲取更詳細的指示。"] = "f080ec403b25479b3bea6d34d7e97dda",
            ["我們的煉金師名叫卡羅萊·安尼斯。她居住在布瑞爾鎮西北角的房屋中。"] = "31cbfadfd213c0536a30ef65e2da9df4",
            ["我猜想你最初的訓練就是挖掘到幽暗城。嗨，明白嗎？挖掘……沒關係。要到幽暗城，你先要到布瑞爾南面的羅德隆廢墟後方，然後乘電梯下去。向那裡的一位幽暗城守衛尋求更多的幫助。"] = "2e97c78ba8df38524753f0708f9146cd",
            ["我聽說幽暗城中有個礦工訓練師。離開城鎮往南走，穿過羅德隆廢墟，你就能到那兒了。然後乘坐電梯下到幽暗城，去詢問幽暗城守衛，你應該能獲取更多指示資訊。"] = "9e32fc29d61e78d418bf12b83291d07c",
            ["接近屍體時的感覺是獨一無二的。你可以沿著城鎮外東南方面的道路前進，到達十字路口後向東走，找到舍倫尼·洛巴爾特。她居住在離道路不遠處的小營帳中。"] = "cebb299ef2f7de153bf58659b5d8051b",
            ["既然所有東西對你來說吃起來都像是灰燼，為什麼還要做飯呢？如果你還有一樣東西不是這樣的，那很好，到布瑞爾南邊的幽暗城去問一位幽暗城的守衛，以進一步瞭解如何找到他們的烹飪培訓師。要到那裡你可以從羅德隆廢墟的後方乘電梯下去。"] = "1c6cc53cc9d4d87c2ebcb2148741091e",
            ["是的，你應該去找奧斯蒂爾·德·蒙。他總住在城鎮東南端的客棧裡。它叫做恐懼之末旅店，你不會錯過的。"] = "b7899941266bd499f36628be4b089ec3",
            ["是的，你總是能看到克萊德·凱林在布瑞爾東邊的澈水湖岸釣魚。但當你到那裡後要當心那些帶著面具的變態者。我們去年就被迫關掉了孩子們的夏令營。"] = "90cd6156af4fabbed61c7d3ef0682ad3",
            ["有消息說范斯·安德格魯姆已經在城鎮東南端的恐懼之末旅店樓上永久定下了一間房間。我想他剛剛離開了閱覽室。"] = "dc627f30c464b24dbaf5d0e40e0aa261",
            ["當人們進入城鎮東南角的恐懼之末旅店時，妮拉會向這些未來的顧客致敬。"] = "372f22b4f09e1c12985532736a35e6ef",
            ["盜賊訓練者名叫馬里恩·考爾。她在城鎮東南角的恐懼之末旅店的閱覽室中。"] = "a3706807400a87a3d36b47b32c146081",
            ["蘭德·洛巴爾特相當擅長剝夜行蝙蝠這類動物的皮。你可以在往布瑞爾東南角沿途的某個營帳中找到他。沿著城鎮東南方的道路走，然後在十字路口向東轉。"] = "e4f311ec0b21740e615d6cb30e9cb438",
            ["說也奇怪，獸欄管理員莫加努斯就在馬廄外面。"] = "b3c7473fb751209da9ccc66fa335c622",
            ["那麼你是在找博文·布里斯博埃斯了。他居住在爐灰莊園大橋另一邊，布瑞爾城鎮西南部。"] = "a05a273555c4e438987174be83fe9a2d",
            ["鐵匠？不，我們最後一名鐵匠都轉變成毫無頭腦的天譴軍團士卒啦。但是鎮子南邊的幽暗城中還居住著一名鐵匠。幽暗城在羅德隆廢墟下面，好聽的名字，是嗎？乘坐廢墟後面的電梯抵達幽暗城，去跟那兒的守衛談談，他們會為你指明方向的。"] = "6635289d43d0b38e56c4dba6cd15143a",
            ["雖然在布瑞爾沒有工程學訓練師，在幽暗城卻有一位。要到那兒，朝村子的南邊走，一直到羅德隆廢墟，然後坐電梯下去。一旦你到了那裡，向一位幽暗城守衛詢問詳細的方位。"] = "48bace730ef5ab4f593d6a3849c15245",
            ["馬里恩·考爾和黑暗牧師貝里爾一起在布瑞爾鎮東南角恐懼之末旅店樓上的閱覽室中。我只是想看看誰是這場對抗的勝利者。"] = "df502e2630a2ea2e0237408499de840a",
            ["黑色、灰色和深紫色是規定的顏色。朋友，看仔細了，可別迷失方向。博文·布里斯博埃斯可以幫助你。你可以穿過鎮子西南的橋樑，去爐灰莊園找他。"] = "d6769fe270aefb1f31493758e255cc9b",
        },
        [1742] = {
            ["他名叫魯伯特·鮑什。我聽說他在城鎮東南角的恐懼之末旅店樓上的某間房間裡。"] = "de253e3169d9f7d6717bd3c610685772",
            ["你一定是要找舍倫尼·洛巴爾特。沿著布瑞爾東南方的道路走，然後在十字路口向東走。她就居住在路邊的某個營帳中。"] = "d527ff651e5c8f5b38b73526706b5b23",
            ["你不算太聰明吧？嗯，如果我是獸欄管理員的話，我應該是在馬廄附近吧？去那邊找莫加努斯吧。"] = "e9a287a2eb1861b87d62565cd3f9941c",
            ["你可以在布瑞爾東南邊的恐懼之末旅店的樓上的一間房間找到范斯·安德格魯姆。"] = "93cc04c8b8e24496ad60223e82204b3c",
            ["你可以在恐懼之末旅店樓上的平臺找到法師訓練師凱恩·火歌的，恐懼之末旅店就在布瑞爾的東南端。我猜你現在去的話有點晚了，他不會再登記給你房間了。"] = "fd95ca0767fb6854229c17e46878eea4",
            ["你可以在穿過城鎮的道路東南端的恐懼之末旅店裡面找到旅店老闆瑞尼。"] = "e5750cf72eef1fd9a7b8998872a7898a",
            ["你想成為一個標本剝制師？我不喜歡那些從我身上獲得材料然後運走的人，因為他們認為我死了。難道不討厭嗎？好了！到城鎮東南邊的一個營地找尋蘭德·洛巴爾特。要找到他需要走布瑞爾東南方的路，然後在十字路口左拐。"] = "b2057081f202c32ff47e8c3e643a50bf",
            ["你會在城鎮西北端發現卡羅萊·安尼斯正試圖炸掉她的房屋。為什麼你不去看看你能否幫她？"] = "de06a1722b12d439c9afc5bbb2bda105",
            ["你看我像個會施魔法的人嗎？嗯，我確實聽說 凱恩·火歌居住在城鎮東南部的恐懼之末旅店的樓上。他那樣站在格雷徹的房間之外可真奇怪。"] = "385fddd86e7c422be8f061e089433318",
            ["你要找什麼技能的訓練師？"] = "453b9c8037ce4d9e2cd70e18ad1d9620",
