            ["為了學習更多的術士知識，你在我面前表現謙卑是很明智的做法$N。"] = "6d671d26f71829b3cfdafaf53866d6f0",
        },
        [2128] = {
            ["你好。我是一個不死族法師訓練師，而你不是一個法師。"] = "449fe8a183d9fbd6474051e5e1ba406e",
            ["你好。我是一個不死族法師訓練師，而你是一個法師。"] = "a6c8531f923dc7ee0e543e0e81ce1717",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "a54fabb9fc0936c92134f8611f4e5e8b",
        },
        [2129] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "a54fabb9fc0936c92134f8611f4e5e8b",
            ["我這個無足輕重的僕人能為你做什麼，$N？需要訓練嗎？"] = "650cd75a030b0fef3f59f216d895e8d1",
            ["找我有事嗎，$c？"] = "901d3b1160b38eacb61be277a1eab438",
        },
        [2130] = {
            ["我不能訓練你。你必須去找你的職業訓練師。"] = "d27bd058351066858c056f51bdfeb0bd",
            ["經瓦里瑪薩斯大人批准，亡靈哨兵的數量增加了。我們將進一步加強打擊敵人的力度。"] = "d727a9a6c19bda725fe90de6453f386d",
        },
        [2131] = {
            ["別浪費我的時間，$c。"] = "3484fd102c48eb2fcac5e4f8ecc5347e",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "a54fabb9fc0936c92134f8611f4e5e8b",
            ["戰士的任務之一就是保護。正如我們在戰場上保護自己的同伴一樣，我們要時刻保護被遺忘者的利益。"] = "bab02b057326c5ce92b70b19685745ed",
        },
        [2132] = {
            ["你是來學習配製藥水的？我能傳授給你很多知識。雖然我已年老力衰，但腦子還是管用的。"] = "e00a650b93c5cb187a919fea9c0b6b04",
            ["我很珍惜我們之間的友誼，但是讓我們面對現實吧：你對藥水的瞭解比我多。要是你想得到訓練的話，就找亡靈馬許醫生談談。他居住在幽暗城的煉金房。"] = "6ef22daba019cddea954f20b7e491d93",
            ["能看到一張友善的臉真不錯。我沒有跟藥劑師喬漢聊過很多，除非他想要什麼東西。他離開墳墓太久了。有一天我也會像他一樣，我聽說。真可怕。或許到那時我就不在乎了。"] = "62828f581202bf71fe7f31d089e549df",
        },
        [2198] = {
            ["向你致敬，英雄！我有來自大陸和島嶼的最新消息，供你參考。"] = "b8290ddda0b05b868413d4053a016622",
        },
        [2209] = {
            ["他名叫魯伯特·鮑什。我聽說他在城鎮東南角的恐懼之末旅店樓上的某間房間裡。"] = "de253e3169d9f7d6717bd3c610685772",
            ["你一定是要找舍倫尼·洛巴爾特。沿著布瑞爾東南方的道路走，然後在十字路口向東走。她就居住在路邊的某個營帳中。"] = "d527ff651e5c8f5b38b73526706b5b23",
            ["你不算太聰明吧？嗯，如果我是獸欄管理員的話，我應該是在馬廄附近吧？去那邊找莫加努斯吧。"] = "e9a287a2eb1861b87d62565cd3f9941c",
            ["你可以在布瑞爾東南邊的恐懼之末旅店的樓上的一間房間找到范斯·安德格魯姆。"] = "93cc04c8b8e24496ad60223e82204b3c",
            ["你可以在恐懼之末旅店樓上的平臺找到法師訓練師凱恩·火歌的，恐懼之末旅店就在布瑞爾的東南端。我猜你現在去的話有點晚了，他不會再登記給你房間了。"] = "fd95ca0767fb6854229c17e46878eea4",
            ["你可以在穿過城鎮的道路東南端的恐懼之末旅店裡面找到旅店老闆瑞尼。"] = "e5750cf72eef1fd9a7b8998872a7898a",
            ["你想成為一個標本剝制師？我不喜歡那些從我身上獲得材料然後運走的人，因為他們認為我死了。難道不討厭嗎？好了！到城鎮東南邊的一個營地找尋蘭德·洛巴爾特。要找到他需要走布瑞爾東南方的路，然後在十字路口左拐。"] = "b2057081f202c32ff47e8c3e643a50bf",
            ["你會在城鎮西北端發現卡羅萊·安尼斯正試圖炸掉她的房屋。為什麼你不去看看你能否幫她？"] = "de06a1722b12d439c9afc5bbb2bda105",
            ["你看我像個會施魔法的人嗎？嗯，我確實聽說 凱恩·火歌居住在城鎮東南部的恐懼之末旅店的樓上。他那樣站在格雷徹的房間之外可真奇怪。"] = "385fddd86e7c422be8f061e089433318",
            ["你要找什麼技能的訓練師？"] = "453b9c8037ce4d9e2cd70e18ad1d9620",
            ["你要找什麼？"] = "2496e7dedec4748fa10b50cbb971b275",
            ["你要找的是魯伯特·鮑什。他和他的隨從居住在布瑞爾東南角恐懼之末旅店的樓上。"] = "4d833ba2be9a9ed29ed79a621d6ebcce",
            ["你說屠夫？哦，急救訓練師！一個樣。當你看到護士妮拉站在城鎮東南面的恐懼之末旅店裡面時你就會明白為什麼。"] = "d52cdea0c5a316cd91c993435b3f0346",
            ["你需要銀行做什麼？好吧，你得穿越布瑞爾南部的羅德隆廢墟，乘坐電梯到達幽暗城。當你到達那兒後，詢問自稱為幽暗城守衛的行動緩慢的憎惡，請求它給予更詳細的指示。"] = "a3e61fd7af1b53b3d710ad8dab75a981",
            ["來福槍、炸藥、炸彈、爆炸綿羊……這些可愛的東西。要學習如何製造這些物品以及其他工具的話，就去布瑞爾以南，羅德隆廢墟下的幽暗城吧。乘坐廢墟後面的電梯，當你到達幽暗城後，向一個幽暗城守衛詢問訓練者的確切位置。"] = "f1ae7876e60c93e2336f0802cc01e837",
            ["克萊德·凱林，當地的釣鱸魚高手，有他自己最喜歡的釣魚地點，就在布瑞爾東部的澈水湖。"] = "c8c457f00ba68e930345dc9a61425874",
            ["去恐懼之末旅店的主餐廳找奧斯蒂爾·德·蒙。酒館就在布瑞爾城的東南角。"] = "026418de080205834ee64ce5d0625a46",
            ["去找法魯薩。我最後一次見到她時，她正站在馬廄和西北方向的房間之間。"] = "703653ea2b256edc8ff3ec853fb0791e",
            ["去鎮子東南角的恐懼之末旅店，你可以在旅店樓上的閱覽室中找到黑暗牧師貝里爾的。"] = "5beef90fab0c2fbc8e782f8a205f7045",
            ["哪一項專業？"] = "68b0bdb01281865de220bb8ce19e964a",
            ["啊，你是在找黑暗牧師貝里爾。他在恐懼之末旅店樓上的閱讀室。他一直在閱讀、禱告，沒人知道他在幹嘛，也誰敢去問他啊？"] = "b0d229770be3e29c722b451fae65aa8a",
            ["在幽暗城中居住著一位蝙蝠管理員。出了布瑞爾城朝南走，然後在丁字路口向西走。羅德隆廢墟就在你的右邊，穿過廢墟，然後進入幽暗城。你可以問問那兒的守衛，請求他們的幫助。"] = "7cde77346a7f6eeabaf54f17380e5d92",
            ["如果我是旅店老闆瑞尼的話，我可能在哪兒？嗯？哦，也許在恐懼之末旅店中。是的，是那兒，我敢肯定。試著去布瑞爾的東南角……你認為自己能找到他嗎？"] = "affc5a63c0a0c78d1f8e58687e0f6be0",
            ["實際上我更傾向於傳統醫學……水蛭，蛆，鋸骨……那類東西。你可以看到我們本地的草藥醫學訓練師，法魯薩，就站在布瑞爾的馬廄的附近。"] = "3b98f483b3fc975239cc1e5337fdbb2e",
            ["布瑞爾鎮沒有銀行，你得去幽暗城找找。在南方的羅德隆廢墟後面的電梯能帶你去幽暗城。你可以問問幽暗城守衛，他們會為你指明方向的。"] = "5adb08a671ae648047709221c58553c6",
            ["很抱歉，朋友，在布瑞爾沒有你想要的東西。你得前往幽暗城。幽暗城位於布瑞爾以南的羅德隆廢墟下。在廢墟後面搭乘電梯即可到達，去問問幽暗城守衛，他會為你指明方向的。"] = "1d78372b655ebdea61f7c5f24bd72002",
            ["想要當廚師？到城鎮南部的幽暗城去接受培訓。你可以到羅德隆廢墟後面找到下行的電梯。當你到達後向那些笨拙的幽暗城守衛尋求更多幫助。"] = "3f03840f6cba54c94a171fec48a1899a",
            ["想飛往某處？你得去幽暗城才行！沿著城鎮南面的道路走，然後往西南方前進，到達羅德隆廢墟。你可以乘坐廢墟後面的電梯到幽暗城，問問幽暗城守衛，獲取更詳細的指示。"] = "f080ec403b25479b3bea6d34d7e97dda",
            ["我們的煉金師名叫卡羅萊·安尼斯。她居住在布瑞爾鎮西北角的房屋中。"] = "31cbfadfd213c0536a30ef65e2da9df4",
            ["我猜想你最初的訓練就是挖掘到幽暗城。嗨，明白嗎？挖掘……沒關係。要到幽暗城，你先要到布瑞爾南面的羅德隆廢墟後方，然後乘電梯下去。向那裡的一位幽暗城守衛尋求更多的幫助。"] = "2e97c78ba8df38524753f0708f9146cd",
            ["我聽說幽暗城中有個礦工訓練師。離開城鎮往南走，穿過羅德隆廢墟，你就能到那兒了。然後乘坐電梯下到幽暗城，去詢問幽暗城守衛，你應該能獲取更多指示資訊。"] = "9e32fc29d61e78d418bf12b83291d07c",
            ["接近屍體時的感覺是獨一無二的。你可以沿著城鎮外東南方面的道路前進，到達十字路口後向東走，找到舍倫尼·洛巴爾特。她居住在離道路不遠處的小營帳中。"] = "cebb299ef2f7de153bf58659b5d8051b",
            ["既然所有東西對你來說吃起來都像是灰燼，為什麼還要做飯呢？如果你還有一樣東西不是這樣的，那很好，到布瑞爾南邊的幽暗城去問一位幽暗城的守衛，以進一步瞭解如何找到他們的烹飪培訓師。要到那裡你可以從羅德隆廢墟的後方乘電梯下去。"] = "1c6cc53cc9d4d87c2ebcb2148741091e",
            ["是的，你應該去找奧斯蒂爾·德·蒙。他總住在城鎮東南端的客棧裡。它叫做恐懼之末旅店，你不會錯過的。"] = "b7899941266bd499f36628be4b089ec3",
            ["是的，你總是能看到克萊德·凱林在布瑞爾東邊的澈水湖岸釣魚。但當你到那裡後要當心那些帶著面具的變態者。我們去年就被迫關掉了孩子們的夏令營。"] = "90cd6156af4fabbed61c7d3ef0682ad3",
            ["有消息說范斯·安德格魯姆已經在城鎮東南端的恐懼之末旅店樓上永久定下了一間房間。我想他剛剛離開了閱覽室。"] = "dc627f30c464b24dbaf5d0e40e0aa261",
            ["當人們進入城鎮東南角的恐懼之末旅店時，妮拉會向這些未來的顧客致敬。"] = "372f22b4f09e1c12985532736a35e6ef",
            ["盜賊訓練者名叫馬里恩·考爾。她在城鎮東南角的恐懼之末旅店的閱覽室中。"] = "a3706807400a87a3d36b47b32c146081",
            ["蘭德·洛巴爾特相當擅長剝夜行蝙蝠這類動物的皮。你可以在往布瑞爾東南角沿途的某個營帳中找到他。沿著城鎮東南方的道路走，然後在十字路口向東轉。"] = "e4f311ec0b21740e615d6cb30e9cb438",
            ["說也奇怪，獸欄管理員莫加努斯就在馬廄外面。"] = "b3c7473fb751209da9ccc66fa335c622",
            ["那麼你是在找博文·布里斯博埃斯了。他居住在爐灰莊園大橋另一邊，布瑞爾城鎮西南部。"] = "a05a273555c4e438987174be83fe9a2d",
            ["鐵匠？不，我們最後一名鐵匠都轉變成毫無頭腦的天譴軍團士卒啦。但是鎮子南邊的幽暗城中還居住著一名鐵匠。幽暗城在羅德隆廢墟下面，好聽的名字，是嗎？乘坐廢墟後面的電梯抵達幽暗城，去跟那兒的守衛談談，他們會為你指明方向的。"] = "6635289d43d0b38e56c4dba6cd15143a",
            ["雖然在布瑞爾沒有工程學訓練師，在幽暗城卻有一位。要到那兒，朝村子的南邊走，一直到羅德隆廢墟，然後坐電梯下去。一旦你到了那裡，向一位幽暗城守衛詢問詳細的方位。"] = "48bace730ef5ab4f593d6a3849c15245",
            ["馬里恩·考爾和黑暗牧師貝里爾一起在布瑞爾鎮東南角恐懼之末旅店樓上的閱覽室中。我只是想看看誰是這場對抗的勝利者。"] = "df502e2630a2ea2e0237408499de840a",
            ["黑色、灰色和深紫色是規定的顏色。朋友，看仔細了，可別迷失方向。博文·布里斯博埃斯可以幫助你。你可以穿過鎮子西南的橋樑，去爐灰莊園找他。"] = "d6769fe270aefb1f31493758e255cc9b",
        },
        [2210] = {
            ["他名叫魯伯特·鮑什。我聽說他在城鎮東南角的恐懼之末旅店樓上的某間房間裡。"] = "01124c3b711e07151142abc5f95268f2",
            ["你一定是要找舍倫尼·洛巴爾特。沿著布瑞爾東南方的道路走，然後在十字路口向東走。她就居住在路邊的某個營帳中。"] = "a5c7a15cdd9cd24c0896986897aa6257",
            ["你不算太聰明吧？嗯，如果我是獸欄管理員的話，我應該是在馬廄附近吧？去那邊找莫加努斯吧。"] = "172651bdd26f58b06745eb92d746a013",
            ["你可以在布瑞爾東南邊的恐懼之末旅店的樓上的一間房間找到范斯·安德格魯姆。"] = "f3fcdf2085aaeddd3fb4d9eb72210d18",
            ["你可以在恐懼之末旅店樓上的平臺找到法師訓練師凱恩·火歌的，恐懼之末旅店就在布瑞爾的東南端。我猜你現在去的話有點晚了，他不會再登記給你房間了。"] = "1e5f1737a1701a50722b2b5518364863",
            ["你可以在穿過城鎮的道路東南端的恐懼之末旅店裡面找到旅店老闆瑞尼。"] = "2557195bf3e59ed32c3d8e138273a3aa",
            ["你想成為一個標本剝制師？我不喜歡那些從我身上獲得材料然後運走的人，因為他們認為我死了。難道不討厭嗎？好了！到城鎮東南邊的一個營地找尋蘭德·洛巴爾特。要找到他需要走布瑞爾東南方的路，然後在十字路口左拐。"] = "3f5cc117ebd220215e10fa35e0a1dce8",
            ["你會在城鎮西北端發現卡羅萊·安尼斯正試圖炸掉她的房屋。為什麼你不去看看你能否幫她？"] = "a7fa537c7b0432b939cd07a8db5249bb",
            ["你看我像個會施魔法的人嗎？嗯，我確實聽說 凱恩·火歌居住在城鎮東南部的恐懼之末旅店的樓上。他那樣站在格雷徹的房間之外可真奇怪。"] = "943f78c6d91bc1ea400acfcaec5316bd",
            ["你要找什麼技能的訓練師？"] = "59f12cd78c4d26b8aee81e68100d276a",
            ["你要找什麼？"] = "2cce376a7f0e367a39a45e26216ab5f2",
            ["你要找的是魯伯特·鮑什。他和他的隨從居住在布瑞爾東南角恐懼之末旅店的樓上。"] = "51f8b17d8b9488e0ccd4bd533aa062d3",
            ["你說屠夫？哦，急救訓練師！一個樣。當你看到護士妮拉站在城鎮東南面的恐懼之末旅店裡面時你就會明白為什麼。"] = "2efa1bcf49300d8f807523fd6673df71",
            ["你需要銀行做什麼？好吧，你得穿越布瑞爾南部的羅德隆廢墟，乘坐電梯到達幽暗城。當你到達那兒後，詢問自稱為幽暗城守衛的行動緩慢的憎惡，請求它給予更詳細的指示。"] = "7184e5ed6132309035e3eec452e87a4d",
            ["來福槍、炸藥、炸彈、爆炸綿羊……這些可愛的東西。要學習如何製造這些物品以及其他工具的話，就去布瑞爾以南，羅德隆廢墟下的幽暗城吧。乘坐廢墟後面的電梯，當你到達幽暗城後，向一個幽暗城守衛詢問訓練者的確切位置。"] = "e409c34e00dbc45b47e8c9dbf314a4dc",
            ["克萊德·凱林，當地的釣鱸魚高手，有他自己最喜歡的釣魚地點，就在布瑞爾東部的澈水湖。"] = "5ba96289663e59e56f3ab679b5ca74e1",
            ["去恐懼之末旅店的主餐廳找奧斯蒂爾·德·蒙。酒館就在布瑞爾城的東南角。"] = "616358afa775aba892d936fda890ea34",
            ["去找法魯薩。我最後一次見到她時，她正站在馬廄和西北方向的房間之間。"] = "977af039ec3c7a44b7db0d8dff2bd8d9",
            ["去鎮子東南角的恐懼之末旅店，你可以在旅店樓上的閱覽室中找到黑暗牧師貝里爾的。"] = "0c7b458308be384d96d85e82cd05977f",
            ["哪一項專業？"] = "8d09546b60b6d39bda2ac4ec0471ced5",
            ["啊，你是在找黑暗牧師貝里爾。他在恐懼之末旅店樓上的閱讀室。他一直在閱讀、禱告，沒人知道他在幹嘛，也誰敢去問他啊？"] = "88eb979b8293db04958ffc41229df9da",
            ["在幽暗城中居住著一位蝙蝠管理員。出了布瑞爾城朝南走，然後在丁字路口向西走。羅德隆廢墟就在你的右邊，穿過廢墟，然後進入幽暗城。你可以問問那兒的守衛，請求他們的幫助。"] = "8e6d351e4b5ed5b89d136ecabc40dd4d",
            ["如果我是旅店老闆瑞尼的話，我可能在哪兒？嗯？哦，也許在恐懼之末旅店中。是的，是那兒，我敢肯定。試著去布瑞爾的東南角……你認為自己能找到他嗎？"] = "1911d77dc4307cbbb8ac8bfe3905aa2a",
            ["實際上我更傾向於傳統醫學……水蛭，蛆，鋸骨……那類東西。你可以看到我們本地的草藥醫學訓練師，法魯薩，就站在布瑞爾的馬廄的附近。"] = "0939bad12351da20cc3b8d4e77a7fee8",
            ["布瑞爾鎮沒有銀行，你得去幽暗城找找。在南方的羅德隆廢墟後面的電梯能帶你去幽暗城。你可以問問幽暗城守衛，他們會為你指明方向的。"] = "a2e87b02900fb5026e9da78b0a6b3a10",
            ["很抱歉，朋友，在布瑞爾沒有你想要的東西。你得前往幽暗城。幽暗城位於布瑞爾以南的羅德隆廢墟下。在廢墟後面搭乘電梯即可到達，去問問幽暗城守衛，他會為你指明方向的。"] = "1139c3ddc8af6aee008200acb0687a4d",
            ["想要當廚師？到城鎮南部的幽暗城去接受培訓。你可以到羅德隆廢墟後面找到下行的電梯。當你到達後向那些笨拙的幽暗城守衛尋求更多幫助。"] = "6f3dc341f1c868637188480b03d81828",
            ["想飛往某處？你得去幽暗城才行！沿著城鎮南面的道路走，然後往西南方前進，到達羅德隆廢墟。你可以乘坐廢墟後面的電梯到幽暗城，問問幽暗城守衛，獲取更詳細的指示。"] = "dcc002025bab5d42756438e0222ade8d",
            ["我們的煉金師名叫卡羅萊·安尼斯。她居住在布瑞爾鎮西北角的房屋中。"] = "3866411706250b90fd5b8f8e06a403fb",
            ["我猜想你最初的訓練就是挖掘到幽暗城。嗨，明白嗎？挖掘……沒關係。要到幽暗城，你先要到布瑞爾南面的羅德隆廢墟後方，然後乘電梯下去。向那裡的一位幽暗城守衛尋求更多的幫助。"] = "15ea84887025f02a521a2456a5bf77a9",
            ["我聽說幽暗城中有個礦工訓練師。離開城鎮往南走，穿過羅德隆廢墟，你就能到那兒了。然後乘坐電梯下到幽暗城，去詢問幽暗城守衛，你應該能獲取更多指示資訊。"] = "b880e21a58d9603b16f9e2ef471c8aab",
            ["接近屍體時的感覺是獨一無二的。你可以沿著城鎮外東南方面的道路前進，到達十字路口後向東走，找到舍倫尼·洛巴爾特。她居住在離道路不遠處的小營帳中。"] = "103bf72df1b5fce49d05a3edff6ff22e",
            ["既然所有東西對你來說吃起來都像是灰燼，為什麼還要做飯呢？如果你還有一樣東西不是這樣的，那很好，到布瑞爾南邊的幽暗城去問一位幽暗城的守衛，以進一步瞭解如何找到他們的烹飪培訓師。要到那裡你可以從羅德隆廢墟的後方乘電梯下去。"] = "8313213d75e6f7833f8797c2bdbcf6b2",
            ["是的，你應該去找奧斯蒂爾·德·蒙。他總住在城鎮東南端的客棧裡。它叫做恐懼之末旅店，你不會錯過的。"] = "8a3263760d4d0df6c2f50cf4266a0ae5",
            ["是的，你總是能看到克萊德·凱林在布瑞爾東邊的澈水湖岸釣魚。但當你到那裡後要當心那些帶著面具的變態者。我們去年就被迫關掉了孩子們的夏令營。"] = "bec655628b2ba6a6a8f247919f4f203d",
            ["有消息說范斯·安德格魯姆已經在城鎮東南端的恐懼之末旅店樓上永久定下了一間房間。我想他剛剛離開了閱覽室。"] = "c60120c8d889359d6ad321e0d26aeeb2",
            ["當人們進入城鎮東南角的恐懼之末旅店時，妮拉會向這些未來的顧客致敬。"] = "ecc77cd6a30b13bcf17021722aa5919f",
            ["盜賊訓練者名叫馬里恩·考爾。她在城鎮東南角的恐懼之末旅店的閱覽室中。"] = "3ee5a4b825abc707bb4630a9bbad2bf3",
            ["蘭德·洛巴爾特相當擅長剝夜行蝙蝠這類動物的皮。你可以在往布瑞爾東南角沿途的某個營帳中找到他。沿著城鎮東南方的道路走，然後在十字路口向東轉。"] = "a25fe9ad1bdfb172b3a2dd3d0ef51db1",
            ["說也奇怪，獸欄管理員莫加努斯就在馬廄外面。"] = "7e077ea3795c4616340d79cc24a4a758",
            ["那麼你是在找博文·布里斯博埃斯了。他居住在爐灰莊園大橋另一邊，布瑞爾城鎮西南部。"] = "7fd1483462d52d9cdaa86c1b708ae95f",
            ["鐵匠？不，我們最後一名鐵匠都轉變成毫無頭腦的天譴軍團士卒啦。但是鎮子南邊的幽暗城中還居住著一名鐵匠。幽暗城在羅德隆廢墟下面，好聽的名字，是嗎？乘坐廢墟後面的電梯抵達幽暗城，去跟那兒的守衛談談，他們會為你指明方向的。"] = "cf043be13d65871775db5915c930b85b",
            ["雖然在布瑞爾沒有工程學訓練師，在幽暗城卻有一位。要到那兒，朝村子的南邊走，一直到羅德隆廢墟，然後坐電梯下去。一旦你到了那裡，向一位幽暗城守衛詢問詳細的方位。"] = "b9c7c0e581d2907d5cd3e5f622b7ca2d",
            ["馬里恩·考爾和黑暗牧師貝里爾一起在布瑞爾鎮東南角恐懼之末旅店樓上的閱覽室中。我只是想看看誰是這場對抗的勝利者。"] = "401d08a40d2bbc1996b8b3974f466abc",
            ["黑色、灰色和深紫色是規定的顏色。朋友，看仔細了，可別迷失方向。博文·布里斯博埃斯可以幫助你。你可以穿過鎮子西南的橋樑，去爐灰莊園找他。"] = "9189817d90eaaf387d6f475085c6270b",
        },
        [2226] = {
            ["你好。我們的蝙蝠訓練很嚴而且吃得不錯。你不會找到比他們還快的了。"] = "fa762cd2402b543f4083d66aa2a57e13",
        },
        [2238] = {
            ["從這裡離開，$c，不然他們也會把你鎖住的。"] = "77c86eaf2987bb99b8be605cc0566070",
        },
        [2239] = {
            ["有個人類手中有能打開這個裝置的鑰匙。我想他的名字叫埃斯頓。"] = "89766cf6963eb64a903985c79701ac18",
            ["當我因為綁著這個大鐵球而不能保護自己的時候，你會嘲笑我嗎？"] = "ed5b5a2b8d5bee46993333b4c3f3eafe",
        },
        [2299] = {
            ["你想要飛往什麼地方？"] = "646a52da6f00e2b6b680741da2aab13f",
        },
        [2302] = {
            ["你好，$c。你願意幫助戰歌峽谷的銀翼哨兵作戰嗎？"] = "5f903d5d4508abe7b82460c9b5fcf80e",
            ["很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。"] = "db6d2a2e49b804a2cf643369c2d678f3",
        },
        [2326] = {
            ["倍受尊敬的古斯塔夫·范沃森醫生能進一步訓練你。他就在塞拉摩的兵營裡治療傷兵。"] = "ac5120ee0f594edb256081dbc34f1a6f",
            ["我可以訓練你急救技能。"] = "61338bf2449f9fe80a4879d402d94c72",
            ["我聽說藏身在激流堡的德尼布·沃克有一本書，這本書一定能幫助你提高急救技能。"] = "73b3f07d486fb7ce23b8df9c95511471",
        },
        [2327] = {
            ["倍受尊敬的古斯塔夫·范沃森醫生能進一步訓練你。他就在塞拉摩的兵營裡治療傷兵。"] = "1d81b661f251fb69f984eaa16be96159",
            ["哦，一個同夥的醫師。我願意傳授任何能幫助你旅途的東西。"] = "5871df482a5322411e3250bb05234252",
            ["怎麼了，$g小夥子:姑娘;？我能幫你什麼忙嗎？"] = "a9c31ad2585736a1fb03d2ae8ab3eacd",
            ["我聽說藏身在激流堡的德尼布·沃克有一本書，這本書一定能幫助你提高急救技能。"] = "6bb0666f31370413b0bedf9c9606f6aa",
        },
        [2329] = {
            ["倍受尊敬的古斯塔夫·范沃森醫生能進一步訓練你。他就在塞拉摩的兵營裡治療傷兵。"] = "1d81b661f251fb69f984eaa16be96159",
            ["我可以訓練你急救技能。"] = "6e0e069ae3df14ed20af0f9912ceff68",
            ["我聽說藏身在激流堡的德尼布·沃克有一本書，這本書一定能幫助你提高急救技能。"] = "6bb0666f31370413b0bedf9c9606f6aa",
        },
        [2352] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "137f53b5268a04b1b5bdb21820557b14",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "b414305e416528da2000301e3515fa68",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "4770f436e4721b1e363a54416ff3594f",
            ["你有興趣探索這些地下城中的一個嗎？"] = "338674bfb1edb2117c563bae8305e5f2",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "e581a9ed3de8105b6729f7dc085e1c17",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "86a94d223c4370fac6e1ac3838f3978d",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "3cb878b29bbead8f6dd51327dc32625a",
            ["厄運之槌位於菲拉斯的中部。"] = "f6eff35098cc2813e2aaba0133e90c9f",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "60ab96695e6dbb39e46aa2a2cb6eaea7",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "70e14cec1f3ddef25bb53cbea8c56ec7",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "0b5e7969b8b45594985feae2eb2ed564",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "f3470ace9961a588dd6ef24942fdbf74",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "fd1eeeb911d448dfafb87bd8acef70d7",
            ["奧達曼位於荒蕪之地最北端。"] = "a5b01fe10a2f3670eed24abec1704d24",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "7b54d00530269ed4fa7441cf0c9dc6b5",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "206f059d0c629c5d37a5efc62769a4a3",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "a98ca602e3662a391ca9f0807a798926",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "22402e5384189f37d277d6f6502d132f",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "bf63140d3b623148e1b74e9a0e0b5219",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "d268a407b36e89a7c70ab981fb46abd7",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d954ed5f8eed6d5d9fba09e4a2c794c3",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "fbc87ee1e0a194ab0eaf5f7c75da9fe1",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "ea68efe1a61ecbb1e167a8048083d87a",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "9cd348728ba38505c5456af01f1ea6f5",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "442564e4ee5fc6e12bc08f7fc207c5ee",
            ["歡迎來到我的旅店，疲憊的旅行者。我能為您做點什麼嗎？"] = "e3e01e02de026cbe5e2560a468bbdebb",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "d93e39bb8315763e590a2f235411c18a",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "2ca43116d936ae90d2a83a9e65633b18",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "226480cbc96165e6dd0338a080871d2b",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "0576d812610ee374192e4e84ef91c2f2",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "fa856e726cbf60331453148913410f70",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "616aaf989a9683312fafbb75a48fe26b",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "39cefc621bbcaa9de4f15bf64910a0dd",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "4fb69760c9da7ebb077cf4bab2e8b3c9",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "72550dddc854b1270a86f40c208f6ae0",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "bfe63c8539d0c2c66acda72719c40dba",
            ["諾姆瑞根在丹莫洛的西邊。"] = "ad9e028bbf4d1db826c98feaf297f9c3",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "629ffce2af79eb3c11349d2f8fa2deb2",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "030c3d5eaa74e0b659b340e1c5a38305",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "8b5f9c1d4b48cf5f54a92b94cfb20ced",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "9b605670acd65783140b807060cc5459",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "e9bfb735f937373390fdaecefdf86203",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "f8d10783a3c760d2420a46cb47298aa5",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "6971e3d1fc84da25d4a4d7539cfcb942",
        },
        [2357] = {
            ["多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了——今天就在這裡找到你想要的馬！"] = "0016d0ff7c43ada7e4f367d5b24e9b81",
            ["很抱歉，如果你不是暴風城中的貴族，我是不會將馬匹賣給你的。這些戰馬是最好的，我們當然不會當它們落入敵人之手。$B$B想要證明自己不是敵人，當然……你只需贏得暴風城的信任，我就可以跟你做買賣了。"] = "33c0e9087e12555f8dc52cc2a68cccb1",
        },
        [2367] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "43ebea4a5129c29af35af2064eb93951",
            ["我可以教你一些釣魚技能。"] = "b285645e1bdb1be37d7bfdc440534eec",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "13d2af5f294a07ae2cff1bf240fa32c1",
        },
        [2388] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "a1c3340c748bfd2a378997d42cba3570",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "f6e7182f2b831d3e98ea00acd3a557b4",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "3f25eaca37dd5ce3380c10c71eac60c2",
            ["你有興趣探索這些地下城中的一個嗎？"] = "488213bad6a40fbf7079b51dde4826ad",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "2391b5317315d4d4a8941b336ba01d82",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "a92e7dde31e809f1b96a4d8f50c2d96e",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "df15192a7814812aa87b737075049c7f",
            ["厄運之槌位於菲拉斯的中部。"] = "69d5225f370d5873a20086b12494e196",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "19478f299bf1f913ecdd844a7b1ec37c",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4af8645fc89247fb0892c4705462e74d",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "c57a00c42fdfecf52c42b66d787bc1cd",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5561946a80fa1778f731cd1da49a7f21",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "fa92810b103689a5e9744a90f05b45f4",
            ["奧達曼位於荒蕪之地最北端。"] = "d3b374cc078d522b47d39d918bf336ae",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "4bad438e187701f17fab5db0369bfa7e",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "2531cc395d4ced6a637c04f1ab1619dd",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "b2f4c438fc5d7bb524d33db32a8d464d",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "2f5d6341d44b8829dd7f6f1dd2237ef3",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "c27212ba1429be052be892df280bdc70",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "acf39d2dcbeb2bb9768b8299a999e831",
            ["放鬆一下自己疲倦的身心。"] = "cf5c0c6563faca35ab89050ffaff07a3",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "0815aba74c3a70d73e32cc5365b4babf",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "7daf3bd91cab3bbe4b086b50a641371d",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "4d9fe927578f203ba1f939866e8eb07f",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "70c1e67468aaeaa3a549f39f40b0750e",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "5a0c8734a5baf412a3c8a6ea7f840971",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "cc9cfe1577ac40fdf30626ca38853f4c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d23384c474fd5420239b53802a4cb878",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "355f0eaf3e41bbd9ac2b4927dd3ae00d",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "465cf8b7ffede50d2c9d078908c27ebf",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "81a3af904e5e838f33cd0c337609ca1e",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "febd2c30f0ceec03812a46456d34b870",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "cec5376f55346bfe3dc2c2cc3e7250df",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "35f023a0322674670e5742c64f6dde74",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "918ba333b33ba169bd8203f33cbfdeb1",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2bd1ba7a047b7f12cd181339448588cc",
            ["諾姆瑞根在丹莫洛的西邊。"] = "45400c7ff98d6669e16f6f738a544da2",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "ffbcb214f8bde35165c1e81f0262353a",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "a99bd805ffc7f479b01c1f060c183d80",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "990feb669a320e4a8ee851b5411d8ac2",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "95e0ef5ee5d277942310d2636ab0068b",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "14d2c5e49f0b36f12cb7480a8300476a",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "f3796e44c383e2f2dab079058435a9e6",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "e8cfd96680fc3ab29c2ca67c5e6131f3",
        },
        [2389] = {
            ["你想要飛往什麼地方？"] = "99afa7bbff40b3ecca37eb15b8c29387",
        },
        [2391] = {
            ["別浪費我時間。我從事研究的時間比你的年紀還要大。去跟幽暗城煉金房的亡靈馬丁·費爾本談談。他或許能傳授給你一些基礎知識。"] = "edb3fbffc27addc3693160ddb35ad2b3",
            ["又來打擾我了。像這樣我還能做什麼工作麼？不用回答，我看起來像是很在乎你的回答麼？為什麼不去煩別人呢？"] = "24a9f0ae55336ce04597528b79ab3c41",
            ["另一名學生。棒極了。這就是林度恩躋身皇家學會從事研究工作的原因，也是我堅持成為一名導師的原因。只要我再獲得一枚教學獎章，我的美名便不會被人所遺忘了。"] = "47491c60fb41002c8b53ee55a847cbc9",
            ["要我訓練你？別開玩笑了——我們都知道這是不可能的。我可無法勝任。你要是想接受訓練的話，就去幽暗城的煉金房找亡靈赫伯特·哈爾希醫生吧。"] = "5b3ba56ab8ce8049d84d48d66345c69c",
        },
        [2393] = {
            ["我可以給你看看我賣的東西嗎？"] = "4dac483e83b8c86599de11ca55258b2c",
        },
        [2399] = {
            ["你在縫紉藝術方面做得很好，我必須承認。現在，讓我們看看你到底有多棒……"] = "a76e41885008445eb4f1436b07ccf3ee",
            ["誰派你來的？你還沒有準備好接受我的指令！當你們準備好以後會得到通知的。"] = "6628421bf475ed47d8d51a305f80ce4b",
            ["這地方通風良好……但是我還在乎什麼？我已經死了。"] = "63cdedde8533ba7dc21f076eea1338a3",
        },
        [2409] = {
            ["你想要飛往什麼地方？"] = "f6ea55ad6f6344693225294350de4559",
        },
        [2432] = {
            ["你想要飛往什麼地方？"] = "f6ea55ad6f6344693225294350de4559",
        },
        [2455] = {
            ["歡迎來到暴風城銀行。我們竭誠為您提供最優質的服務，包括金融帳戶和絕對安全的儲物箱。$g先生:女士;，您是否已經擁有了本銀行的帳戶呢？"] = "1cf62073cd912caabcc1fd6d29dd3aa6",
            ["沒有人能夠從這裡偷走東西。從來沒有人……從來！"] = "8aebd1628c8cd2becdb32845edc4fbe8",
        },
        [2456] = {
            ["歡迎來到暴風城銀行。我們竭誠為您提供最優質的服務，包括金融帳戶和絕對安全的儲物箱。$g先生:女士;，您是否已經擁有了本銀行的帳戶呢？"] = "884e826914eac49c2ac85af2e236b022",
