        },
        [2485] = {
            ["作為一個法師，你是極少數可以操縱傳送門魔法來幫助你回到這裡的$r之一。如果你準備好了，我現在就可以教你。"] = "c0b64230899c1f169032e2124bab7479",
            ["我不認為你具有掌握傳送門魔法所必需的潛質。"] = "6169b63082c1481ee1b292a6bd277450",
        },
        [2489] = {
            ["作為一名法師，你是少數可以召喚傳送門返回這個地方的$r。如果你已經準備就緒，我就可以教你這種法術。"] = "f69b2a52cbd83a17600754efeeae8fbe",
            ["我不認為你具有掌握傳送門魔法所必需的潛質。"] = "a53aefa25ac89a757bcbfc41b3fc84f0",
        },
        [2492] = {
            ["作為一名法師，你是少數可以召喚傳送門返回這個地方的$r。如果你已經準備就緒，我就可以教你這種法術。"] = "3de4dfc277400108c32e9317af807f3a",
            ["我不認為你具有掌握傳送門魔法所必需的潛質。"] = "94b6577e5651410a517d8b6494716ade",
        },
        [2496] = {
            ["歡迎來到寶藏海灣，夥伴。希望你在這兒度過一段快樂平靜的日子 - 重點在後者。如果你口渴的話，我們這兒有很多飲料；如果你擔心受怕的話，我們這兒還有很多保鏢。$B$B現在……我這個熱砂港卑微的僕人能為你做什麼呢？這麼說好了 - 你又能為我做些什麼呢，嗯？"] = "a122cd69a20b3e81ab38fa94be544fd8",
        },
        [2627] = {
            ["他們說小洞不補大洞……什麼來著？啊，我記不得了。反正是愚蠢的說法。"] = "4695d885c5423f51c542ad1df66c86b0",
            ["嗯，嗯，還不壞。或許我能讓你看點什麼……"] = "86645eb4b7a73026276b0f113606af33",
            ["對一個業餘者來說……這還行！你的知識量已經跟我持平了。要是你想學習更多知識，就去幽暗城找喬瑟夫·格里高利談談。"] = "379c74fd86ed0bbf02d5ee95a1c7479c",
            ["是的，你知道一些事情！如果你想學會更多的話就必須與暴風城的喬吉奧·波利羅談談。"] = "bcf239bdb85060a4bc12b087536a094e",
        },
        [2670] = {
            ["啊，我最喜愛的顧客之一。你似乎是個有能力的術士，$N。很高興認識你。要是我能幫上什麼忙，請儘管開口。$B$B我和我的兄弟都認為你這樣的人才能領導我們進入新紀元。一個擁有力量……和控制力的人……讓軍團臣服於你只是時間問題。$B$B我有些羡慕你了。"] = "dfd92d7ff973be700d5eaab3126b732b",
            ["歡迎來到我的商店，$c。古斯提兄弟能為你做什麼嗎？"] = "99c06dc6ce2b538a25922d66ed241e64",
        },
        [2704] = {
            ["嗨。你到這兒來學習如何使用新武器算是來對地方啦。"] = "cc3e350a79b20307088a569e80902909",
            ["居住在雷霆崖低處山峰的牛頭人武器管理人安塞瓦可以教你使用單手錘、雙手錘、棍和槍。  居住在幽暗城戰爭區的亡靈武器管理人阿基巴德可以教你使用十字弩、匕首、單手劍、雙手劍和長柄武器。  居住在這兒的相貌醜陋的獸人塞尤克可以教你使用弓箭、匕首、拳頭武器、單手斧、雙手斧和投擲武器。"] = "00786fcaef5b82cb1cc4964e5ab1ea1a",
        },
        [2788] = {
            ["你好，$N。歡迎來到避難谷地。"] = "9c5dca74ac7c977fa3de9d8d739f8773",
            ["別擔心斯奎爾圖，$N。他不想這麼粗魯的，他只是非常繁忙。我們不如趁著等他完成偵察任務的時候做些更有用的事情？"] = "2a934c9aeb08dec90a0d0e7b99a9e8d0",
        },
        [2798] = {
            ["塵泥沼澤蕨牆村的格魯克卡恩在賣指南書，你需要好好研究它來提高自己的技能！"] = "b1a4bc076a7a69d393730100ba28a6d7",
            ["我可以訓練你急救技能。"] = "0a7cfd25fd53892de58e9eaf21bc1e16",
            ["現在，只有有名的格里高利·維克托醫生能提高你的技能啦。你可以在落錘鎮的阿拉希高地找到他。"] = "9cf8ec329c7dba4ed49715a51df03f95",
        },
        [2804] = {
            ["你是來幫助我們在戰歌峽谷作戰的嗎？為了部落，$c！"] = "61dae5f4ed0e4cb3f60d344587e21b7c",
            ["很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。"] = "7fe3331e4b1c06adee7ab9eb667d175d",
        },
        [2817] = {
            ["你在這荒蕪之地到處遊蕩，一定是因為缺錢花了，$c。一定是像我一樣缺錢。$B$B要麼就是因為你瘋了。瘋了，像我一樣。"] = "9c20efde5f130887d0c129a052780d46",
        },
        [2834] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "0bf837bea513c0c82387777d0998bdfb",
            ["我可以教你一些釣魚技能。"] = "2d127f614bfaf60be0fcf5c914c9f116",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "3bcdd8ed1fc1986116ad0c43c7de1475",
        },
        [2835] = {
            ["你想要飛往什麼地方？"] = "65b6f5b0f34f015f60d92c6c8d6e3d71",
        },
        [2836] = {
            ["什麼？我當然是一個鐵匠。什麼，你認為矮人是打鐵最有效率的種族？好吧，可能是那樣。去找一個矮人來幫你！"] = "29b36a70548ade1ec5054bd5082e4b54",
            ["你是在開玩笑吧？你一定是在開玩笑！你認為我是個取悅於你的小丑，是嗎？我是小丑？嗯，是的！你認為我是小丑，是吧！"] = "939a1307b0cf9e41fb14a7b51a7e6adc",
            ["你表現得像這是我見過最好的垃圾。當然它還過得去，但我每天都看到這類‘還行’的東西。告訴你吧，你若能想辦法讓我叫好，我就會教給你能讓矮人們在睡夢裡都會笑的東西。"] = "0a4352094f4852338fc9624bcf71bd3f",
        },
        [2837] = {
            ["你做得比我要好！你需要一個經驗比我還要多的人。那就是安尼希爾，一個在達納蘇斯工匠區生活的夜精靈女士。"] = "f84b4daad586c1635158e862119c4e33",
            ["你操縱得比我要好！你需要一個經驗比我還要多的人。那就是赫伯特·哈爾希醫生，一個在幽暗城煉金房工作的亡靈。"] = "6ce7cfa7b11912553573a81e9e702be1",
            ["我有許多處方可供選擇，我還可以為你打折！"] = "0bd8140cb84691dca36c53f2d79843eb",
            ["格里克斯和我達成一項共識：他給我供貨，而我給他錢。這是很認真的！那個海盜為了一小袋皺皺巴巴的皇血草收我多少錢……足夠把一個成年的哥布林弄哭了。"] = "e56ab09499777010cc558c0dd0ece4c2",
        },
        [2851] = {
            ["你想要飛往什麼地方？"] = "0edd3c73540d735f036ac6e027466523",
        },
        [2855] = {
            ["我們使用動物皮毛製作物品。"] = "414eb2110800e49fbeef5b9e23f4a1e9",
            ["我會將我所知道的傳授給你的。"] = "011f710eb536c93c6af1ca4daa89c86b",
            ["我知道一些，但我不是專家。祝你好遠，瑪加爾也是。他就站在商店後面。看看他是否能幫助你，但是小心別惹惱他。他脾氣有些暴躁。"] = "ff0d7b4773f6d4aaa94d74340ab3d2c4",
        },
        [2857] = {
            ["你知道誰是真正聰明的人嗎？諾格！甚至比我還要聰明。你去告訴諾格是桑德派你來的！你可以在那邊的控制台那裡找到他。"] = "c0e4ed9720381722eb52b7670182508e",
            ["你認為你很聰明嗎？你認為你得到了嗎？讓我們查明真相！"] = "421cebf2dd4b84c010b52de939feef56",
            ["誰說獸人不聰明？當工程師很費腦筋的！"] = "ffe9f497233899e162f84eafcbd6d0d3",
        },
        [2858] = {
            ["我要如何效勞？"] = "28118fefcc53acdaddf2117a97b1e13a",
        },
        [2859] = {
            ["鷹巢山這邊最快的獅鷲獸了。想乘坐嗎？"] = "9a496e2e710165d755663d0d9ae15ef8",
        },
        [2861] = {
            ["你想要飛往什麼地方？"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [2878] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "12e2351404174f85aa98fa3a3524bcd0",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "b439ced1ada35971e9ff2706f428bff0",
        },
        [2879] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "12e2351404174f85aa98fa3a3524bcd0",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "b439ced1ada35971e9ff2706f428bff0",
        },
        [2916] = {
            ["歡迎來到探險者聯盟。如果你需要書面資訊的話，我也許能幫你。"] = "d0ef52056e69de8890c17a16c8e0a5ac",
        },
        [2941] = {
            ["不管我是不是瑟銀兄弟會的，只要有個黑鐵矮人敢靠近我，我一定會讓他們嘗嘗我鎚頭的利害！現在，我可以送你去哪裡，$g小夥子:小姑娘;？"] = "f38b9f9eeca159b5ac1ef5dcae9ffdb8",
        },
        [2943] = {
            ["你好，$C。看來你最近在進行一項秘密的收集工作？你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段代碼。把代碼告訴我，我就會給你一份特殊的獎勵作為回報。"] = "c5afae87abc614718a9d01193dc59430",
        },
        [2980] = {
            ["你好，$N，歡迎來到納拉其營地。關於你來到的消息很快就在部落傳開了。"] = "20e50f7907859f3c67714458b3ebf738",
        },
        [2995] = {
            ["當坐在一頭雙足飛龍背上時，你就會發現它的力量和速度的確不是徒有虛名。"] = "162e14a98f2a88c099856abef92342b8",
        },
        [2998] = {
            ["你似乎正在尋求知識。也許你在找尋鍛造之道，也許我能在這條道路上指引你。但是一旦你決定從事鐵匠這個職業，你就應該學會聆聽鋼鐵中的那些靈魂的呼喊。"] = "b0b47cf8dcffc971f677db7811e6e84d",
        },
        [3004] = {
            ["你真是一個意志堅定的學生。我很高興給你提供指導！"] = "c71201046e02402ce3ccad5ac9788d94",
            ["在我幫你之前你必須學會一些基礎的東西。與我的徒弟范恩談談。他很耐心而且願意教你所需的知識。"] = "b3710bc3fd8b71a4f79dd71616deb9a4",
            ["我的知識有限，儘管我還在繼續學習。現在該你繼續了，旅行者。在幽暗城找到喬瑟夫·格里高利並告訴他你準備好了。"] = "3def2f3bfaf2254698c9601afcf6a534",
            ["這些圖案難道不漂亮嗎？每一個都有自己的風格。"] = "885c5bf0a97c2817b7251f03b18168e6",
        },
        [3007] = {
            ["凱恩把我們帶到了一片充滿希望的大地。我們很幸運，因此我們再把好運帶給別人。這就是我為什麼開始教學的原因，$n。"] = "c15b86c60ca6a98e65a1d56247b8f0fb",
            ["我的才能有限，你也已經達到了。恭喜你，$N。你的下一站應該是菲拉斯的莫沙徹營地。牛頭人哈拉納·鐵皮住在那裡；她的技術很有聲望。"] = "2cc85bf48153fefcf85050d745cf9fc8",
            ["我自己不久前也是一個新手，所以我覺得我不太適合教你。試著跟那邊的塔恩或是瑪克談談。他們之中應該有人能回答你的問題。"] = "e97320918e69f72e3bb5d9b77997f0f0",
            ["針太細，線太粗，針腳倒還不錯。我們與索爾和其他人的合約將繼續有效。部落不會被驅逐出這片土地的。"] = "bff6354587177ea12e5e19d6fb616689",
        },
        [3008] = {
            ["你的智慧勝於我，朋友。與這裡的塔恩談話；他對皮革的知識比我要豐富得多。我肯定他會歡迎新學生的。"] = "edf5f8de4140afd1bce34fd502315c9b",
            ["凱恩自己住這兒，他們說。一旦我完成了製作一件合適的禮物，我就會把他找出來。或許他會有智慧的話要對我說。"] = "a1adc9308232c8c0f4e71953e5b803bf",
            ["在你開始任何工作之前都要洗淨雙手。皮革被血或塵土玷污了會帶走它的自然美。"] = "9bcfa971f468ee6490afd446429c6d90",
        },
        [3009] = {
            ["你製造藥劑的技術已經在我之上。去幽暗城的煉金房找亡靈赫伯特·哈爾希醫生。他可以繼續你的訓練，而你也可以親眼目睹他的人民所遭受的苦難。"] = "fceb9cd6f78850904dc17716526c631c",
            ["你難道感覺不到大地之母為了她所丟失的孩子，也就是亡靈們，而出現的苦惱嗎？快些說，$N。每一秒對我都很珍貴。我們必須幫他們找到回歸她身邊的路！"] = "58a07ba5d668196689ecb253dea303f8",
            ["當我們的盟友，也就是亡靈們，在遭受可怕苦難時候，我如果還在這裡訓練新手，這會讓我感到良心不安。請找那邊的克瑞談談；他目前能夠幫你。"] = "8499a42fa2ab8897c99ee43a121f6abc",
            ["第一次看見亡靈時，我哭了，我無法想像他們的恐懼和孤寂。大地之母在我耳邊吟唱，她告訴我：「拯救他們吧。」"] = "7ce695ef7f2710c9d9137cd9cc2d2a20",
        },
        [3011] = {
            ["啊，很好。你是個優秀的學生，我對你非常滿意。現在，我們開始訓練吧？"] = "e14bb275961fa9b3f9f8cc7b5eb43400",
            ["我的家族數代都從事附魔工作。我在很小的時候就學會了這項技能，就像我兒子現在在做的一樣。"] = "0c0d9f103197b5c72b584118ac04a7e9",
            ["明顯莫特並沒有派你到我這兒來。他知道得很清楚。你還無法理解我能傳授給你的知識。去外面找我的兒子莫特，他會對你進行訓練的。"] = "b0597ee74d61de5231baccb71303394d",
            ["赫加斯掌握的知識遠勝於我。你得去石爪山脈的太陽石居所找他，繼續訓練。"] = "9d6c63af01c654fc15d4e6f51b04ef89",
        },
        [3026] = {
            ["加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。"] = "0ed954dd02d4a7694fc374f6df8dc387",
            ["我可以教你如何烹飪！"] = "de1872cd5c5303ee685544d18a1c6b9d",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "f4ecc692c98606d458fb7c830b10e27c",
            ["葬影村的烏蘭可以賣給你「高級烹飪教材」。如果你想要提高烹飪技能的話，就需要這本書。"] = "781459db7da362b3fa5744abdcd013b1",
        },
        [3028] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "85322120ed7dcca1297d4aab61c178ea",
            ["我可以教你一些釣魚技能。"] = "40d6df5ee6a68543af15fab16ad8ee8e",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "3754efa5bf514e289af226829e49e360",
        },
