        [3052] = {
            ["你殺了鬼嚎。你這個傻瓜！"] = "924b1b0c6fc974b7903fe962433db58f",
            ["年輕的$c，靠近一點。我年輕的時候耳朵可好使了，但現在你必須大聲說話我才能聽到。"] = "6ab9eb0622e9b06ba41a8dd0ee7e3b47",
            ["我在這片平原上生活了很多很多年，我捕獵過許多兇猛的野獸，從來沒有失敗過……直到我遇見了鬼嚎。$B$B很久以前，這只巨狼曾經是牛頭人的盟友，還和燃燒軍團英勇作戰。不過後來它被一個惡魔所傷，身上的傷口一直沒有治癒。最後……這道傷口把它逼瘋了。$B$B現在它總是痛苦地在平原上遊蕩，尋找終止它的痛苦的方法。我很慚愧，因為我無力把他殺掉……"] = "d9799a53b63bce336c76cf88c68e6cfc",
        },
        [3057] = {
            ["啊，毫無疑問，他一定是想要成為一名戰士！我想你是來參加兒童週的，是嗎？你的行為堪稱楷模，其他人必定會以你為榜樣的，這令那些疲憊不堪的靈魂倍感欣慰。$B$B我很樂意幫助你和這位年輕的男子。嗯……我要給他提些什麼建議呢？聽聽靈魂怎麼說吧，是的……或許是關於吃掉所有蔬菜……"] = "b7a8229dca2676591932185ee439b12b",
            ["年輕人，歡迎你來到雷霆崖。在這兒你能卸下負擔，享受庇佑。我們歡迎所有的部落居民來到雷霆崖。$B$B我的朋友，靈魂都會來這個神聖的地方復活。尊敬他們吧，這也是尊敬你自己。"] = "6a6507689e26d6a64d8cd2d70050e9b6",
        },
