        [3064] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "0ad2a902852beef6cfe7ead6b6979fff",
            ["我們的工作就是保持平衡，如同塞納留斯所教給我們的一樣，$c。他就是指引我們前進的明燈，而我們必須竭盡所能保護它的光芒。"] = "4346d3d89406f259d67b448273c50839",
            ["歡迎你，我的$g兄弟:姐妹;。如果你是來接受訓練的，那我很高興能訓練你。$B$B如塞納留斯教導我們的一樣，我們一直都是平衡的保護者。永遠不要忘記這點。"] = "63bd6c629838bc3014277633d29e8dd1",
        },
        [3065] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "9ccfbeb35c89e4770c3695a5c842eef7",
            ["我不具備你想學的知識。"] = "85e3aafdd07b5fa9e4eeb2daf1cd053a",
            ["牛頭人熱衷於狩獵，這是流淌在我們血液中的靈魂。"] = "55a66d0b8af1c06325804f95e63b73a9",
        },
        [3066] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "9ccfbeb35c89e4770c3695a5c842eef7",
            ["靈魂引導你來到我這兒。我要怎麼幫你？"] = "d96f407d05286ba207ff46bf75ef4510",
            ["願靈魂與你同在。"] = "1eec7529a102737979dbaf19908f6ac0",
        },
        [3067] = {
            ["加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。"] = "74007003c2cd2bd77e1c3e8b0496a254",
            ["我可以教你如何烹飪！"] = "70f65371057af31cdb1fa7f511b011d1",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "aa33a0b2e8a8965bb6b87437e70b467c",
            ["葬影村的烏蘭可以賣給你「高級烹飪教材」。如果你想要提高烹飪技能的話，就需要這本書。"] = "3c198949d138d51ba2c086ace10803eb",
        },
        [3069] = {
            ["我們在此繁衍生息，生生死死，數年來大地卻亙古不動。因此，這片土地並不屬於我們，$n。我們是屬於大地的。因此，我們守護著它，沒有它我們就無法生存。"] = "9802c328fee5a83bc01704102bf807c7",
            ["我已經沒什麼可教你了。帶著大地之母的祝福離開吧。在雷霆崖的中央高原西北方的商店找到牛頭人塔恩。願你得到他智慧的指引。"] = "e5c3faa7754d65e972344cb259b1aec1",
            ["肉、獸皮、骨頭……好的獵人是不會浪費任何東西的。每塊獸皮都有利用價值，也許能用來增強盟友的武器裝備。單獨來看，我們每個人都很強大，但是團結在一起我們就無敵了。"] = "f13238d0343549166ee185d5c7b13512",
        },
        [3084] = {
            ["一個志趣相投的團體可以成為一支非常強大的力量。克拉姆會幫助你們達到這個目的。你可以在雷霆崖電梯旁邊中部高地的底層的公民資訊中心找到他。"] = "7428818296fb57ab2ba6a762f2e0d2d1",
            ["你可以到中部高地的底層的雷霆崖銀行存放你的財物。"] = "bb2889c7bfa57a143417bd9b1f197fc1",
            ["你可以在中心高地上找到雷霆崖銀行。"] = "625203147fa733c66de63ce3f3252013",
            ["你在找什麼？"] = "b3d11178772212cc804676804bb92ca1",
            ["你好尊貴的客人。圖拉克·符文圖騰和其餘的德魯伊正在長者高地上的長者大廳等你。"] = "5756887f0cd1cbab07deea21bfd1aeb8",
            ["你對自己的寵物夥伴表現出的關愛之情是值得讚揚的。矮山上的布林魯格能幫助你照看寵物。他居住在銀行和旅館之間的地方，去找他吧。"] = "d7325e94b3d82c25fc436cfe7d51f3f0",
            ["你想知道如何用鐵砧和錘子製作東西嗎？卡恩·石蹄可以教你這些。他是個鐵匠，就在中部高地的水池旁。"] = "b3ac26184e7b679b5f3a5fd050ceed51",
            ["你想要加入哪個戰場？"] = "1d738815ffbfa1178b5cebf27d5e3cf0",
            ["你想要幫助阿拉希盆地的污染者打敗阿拉索聯軍嗎？很好，去預見之池找馬丁·林塞尋求幫助吧。"] = "da5ea3194230fd515aa40fc906d898ab",
            ["你想要找什麼？"] = "b3d11178772212cc804676804bb92ca1",
            ["你應該找柯布神父談談，到靈魂高地下的預見之池去找他吧。"] = "764977ab49461a0e2f73e5c89e64d7bb",
            ["你是魔法的研習者？嗯，好吧……你可以在靈魂高地下的預見之池中找到他們。"] = "337db40ce448a7dc218d2910d441596a",
            ["你沒有浪費那些你必須殺死的動物，因此你賜予了這些動物的靈魂以榮譽。阿絲卡·迷霧行者將會給你演示怎麼處理。她在高地上有個廚房。"] = "9e2f8a46117e84f56a1520a66a6bde35",
            ["你能在中部高地的底層的雷霆崖銀行外面找到一個郵筒。"] = "0be0166409128e852e0cf07097c3b1cc",
            ["你要找什麼技能的訓練師？"] = "c5fec459a17d0b54dc8cfb9f0c9066ae",
            ["你要找哪一類型的訓練師？"] = "c5fec459a17d0b54dc8cfb9f0c9066ae",
            ["你要找的一定就是泰姆·狂暴圖騰。去獵人高地找他。"] = "b26bc8fc22a99ad20945a9589f5b955d",
            ["你需要布林魯格的幫助。他在旅館和雷霆崖銀行間較低的山上。"] = "5249bd4ce3fc5b36c84b65c6cdbaac96",
            ["充分利用每塊碎片會讓我們更加節約並會拉近我們和大地之母的距離。莫蘭塔會教給你方法。到中部高地上的雷霆崖兵器庫外面可以找到她。"] = "1697153761e0b67c57f1cdd4dc2f2c12",
            ["利用敵人的獸皮來保護自己這一想法運用了擬態學的知識。要進一步提高製皮技能，你得去雷霆崖防具店找庫納。"] = "a1d048a682603a6da0676d45f85019cb",
            ["到中部高地的「貝娜的煉金店」去找貝娜，她可以指導你學習配製藥劑的方法。"] = "9c3a8733672857571a79608e45334e15",
            ["到中部高地的附魔店去看看吧。泰戈會很樂意幫助你的。"] = "9daecfcdaaa5812a8e8e882f46b515a2",
            ["動物的朋友就是我的朋友。你要找的獵人大廳就在獵人高地的頂部。"] = "cd34633c29559796c6ebc619f7cdc14a",
            ["去中部高地的底層的雷霆崖銀行以南的建築物中可以找到旅店老闆帕拉。"] = "8f087943366a3acf764b32af4c3ded23",
            ["去中部高地的石蹄地質學會找布瑞克·石蹄，他會教你如何採集礦石和寶石。"] = "ab35cc7d314a40c2e9345c2f6bd27c2f",
            ["去找克拉姆吧。你可以在中心高地上的雷霆崖諮詢處裡找到他。"] = "0c6cb2a334460da852eecdbb7a3eb5c1",
            ["去長者高地的長者大廳找圖拉克·符文圖騰吧。"] = "f32f1f8317df644d79d3324fc75752ef",
            ["去雷霆崖中部高地的雷霆崖防具店找猶納吧。"] = "3ae20e97dad81c4d151a6d8c0b8448c7",
            ["去靈魂高地下面的預見之池找馬丁·林塞。他會幫助你前往阿拉希盆地。"] = "3de798b62a6a7c9477fb4ead6227ff5c",
            ["和其他所有事物一樣，金屬應該被平衡的使用。卡恩·石蹄在中部高地的底層的池塘邊設立了一處鐵匠鋪。去尋求他的指引吧。"] = "e6ee92e9034e719f370e30f576c15eda",
            ["哪一項專業？"] = "4a850dc32d00c265e503622c595cebf4",
            ["啊，你是在找安塞瓦。去雷霆崖武器店中部高地的底層找他吧。"] = "1289a558c033b0924050a149cd96fe87",
            ["啊，和天空中的巨鳥一同翱翔。去雙足飛龍巢穴頂端找塔爾吧。他會指引你完成你的夢想的。"] = "a71221b80997e8993fe99d8f65940c87",
            ["啊，那你就要去獵人高地上的獵手大廳了。你可以在那裡找到像浩特·雷角那樣偉大的獵人。"] = "ec41eb4745bf50e326e8e13f25e45b8f",
            ["在武器使用方面，沒有人能勝過安塞瓦了。據說他接受過我們尊敬的祖先，最偉大的戰士的靈魂的指導。去中部高地的底層尋找他，他會教你的。"] = "4113d427578d33dd0d7cc5960d9e551b",
            ["在雷霆崖，你肯定找不到比阿絲卡·迷霧行者更好的廚師。嗯……我在這裡都可以聞到他正在烹製的美味佳餚。你可以在中部高地的廚房裡找到她。  呃……我又餓了。"] = "f62291a619a18dcacc69b5f64e8dc599",
            ["坦帕以她製作的衣物而聞名，你可以在中部高地的雷霆崖防具店找到她。"] = "2a0854c8bb2974724fa986a879759c63",
            ["大地之母有許多秘密，布瑞克·石蹄能幫助你發現一些秘密。你會在 石蹄地質學會的中部高地的底層那找到他的。"] = "9c03014605b27c25c059f0223bc21ad6",
            ["大地之母發出召喚，你得做出應答。你可以在靈魂高地找到靈魂大廳。"] = "dfd2bbc7b4882c8ae2435868f54dce8f",
            ["好好利用自然界的草藥，它會成為你有力的助手的。去貝娜的煉金店找她吧，接受更多訓練。"] = "599c6d8be27d0c47d6ed586b58d5e540",
            ["如果你想要學習草藥學的話，就應該去找克米恩·冰蹄談談。他在中部高地那裡。"] = "83473bcdaf1b33eec50ef89c07b8748c",
            ["它就在雷霆崖下方，在銀行附近找一找吧，離這兒不遠。"] = "959837cc6b3520206fd7ffcd50a3fc7a",
            ["山頂漁具店的卡爾·迷霧行者將為你指明如何實現內心平靜的同時還能通過釣魚為自己準備好下一餐。"] = "c00a4b671e155d6fa7a2d4aa63e871fb",
            ["強壯的身體和精神。沒有比這更強大的組合了！去獵人大廳跟薩爾克·狂暴圖騰找尋自己的命運吧。"] = "9f80018ebca95bca3d012c9885917333",
            ["急救是一項很有用的技能。在戰鬥中，它常常能救人一命。如果你想要學習這項技能的話，就去靈魂高地的「精神治療」小店裡面找找潘德·縛石，他可是這方面最好的訓練師。"] = "404195be7635731d800fe49c72496fde",
            ["想到這些可憐的亡靈靈魂的遭遇，我感到非常悲傷。你可以去靈魂高地之下的預見之池附近找大法師山姆。"] = "625f49a102fa08e5850ceb7e193dfaaf",
            ["想要加入我們的行列？薩爾克·狂暴圖騰可以指引你，他就在獵手大廳裡。"] = "da0f47520f4f0e59ff8825cae6d258b6",
            ["我不會因為你想學釣魚而責怪你的。莫高雷有卡林多大陸上最好的釣魚勝地，而在山頂漁具店中，你可以找到釣魚所需的一切裝備。  告訴卡爾·迷霧行者是我讓你去的！"] = "fedcf5e7226755c1e4b423ea45d0b484",
            ["我知道在雷霆崖有人可以幫助你進入奧特蘭克山谷。去獵人高地找泰姆·狂暴圖騰。希望你找到你在找的人，$n。"] = "32652d64d7ec3c956ec22966227d3aad",
            ["我記得不久之前我有新郵件寄出。你可以在中部高地的底層雷霆崖銀行外找到郵箱。"] = "4953668f5dcca129474b758d1d23b145",
            ["拍賣場位於雷霆崖的中央尖塔，在雙足飛龍塔下方附近找找吧。願你的祖先保佑你。"] = "a4a9ad83a2b44afa7328bfec39dea3c7",
            ["旅店老闆帕拉能幫助你得到身心的休息。他就在中部高地的底層的雷霆崖銀行以南的建築物中。"] = "a76e86e6fc61fee2e4a3508cf1d715f5",
            ["獵人大廳的克古爾·血斧將會幫助你進入戰歌峽谷。"] = "8dd5ae8dd52efbfbadf578cc9ba63982",
            ["生活是一場競爭，「大難不死必有後福」這句俗語並不是始終正確的。有時傷口癒合得很慢，這就是我們需要綁帶的原因。靈魂高地的潘德·縛石能教你急救的技能。"] = "4d9ce77b1fd1d043523dd81e104c633b",
            ["真是無謂的攻擊，但是如果銀翼要塞的傢伙不想要和我們和平相處的話，那麼他們還能留給我們什麼？去獵人大廳找克古爾·血斧，他將會幫助你進入戰歌峽谷。"] = "7b590df5fa47f42b00a668a61d2d41b9",
            ["給部落做衣服與其餘的工作同樣重要。你該到雷霆崖防具店裡面尋找坦帕。她對針線活有自己的天賦。"] = "63954ad79a181f4bdebcb1e87ea78d14",
            ["自然會提供我們所需的一切。跟中部高地中層克米恩·冰蹄談談草藥學吧。"] = "0e3a1c24f70f1c359a96057de011b71d",
            ["莫蘭塔可以教你如何剝皮。你可以在中部高地的卡恩鐵匠鋪旁找到她。"] = "e7af07864db4b2551b191f075ac7869a",
            ["附魔體現了毀滅和新生的迴圈，這正是自然界的基本準則。晨行者附魔師將為你展示這一切。"] = "c88c9780cf6c0a23744737daab1c43fe",
            ["雖然亡靈受到重創，但是他們還是趕來幫助我們。我只希望我們也能對他們有所幫助。去靈魂高地下麵的預見之池附近尋找柯布神父。"] = "90d649ee3e1d08c27a8665c6bdeff359",
            ["雙足飛龍巢穴就在城鎮中心的圖騰柱頂部。"] = "16b85a7fda02544a6b24467f4130d30f",
            ["靈魂大廳是薩滿的家園，它坐落在靈魂高地上。願你的先祖保佑你。"] = "26cdb9ef81f934c56123ecd5f8f82223",
        },
        [3087] = {
            ["加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。"] = "d25a7e0932a93ba447d43caf3968c467",
            ["去銀風避難所找珊蒂瑞亞吧。她可以賣給你「高級烹飪教材」。"] = "efa6e9ddc589d11d0aeee639e21deb43",
            ["我可以教你如何烹飪！"] = "1e74135d166c75a3fff7f83d3426831e",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "9894fe017afd5c82d452ec8f283f45f3",
        },
        [3136] = {
            ["不要那樣從陰暗中走出來。下次你要先給女生一點警示。"] = "1fe2c17c84497dfe5eedaab4db4f4385",
            ["自從陰影佔據了暮色森林我就一直無法入睡。我總是被風中傳來的可怕尖叫聲驚醒。那聽起來好像羔羊的叫聲，而且聲音從不會停止。"] = "87e8317d1f6872386f47da8545ea8768",
        },
        [3143] = {
            ["試煉谷能將最軟弱的新兵鍛煉成一名合格的部落戰士。無法通過試煉者將被拋棄，獨自忍受驕陽的煎烤。"] = "bf70aae4154725dec8a65fa84ba0d954",
        },
        [3144] = {
            ["<伊崔格笑了。>$B$B年輕人，世界不總是這麼混亂不堪的。那只是天譴軍團籠罩大地前的一段時間。在羅德隆的那些地方在成為瘟疫之地之前。$B$B就是在那裡索爾從死亡之中拯救了我，也是在那裡我加入了新的部落…但是我跑題了。這是另外一個時期的事。是的,另外一個時期……或許…"] = "d1d468798ae21889e9e8e4d685954dd3",
            ["事實上。奈法利安，死亡之翼的子嗣現在正統治著黑石塔。雷德受到龍的支配。$B$B只要你能設法穿過晉升大廳。$B$B<伊崔格歎息著。>$B$B此外，只有受到黑龍尊敬的人才有特權進入。"] = "4351f340dd37cf3042c3470df13089b3",
            ["你好，年輕的$c。"] = "7c980a9713ee9148bd335d78781ea63e",
            ["我想你會的。或許有一天你能將消息傳給我的一個老朋友。我聽說他還在那片森林中。$B$B<伊崔格低下頭，好像在做祈禱。>$B$B雷德，是的……雷德和他的兄弟麥姆統治了黑石塔，與黑鐵矮人經常發生衝突。他們試圖將黑鐵矮人完全趕出城市的上層部分，但是只有在飛龍來到和麥姆死掉之後它才真正實現。"] = "6c5944288c88bc17770c52dcfebe4503",
            ["我走了。我不屬於黑石。不，我的孩子不能白白死去。我不會在雷德這樣無能、熱衷於權利的瘋子手下做事的。$B$B我隱居在壁爐谷附近羅德隆的森林中。"] = "1d803963294928c2845b06bc6528c6a8",
            ["或許吧。年輕人，現在就出發吧。去找酋長，他肯定會樂意知道你的發現的。"] = "6e2fb94314a29ef6b19356b5b26a6a8e",
            ["是的，年輕人，你不需要讓我相信這些事情，酋長和我有很多過去的故事要說。然而你所做的貢獻是眾所周知的。$B$B就象我說的那樣，雷德已經為他的人民找到了新的家園，我也是那些不知疲倦跟隨他的人中的一員。$B$B那一次衝突激起了其他……其他無數的衝突。就是在黑石氏族和黑鐵矮人為了黑石塔的戰鬥中我的兩個兒子被殺害了。就在那時我意識到了我在黑石氏族的日子結束了。"] = "1f202d29690acd4df3f48c1e0c19c225",
            ["雷德，是黑手的兒子，他是黑石氏族的酋長。他是一個十足的惡棍。$B$B當第二次大戰結束時，雷德和他的兄弟麥姆逃往黑石塔要塞避難。雷德正是在那兒宣稱自己為黑石氏族的酋長的。"] = "135df692a98ed33e9a1d293d6f787ec3",
        },
        [3149] = {
            ["我不知道你為什麼想要離開這陽光燦爛的沙灘和藍色晶瑩的水域。這裡就像是天堂。但是不要告訴我的哥哥薩匹塔這些，他整天被困在提里斯法已經夠難過的了。這裡的地精飛艇目的地是奧格瑪，所以你不用擔心得聽他發牢騷。但是如果你到了提里斯法，要留意我的警告並且不要讓他開始抱怨。"] = "ea11609900c4cc9251d7ec133d6d262b",
        },
        [3150] = {
            ["這是用錢能夠建造出的最好最先進的交通工具。什麼？礦道地鐵？地精？聽著，朋友，如果你相信那種廢物的話，我就把荊棘谷中的那尊雕像賣給你。那麼，你到底是要走著去格羅姆高營地，還是乘坐這架精美的飛行機器？你選吧。"] = "e3996fa2197a021a95b58d4b134537dd",
        },
        [3153] = {
            ["你是來接受訓練，還是來浪費一個戰士的時間的？"] = "141f23d07f540e8c7b0ef9335bda601e",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["我不訓練你這樣的$c。在你惹惱我之前找你自己的訓練師吧。"] = "5c32ac92759b0e79eade7dc21f7e569f",
        },
        [3154] = {
            ["嗨，你需要繼續前進，去找$c訓練師。"] = "990d212bc9e694de1969260a75b5fbb0",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "857ea30c7f6e11d987a132b4e84da4dc",
            ["我可以為你效勞嗎?"] = "9e572f75c6a0e8bd86745cd88bcd9126",
        },
        [3155] = {
            ["我不能訓練你。"] = "60044d7f82718835ed805cb5fdc7067b",
            ["碎手氏族將會見證部落的崛起和榮耀，酋長的懦弱不會阻止我們！"] = "5070548a9c45a19ece573bb4b49296f4",
        },
        [3156] = {
            ["你的意志不足以操縱我們控制的軍隊$c。"] = "5a92f47cf481eb3def2615b8693c94fc",
            ["你知道的已經夠危險了，但是對我來說你看起來還需要訓練$n。"] = "f097ab331f582c2d79e805e164a7c169",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [3157] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "28f6b8de934060edb89ab0339b080fcf",
            ["靈魂引導你來到我這兒。我要怎麼幫你？"] = "93ff0e2abb20dcd5c4b04b86b60d8ab3",
            ["願靈魂與你同在。"] = "7be5b41b6547e9fda9b4b9cb85616226",
        },
        [3169] = {
            ["你是來接受訓練，還是來浪費一個戰士的時間的？"] = "141f23d07f540e8c7b0ef9335bda601e",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["我不訓練你這樣的$c。在你惹惱我之前找你自己的訓練師吧。"] = "5c32ac92759b0e79eade7dc21f7e569f",
        },
        [3170] = {
            ["我不能訓練你。"] = "60044d7f82718835ed805cb5fdc7067b",
            ["碎手氏族將會見證部落的崛起和榮耀，酋長的懦弱不會阻止我們！"] = "5070548a9c45a19ece573bb4b49296f4",
        },
        [3171] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["我按照傳統一代代地訓練、指導年輕獵人。"] = "8a5b6aaedb16daf4e6daba6392ce1f16",
        },
        [3172] = {
            ["你的意志不足以操縱我們控制的軍隊$c。"] = "5a92f47cf481eb3def2615b8693c94fc",
            ["你知道的已經夠危險了，但是對我來說你看起來還需要訓練$n。"] = "f097ab331f582c2d79e805e164a7c169",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [3173] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["靈魂引導你來到我這兒。我要怎麼幫你？"] = "7857c55cf19a633dd72142ae5b1f6578",
            ["願靈魂與你同在。"] = "e7a2c0dc7f07afebb450c37adc691ede",
        },
        [3174] = {
            ["我若聽到任何有關水禽的意見, 你將來就必須用管子進食。"] = "dcf73814792bd6614277533502604599",
        },
        [3179] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "43ebea4a5129c29af35af2064eb93951",
            ["我可以教你一些釣魚技能。"] = "b285645e1bdb1be37d7bfdc440534eec",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "13d2af5f294a07ae2cff1bf240fa32c1",
        },
        [3181] = {
            ["倍受尊敬的古斯塔夫·范沃森醫生能進一步訓練你。他就在塞拉摩的兵營裡治療傷兵。"] = "9c8fb9d3a4f7df72d0d9fc92d703fc17",
            ["我可以訓練你急救技能。"] = "7f7be7d9f859827d61dd9fcd5450e23e",
            ["我聽說藏身在激流堡的德尼布·沃克有一本書，這本書一定能幫助你提高急救技能。"] = "c0c9e599067b43084770b8a1fe8ce769",
        },
        [3184] = {
            ["你的問題我都回答不了，$n。你需要與奧格瑪暗巷區的獸人耶爾瑪克談談。他會幫你的。"] = "3ccc9d3982a4f8dde9b5653bc0c2e796",
            ["你看起來像是個喜歡冒險的人。而我，自從我們食人妖來到這裡我就受夠冒險了。現在我每天都是既來之則安之，而且我訓練其他傢伙替我冒險。"] = "2bddeb2204ae9a7ba01d834050d650f4",
            ["準備好接受下一次訓練了嗎？好吧。首先，你得放鬆。隨意攪動藥水就可以了。"] = "d7183ddb231e293b65e81976fe37b4d9",
        },
        [3191] = {
            ["我可以教你如何烹飪！"] = "3c5599de03c8689a7c59e4a9c7e86daa",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "6b8ea29137624c8512925cd734b18e4f",
        },
        [3212] = {
            ["不幸的是，血蹄村中沒人懂得裁縫技能，但是你可以在雷霆崖找到訓練師。出了村子，沿著北面的道路走。乘坐雷霆崖電梯到達頂部，然後問問那兒的守衛，他們會為你指明方向的。"] = "bbf8a87da18419b0d4c795a3f40babb6",
            ["人總是要休息的。在血蹄村的西邊，旅店老闆考烏斯經營著一家很大的旅館，為人們提供休息之所。你去那兒找他吧。"] = "d0fbd1df4ebdde74721d6f5659827225",
            ["你可以在村莊西北角的大帳篷裡找到派爾·沉默行者。他可以教給你你想要的。"] = "a234d4b10d5440d815b7b7172e8e8687",
            ["你可以在血蹄村西北角的大帳篷裡找到姚恩·深刺。"] = "951cf972b72fa8a3afed83790bceb3f0",
            ["你在尋找尤薩恩·靜水。你可以在村子的西面找到他，他就在石牛湖釣魚。"] = "50f0680942e77b17d91b589f7a3a11f1",
            ["你在找什麼？"] = "b3d11178772212cc804676804bb92ca1",
            ["你希望把大地之母的骨頭設計成可以幫助部落的工具。好的，好的。沿著北邊的路走出血蹄村直到一部可以上到雷霆崖頂部的電梯那裡。那裡的守衛可以給你更多幫助。"] = "e150bdb40bb2ad6d87a0d8460847996a",
            ["你想要找什麼？"] = "b3d11178772212cc804676804bb92ca1",
            ["你應該去聽聽根妮亞·符文圖騰的忠告。她在村子東面的大營帳中。"] = "dce81535973ad9064578c7dc07d654a1",
            ["你是說裁縫？嗯。是的，當然。你得去正北方的雷霆崖。沿著村外的道路走。到達雷霆崖底後，乘坐電梯去雷霆崖頂部，跟那兒的守衛談談。"] = "aae10fc784263c4cb468d55cea4fd71e",
            ["你要找什麼技能的訓練師？"] = "c5fec459a17d0b54dc8cfb9f0c9066ae",
            ["你要找哪一類型的訓練師？"] = "c5fec459a17d0b54dc8cfb9f0c9066ae",
            ["克朗·石蹄在村子東南角的訓練圈裡。"] = "14d4e5dc44125fe42705f2ed118e5aed",
            ["去北面的雷霆崖吧，從那兒開始你的旅程，朋友。一旦你到達雷霆崖，那兒的守衛會直接告訴你你要找的東西在哪兒。"] = "7c186bc25b44ca7d456a044d9c8671a4",
            ["只是想想那美味，我就已經垂涎三尺了。派爾·沉默行者是血蹄村最好的廚師。你可以在村子西北角的大營帳裡找到他。"] = "1c9e8d41e271bfa8a081921047868b8c",
            ["只有在天空自由翱翔時，靈魂才能得到真正的解脫。在我們偉大的部落中心雷霆崖就有這樣一塊地方。血蹄村外以北的道路就通往那兒。一旦你乘坐電梯到達高處，就找雷霆崖守衛談談，他會做出進一步的指引。"] = "e3b119cda97abe5ee10979d688350484",
            ["只有在雷霆崖上的神秘之地才能找到這樣的智者。沿著血蹄村北面的道路一直走，直到你來到雷霆崖底的電梯。乘坐電梯到達頂端，詢問雷霆崖守衛，您能獲取到更多的幫助。"] = "360397b474c43b7dcab78b62333d6ac1",
            ["哪一項專業？"] = "4a850dc32d00c265e503622c595cebf4",
            ["啊,是的，剝皮。沒有人比姚恩·深刺還善於運用剝皮刀了。你可以在村莊西北角的大帳篷找到他。"] = "822d9c5197a44204042199ef7be11a36",
            ["啊是的，你必須找到希克瓦。我記得我最後一次見她時她在旅館前面站著。"] = "4e99c32785b303ece538f803ff4fcb96",
            ["啊，你必須去雷霆崖最高處拜訪他們中的一人。沿著血蹄村北面的道路走。雷霆崖底有電梯可達頂部。當你到達那兒時，可以詢問雷霆崖守衛。"] = "9e546e689233ec91191a43a7e36c67f5",
            ["嗯，我覺得你需要到雷霆崖去弄清楚。出了血蹄村沿著公路一直往北走。你會到達雷霆崖的底部。乘電梯到頂部你就可以向雷霆崖的任何一個守衛尋求進一步的幫助。"] = "bd7be540acfdb0455e58364636e73dda",
            ["在北方的雷霆崖，你能學到草藥學。沿著村外的道路走，乘坐雷霆崖電梯到達頂部。那兒的守衛能為你指明方向。"] = "201f3cba26808c32bb7ee62dfa628e09",
            ["在北方的雷霆崖，有一名雙足飛龍管理員。乘坐電梯到達雷霆崖頂部，問問那兒的守衛，他們會為你指明方向的。"] = "b0b81da2b32d5fdbc23302be9744240a",
            ["在大地之母心目中，學習如何與自然融合一體是件榮耀的事兒。如果你想成為一名獵人，你必須去血蹄村北部找雅文·刺鬃。"] = "21ee90ef1c873dcee3c9e57987f0dab4",
            ["在我的家鄉雷霆崖，有一位鐵匠訓練者。如果你想成為一名鐵匠的話，就朝北走，去雷霆崖，然後問問那兒的守衛吧。"] = "302142138778affead2a13087925b7b1",
            ["在血蹄村的東邊，有一座巨大的營帳。納姆·逐星在那兒等著你呢。"] = "460e9ebf106048fdb04f6a2f81157b23",
            ["希克瓦能在你需要的時候幫你照看寵物。去旅館前面找她吧。"] = "38fd4c76a36f825f232997fc50761870",
            ["德魯伊的生活方式跟薩滿相差無幾。根妮亞·符文圖騰正在對此進行研究。去血蹄村東面的大營帳中找她吧。"] = "6c2a1f69d196c4657a53b7c110c61e4c",
            ["我聽說北方的雷霆崖有個礦工訓練師。沿著村外的道路前進，然後乘坐電梯到達山頂。任何一名雷霆崖守衛都能幫助你。"] = "e6cb4ccc587cd2a258b3ded78ae7a3f0",
            ["授人以魚不如授人以漁。尤薩恩·靜水會教你如何釣魚。到石牛湖岸邊的血蹄村尋找他的智慧所在。"] = "a50a61ff9211f062ebc4c78f9fccc5f6",
            ["旅店老闆考烏斯可以滿足你的需求。你可以在村子西邊的屋子中找到他。"] = "07ac0c881242c277b1b4be65bb1bb779",
            ["村子裡可沒這樣的地方，在高高的雷霆崖上應該有。出了血蹄村沿著北面的道路走，乘坐雷霆崖電梯到達頂部，找那兒的守衛談談。願你的祖先保佑你。"] = "c61c8d0a95bbdd9d8df4d9db44c53e73",
            ["村子裡居住著一位名叫納姆·逐星的智者。他能繼續訓練你，使你成為一名真正的薩滿。"] = "af5b82f4f5903c5285a8c966bbd9396d",
            ["查爾·硬皮居住在村子西北角的大帳篷中。他能教你一些製皮的必要知識。"] = "f68fe1ab41731a31f4c94d358440f989",
            ["用大地之母的果實配製藥水來幫助我們進行持久抗爭是一件光榮的行為。如果你想學習配製藥水，就得去北方的雷霆崖。當你到達雷霆崖頂部時，去問問那兒的守衛，他們會給你詳細的指引的。"] = "f53e995a55576c4dc433b9e11460ad87",
            ["當我們使用動物的皮革時我們必須熱愛食物或帶給我們的保護，我們給大地之母以榮譽並尊敬動物。查爾·硬皮會教給你這些事情。你可以在血蹄村西北角的大帳篷找到他。"] = "e1efe823ee30b1c010852c13a53cb700",
            ["維爾拉·幼蹄在村子西邊的房子中進行訓練。"] = "4f5f7ae4d60dbe2bd1bf43b0ad2e8786",
            ["繃帶、抗毒藥品這些東西在草原生活中是不可缺少的必需品。維爾拉·幼蹄能教你如何製作它們。你可以在血蹄村西邊的房子中找到她。"] = "3134d4a4d8b645aeefba37aba15985b7",
            ["要是你想學習草藥學，就必須去雷霆崖。出了血蹄村，沿著北邊的路走，然後乘坐電梯到達山頂。你可以問問雷霆崖的守衛獲取幫助。"] = "52d1b670cce86f12a40bdf74b938d00d",
            ["要是你想成為一名戰士，就得去找克朗·石蹄。你能在村子的東南角找到他，他通常就在那兒訓練學生。"] = "37885a7674244dd6e4cdeec2c68f5685",
            ["雅文·刺鬃在村莊北面等你。他能教你獵人之道。"] = "4c1b626c145d8077c5aa2db55852dcfa",
            ["雖然我們在血蹄村沒有煉金術訓練師，在北面的雷霆崖卻有一位。沿著這條路去那兒，當你到達頂部時再向一位雷霆崖守衛詢問具體方位。"] = "83cd87a9bd04fe41340d47a6a3863fb1",
        },
        [3215] = {
            ["不幸的是，血蹄村中沒人懂得裁縫技能，但是你可以在雷霆崖找到訓練師。出了村子，沿著北面的道路走。乘坐雷霆崖電梯到達頂部，然後問問那兒的守衛，他們會為你指明方向的。"] = "bbf8a87da18419b0d4c795a3f40babb6",
            ["人總是要休息的。在血蹄村的西邊，旅店老闆考烏斯經營著一家很大的旅館，為人們提供休息之所。你去那兒找他吧。"] = "d0fbd1df4ebdde74721d6f5659827225",
            ["你可以在村莊西北角的大帳篷裡找到派爾·沉默行者。他可以教給你你想要的。"] = "a234d4b10d5440d815b7b7172e8e8687",
            ["你可以在血蹄村西北角的大帳篷裡找到姚恩·深刺。"] = "951cf972b72fa8a3afed83790bceb3f0",
            ["你在尋找尤薩恩·靜水。你可以在村子的西面找到他，他就在石牛湖釣魚。"] = "50f0680942e77b17d91b589f7a3a11f1",
            ["你在找什麼？"] = "b3d11178772212cc804676804bb92ca1",
            ["你希望把大地之母的骨頭設計成可以幫助部落的工具。好的，好的。沿著北邊的路走出血蹄村直到一部可以上到雷霆崖頂部的電梯那裡。那裡的守衛可以給你更多幫助。"] = "e150bdb40bb2ad6d87a0d8460847996a",
            ["你想要找什麼？"] = "b3d11178772212cc804676804bb92ca1",
            ["你應該去聽聽根妮亞·符文圖騰的忠告。她在村子東面的大營帳中。"] = "dce81535973ad9064578c7dc07d654a1",
            ["你是說裁縫？嗯。是的，當然。你得去正北方的雷霆崖。沿著村外的道路走。到達雷霆崖底後，乘坐電梯去雷霆崖頂部，跟那兒的守衛談談。"] = "aae10fc784263c4cb468d55cea4fd71e",
            ["你要找什麼技能的訓練師？"] = "c5fec459a17d0b54dc8cfb9f0c9066ae",
            ["你要找哪一類型的訓練師？"] = "c5fec459a17d0b54dc8cfb9f0c9066ae",
            ["克朗·石蹄在村子東南角的訓練圈裡。"] = "14d4e5dc44125fe42705f2ed118e5aed",
            ["去北面的雷霆崖吧，從那兒開始你的旅程，朋友。一旦你到達雷霆崖，那兒的守衛會直接告訴你你要找的東西在哪兒。"] = "7c186bc25b44ca7d456a044d9c8671a4",
            ["只是想想那美味，我就已經垂涎三尺了。派爾·沉默行者是血蹄村最好的廚師。你可以在村子西北角的大營帳裡找到他。"] = "1c9e8d41e271bfa8a081921047868b8c",
            ["只有在天空自由翱翔時，靈魂才能得到真正的解脫。在我們偉大的部落中心雷霆崖就有這樣一塊地方。血蹄村外以北的道路就通往那兒。一旦你乘坐電梯到達高處，就找雷霆崖守衛談談，他會做出進一步的指引。"] = "e3b119cda97abe5ee10979d688350484",
            ["只有在雷霆崖上的神秘之地才能找到這樣的智者。沿著血蹄村北面的道路一直走，直到你來到雷霆崖底的電梯。乘坐電梯到達頂端，詢問雷霆崖守衛，您能獲取到更多的幫助。"] = "360397b474c43b7dcab78b62333d6ac1",
            ["哪一項專業？"] = "4a850dc32d00c265e503622c595cebf4",
            ["啊,是的，剝皮。沒有人比姚恩·深刺還善於運用剝皮刀了。你可以在村莊西北角的大帳篷找到他。"] = "822d9c5197a44204042199ef7be11a36",
            ["啊是的，你必須找到希克瓦。我記得我最後一次見她時她在旅館前面站著。"] = "4e99c32785b303ece538f803ff4fcb96",
            ["啊，你必須去雷霆崖最高處拜訪他們中的一人。沿著血蹄村北面的道路走。雷霆崖底有電梯可達頂部。當你到達那兒時，可以詢問雷霆崖守衛。"] = "9e546e689233ec91191a43a7e36c67f5",
            ["嗯，我覺得你需要到雷霆崖去弄清楚。出了血蹄村沿著公路一直往北走。你會到達雷霆崖的底部。乘電梯到頂部你就可以向雷霆崖的任何一個守衛尋求進一步的幫助。"] = "bd7be540acfdb0455e58364636e73dda",
            ["在北方的雷霆崖，你能學到草藥學。沿著村外的道路走，乘坐雷霆崖電梯到達頂部。那兒的守衛能為你指明方向。"] = "201f3cba26808c32bb7ee62dfa628e09",
            ["在北方的雷霆崖，有一名雙足飛龍管理員。乘坐電梯到達雷霆崖頂部，問問那兒的守衛，他們會為你指明方向的。"] = "b0b81da2b32d5fdbc23302be9744240a",
            ["在大地之母心目中，學習如何與自然融合一體是件榮耀的事兒。如果你想成為一名獵人，你必須去血蹄村北部找雅文·刺鬃。"] = "21ee90ef1c873dcee3c9e57987f0dab4",
            ["在我的家鄉雷霆崖，有一位鐵匠訓練者。如果你想成為一名鐵匠的話，就朝北走，去雷霆崖，然後問問那兒的守衛吧。"] = "302142138778affead2a13087925b7b1",
            ["在血蹄村的東邊，有一座巨大的營帳。納姆·逐星在那兒等著你呢。"] = "460e9ebf106048fdb04f6a2f81157b23",
            ["希克瓦能在你需要的時候幫你照看寵物。去旅館前面找她吧。"] = "38fd4c76a36f825f232997fc50761870",
            ["德魯伊的生活方式跟薩滿相差無幾。根妮亞·符文圖騰正在對此進行研究。去血蹄村東面的大營帳中找她吧。"] = "6c2a1f69d196c4657a53b7c110c61e4c",
            ["我聽說北方的雷霆崖有個礦工訓練師。沿著村外的道路前進，然後乘坐電梯到達山頂。任何一名雷霆崖守衛都能幫助你。"] = "e6cb4ccc587cd2a258b3ded78ae7a3f0",
            ["授人以魚不如授人以漁。尤薩恩·靜水會教你如何釣魚。到石牛湖岸邊的血蹄村尋找他的智慧所在。"] = "a50a61ff9211f062ebc4c78f9fccc5f6",
            ["旅店老闆考烏斯可以滿足你的需求。你可以在村子西邊的屋子中找到他。"] = "07ac0c881242c277b1b4be65bb1bb779",
            ["村子裡可沒這樣的地方，在高高的雷霆崖上應該有。出了血蹄村沿著北面的道路走，乘坐雷霆崖電梯到達頂部，找那兒的守衛談談。願你的祖先保佑你。"] = "c61c8d0a95bbdd9d8df4d9db44c53e73",
            ["村子裡居住著一位名叫納姆·逐星的智者。他能繼續訓練你，使你成為一名真正的薩滿。"] = "af5b82f4f5903c5285a8c966bbd9396d",
            ["查爾·硬皮居住在村子西北角的大帳篷中。他能教你一些製皮的必要知識。"] = "f68fe1ab41731a31f4c94d358440f989",
            ["用大地之母的果實配製藥水來幫助我們進行持久抗爭是一件光榮的行為。如果你想學習配製藥水，就得去北方的雷霆崖。當你到達雷霆崖頂部時，去問問那兒的守衛，他們會給你詳細的指引的。"] = "f53e995a55576c4dc433b9e11460ad87",
            ["當我們使用動物的皮革時我們必須熱愛食物或帶給我們的保護，我們給大地之母以榮譽並尊敬動物。查爾·硬皮會教給你這些事情。你可以在血蹄村西北角的大帳篷找到他。"] = "e1efe823ee30b1c010852c13a53cb700",
            ["維爾拉·幼蹄在村子西邊的房子中進行訓練。"] = "4f5f7ae4d60dbe2bd1bf43b0ad2e8786",
            ["繃帶、抗毒藥品這些東西在草原生活中是不可缺少的必需品。維爾拉·幼蹄能教你如何製作它們。你可以在血蹄村西邊的房子中找到她。"] = "3134d4a4d8b645aeefba37aba15985b7",
            ["要是你想學習草藥學，就必須去雷霆崖。出了血蹄村，沿著北邊的路走，然後乘坐電梯到達山頂。你可以問問雷霆崖的守衛獲取幫助。"] = "52d1b670cce86f12a40bdf74b938d00d",
            ["要是你想成為一名戰士，就得去找克朗·石蹄。你能在村子的東南角找到他，他通常就在那兒訓練學生。"] = "37885a7674244dd6e4cdeec2c68f5685",
            ["雅文·刺鬃在村莊北面等你。他能教你獵人之道。"] = "4c1b626c145d8077c5aa2db55852dcfa",
            ["雖然我們在血蹄村沒有煉金術訓練師，在北面的雷霆崖卻有一位。沿著這條路去那兒，當你到達頂部時再向一位雷霆崖守衛詢問具體方位。"] = "83cd87a9bd04fe41340d47a6a3863fb1",
        },
        [3216] = {
            ["你要仔細聽好了，別輕易相信或懷疑你所聽到的一切。因為即使是朋友也可能將自己送上死路，$c。$B$B我們偉大的酋長深知這一點，為了證明部落中有一些術士並不想從內部毀掉部落，或是為了獲得權力，我自願盡我所能幫助年輕的首領。"] = "b4db7422b050ec4c88d959b16d7d2d02",
            ["哈哈！除了他們的領導人——薩特, 巴札蘭, 還有術士耶戈什——是的，他們所有人。這就是我不斷的派索爾的信徒到他們那兒去的原因。這樣會讓索爾覺得我正在剷除他偉大城市中邪惡的人。事實上勝利是雙重的：殺掉索爾的信徒並測試一下那些燃刃的力量，看看他們是否真的有資格加入我的隊伍。"] = "928454d2578950fa6fb82aada645bbc0",
            ["啊，是我們的人。很高興看到我們的隊伍增長如此迅速，以至於我都記不清每個人的容貌了。$B$B索爾那個傻子認為我正努力改善術士的形象並為他服務呢。白癡！燃燒軍團在耗盡這世界的資源後會將它化為灰燼的。"] = "b8b755fa02767f4b1ab4edb5fb08b0d4",
            ["天真的傻子。火刃就是暗影議會！議會擁有許多信徒和組織，但是他們都服從於議會的意願。我或許能領導火刃，但是我無非是議會手下的一名爪牙，就像你是我的爪牙一樣！$B$B看看燃刃吧——他們中的大多數人認為自己會成為下一批極具潛力的術士，並成功替代暗影議會。"] = "9d30b90a514baebe7e41278776ffc316",
            ["我會讓你知道這一點的。很明顯，你如此迅速地成為中尉，已經證明了自己的實力。或許稍後你回到我這兒時，我會派給你任務的。委員會崇尚那些能熟練運用魔法的人，但也歡迎各種族的僕從，無論該僕從從事何種職業。"] = "3ab46d5a9682d81751ca9dfa2e99a0bc",
        },
