        [3296] = {
            ["什麼，你找不到那裡？到精神谷湖裡的暗木小屋去，就在力量谷往上靠西的地方。"] = "2eae00e94c3eecdbf2462e9dfa78b8a4",
            ["你可以在力量谷中部的銀行外面找到接收你情書的地方。"] = "072bbffeb611bfaace92898c40fcf12c",
            ["你在尋找格羅達爾和暗火營地？在被稱作暗影裂口的地下洞穴裡找到他們。有兩條通道可以進入洞穴，一條在智慧谷的南面，另一條在暗巷區裡面。"] = "0698ec224bc7a0fd621ac60e8efa1344",
            ["你在尋找部落大使館裡的烏特倫。在力量谷的西邊你可以找到他。"] = "71970291a3ab9199914f897241acc4b3",
            ["你在找什麼？"] = "11f7e88f267338a9a8803626e9eb30be",
            ["你希望利用這些屍體以表示對它們的尊敬，這很好。去暗巷區中心的 科多獸皮工店找蘇爾德吧。"] = "b71ac0b129e303f2e0d83640555128a9",
            ["你想在哪個戰場追求榮耀呢？"] = "e919f627ec93189b9e052d3ae120da80",
            ["你想找的是卡德里斯。她和其餘的薩滿正在智慧谷索爾的要塞的入口房間那裡。"] = "51a01677ab631a12e7d309b5687d3723",
            ["你想要幫助阿拉希盆地的被遺忘者打敗人類嗎？那就去勇者大廳找迪茲·斯諾班談談。"] = "23bbff30f9e429d824918493908635e8",
            ["你會在力量谷中央的奧格瑪銀行外面找到它們中的一個。"] = "e0e6795a2a739fd62fe20834f1d3ff96",
            ["你會在榮譽谷找到那個哥布林和他的玩具商店的。"] = "8cd6b270a77a323ae36771bf7b388624",
            ["你的嗓子喊啞了是嗎？在力量谷就可以找到奧格瑪拍賣場。"] = "180f756a443773f9b08c470a7bf7efc5",
            ["你的搜尋基本結束了。到智慧谷的索爾的要塞入口房間裡找尋真知吧。"] = "2fbfb318d5dc89b3a1d85305c71f4e19",
            ["你的目標位於榮譽谷西北角。你會在那兒發現獵人大廳的。"] = "51c81b6b8b401941a5a80ec07d3cf189",
            ["你肯定會想從札姆沙那裡學些什麼的。當你從力量谷進來的時候走左邊的樓梯到暗巷區上層的博斯坦的火坑去。"] = "431eb88bb07fa6381014c842373d0570",
            ["你能給我的斧頭附魔嗎？我需要永久性的。或許晚些。到智慧谷附近的暗巷區西端找到古丹的符文工藝店。"] = "1280f9f183703298db351e358105cdc5",
            ["你要去傳說大廳？它就在西邊的力量谷之上。如果你不是官員的話，你是不能進入傳說大廳的，但是你可以跟大廳外的巴沙談談。"] = "30dd36a9611a5248ae78a22056a25043",
            ["你要找什麼技能的訓練師？"] = "bb48a6496b0f939b97d651fb87555c27",
            ["你要找科多獸皮工店是吧。去暗巷區中心吧。"] = "739d876c38f19ef98b95c5ae9bb322ff",
            ["你認為雙足飛龍管理員會在哪兒？到力量谷的飛行塔的頂部去！"] = "058360cd0cfb26d7fc00ef22bcb6d9f7",
            ["克蘇卡會把你多餘的寵物圈養起來的。到榮譽山谷的競技場和獵人大廳之間的畜欄裡找到他，現在走吧！"] = "b0e64bb72a28ec8edf23f963ff9ce7c8",
            ["別讓我發現你盜竊了任何東西！去暗影裂口地下尋找申蘇爾以及他的迅影兄弟會。在智慧谷以南能找到通向那兒的通道。"] = "453a8ae094156bcd4e2d1b85c9a3df31",
            ["到力量谷去，在飛行塔的南面就是奧格瑪銀行。"] = "3b2d3f4253346fe54a8af9329b9583ef",
            ["到力量谷的飛行塔頂部可以找到雙足飛龍管理員。朵拉斯會確保你到達你想要戰鬥的地方。"] = "c50805eb336264793c344418e5961fbc",
            ["到暗巷區的科多獸皮工店那裡去。問問卡瑪瑞。"] = "ec858405ef47afd35954b41baf604e21",
            ["到榮耀谷去找到勇者大廳並與格雷茲·怒拳談談。告訴他們我在這裡的輪崗結束後就會去向他們彙報。"] = "9d782b04ca119ec2bc56975d49b1e444",
            ["到榮譽山谷去並在馬廄附近找到克蘇卡。"] = "3721283f14bf5a96478d4e27f054a4e2",
            ["到榮譽谷的湖泊的東北方找紅石谷礦業工會。與那裡的馬卡魯談談。"] = "03234dcd1c0db3655e7b003ee852c8fd",
            ["到榮譽谷的獵人大廳去，它就位於就在大劇場的西邊。與那裡的奧瑪克談談。"] = "2cf644ba2f510e7a4b8706d23090659a",
            ["去力量谷尋找旅店老闆格雷什卡。她的旅館主城門以北東側的地方。"] = "2bba707a81f7cb342da5648c95205a58",
            ["去力量谷西邊的山頂找找看。他們只會讓官員進去的！如果你不是官員，可以跟外面的巴沙中士談談。"] = "e7866663b8f38742244edaa262c62e11",
            ["去勇者大廳找污染者迪茲·斯諾班，他會幫助你進入阿拉希盆地的。"] = "d79187c46c1d132053867c2cbc1e9e3e",
            ["去城外東南方找飛艇降落塔。"] = "3e4dab27994d3297fb026a55aa21667f",
            ["去大樹以西的暗巷區中心尋找耶爾瑪克藥劑店。"] = "9e0185cc1cebabdbc4e8995462442fd6",
            ["去榮譽谷的傳說中的裝備店中找塞尤克和哈納什。注意你的言行，否則塞尤克也許會將你作為餵狗的美食。"] = "0e4181512160358580b16051647a2601",
            ["去榮譽谷的勇者大廳找格雷茲·怒拳談談。並代我向他問好！"] = "d64d7b97dd43fd06735418ebd2a16c48",
            ["去紅石谷礦業工會東北部的榮譽谷找諾格機械店。"] = "1a123cd209d94b6100489b018fff1c1f",
            ["古丹的符文工藝店就是你要去的地方。到暗巷區的西端可以找到，就在智慧谷的旁邊。"] = "7c40c8dcef4c28192551a41a2dee01de",
            ["哪一項專業？"] = "539255a3b21365ed1ab0beecd22e319f",
            ["嗨你，你是不是想要去詹迪亞的加迪植物園。我剛剛沒有說清楚嗎？哦，我肯定累了！只要沿著智慧谷裡的阿索蘭的市場後面的木製臺階到達暗巷區，你可以看到加迪就在那裡的上層。"] = "ed31d9f384101e3d6caedb2bb8b89983",
            ["在城市的大門外有一處路標，指向地精塔。去跟塔頂的地精飛艇管理人弗雷薩交談。"] = "ac0ba2a4466278a2ed6ceac133133a36",
            ["奧格瑪拍賣場位於力量谷。去火槍進口公司東面找它吧。"] = "311c5f6a0a1dddef0371a0c113bb62ab",
            ["奧格瑪銀行在力量谷那裡。去主城門以北的地方找找吧。"] = "0d0d3b2be6dc0e0448bd8ad0d1a6199b",
            ["如果你想要去奧特蘭克山谷，去和卡爾特拉·血喉談談。你可以在榮耀谷的勇者大廳找到她。"] = "1012c1ecc8ed009687e7f7451230d860",
            ["如果耶爾瑪克認為你有能耐的話，他會教你配製藥水的。去暗巷區中心的商店找他吧。"] = "fdeac495307fb2d96ba514b92ca0eb97",
            ["布衣！？那不會幫你抵擋住好鋼做成的武器的！哈，如果你確定你想當個裁縫的話到暗巷區的瑪加爾布品店那兒去吧。"] = "770f29a21112974898d2bcf70bbdc410",
            ["往上走到力量谷西邊，到精神谷的暗木小屋找皮菲瑞多談談。"] = "716e7e4fb54f6b7f439717f8e1cb509c",
            ["想學習如何使用新武器？去榮譽谷的傳說中的裝備店中找塞尤克和哈納什吧。"] = "9edff2b4be1867c383c57d9f437a1916",
            ["想找迅影兄弟會的申蘇爾，是嗎？去暗巷區，過了杜佛斯回收店之後就可以找到通往暗影裂口的通道。"] = "78c4d657469f59de32a6b3a9a4ebdc4e",
            ["我們不是剛從燃燒軍團魔掌中逃脫嗎，現在你卻又跟惡魔糾纏不清了？去地下洞穴暗影裂口尋找暗火營地。在暗巷區中有一條地道通往那兒。"] = "65f8dda67d9c8c8f969b388ee0edf169",
            ["我們必須要消滅戰歌峽谷裡那些精靈跟他們懦弱的盟友。如果你可以幫助部落的話，就去榮譽谷的勇者大廳跟布拉古爾談一談吧。"] = "970ddc32d4b7a525c189dc519ff7a728",
            ["我多想和你一起加入偉大的戰鬥，但是我必須待在這裡值勤。去奧格瑪榮譽谷的勇者大廳找卡爾特拉·血喉，她將會幫助你進入奧特蘭克山谷。為部落帶來榮耀，$N！"] = "85f1dfbc6635cf1f0129f8b498acbd11",
            ["我猜有人在戰鬥結束後需要幫我們這些戰士包紮傷口。到精神谷的靈魂小屋旁邊的適者生存小屋找阿諾克。往上走去力量谷的西邊找到一個湖。那就是他待的地方。"] = "6be79c4541f77d8d29acbf888f562299",
            ["或許有一天薩魯·鋼怒會教你學會製作一把質地精良的斧頭。沿著紅石谷礦業工會右邊的道路，到榮譽谷的「燃燒的鐵砧」店裡去找他吧。"] = "9da815f247cef1730191b3131d74d0b9",
            ["旅館位於主城入口以北，力量谷右邊的第二幢建築物。和旅店老闆格雷什卡談談。"] = "ab72d7c83a6d226e67a075b1ba52048e",
            ["札姆沙在暗巷區上層的博斯坦的火坑。當你從力量谷進入暗巷區時走左邊的樓梯。"] = "0a849e65bb54685b03424a28e2b4c13c",
            ["治療技能是給那些無法忍受痛苦的人學習的。如果你一定想學習的話，就去力量山谷上面以西的精神谷找靈魂歸宿吧。"] = "03d023b4146dbfca47b38d4edcaa7764",
            ["瑪加爾的瑪加爾布品店在暗巷區裡。去科多獸皮工店旁邊的大樹南邊就可以找到他。"] = "908c0040569523d5a3f6346f2a16f4ba",
            ["草藥……你需要前往暗巷區，去加迪的植物園找她談談。在智慧谷阿索蘭的市場後面有木製的階梯。沿著階梯可以到達暗巷區的上層。"] = "f4d8e423146d1060237e65e944828604",
            ["薩尤斯與他的牧師在精神谷那的靈魂小屋裡。去力量谷上方西側的湖泊那裡可以找到他。"] = "ea2acf9d681b135ace8c51a731759494",
            ["蘇爾德將教你如何練習技能。去暗巷區的科多獸皮工店找他吧。"] = "5d4bbbbb15b947844d18eda0fa01c581",
            ["跟燃燒的鐵砧的薩魯·鋼怒談談。沿著紅石谷礦業工會右邊的道路走到盡頭，去那得榮譽谷找他吧。"] = "e64f4df8c7e58b6297509a694416a3f4",
            ["部落大使館位於西邊的力量谷。"] = "96570b0e28f301933f76f87ab8b65194",
            ["釣魚是那些沒有在戰鬥中死去的老人的運動！到榮譽谷的湖邊可以找到魯瑪克。"] = "a2e192907f9e8f21779ac2c1b989d419",
            ["銀翼哨兵算不上是個可敬的對手，但是如果你對屠殺他們感興趣，那麼就去勇者大廳找布拉古爾吧。"] = "79112947d6abd6ba4573faecea150b38",
            ["阿諾克能製作很好的繃帶。他住在精神谷靈魂歸宿旁邊的湖畔，就在適者生存小屋。它就在上方的力量谷西邊。"] = "bce8743c8a0bd63dc3920724e764d1fa",
            ["馬卡魯整天都在榮譽谷的紅石谷礦業工會，就在湖邊。"] = "9735ac53d3d67045070581d0843fe26d",
            ["魯瑪克……總是在榮譽谷的湖邊釣魚。你找到他後，順便幫我向山吉斯問好。"] = "ff136b77a5b4f0167b2bc90bed633ab3",
        },
        [3305] = {
            ["只要那些矮人一直待在那裡，我們就不會有麻煩。你現在要去哪裡，$N？"] = "e335b9f12333a886ef964fef76e376d8",
        },
        [3306] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "3108806b44f37624987d36cafc8de658",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "963db5ef5555edf879e137a605643024",
        },
        [3309] = {
            ["你寧願把你的貨物交給一個哥布林嗎?"] = "bc269ca0f3298e0f908bb9eedbbb29c7",
            ["先不說外面的那些衛兵，我和我的兄弟們可都參加過海加爾山之戰。誰想要在銀行裡面行竊，那就先過我們這一關。"] = "a90d1a70d1794a0870befff1ef52b64e",
            ["我會用我的鮮血來保證這座銀行的安全，你覺得很放心吧？"] = "3b27a7cc7f607a01029609d1a72bc83d",
        },
        [3310] = {
            ["在你從雙足飛龍背上往下俯瞰這個世界之前，不能說你真正活過。"] = "f7834eaebb9cc6ecebe0cae418cf5f59",
        },
        [3314] = {
            ["告訴我你要什麼，別磨磨蹭蹭的。"] = "92c1b07e4e165a8813160a0c5e6a6a0c",
            ["經歷了多年的戰亂和奴役生活，再次擁有一個家園的感覺真好。"] = "42358e20aa4821ec13efafe2dafad720",
        },
