            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
        },
        [3327] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["我不能訓練你。"] = "60044d7f82718835ed805cb5fdc7067b",
            ["我給你帶來一些東西，$n。它們看起來挺重要的。"] = "be71e303387ffea0be60a35c3c78e8d3",
            ["碎手氏族將會見證部落的崛起和榮耀，酋長的懦弱不會阻止我們！"] = "5070548a9c45a19ece573bb4b49296f4",
        },
        [3328] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["我不能訓練你。"] = "60044d7f82718835ed805cb5fdc7067b",
            ["拉文霍德的信差今天早上將這封信交給了我。這是寫給你的，$n。"] = "665345d33fb8e63831d075e7b6457308",
            ["碎手氏族將會見證部落的崛起和榮耀，酋長的懦弱不會阻止我們！"] = "5070548a9c45a19ece573bb4b49296f4",
        },
        [3332] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "665bbb3772dc4ca6c973b2ba079bf837",
            ["好吧，我可以教你釣魚。"] = "081b59701643fc144f37758247997960",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "0b512be0e7d51bb900e38c95885108fe",
            ["魚肉真鮮美。你來學釣魚的？還是來吃魚的？呣……"] = "a92b422f060c1d7ccb871bbb1aeede31",
        },
        [3341] = {
            ["我獨自走在路上，為了捍衛榮譽和清除這片大陸上的敵人而戰。$B$B我能為你做什麼，$N？"] = "8f91f2acecd0ce7ec9e9398bfec0d760",
            ["是的，我見過你要找的薩滿。上次我見到她的時候，她正往西邊去。她隱居在鋼鬃部族上方的小山上。如果你夠聰明的話，就可以找到一條通往小屋的山路，就在北邊不遠的地方。那條路可以讓你避開野豬人，直接找到她。"] = "352919ecdb6b9b239ce6b40f838cf528",
        },
        [3344] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "28f6b8de934060edb89ab0339b080fcf",
            ["靈魂引導你來到我這兒。我要怎麼幫你？"] = "93ff0e2abb20dcd5c4b04b86b60d8ab3",
            ["願靈魂與你同在。"] = "7be5b41b6547e9fda9b4b9cb85616226",
        },
        [3345] = {
            ["你現在沒有資格受我的培訓，陌生人。先到我的助手夏格那裡學習一段時間。"] = "e5af5d1c3def492a1f23240e2763be98",
            ["你的技藝勝過我的水準了，陌生人。與石爪山脈烈日石居的赫加斯談談。他會傳授你比我還要多的知識。"] = "b763ebb2808596a973203acbe4b2c81b",
            ["幹得好！你的眼中閃動著活力和自信？我明白，我年幼時就跟你一樣充滿活力！讓我看看能不能教你點什麼。"] = "0535431e80accd3492c256c1ceb98fe1",
            ["有些冒險家認為附魔術不起作用。我發現當我向他們挑戰，要與他們作戰時，他們的看法就改變了！"] = "3c96e38d8275bcb879a7e7eb43dca519",
        },
        [3347] = {
            ["你找錯獸人了。我不訓練新手。去問問那邊的小伍特……謙虛一點。"] = "dc5f01a7caf937c808eda68e7ed6a043",
            ["另一名學生，是嗎？好吧。我看看有什麼能幫助你的。"] = "d3bef4bf422a40408d5b3a0703f1e056",
            ["我很忙，$n。告訴伍特去處理一切。那個年輕人整天都焦慮不安的。他大部分時間都處於這種狀態，像是要做些什麼。"] = "394b7578a863582891b710fc0e4197bb",
            ["見到你是我的榮幸，$N，但是你在配製藥水方面比我厲害。去幽暗城 煉金房找亡靈赫伯特·哈爾希醫生。他能幫助你。"] = "a072b3abc76b71077e3d1be09b95da83",
        },
        [3348] = {
            ["嗯……"] = "c34ef3d11704ad9a5aadd00c5c258be2",
        },
        [3352] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["我不能訓練你。"] = "27047ba17cce8edfba9757279f001d39",
            ["我有許多知識可以讓你大開眼界，$c。你必須學會帶著榮耀去狩獵。"] = "5b5b66a181411dac0931427a9ff18c6c",
        },
        [3353] = {
            ["你是來接受訓練，還是來浪費一個戰士的時間的？"] = "141f23d07f540e8c7b0ef9335bda601e",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["我不訓練你這樣的$c。在你惹惱我之前找你自己的訓練師吧。"] = "5c32ac92759b0e79eade7dc21f7e569f",
        },
        [3354] = {
            ["你是來接受訓練，還是來浪費一個戰士的時間的？"] = "141f23d07f540e8c7b0ef9335bda601e",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "3a364a4573d4825a6795e3bb454069d4",
            ["我不訓練你這樣的$c。在你惹惱我之前找你自己的訓練師吧。"] = "5c32ac92759b0e79eade7dc21f7e569f",
        },
        [3355] = {
            ["你有什麼事？你是來接受訓練的嗎？你是來尋找鋼鐵的秘密的嗎？還是要學習鍛造的技巧？快說！"] = "03b20e4ae05f8ecd44ff03f0c3561c3f",
        },
        [3362] = {
            ["嘖嘖，勇敢的$c！我有最訓練有素的狼來讓你挑選。你到哪裡都不會發現另一種動物有與狼同樣的耐力和生存本能！請你親自來查看一下他們吧。"] = "45462d0bfb55988ee297f81dc43938d9",
            ["我只跟奧格瑪和獸人的貴族做生意。證明自己吧，我將給你看看那些強大的狼。"] = "889004b6fde3d6412a91b1aff5e0f67c",
        },
        [3363] = {
            ["什麼？你為什麼在煩我？哎呀，我打賭你甚至不能製造一件高品質的長袍！去找斯諾恩談談，等你水準提高以後再來找我！"] = "3d2ea831ad1620f66cc7300a9bfe1240",
            ["你那時給我看了某些結果！現在該我給你看看結果了！"] = "97a07a6619bced8dc7c9433b4974c6de",
            ["你需要找一個比我懂得多的人。去找幽暗城的喬瑟夫·格里高利談談。那麼，你還在這裡幹嗎？"] = "251c4b189af8f0c50a129485f212f8d2",
            ["我能製造你在商店裡看見的若干東西。你認為如何？小心回答，這也許能決定你的命運。"] = "d6420130e1b1b2f317ac78e25124b3bc",
        },
        [3365] = {
            ["你在學習好基礎知識之前不能學我的技藝。如果你對訓練感興趣的話就去找卡瑪瑞談談。"] = "2fd61c589f9bb1577b01643f5801f516",
            ["你在我這裡學不到新的東西了；你知道的已經很多了。如果你想得到更多培訓的話，去找雷霆崖中央高原西北方商店裡的牛頭人尤納談談。替我向她致意，怎麼樣？"] = "27197dd40c94aa0130b97cc1d108ba6a",
            ["奧格瑪地形迂回曲折，能有效地阻止入侵者。你能想像這些矮小的地精在多麼短的時間內就迷失方向嗎？哈哈！如果夠幸運的話，我會追蹤到他們，將他們變成我的寵物。"] = "f1a951b15107960a9c72aa1be0135f4d",
            ["我忙嗎？這話什麼意思？你覺得我只是成天站在這兒玩弄手指嗎？如果你想買些什麼的話，跟罕杜爾談談。"] = "5dc27cf243a0b86654eea241255fe527",
        },
        [3370] = {
            ["即使在和平時期仍然會有戰爭，而許多氏族仍在酋長的領導下奮勇作戰。你是來為奧格瑪而戰的嗎？"] = "9a8bdb372e76473a8705a53b71983df8",
        },
        [3373] = {
            ["我是一個從事藥學的獸人，$r。如果你是來學習的，我會盡我最大的努力教你。"] = "8e7239601de1c8f6d5c6553a819d76ab",
        },
        [3387] = {
            ["雖然我們把這塊土地稱作貧瘠之地，但對於睿智者來說，這裡到處都是生命。"] = "be12953a2eb9e2b4f53206a938cf050f",
        },
        [3389] = {
            ["我們有自己的職責，$c。對部落應盡的職責。"] = "a325f9b1e91967df6e334cb3d0b0784d",
            ["我聽到他來了！朝西看！"] = "99de77c0a5a974e26ae9dfd849d37ce8",
        },
        [3399] = {
            ["札姆沙能幫你嗎，$r？"] = "ad344693e6c8ac1ec01370090a570643",
        },
        [3401] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "5016339405f25a1000a29e26a0caf19c",
            ["我不能訓練你。"] = "6de484f4be256ef1578f9421e15df66b",
            ["我給你帶來一些東西，$n。它們看起來挺重要的。"] = "d40a242b76d3772a9974107e9b235081",
            ["無論索爾是否存在，碎手氏族的秩序都將延續下去。"] = "4f0a9d40e9cc2c1e6b1295172014d77e",
            ["碎手氏族的影響遍佈這一地區。我們已經統治了整個卡林多——法律，政治，軍事，一切的一切。我們無所不知，我們目及一切。$B$B你現在已經成長到能夠為我們效力的時候了，$N。是時候讓你投入戰鬥了。$B$B你做好接受下一個任務的準備了嗎？"] = "e5b80def6be2f085b63829ee15ec4de0",
        },
        [3402] = {
            ["碎手氏族的贊杜沙。贊杜沙怎麼會幫你？他不能！也絕對不會！"] = "278905793296e13c5c606639f4c4456e",
        },
        [3403] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "857ea30c7f6e11d987a132b4e84da4dc",
            ["靈魂與你永在，孩子。我能為你做些什麼？"] = "6c82842b379af58a9a58e28cb35a4d49",
            ["願靈魂保佑你。"] = "5bcfe44c67f5e0a247451c8d54a13c74",
        },
        [3406] = {
            ["嗨，你需要繼續前進，去找$c訓練師。"] = "3a75f8b0a2ec11bc929978a4d421dc5a",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "5016339405f25a1000a29e26a0caf19c",
            ["我可以為你效勞嗎?"] = "da08a8de6ae36ba7023d844f7af43f4c",
        },
        [3407] = {
            ["來學習獵人之道吧。驕傲，榮譽，還有傳統。"] = "a0f285cb56be6782c0dc978d5a0617af",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "857ea30c7f6e11d987a132b4e84da4dc",
        },
        [3408] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "5016339405f25a1000a29e26a0caf19c",
            ["我可以為你效勞嗎?"] = "da08a8de6ae36ba7023d844f7af43f4c",
            ["放輕鬆點。我只訓練戰士。"] = "ca064fbb60369e53eafa38882b28ef51",
        },
        [3412] = {
            ["你已經通過測試了，幹得好！對你的培訓可以繼續了。"] = "aebf8bffcdfdd4b408e4f5ba08fd3f15",
            ["你贏得了到一個更高級的導師那裡學習的權利。去見見我那邊的朋友羅克希克。"] = "00008c92982d394e12b610e2f162f1fb",
            ["你還沒有資格接受我的培訓。先去見見桑德，就在那張桌子旁邊。當他說你可以了再來找我！"] = "79a7ae7ace70459d2510259f506e19c4",
            ["要是離天黑還有些時間的話……"] = "71545b2af437b8e180d49ce9b50338cd",
        },
        [3413] = {
            ["你好，$N！如果你需要的東西在我店裡找不到，那麼我可以專門去幫你找一下！"] = "3c995182358b09d304bb6e1c0a9dd8d1",
        },
        [3429] = {
            ["歡迎來到十字路口，$c。我叫索克——以酋長的名義，我負責在這兒進行防禦。$B$B請你在這裡隨意一些。在你處理生意的時候，沒人會對你佔用空間有所異議的。$B$B我們的安全存在許多威脅。如果你想熟悉周圍的情況的話，就跟其他人談談吧——或許他們會派給你一些任務的。"] = "bc68f87f28d14f99d8f8ff4c267ffea2",
        },
        [3432] = {
            ["我從南邊到十字路口來尋求幫助，$c，但是那些膽怯的傢伙都不願意伸出援手——就連強大的索克也污辱我。他是一名很好的領導者，但是他拒絕了我的請求，這讓我感到非常惱怒。$B$B他聲稱我的憤怒令我變得魯莽——妨礙我的正常判斷——但是我一定要復仇！"] = "63a72ba3d24c591ed6c49d61ff2efbe2",
            ["謝謝你，$n。你安撫了我死去的妻子的靈魂，我將永遠無法報答你的恩情。$B$B我想我會永遠仇視野豬人，但是現在我已經得到了滿足。$B$B我必須開始重建生活。"] = "bad017b3adfc64250ce72451884a2780",
        },
        [3433] = {
            ["酋長指示我學習各種武器和護甲知識。他把我派遣到這獸人和牛頭人文明的集合之地，接觸盡可能多的旅行者，學習整個貧瘠之地的文明。$B$B他認為即使是最未開化的文明也有值得學習的地方——比如野豬人和半人馬。"] = "7d7cdc1000a3951e96ce7ea9aae1068e",
        },
        [3442] = {
            ["很多事情要做，很多事情要做！協會已經給了我們最後的期限，我們決不能超過這個期限！"] = "f04e73ec5cd32473774944eedc48a86f",
            ["有趣，真有趣……我知道有個德魯伊居住在哀嚎洞穴上方的山頂，$N。她也許能告訴你有關這塊碎片的更多資訊。$B$B現在，我必須工作了！"] = "b553c80d00cdd9070918c489df5ae9bc",
            ["看看，風險投資公司的新伐木機比我的要好多啦，從可拆換的機械臂到控制把手，都是那麼棒！我的老闆給我下了死命令，但我們卻拿不出任何東西。$b$b現在我們自己的設計研製工作已經完全停止了，所以我決定向他們「借」一個。我派維茲克蘭克去淤泥沼澤偷一個回來，但他到現在還沒音訊！"] = "3b982d83ca250aba2a857fe1a2388627",
            ["雷德沃克斯主管讓我負責新型伐木機的研製計畫。只剩幾個月了，我處在水深火熱之中！我需要你的幫助，$n！"] = "0cc088f013cb6fc40acf3a7acfed831d",
        },
        [3448] = {
            ["我們所處的這個時期就像風雲般變化無常，$c。要謹記這世上什麼才是真實而長久的，並好好保存它。其餘的事物都毫無用處。"] = "3c1076a9c4093b75e0ba1a3c06c09528",
        },
        [3478] = {
            ["靈魂將你帶到我這兒來，感謝他們。"] = "226e4c5248a59d219e14d288106c8613",
        },
        [3483] = {
            ["貧瘠之地陽光灼熱，那兒的居住者充滿敵意，是考驗你的力量和決心的最佳地點。"] = "18a3a77c5ae8b48a2bbaab1d5d833914",
        },
        [3484] = {
            ["嗨，我能為你做什麼呢？"] = "b9c260f10777917d0aaa23c86b095d93",
        },
        [3489] = {
            ["看看我的肉，朋友。你不會想雙手空空就進入貧瘠之地吧。"] = "3cbc06359ec26be5a68c387070b4ffd6",
        },
        [3494] = {
            ["什麼？你要什麼東西？"] = "b0fb181dddc32fa304d6805b255e6bde",
            ["恐怕你得離開我了，朋友！你該去找奧格瑪的諾格，他將帶你進入下一階段!"] = "f87c37944192073e24d10f1a070e94b4",
            ["我不能幫助你！你會遇到比我更精於此道的人！你是聯盟的人，你得跟暴風城的利廉姆·火軸談談。"] = "1389ded94ec799fa553e34c3557ac12c",
            ["是的，我有些東西要給你看看。我們來看一下你做得怎麼樣，或許你會令我吃驚的！"] = "af9ccb95467b25c6dc0eaa8a4d0cf1cf",
        },
        [3516] = {
            ["如果你是來浪費我的時間，那你就是在浪費整個塞納里奧議會的時間。為你自己著想，希望你不至於那麼蠢。"] = "dbf255d67eb367a5e2e26df7615ab1d9",
            ["沒錯，但是如果你精通草藥學的話，你會發現它非常有用！你要做的是用特別的種子來細心培育藥草——而不是一遇到風吹草動就揮斧亂砍。雖然你即將得到的常青袋能讓最沒有經驗的新手輕鬆進行種植工作，但那些對草藥學有天資的冒險者將會得到更豐碩的成果。"] = "246b760cf38fc3d7b56b064fcda8d886",
        },
        [3518] = {
            ["暴風城最好的貨物啊，朋友，你絕對不應該錯過。看看有什麼你需要的東西嗎？"] = "0a50227fd4a79a221c5e74147031f06e",
            ["看看我賣的東西吧，有什麼你想要的嗎？"] = "a86de99ac7614f683ab7eab24b0a0b93",
        },
        [3523] = {
            ["去結交朋友吧。我能幫你嗎？"] = "e291d9ad0a70ad2cbfd236c26b801d03",
            ["我知識淵博，但我還不是專家。你知道你該去找誰談話嗎？雷安諾！她就在不遠的地方。到幽暗城打聽她的下落。"] = "e5260b81bc08d0a40f54722eafa81dcb",
            ["這麼說……你想當一名裁縫？很好，讓我們看看你是否具有這樣的潛質。"] = "aa04b66da46a80a2753c940c3f9f1a2e",
        },
        [3545] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "1566d430b06beb690f54132cef76af32",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "043d1db9fcbabde933fe81bd22b51be2",
        },
        [3549] = {
            ["你已經掌握了它的用法。我沒有什麼要教你的了，但是找亞瑟·摩爾談談，他是在幽暗城盜賊區工作的一位被遺忘者。告訴他是我派你去的。"] = "151ec51becd067dfa6e36901ab1189a4",
            ["在瘟疫來之前，我對皮革一無所知。現在我的知識可以傳授別人了。死亡讓我有了很多時間供自己支配。"] = "d626b39784157d5421d92e7ddf077906",
            ["膚質很好。它將你包裹其中。你也許已經注意到我的皮膚不是那麼好。我過去常常擔心自己的毛孔。這些日子我幾乎不擔心皮膚了。在某種程度上，它得到了解放。"] = "21c1a4ade87cbd580ae80aa7f1f7ae8d",
        },
        [3557] = {
            ["你的打擾在佔用我的寶貴時間，你最好帶來的是好消息。"] = "ba7308311ab1b7a9aa44fa79f5819089",
            ["啊是的，另一個要燒爐火並鍛造戰鬥武器的人。我當然會教你怎麼操作。"] = "5c340e45de61831b7a0d003ad85ea723",
            ["我的孩子，你學得很好。去幽暗城找一個名叫詹姆士·範·布朗特的鐵匠。他能傳授給你更多的知識。我想他應該在戰士訓練大廳附近鑄造武器。"] = "1480eac77cfa26ca7f7f181a30f7627e",
        },
        [3571] = {
            ["一位名叫勞爾娜·晨光的女祭司住在多蘭納爾，我認為你可以在旅店北面找到她。"] = "2c6cd31df344e81e13802e0526bd4f82",
            ["一個盜賊？我不習慣跟那些傢伙打交道，但我相信詹諾克就是你要找的訓練師。你可以在多蘭納爾的旅店找到他。"] = "83667d262f35fc73bb7553229dba8a25",
            ["一艘魯瑟蘭的渡船會從泰達希爾底部的魯瑟蘭村出發前往奧伯丁。達納蘇斯的傳送門會讓你安全抵達魯瑟蘭村。"] = "6c037df3b7038d9b82a973b662d9e670",
            ["不知道瑪洛尼是如何採集到那些最為嬌嫩的草藥的。顯然你得向他多多學習。他就住在多蘭納爾的旅店東邊。"] = "fa2f6a0bf9ea5e78c7cd9a9670147fcc",
            ["你可以在去達納蘇斯的路上看到拉德納爾在他的屋外練習手藝。你應該停下來看看他有什麼可以教你的。"] = "2e33db29fb989db5225ed21dd00dfc75",
            ["你可以在多蘭納爾周圍找到眾多的訓練師，他們有豐富的經驗可以傳授給你。你想要找哪一位？"] = "3b62e4181d8e155be0d34c32038137f0",
            ["你可以在多蘭納爾旅店的老闆凱達米爾提供的床上安穩地睡一覺。"] = "94a6749341ef5f66c12f93180c75a230",
            ["你在尋找一個德魯伊的訓練師？那麼你應該到多蘭納爾旅店南面的月井去見見卡爾。"] = "7c41a2cdee58db931c3f57aaeecede92",
            ["你在找尋一個盜賊？我認為詹諾克很適合你的描述。你為什麼不到多蘭納爾的旅館裡去找他談談呢？"] = "7ee91439488e010165881cb797efaa1e",
            ["你尋找一個喜歡動物的人？那麼你應該到多蘭納爾旅館的外面尋找瑟里亞迪。她就是你找的那個人。"] = "f973dc94f8e2f3e5bb9ad0a919636750",
            ["凱拉·風刃的戰鬥技能爐火純青。她可以對你進行訓練。到多蘭納爾的旅店中去找她吧。"] = "2ff6748c5381da2b47cccf19dd9e9d98",
            ["勞爾娜·晨光為居住在多蘭納爾附近的居民們提供醫療服務。或許她能教你如何成為一名牧師。"] = "4884b53e55dec4a3470d470b3fa83514",
            ["啊，友善的瑟里亞迪。在她的庇護下，所有動物都很安全。你可以在多蘭納爾的旅館外找到她。"] = "4b9bee6beacd2d5faf637d1fc7af3558",
            ["塞恩德拉在煉金術方面的知識有些局限，但是我相信那也足夠領你入門了。她就在多蘭納爾旅店的東面。"] = "2f7ad8bfc99055a560658a285e3618b3",
            ["塞恩德拉的態度非常和藹，她的藥劑也很不錯。你可以在多蘭納爾旅店的東邊找到她。"] = "64eab3bd0b6e3e418b180b01fb4cd9a0",
            ["奧拉密斯湖近來遭受襲擊，所有的漁夫都已經搬遷到達納蘇斯了。你應該去那兒看看。"] = "f04c72b9d344f81d24b170747fc637e9",
            ["奧蘭納·鴉眼將她的天賦部分歸結為與神諭林地的靈魂進行了交流。你應該能在那兒找到她的。"] = "9963e2c8079556e7e03308c3b714ad3d",
            ["如果你需要通過休息恢復體力的話，多蘭納爾的旅店是你最佳的選擇。旅店老闆凱達米爾將幫你打點一切。"] = "7044a367e4a4d0f456163951264eed1d",
            ["官方事宜只能送交達納蘇斯處理。你必須前往那兒去創建自己的公會。"] = "d02f310024399482b9dac67cfc148f64",
            ["從事某種專業的學習是一個長期的過程，但是回報很豐厚。你想選擇什麼樣的專業？"] = "d23c8b801de15e2ee7f38ac7e99b1867",
            ["德魯伊訓練師卡爾通常待在多蘭納爾的月井。我想他可以對你進行訓練。"] = "16bba8106fe5aa116151356d9d0c1668",
            ["想要找到魯瑟蘭村的渡船，你得先去達納蘇斯，通過傳送門進入魯瑟蘭村。"] = "f7f50698e64399e73c940b8e5999f55e",
            ["我以前曾有幸看到在凱拉·風刃作戰，因此我相信她可以好好訓練你。到多蘭納爾旅店去找她吧。"] = "c71b255b624a3a50ff4387076cd62716",
            ["我們當然歡迎多蘭納爾的廚師再多幾個，但我並不是說札瑞恩廚藝欠佳。你為什麼不去找這個廚師看看他能教你什麼？"] = "0a5ce5d8a7759f29e79e96556ab20845",
            ["我敢肯定在達納蘇斯有一個裁縫可以對你進行訓練。當你到了那裡之後，就向達納蘇斯的某個哨兵詢問一下裁縫住在哪裡吧。"] = "fde658d3d3dda267bafe6d6134c02642",
            ["拜恩希在急救方面的技巧已經很知名了。如果你想向她學習的話，你可以到多蘭納爾旅店的北面去找她。"] = "51ebad09e83f3656e4c78bc259beef52",
            ["拜恩希經常為在野外巡邏的哨兵服務。如果你想學習急救的話就該找她談談。"] = "5236c19b097c185960d21473a0f76c58",
            ["札瑞恩看起來很瞭解烹飪行業。為什麼你不去看看他是否會給你一些食譜呢？他通常在多蘭納爾的旅店旁邊烹飪。"] = "83e47373c7b037c97ea19a841c67728b",
            ["林精使漁民在多蘭納爾很難有所收穫。你最好去達納蘇斯找找他們。"] = "1806edb01b654109c85d847d2fc7129a",
            ["泰達希爾有許多你需要去看看的地方。告訴我你在找什麼。"] = "274ed111b1b971c19cf221ceb6d4da6d",
            ["納迪婭·織髮離開自己的家園前往達納蘇斯進修去了。她精通製革，而且是一名優秀的老師。你該去向她求教。"] = "f29cadd86be2633b030d2922ef0d73a4",
            ["納迪婭在數年的實踐中掌握了製皮技術。沿著通往達納蘇斯的道路向西走，去拜訪她，或許她能傳授給你一些知識呢。"] = "59c29a24054e9781525056418704352b",
            ["裁縫所需的多數物品都是從達納蘇斯獲得的。他們都在那兒工作，這並不是件奇怪的事情。要是你想成為一名裁縫的話，你最好前往達納蘇斯。"] = "565828b0bf2c0a029bdd705634e05c4c",
            ["要學習草藥學，你得向瑪洛尼好好討教。去多蘭納爾旅館東邊找他吧。"] = "80ed9b7cf270b2683ac103fb42181eba",
            ["要是你想找獵人的話，就去拜訪達札拉吧。他通常在多蘭納爾旅店的外面。"] = "6a033c0f5e434887661d585271c95874",
            ["要是你想找銀行的話，就去達納蘇斯的中央地帶。你可以在那兒存儲自己的財寶。"] = "4ea5d9544049803bcffe33d330e2fb7d",
            ["諸如公會登記表等文件可從達納蘇斯的公會註冊員那兒獲得。"] = "073009f4d29320fba71c2b204da1fac8",
            ["達札拉以他的狩獵技能在多蘭納爾小有名氣。為什麼不找他談談，看看他能教你點什麼呢？"] = "a50cc4748a430d5984fd12118582d8e4",
            ["銀行位於平靜的達納蘇斯城。如果你想存儲自己的財物的話，就得去那兒。"] = "6427b5ad172185229fdf52a2a91052ea",
            ["阿蘭娜大部分時間都在神諭林地練習技能。如果你想學做一名附魔師的話，就去那兒找她吧。"] = "15211b4d4b796d136e52a122b432560f",
        },
        [3593] = {
