            ["歡迎來到塞納里奧議會，$c。"] = "7b9df1f70b5451c09c6a5311f56bf07e",
        },
        [4155] = {
            ["歡迎來到達納蘇斯銀行。我們提供金融帳戶和存儲貴重物品的保險箱。你要開戶嗎$g先生:女士;？"] = "72fdda7ff30be23db5fd1e0d05a37089",
        },
        [4156] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "49c592e9b3c5eeb0c33e65239b4c0b06",
            ["我可以教你一些釣魚技能。"] = "b4dab18389b060695ecdb043fb33d368",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "e170ac547f813e355db1e3b75f753815",
        },
        [4159] = {
            ["你幹的很好，旅行者。我能收你當徒弟令感到很驕傲！"] = "0fb161fe21a8ff5f560e714f38fb0b44",
            ["你的才能出眾！你真是有靈性。你要想繼續追求知識的話，找暴風城的喬吉奧·波利羅談談。他深受眾人尊敬，而且他能深化對你的指導。"] = "8fde40eee1eab031066dd85909d1ef50",
            ["多好的天氣！它讓我有了創造新設計的靈感。"] = "8ad0f749911a3563135d77e9f55d331f",
            ["必須首先學習一些基礎知識。蒂安娜就站在旁邊，找她談談然後回來找我。"] = "35b8db7ba4c158e508af94c80ef204f9",
        },
        [4160] = {
            ["你的培訓進展很好。你該為你的成就感到自豪。"] = "015468259c43500419a2f50f203dbd3e",
            ["你製造藥劑的技能需要再高超一些才能當我的學生。在此期間，在那邊的希爾瓦娜·林月或米拉·法拉科納可能會幫助你。"] = "58b32f3b07654af166e55ee5ae463360",
            ["現在你該找一位更加淵博的老師了。在菲拉斯的羽月要塞居住著夜精靈凱蘭娜·風語。她有聰明的頭腦；毫無疑問她能繼續教你。"] = "a6416950bbc59cd6baa28946a3f76041",
            ["雖然每次我都使用了相同的成分，但配製出的藥水似乎都達不到預期的治療效果。這只能得出一個結論：植物發生了變化。我還不清楚具體原因。"] = "13119ff66e549fa7660732b19647f9bd",
        },
        [4163] = {
            ["你好，年輕的盜賊。你在找什麼？"] = "249236308a24ca006ca2a9251d3eea0a",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
            ["我們代表的是黑暗，永恆而無形。"] = "e8b964bb2f42459fd5d4d58181834b5d",
            ["拉文霍德的信差今天早上將這封信交給了我。這是寫給你的，$n。"] = "8a0abdcbc600f60a9fcf653afbc414fa",
        },
        [4165] = {
            ["作為一個法師，你是極少數可以操縱傳送門魔法來幫助你回到這裡的$r之一。如果你準備好了，我現在就可以教你。"] = "c0b64230899c1f169032e2124bab7479",
            ["我不認為你具有掌握傳送門魔法所必需的潛質。"] = "6169b63082c1481ee1b292a6bd277450",
        },
        [4193] = {
            ["很高興能將你收入麾下。讓我們開始吧。"] = "a5bb9bf7601a2bba6b4270f85bdd04f4",
            ["現在是你去達納蘇斯跟邁裡恩談談的時候了。她將對你進行指導。"] = "2b4f7103b433f22f1e0130533daa0976",
            ["縫紉需要嫺熟的手法，以及……也是最重要的，耐性。"] = "afa3c58692e1f910f1511cf81176b4cf",
        },
        [4200] = {
            ["儘管黑海岸比泰達希爾更危險，但是很多漁夫都在此謀生。"] = "40cb7a31eb60d273876ed5e0a23aa52f",
        },
        [4205] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "30ee103c545f987ab518c70f6d3e640e",
            ["我不能訓練你這樣的$c。"] = "f2c2c7d6984ce15c597fe07b1c728e29",
            ["歡迎來到塞納里奧議會，$c。我要怎麼幫你呢？"] = "7dd7ee318342731a34bf5316088d4c74",
        },
        [4210] = {
            ["加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。"] = "39b65bdd01752b5105cbbb2683f8191b",
            ["去銀風避難所找珊蒂瑞亞吧。她可以賣給你「高級烹飪教材」。"] = "9530fe03acd8fd0d529479909397654b",
            ["我可以教你如何烹飪！"] = "d8db5bcf701df43b6392f5a3b85ce404",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "95be6f4a5e8c06f411a7922aba42f920",
        },
        [4211] = {
            ["倍受尊敬的古斯塔夫·范沃森醫生能進一步訓練你。他就在塞拉摩的兵營裡治療傷兵。"] = "d3686c1236f20aa21b8980c23e1b8adb",
            ["我可以訓練你急救技能。"] = "d4d40db0ea32c39f6285731935893eca",
            ["我聽說藏身在激流堡的德尼布·沃克有一本書，這本書一定能幫助你提高急救技能。"] = "f4ce78e835b2a64f849bbc3c885698a9",
        },
        [4212] = {
            ["$g尊敬的先生:女士;，在你掌握製皮的更多知識之前，我還不能幫助你，對此我感到很遺憾。跟法多恩或達麗亞娜談談。他們能教你所需的技能。"] = "5d568f2ee6e5585a3694d234762d64af",
            ["你的進步已經超越了我能教授的技藝了。現在到辛特蘭的鷹巢山去找矮人德拉克·石拳談話。他的作品太棒了，比我的好多了。"] = "7461509c37eb6a03aa5e3875c4eeb8d1",
            ["別試圖將你的意願強加到皮革上。而是讓其天然的特性顯示出自身的形狀和功能。這不是一場戰役。與皮革協同工作，而不是與其作對。"] = "2311acc40d0eada3baa06ec889348fc2",
            ["草地柔軟青蔥。空氣清新，陽光明媚，歌聲飄飄。泰達希爾的夢想終成現實。但是為什麼我感到有種不詳的預兆？"] = "4c3e882d5b6e6e4d3050a7dcc19f97b7",
        },
        [4213] = {
            ["你是一個非常棒的附魔師。我恐怕已經超出我的才能了。到阿祖拉之塔找到基塔·費溫德。現在只有她才配作你的導師。"] = "41da82d3c3fe92c245b041f83fe5f39c",
            ["你還沒有學會基礎知識，流浪者。你找我的助手拉琳娜·夏月談話了嗎？可能你需要跟她談談。"] = "3179709b6d6763d00fafe6e4d749f3e0",
            ["我確實有能力對那些有價值的人進行教學。你是這樣的人嗎？"] = "a53ae503ee886bb7a89a674e55487015",
            ["真是細緻的工作！你完全有資格獲得我將授予你的知識！"] = "3184759a6de00367ad581b70c97d3358",
        },
        [4214] = {
            ["你好，年輕的盜賊。你在找什麼？"] = "359b565e3f9598b0c4c99d31465a6002",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "30ee103c545f987ab518c70f6d3e640e",
            ["我不能訓練你。"] = "f7c03ed04dab075fddaf94fa5e6690d8",
            ["拉文霍德的信差今天早上將這封信交給了我。這是寫給你的，$n。"] = "cd9efe92b4cd73363689d342f33b4061",
        },
