        },
        [4217] = {
            ["你找塞納里奧議會有什麼事，$N？"] = "fb107f4dbefdbafaf3a91b5c9b3d998b",
            ["歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B據傳塞納里奧議會戰事不斷，但是你不該輕信這些謠言。我們的德魯伊首領范達爾·鹿盔將領導我們和整個泰達希爾取得勝利！"] = "765d7c8eab15fae760b184c664fb9e9a",
            ["要是你願意的話，除了訓練之外，我還可以用自己的力量將天賦從你的頭腦中抹去。我要警告你的是，你每經歷一次這樣的過程，執行這過程的難度就會增加一分，而且所需的費用也會隨之上升。"] = "d8d678c1fa7a5d0ec00c8daf69cd26f9",
        },
        [4218] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "30ee103c545f987ab518c70f6d3e640e",
            ["塞納留斯保佑你，$c。我們的首領大德魯伊鹿盔會帶領我們和整個泰達希爾開始全新的生活！"] = "04deb31038105cfd74ab05f52c151823",
            ["歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B據傳塞納里奧議會戰事不斷，但是你不該輕信這些謠言。我們的德魯伊首領范達爾·鹿盔將領導我們和整個泰達希爾取得勝利！"] = "765d7c8eab15fae760b184c664fb9e9a",
        },
        [4219] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "30ee103c545f987ab518c70f6d3e640e",
            ["塞納留斯保佑你，$c。我們的首領大德魯伊鹿盔會帶領我們和整個泰達希爾開始全新的生活！"] = "04deb31038105cfd74ab05f52c151823",
            ["歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B據傳塞納里奧議會戰事不斷，但是你不該輕信這些謠言。我們的德魯伊首領范達爾·鹿盔將領導我們和整個泰達希爾取得勝利！"] = "765d7c8eab15fae760b184c664fb9e9a",
        },
        [4241] = {
            ["為冒險家服務是我的榮幸，因為他們即將成為英雄。"] = "1245860919a037af19c20e24c625c670",
        },
        [4256] = {
            ["要是你問我的話，沒有比礦工更好的職業了，也沒有比矮人更好的礦工了！"] = "77ab7ea3aff9f5b83ed9f444750c2f64",
        },
        [4258] = {
            ["你看起來就是一個天生的鐵匠。你的指甲縫中都是煤灰，雙手充滿了鋼鐵般的力量。啊，我甚至可以感覺到鐵匠的血液在你的血管中奔流。你應該是來這裡學東西的，好吧，$g小夥子:小姑娘;，拿起錘子，讓我看看我能教你些什麼吧。"] = "6d836253374e7258f1d26abac7475d18",
            ["很抱歉$g小夥子:姑娘;，但是你基礎不足，我不能教你。但是別煩惱，跟我的學生洛特加斯談談，他會幫助你的。"] = "ae2d32ca31d33d2e9a8717028c168fb8",
            ["我不能對你進行什麼指導啦，你能用鐵錘和鐵砧做出如此令人稱奇的東西。我建議你去找一個名叫布里克·基克拉夫的哥布林，你可別告訴別人,我最後一次聽說他在藏寶海灣經營一家商店。"] = "c3356da865caee5c14d5f6bf59f6db2a",
            ["我希望你千里迢迢來到大鍛爐不只是為了取暖。$g小夥子:小姑娘;，我能幫你什麼忙嗎？"] = "e40bd9cff0a2b475b7f856f9b06f20cd",
        },
        [4262] = {
            ["$c，如果那就是你的願望，那麼去戰士區找克拉斯·狼心談談。他是阿拉索聯軍的代表，能幫助你到達阿拉希盆地。"] = "f59a17baa98d87d57ad047e9e528c0a0",
            ["一個新手採藥師？那你該找神殿花園的菲羅迪恩·喚月聊聊。他或許有些專業訣竅要傳授給你。"] = "ffcf7d3fc05ebc9a1303d2c59a697fcc",
            ["一個郵筒？你要發信，或者也許你要收一封信？我希望是個好消息！在達納蘇斯中心銀行外面就有一個郵箱。"] = "4f8593ba9dc0933eabfbe1601c8a4af6",
            ["不隨意浪費東西是我們的傳統文化。當我們不得不殺死某種生物時，我們會想盡辦法不讓它白白喪命。  要是你想學習剝皮的話，就去工匠區找艾拉迪爾吧。"] = "c96f29161dcade9647c6f8707b27e20c",
            ["世間動物死時會將它們的生命和獸皮賜予我們。要是你能尊重它們的犧牲，或許剝皮者這個職業會適合你的。去達納蘇斯北部的工匠區，找艾拉迪爾談談，學習更多知識。"] = "d56f05ee073017a9143e842d802a0700",
            ["你可以在達納蘇斯銀行找到你存放財物的地方，它就在我們神奇的城市中央。"] = "8eb9ba45b797263e4803382aebcf7ae3",
            ["你很幸運來到達納蘇斯，因為你遇到了像祖卡斯特這樣多才多藝的獵人作為你的培訓師。我建議你到塞納里奧區拜訪她並尋求她的指導。"] = "d15a97ec9abacddad8435f5774a0eb2c",
            ["你會在戰士區的護衛隊中找到希達奈爾，她敏銳的眼睛掃視著森林，尋找著膽敢進入我們美麗的城市的敵人。"] = "f44318c049c218b57b0e409073bd7f96",
            ["你要做的事情需要很大的努力，$N。要進入戰歌峽谷，你就得跟銀翼哨兵的軍官艾薩拉斯談談。她會為你指引方向的。願女神的祝福與你同在！"] = "6fb5236e00160c864eb6347215bab509",
            ["你要找的是維斯派塔斯。他負責看管在泰達希爾底部往返的角鷹獸。你可以在通往魯瑟蘭村的西達納蘇斯那兒找到他。"] = "21666b1c2ab2afe583fd533d9f03402b",
            ["儘管我可以將覆蓋著整個泰達希爾的草坪當作很好的床鋪，但是工匠區中塞琳尼經營的旅館對那些享受一下奢華生活的人來說再合適不過了。"] = "5573d0a9c052f20b0f5fb6476dc53256",
            ["哦，癡迷於物資財富嗎？好吧，想找好東西，你得去貿易區的拍賣場找找。"] = "d90f95e047a57954e455f354c946ef06",
            ["在灰色年代，德魯伊對周遭的人都很友好。你隨便問塞納里奧區的任何一個德魯伊，他們會給出相同的說法的。"] = "f818dab29f5921c495fafd0e54c105fe",
            ["在貿易區那邊已經有一家開始營業了，如果你沿著銀行往東南方走，應該很容易發現！"] = "9053576b60544f166b688a294bcea667",
            ["在達納蘇斯的東北部，也就是工匠區，你會在旅館外面找到郵箱的。"] = "f051b310bb2a6de52b45a40b67fd3a3f",
            ["太陽已經升起來了嗎？夜晚的時間總是太短！嗯，塞琳尼會好好照顧你的。她在達納蘇斯東北面的工匠區招待客人。"] = "4a2ffe6ddb889c11783a240b6fbb5753",
            ["如果你有希望學成一位裁縫的話你當然應該去找邁裡恩。她住在達納蘇斯東北方的工匠區。"] = "244b2695394eae58d2ff7f21af8ec998",
            ["如果你真的想做這個職業，就去達納蘇斯北部的工匠區找一個技藝純熟的煉金士：安尼希爾。"] = "92c77d24eda0e89d883523e9617dfaab",
            ["它是一項耗時，但是會很有收穫的技能。與貿易區的阿斯坦婭談談或許你能學到一些有用的東西。"] = "04597ac6ff8258c56c07b668a4c288ac",
            ["居住於塞納里奧區的德魯伊一直在大德魯伊鹿盔的領導下警惕地保衛著自然界。你可以在達納蘇斯北部找到他和別的德魯伊訓練師。"] = "1050e24a7181b4781e75952eb85b3d9a",
            ["希達奈爾訓練出許多衛戍，他們守衛著我們心愛的城市。我相信她會使你成為一名戰士的。去城門附近的戰士區找她吧。"] = "2fe98252b42a97d60efb568891e47919",
            ["很多人都試圖追隨著盜賊的腳步，但是只有夜精靈能真正被黑夜接受。如果你想在陰暗的道路上前行的話，就去塞納里奧區找塞尤娜吧。"] = "9955006745f984da2926e3193c72c1bf",
            ["我們種植蔬菜。野兔吃我們的蔬菜。狼群以野兔為食。我們捕殺狼群，從它們身上獲得肉和獸皮。這就是神奇的生物鏈，或許你用別的什麼詞語來描述它。  去塞納里奧區找泰龍尼斯吧，我得繼續執行自己的職責了。"] = "86a6b22447f3864053114200f5749bbf",
            ["我剛好認識一個你所說的$c。你應該去戰士區找布洛岡·石盾。"] = "fde3cbd79786d9234392c6be3a040901",
            ["我的大部分武器都來自戰士區的伊琳尼雅·月火。要是你想學習如何使用新武器，就去找她吧。"] = "3fdb5882d52420a10cedda5c6704aa3b",
            ["數百年以來阿拉辛一直很關心我們獵人視作朋友的動物。他對動物的關心被周圍的獵人所追隨。如果你也來向他請教，那麼就到塞納里奧區找他。"] = "417a4e706b4f46ae4fb091d34eec2534",
            ["月神殿是伊露恩的祭司們的家園。你會在那兒找到賈德莉亞和拉瑞亞，她們會對你的牧師生涯做出進一步的指導。"] = "5963595e8e789ae76d21d76349020da9",
            ["月神的力量支配著你！月神的力量支配著你！  出發吧！去達納蘇斯東部的月神殿中央大廳找賈德莉亞！"] = "fe788e668631819d89ea6f47c42c2f9e",
            ["有許多戰場可供選擇，你要去哪一個呢？"] = "bc8107859019ab2e37a4c010332b9f07",
            ["沒有具備天賦的附魔師，刀刃不可能如此鋒利，護甲也不可能如此堅固。塔蘭丹就是這樣的附魔師，他可以教你如何給武器和護甲附魔。去工匠區找他吧。"] = "244792d6c2e0f82f39ae6c0a4b8bc872",
            ["泰龍尼斯製作武器的技能無與倫比。他不會收學生的錢，你該為此感到慶倖。去吧，去達納蘇斯東北部的工匠區找他吧。"] = "460a90211acc699941f3d86d6b4ff971",
            ["煉金師？這沒什麼$c。安尼希爾通過不懈地努力，成為了工匠區技藝最純熟的煉金術士。如果我是你的話，我會馬上趕去那兒的。馬上！出發吧！"] = "dd479dae533f32a3992c77a3d1aa7f7e",
            ["琳沙娜能為你提供所需要的文檔，她居住在達納蘇斯東北部的工匠區。願你的夥伴為夜精靈帶來無比的榮耀吧！"] = "3eb0dbc4dec391944ba49aa445235c37",
            ["當你沒有醫師來料理你的傷口時，急救知識可以救你的性命。我會請教工匠區的丹納羅爾關於這門技藝的問題。"] = "6fd835875fbe8020422ad312f515153d",
            ["祖卡斯特是她那個時代最偉大的獵人。最近，她在塞納里奧區教那些獵人初學者。"] = "00076a2f6e55d2922d9773ef70577aa5",
            ["穿著邁裡恩縫製的衣服，人們可能會以為她的繡花針是被月神賜福過的。除非你的針也受過同樣的祝福，否則你最好去拜訪她一次並聆聽她的教導。你可以在達納蘇斯東北方的工匠區找到她。"] = "df79484b5472d76db96b41898d02b9b7",
            ["維斯派塔斯的角鷹獸會送你到達目的地的。穿過達納蘇斯西部入口，去魯瑟蘭村找他吧。"] = "6d0616990747b3cf281cc9641375724d",
            ["草藥的收集和與之相關的知識是菲羅迪恩·喚月的專長。去達納蘇斯西南部的神殿花園找他吧。"] = "1e49a3cf6e73b8db88f365f3278429d3",
            ["要是你想做盜賊的話，就該去找塞尤娜。她居住在西部森林盤旋山道下的塞納里奧區。"] = "75e196ec78d6cb7a83a96b0b2894c9b7",
            ["要是你想要組建公會的話，你必須去見公會管理人琳沙娜。她在達納蘇斯東北部的工匠區。"] = "36a062f0dc1636d9af51d4236918fc7a",
            ["讚美伊露恩！你要尋找戰歌峽谷的戰場軍官？她的名字叫做艾薩拉斯，她就在戰士訓練師的旁邊等著迎接你。"] = "3b431228797b39bb81cdc82774f643d5",
            ["身上又多了一種材料$g小夥子:姑娘;，是吧？嗯，如果你攜帶的物品過多的話，可以將它們存儲在城中心的達納蘇斯銀行中。"] = "c45c7553069860089340adb456de7764",
            ["通過千百次的錘煉，伊琳尼雅·月火已經掌握了若干種武器的使用方法，現在她為別人提供訓練。如果你想接受訓練的話，就去戰士區找她吧。"] = "9a3ffcf5f60258c99f20760ca3d68d55",
            ["過獎了，但我真的不感興趣……什麼？你想知道在哪兒能學習附魔知識嗎？哦，真令人為難！呃，你應該……我想你應該……去找那個，嗯……塔蘭丹！對，去工匠區找塔蘭丹！"] = "8efec801651f3192ea4b39d9178f4ff8",
            ["達納蘇斯有無數令人驚異的地方，你想去哪兒？"] = "5f49a0ce5b3654379f0db519a20b64a4",
            ["達納蘇斯有許多熟練的訓練師，他們擁有數年的訓練經驗。我會介紹一名導師給你，沿著你選擇的道路前進吧。"] = "05f41dc20d172bc58dcbca463c852a7a",
            ["達納蘇斯的工匠們可傳授很多工藝知識給你。告訴我，你對哪種工藝最好奇？"] = "b653ff673ce5e58760ed8282427e63d7",
            ["阿拉希盆地的人類急需我們的幫助。你得找戰士區的克拉斯·狼心談談，他會準備好幫助你的。"] = "6307e625367c135b351d633c760f9a2e",
            ["阿拉辛是個值得信賴的人，讓他來悉心照料你的任何寵物。他就住在獵人們聚集的塞納里奧區。"] = "59d50b4f9dac8cf71ca0cfbdeaec5833",
            ["阿斯坦婭在她經常垂釣的地方釣起了一些古怪的財寶。去貿易區找她吧，讓她給你看看。"] = "bd5332cda23cfb988a28235b91583693",
            ["阿雷貢做的食物很受歡迎。他總是在工匠區忙於製作新的美食。要是有 塞納里奧綠色烹飪的話，你一定要嘗嘗。  如果你不介意的話，我必須先去調查一下接二連三的鹿群失蹤事件。"] = "7a065b152cd98b50e6ec1647535c2bc0",
            ["阿雷貢是一名技藝精湛的廚師，數個世紀以來，他都在精進自己的廚藝。要是他願意教你的話，你就得謝天謝地了。要是你相信自己的實力的話，就去工匠區找他吧。"] = "ed3705061b45f850ff33561c67657b78",
            ["雷矛衛隊需要你的幫助，趕快去參加對抗霜狼氏族的戰鬥吧，$n！和戰士區的布洛岡·石盾談一談，他會幫助你去到奧特蘭克山谷。讚美伊露恩！"] = "a3be30c0db4f2d4b202783dd948834c7",
        },
        [4267] = {
            ["你想要飛往什麼地方？"] = "e9f2c6ae11c08606a3e902729508a45b",
