        [4312] = {
            ["你想要飛往什麼地方？"] = "008491a7c8f31e3556f00e8c3fdc3190",
        },
        [4314] = {
            ["你把我的魚嚇走了！你到底要怎麼樣？"] = "fdcd1e64bf065be3a6c23042d93a5b68",
            ["你看不到我在這裡釣魚嗎？"] = "6d360eae76ce9d8dd443dda348dde45e",
            ["我可以為你做什麼$c？"] = "8954aa5e093a20511ce5bc5c69380aac",
            ["我要一直待在這裡直到釣到68磅重的石斑魚！你卻要離開到什麼地方去，是不是？"] = "618fd179dc62675047c361ba163020cb",
        },
        [4317] = {
            ["你想要飛往什麼地方？"] = "26d3fb863cf374254276fad4c4fb1b43",
