            ["你想要飛往什麼地方？"] = "8ee9e2b8b1fbeba82851331d36cb251c",
        },
        [4419] = {
            ["你好，$c！歡迎來閃光平原觀看賽車！"] = "cf552d2d1ba02525e8fcd3e41003294d",
            ["哥布林的賽車馬力強勁，但地精的賽車也有不少獨到之處……"] = "85279dcb34b8519c4aa585d439098471",
            ["哪個車隊的賽車最快？天知道？！？"] = "f8abb3ccf31041b3183d41a1896f28e3",
            ["歡迎來觀看賽車！希望你喜歡這裡，但請記得不要把錢都下注在同一個地方！"] = "3fda9ba9ead86b9e29b7d1fc68875623",
            ["約翰森不想讓提爾斯知道他還在閃光平原，所以他把自己變成了一隻小雞！$B$B如果你找到約翰森，就向他招招手。說不定他會跑過來的。"] = "818428d85cc2451411dffed3878e6204",
        },
        [4429] = {
            ["你在尋找勇氣？哦，你沒聽到我的話，但是……或許你該問問塔里的科魯克萊德，他會告訴你……"] = "6ca0e5f286f5115ccba86010cc9d19a7",
            ["哈！提爾斯這段時間以來都在找他，但是他不想被找到。他是一隻小雞。"] = "4cf39f0b48e67e4fb4e5d3538ae49f07",
            ["哦，你說的是約翰森？我聽說他躲起來了。"] = "38a01b6277bccedcf3bd8f0506a44706",
            ["如果你問我，那我要說，哥布林的科技更加先進。我們有工具，我們還有天賦！"] = "ef38b09c14f46b5a8dcf5d782c630fd6",
            ["如果我是你，我就賭哥布林贏。壓其他車隊都是在浪費時間。"] = "84067fc993444ce72a27b52f4f74bec4",
            ["我已經把錢壓在哥布林身上了！如果你夠聰明的話也應該賭哥布林獲勝！"] = "8a6ae51d27ab952a233cd6f757870376",
            ["我聽說下一場比賽的時候他們要把地精的車炸掉！不管是真是假，我會待在安全的地方。"] = "0c2296859db21b24eb9910aa4b0c2053",
            ["要不是地精的狗屎運，他們就永遠不會贏！"] = "1707d93334e41f8adae340c8be1bc91a",
        },
        [4430] = {
            ["我的資料分析師認為這次我們會比上次的紀錄提高二十秒！"] = "29cb9f241b67a6bd58f46757f27f6f9e",
            ["我給我們的車裡安裝了新的矩陣式調節器，它可以使賽車的引擎轉速提高至少百分之十五！"] = "bb2e2ac84fdaea93b4cb5f24ace4d539",
            ["我那兩歲的兒子設計的賽車都比那些可笑的哥布林造出來的破爛跑得更快！"] = "5a9bf6255acd34e980aebcd04a7a6def",
            ["約翰森？我認為他在附近的某個地方……"] = "5d227c61a514e3f0b41f912efe022c52",
            ["膽大的約翰森？我聽說塔頂的部落主科魯克萊德知道他在哪兒。"] = "288dfdbe6b0b08a6f2781e22dc5d8ce0",
            ["要不是哥布林的狗屎運，他們每次都會把車撞進山裡去！"] = "413ec8412f752d13ea7d3bc09e39592d",
            ["這些天提爾斯和他的助手都變得怪怪的。"] = "329639fd7e8c50ac0b798afe6c0f563e",
            ["這種車賽是展現我們高新科技的大好機會！"] = "88d6d4700d0a9435deac731bbef17f8c",
        },
        [4488] = {
            ["不，回答我，$N：$B在羅德隆瘟疫爆發之前，是誰變成了巫妖王？"] = "f6f7ba02da1200cdb9a4345823966550",
            ["有人找我談話總是件高興的事兒。事情進展如何，$c？"] = "b219a709c06746dd4308b42ceae14a51",
        },
        [4489] = {
            ["你好，$c。有什麼我能幫忙的嗎？"] = "06ed16ee9dc4b0c6ba6d2eea8e2d58cc",
            ["我想問你，$c：$B在泰坦創造的守護巨龍中，是誰後來變成了被稱作死亡之翼的邪惡生物？"] = "8a2e3ce00848461a788a1c12e87e9577",
        },
        [4498] = {
            ["你好，$c。"] = "9df67739a99bd32b0305f64bf3916331",
        },
        [4542] = {
            ["<大檢察官法爾班克斯拉起他的粗呢大衣露出幾個可怕的疤。>$B$B因為我在那裡...我是大檢察官最信任的顧問。我應該知道... 我感覺到有什麼事不太對勁但我還是容許它發生了。你相信那裡有一千個或更多的天譴軍團嗎？"] = "51188fc10a87cced513453708b5ed8eb",
            ["<大檢察官法爾班克斯搖搖他的頭。>$B$B不...他站在暗處，看著不死軍團突襲我們。很快地，我的力量已經消耗殆盡。我是第一個倒下的人...我無意識地倒在那裡他們當然會把我一塊一塊的肢解；但他們竟完全忽略我，把全部的注意力放在大檢察官身上。"] = "8dc3c54670f0b069274f87a57d834908",
            ["<大檢察官法爾班克斯搖搖他的頭。>$B$B不，$r；他的兒子只有一個死了。其他還活著...$B$B<大檢察官法爾班克斯指向天空。>$B$B外域...到那裡找他..."] = "0405e4235c3c4375d54a46badf6f9a18",
            ["<大檢察官法爾班克斯點點頭。>$B$B是的，小莫格萊尼，也就是血色指揮官，我懷疑 - 他與大十字軍戰士交易。讓他的父親陷入埋伏就像羊入虎口一樣。"] = "c6b0e8d92e327360ee6e22abe88e74a0",
            ["你是說，你不知道？你背上揹著的劍 - 它叫做灰燼之劍；以它原本的主人命名。"] = "5305da0d8750979d1bc134fec6194486",
            ["公爵是十字軍的關鍵人物。是的，莫格萊尼會被稱為灰燼之劍是因為他與巫妖王軍隊對抗的功績。只有劍和信念，莫格萊尼就能走進不死族的軍隊再毫髮無傷的走出來 - 敵人的灰燼不過是證明了他曾在那裡而已。你明白嗎？死亡的臉孔都怕他！我看到他都會顫抖！"] = "5d26127991e8911d63d93013418dcde7",
            ["天譴軍團將屍體在我身上堆起來的時候，假死是我唯一能做的事。我上方只有黑暗和戰爭隱約的聲響。鐵器的碰撞聲，痛苦的咬牙磨牙聲……可怕，恐怖的聲音。然後就一片靜默。他呼叫我的名字！「法爾班克斯！法爾班克斯你在哪裡？回答我法爾班克斯！」然後就聽到一個令我不敢相信的聲音。背叛者的咬噬，$r..."] = "f95886b49c3b646b540936a1c253acc0",
            ["我擔心你手裡握著的那把劍已無法挽救了。仇恨已經太深。但別失去希望，$c。上帝關起一扇窗就會為你開啟另一扇門。$B$B找到他的兒子 - 你永遠也找不到那樣虔誠和忠心的人了。據說他可以不需要舊的那把被玷汙的劍，就能建造一把新的灰燼之劍。"] = "2ec9cfd31d00a8b0299dc181a8190cd6",
            ["是的，我成功了，為了讓小莫格萊尼的罪行得到懲罰，我找到了回血色修道院的路。我大喊大叫。我把故事告訴每一個願意聽的人。我有可能為此被冷血地謀殺，拖進這個組織內無人知道的黑暗祕密。但有些人聽了...有些人聽了我的話。因此產生了銀色黎明..."] = "91edc5312c9d7985a58d5ec06e446c8b",
            ["是的，莫格萊尼公爵：血色十字軍最初的創始人。一個擁有堅定信念和貞潔的騎士；莫格萊尼後來被他自己的兒子背叛並在斯坦索姆裡被科爾蘇加德的軍隊殺害。我就說到這了...."] = "ef7daa42b41400a1595d39af4a6e8762",
            ["是阿比迪斯將軍，大檢察官伊森利恩，和莫格萊尼公爵組成了十字軍。在初期的時候，十字軍是高尚的軍隊。你現在所看到的瘋狂和狂熱行為當時都不存在。直到一個叫做大十字軍戰士的人出現，腐敗的輪子才開始轉動。"] = "49e8b244faaa788e192bdbf757290769",
            ["終於，詛咒被解除了。謝謝你，英雄。"] = "3146d1e3ce619ce4be9719884bfd59d3",
            ["英雄死亡的唯一途徑，$r:是死於悲劇。大十字軍戰士和科爾蘇加德達成協議！他們佈下了一個埋伏陷阱導致莫格萊尼的死。那種背叛是只有最信任最親愛的同伴才有的行為。"] = "351782cc2c2eab075255b02928b70aab",
            ["這是灰燼之劍，蠢蛋！隨著天譴軍團在我們身邊出現，莫格萊尼的劍開始發光...嗡嗡作響...小莫格萊尼把這當作開始逃跑的信號。它們全都飢餓地突擊我們，那是我從未見過的情況。"] = "8e73eebbc5846e6d2b35af2153300f68",
            ["還不夠。$B$B<法爾班克斯淺淺的笑了笑，掉進了回憶的漩渦裡。>$B$B一千個人來一千個人死。是聖光！是莫格萊尼的力量！它們來的有多快他就能多快把它們擊敗。在混亂之中，我注意到小莫格萊尼還在那裡，站的遠遠的。我呼叫他，「幫幫我們，雷諾！幫幫你的父親，孩子！」"] = "e174ab34785ee68b6e6d0710eca52df1",
            ["那個男孩拾起灰燼之劍並且在轉身的時候將劍刺進了他父親的心臟。他最後說的話永遠在我心頭：「你做了什麼，雷諾？你為什麼這樣做？」"] = "bec302f02e2201f067255a714e311fff",
            ["那把劍和莫格萊尼是一個整體。你明白嗎？這樣的行為腐敗了那把劍並讓莫格萊尼自身的腐敗成為科爾蘇加德的死亡騎士。我發誓如果我還活著，我會揭發這項可憎罪行的始作俑者。我仍在天譴軍團的腐敗和感染之下的這兩天 - 聚集越多力量越好一起逃離這個夷平的城市。"] = "53ad3252b278c0ae93d1b6b40ce3adc1",
        },
        [4551] = {
            ["我要如何效勞？"] = "7c8c7304e2aa7ceedcd878cb5540437f",
