            ["我可以教你一些釣魚技能。"] = "7e16cec2614e5f2a337e7a0f19d3b1fb",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "2d7b16d91c48d1f95424bebad9fad5b4",
        },
        [4576] = {
            ["你需要一個真正大師的指導！到塔倫米爾的達瑞爾·斯塔克那兒去試試你的運氣！"] = "219eb27afa3b0d2ddc962f79765170b8",
            ["太好了！我能斷定我的努力不會白費！"] = "094fa5433027839383a3e504a5026efe",
            ["布料也可以。就我個人來說我更喜歡使用人皮。"] = "a28ef0400b8b68493cc0c0bec5e96f56",
            ["當時機合適時，我會傳授知識給你的……不是現在。你還得學習更多的知識！"] = "e8b392cb37c329c537afc0e93b50fbad",
        },
        [4578] = {
            ["在光明與黑暗之間，還有陰影……而那些陰影有些你未曾見過的力量。"] = "32c32b0abd07adc607eabc8dab11e7f6",
        },
        [4582] = {
