            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "a54fabb9fc0936c92134f8611f4e5e8b",
            ["我這個無足輕重的僕人能為你做什麼，$N？需要訓練嗎？"] = "ca5ae8d63433bb1a991ae3a7d4a633fc",
            ["找我有事嗎，$c？"] = "901d3b1160b38eacb61be277a1eab438",
        },
        [4609] = {
            ["你如此大膽地跑來找我，想要接受訓練，我對此可不高興。穿過拱道，沿著坡道向東南方走，跟亡靈馬丁·費爾本談談。他能教你一些基礎知識。"] = "89dfbc51cc4699f0f3e8fbf7cf4a12d8",
            ["到這兒來學習的嗎？很好。我想要是我教你的話，你不會對我們的聯盟造成太多的傷害。只要你一心對付我們的敵人。"] = "5c9cac6d701387d0eb5882649854f365",
            ["我沒有可傳授給你的知識了。穿過拱門走下斜坡到東南方，找赫伯特·哈爾希醫生談談。他是個被遺忘者，他能教給你更加高級的技術。"] = "ef9aaac1e3da49f65602785a177bfb20",
            ["有奧格諾恩提供所需的供應，我可以不用尋找一株草藥就能完成在這裡的任務。如果我永遠都不用再次看到自然的奇跡，這就不會很快發生。"] = "dbd4a28dca16161d9053687453a92060",
        },
        [4611] = {
            ["你的技術太差了，還不能跟我學習。去跟那邊的馬丁醫生談談，或者爬上斜坡到東南方去看看馬許醫生。他們是被遺忘者，可以給你所需的訓練。"] = "183281291d4acd1b6242a8bc12427ef3",
            ["我和我的同伴正在收集我們所知的致命物質，並在敵人身上測試它們的效果。一旦我收集齊備，我將製造出這世界前所未有的瘟疫。"] = "c989bb417bf3ad34f8fec01bb109cf46",
            ["準備好接受訓練了？保持速度，$N。我們要走的路還長著呢。"] = "6785653724e3b6091cc91439955fe110",
            ["難以置信。你配製藥水的技能已經能跟我匹敵了。我不能再訓練你了，去悲傷沼澤找斯通納德的獸人羅格瓦爾談談。他以他的寶刀而聞名。"] = "f578ceea65698599fa038d8a9a944952",
        },
        [4613] = {
            ["歡迎來到幽暗城公會登記處。你需要什麼幫助麼？"] = "3fa902384e7e58171d9d75b73691b44d",
        },
        [4616] = {
            ["不，不，在你準備好跟我學習之前你還需要很多訓練！去跟那個保守的業餘人士瑪考布·威恩談談。他就是那個埋在書裡的人。"] = "0d5d618e483f1cf0c19645c1d8efe716",
            ["好吧，我明白些了。但是，你有潛力，這點我不會否定。多加留心你或許就能學到什麼東西！"] = "bec8ab340577543a45e2fa06872d01b1",
            ["如果我不是天天都陷在這裡，我已經得到訓練你們這些人的技能了！不幸的是事實不是這樣。去找石爪山脈太陽石居所的赫加斯談談。"] = "7217b0d1581a639542adae21f445f93d",
            ["我很少有訪客。你在尋找某種特殊的東西，是嗎？"] = "014b07ee972c5fd050bf0997fe5b94ee",
        },
        [4631] = {
            ["我看見一些有趣的人在港口進進出出。小心，$N。你永遠不清楚誰值得信任以及跟這兒發生的所有事情的緣由……"] = "dcf0c1ee4db440b6fbbc86387f776c61",
        },
        [4730] = {
            ["唉$c，你不是達納蘇斯的貴族，也不是泰達希爾的高等精靈。除非你以實際行動——不僅僅是口頭上的話語——證明自己的友好態度，那樣的話，我會提供馬匹讓你挑選的。"] = "f0e0e0355a74b78bd4d0da79fda2ad22",
            ["承蒙月神的關照，我很高興給你在整個泰達希爾找到的最好的坐騎，甚至是這世上最好的--黑豹。數年來，哨兵部隊一直倚賴這些同伴的價值。$B$B抓緊時間，朋友，挑選一匹你滿意的。我敢肯定你不會失望的。"] = "a781c38bfffdae4147fb52746afd65fc",
        },
        [4731] = {
            ["很高興我能代表皇家藥劑師學會為你提供最好的戰馬。這些戰馬與我們一樣經歷過考驗和磨難，現在它們已經遠勝於那些血肉之軀所鑄成的戰馬了，它們更為強壯，更易恢復精力！好好看看它們吧。"] = "f167e87b57a2b94049d4b806ea806d69",
            ["皇家藥劑師學會對愚蠢的傢伙可沒有耐心，我也一樣。或許下次我們談到戰馬的時候，你會被當作是幽暗城的貴族。到那時……"] = "eef6f7f6fd25d10d8ba7e4fca44b8d27",
        },
        [4732] = {
            ["在我教你騎術之前，你必須達到被暴風城的人類所崇拜的聲望才行，$c。"] = "9821f399d475cf61a0344386783f28f9",
            ["我可以教你騎馬的技巧，只要你有足夠的金幣支付學費！"] = "2b4a5b1134898503d988f837bd4622b7",
        },
        [4752] = {
            ["在我教你騎術之前，你必須達到被奧格瑪的獸人所崇拜的聲望才行，$c。"] = "0ad48a7977bee1530dd7069a59b4a0f0",
            ["我可以教你騎狼的技巧，只要你有足夠的金幣支付學費！"] = "c5b64d59481d597745eaaada6e211af8",
        },
        [4753] = {
            ["在我教你騎術之前，你必須達到被達納蘇斯的夜精靈所崇拜的聲望才行，$c。"] = "950e62db1899a7457b6402427589475d",
            ["我可以教你騎豹的技巧，只要你有足夠的金幣支付學費！"] = "526f461af3793f53ec97bde2843a2b62",
        },
        [4772] = {
            ["在我教你騎術之前，你必須達到被鐵爐堡的矮人所崇拜的聲望才行，$c。"] = "5a3771c3d2bdfebe5e171c408b765d17",
            ["我可以教你騎山羊的技巧，只要你有足夠的金幣支付學費！"] = "5d9316f17b94eb5c320945684a88c12d",
        },
        [4773] = {
            ["在我教你騎術之前，你必須達到被幽暗城的被遺忘者所崇拜的聲望才行，$c。"] = "dcd0a28a88596d37aad3b937bda5ab9f",
            ["我不能教牛頭人騎骷髏馬。很抱歉，我幫不了你什麼忙。"] = "cfd3dc91c0e2de59b41ea2ec7cabbeff",
            ["我可以教你騎骸骨戰馬的技巧，只要你有足夠的金幣支付學費！"] = "2e65eb1fa48fb06278bb020f60a84d34",
        },
        [4885] = {
            ["多年的精心飼養和細緻的品種培育使我能夠有機會向你展示這些良種馬。請慢慢挑選，馬是你長期的夥伴，朋友。不要把自己低估了——今天就在這裡找到你想要的馬！"] = "b2eb329ecae1bc16999a40f0d3b30dc8",
            ["很抱歉，如果你不是暴風城中的貴族，我是不會將馬匹賣給你的。這些戰馬是最好的，我們當然不會當它們落入敵人之手。$B$B想要證明自己不是敵人，當然……你只需贏得暴風城的信任，我就可以跟你做買賣了。"] = "3abbcc0541b691e0b8bbe9d7c11ad032",
        },
        [4895] = {
            ["他給你蜂蜜酒$b$b他給你啤酒$b$b他總是過著快樂的生活$b$b這麼多年他為我們每個人都服務過$b我們叫他微笑的吉姆。"] = "6f8224b4f320e401defad08ad3ce0181",
        },
        [4900] = {
            ["你需要我的幫助？可以。你需要什麼？"] = "953a2f6b83ade3437b2b31391f79f95b",
            ["別那樣看我。我也許跟你不同，我不是個冒險家，但是這並不意味著我的力量比你小。忙碌的生活會讓你的手臂變得強壯的。"] = "b8c5e8911ab1e330ffe50027b082bf9a",
            ["很抱歉，$n，但是我可不在新手身上浪費時間。你得找一個跟自己技能相近的人。去達納蘇斯的工匠區找一個名叫米拉·法拉科納的夜精靈。"] = "b27d8d76ceedb566e8ec960533bf3a52",
            ["我沒有什麼可教你的了。但是，我聽說有位名叫安尼希爾的夜精靈也許能教你。她居住在達納蘇斯的工匠區。"] = "18b7641805b9860312823c6781f21372",
        },
        [4926] = {
            ["人類在貧瘠之地的邊界處建了一座旅店，他們叫它樹蔭旅店。幾個星期前，這家旅店被燒掉了。$b$b酋長讓我們別去搭理那些人類——除非他們越過邊境，不過看來有人違背了酋長的意願。$b$b他讓我負責查明事情的真相。如果你想幫忙的話，就去查看一下樹蔭旅店的廢墟，把你能找到的線索都給我帶回來。"] = "8b40a379be9d0422acd93cc0ce1dd2fe",
            ["人類宣稱塵泥沼澤是他們的領地，但是石錘部族在我們的幫助下將他們趕了回去。"] = "c54732d09cb3a1663d7e277b1364f2bc",
            ["如果雷瑟和樹蔭旅店被燒毀的事有某種聯繫的話，你就得找到他，問個清楚。$b$b我派了奧格隆去追他，應該是朝東南方向去了。去跟奧格隆會合，然後一起去找雷瑟吧。"] = "4d81478e7c4dd7fd2c1d6764a9644265",
        },
        [4944] = {
            ["塞拉摩的衛兵都是原本駐紮在卡林多的聯盟精英力量。即使遠離了家園，但我們還是會努力維護聯盟的律法。"] = "a3944720bf739eea8f6e8620dda9802f",
            ["我們對於樹蔭旅店被焚燒以及詹姆士·海厄爾的妻子和孩子沒能及時逃脫這些事情瞭解得並不多。$B$B我們想要找到詹姆士的屍體，但是他卻根本不在那堆廢墟中。$B$B我們有一些線索，但是證據仍然很缺乏。我們希望能通過衛兵和塞拉摩人民的幫助讓這件慘案得以大白天下。$B$B如果你也想幫忙的話，可以到貧瘠之地的邊境那裡調查一下旅店的廢墟。"] = "c00f3b3d2d31c0618519d6001d85e5e8",
        },
        [4949] = {
            ["<索爾笑了。>$B$B注意……現在專心些，$N。黑龍的母親，奧妮克希亞，從她在暴風城的權位上被推翻了。她已經逃到她在塵泥沼澤的窩裡。$B$B她不能生活在離我們的首都這麼近的地方。我們必須先發制人！$B$B我想要消滅她，$N。"] = "b241537b75e65a8257b769bec9de42b7",
            ["<索爾笑了。>$B$B還有這麼多要學的，$r。$B$B你太年輕了，記不得多年前的戰爭和流血。記不得我們的人民所承受的詛咒的重壓。$B$B我們現在與聯盟的形勢很脆弱。小衝突和小規模戰鬥時常發生，但是仍有和平--我們的人民數千年來未有過的和平。你願放棄這個並把我們再次投入這片混沌中去面對一個新的敵人嗎？這個敵人在毀滅我們之前是不會停手的。"] = "694b0c97e3b67e685f1271af1647e677",
            ["不，$N，你沒有。我沒找你茬，但是你跟年幼的我非常相似：衝動、叛逆、思維缺乏連貫性！這些特點在我身上已經蕩然無存。$B$B悲傷夠了。$R，我有個任務要你完成；或許你會在執行任務過程中喪命。"] = "5aec396019fcdfa270db2683b7040e77",
            ["似乎黑龍的勢力範圍已經超越了燃燒平原，擴展到暴風城了！人們揭下了篡位者的面具並將他流放出境。"] = "656b974c364b6b98a0e3c251f8c80d6d",
            ["在我眼中，部落的所有成員都是平等的，$n。我們的血液被惡魔瑪諾洛斯污染了，人民承受著重負，如果不是為了學識和榮耀的話，我們幾乎就快淪為天譴軍團了。$B$B協助部落，讓我們獲得新生，這是你的職責。但是你也得明白什麼時候應該對朋友同情，對敵人憐憫。$B$B好好理解。這是新生的部落，而不是缺乏自由意願的惡魔軍隊。"] = "9fdeb82237b72e8801030487901e690f",
            ["真的。黑龍之母運用幻象和欺詐術將自己偽裝成貴族法庭的成員。更糟糕的是，現在，她似乎已經控制了暴風城的伯瓦爾·弗塔根公爵。$B$B做出這樣愚蠢的軍事決定不足為奇。聯盟軍隊最近的行動令我們頭疼。現在我們知道，黑龍正試圖分裂帝國——從內部分裂它。"] = "0dffdc856101982122f927ec598e0d13",
            ["碎手已經在黑石的大本營中安插了數名間諜。儘管資訊收集的過程已經慢了下來，但是我們發現了一些不容忽略的現象。"] = "acb7f455459071212f789dd2f7374d82",
        },
        [4967] = {
            ["很高興遇見你，$n。要做的事情還很多，我們必須抓緊時間。"] = "96a3daa8a4f7ab7babfc5a1c8d9f5ca1",
        },
        [4968] = {
            ["亨德爾已經被我們逮捕了，$n。謝謝你。$B$B儘管審訊的進展會比較緩慢，但我向你保證，他會告訴我們他所知道的一切。$B$B現在還請你耐心等待。如果我需要你的幫助，就會馬上聯繫你。$B$B在那之前，請享受塞拉摩之旅，我邀請你作為聯盟的朋友來到我們城市，要待多久隨便你。"] = "a078043dde2955ab1a66ca8a6e5495e0",
            ["歡迎你來到塞拉摩，$n。$B$B我沒時間跟你寒暄，我為自己的唐突向你道歉，但是我必須以城市為首。我們的生活和聯盟的尊嚴受到了嚴重的威脅。要想使我的人民平安幸福，我就必須對不在我們控制之外的力量保持警惕。$B$B或許稍後我們能找時間談談。"] = "6a4b81d7d70a940c7734d52c5bd021ed",
        },
        [4974] = {
            ["歡迎來到暴風城公會註冊辦公室。有什麼需要我幫忙的嗎？"] = "fcf3b1fc15ddd12af2f77de7cacba3b3",
        },
        [4981] = {
            ["暴風城最好的貨物啊，朋友，你絕對不應該錯過。看看有什麼你需要的東西嗎？"] = "0a50227fd4a79a221c5e74147031f06e",
            ["看看我賣的東西吧，有什麼你想要的嗎？"] = "a86de99ac7614f683ab7eab24b0a0b93",
        },
        [5054] = {
            ["我們的祖先教誨說，集體的力量勝過個人的力量。你想要加入公會為了雷霆崖的榮譽而戰嗎？"] = "3e32631ac3a950dee327a67b4a766065",
        },
        [5111] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "e76319f8e0a3393f78b709a653ebd046",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "a4d0603824a832576cec3e3d0e01eb3a",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "970d265673ae5fad5a5c1dc628457490",
            ["你有興趣探索這些地下城中的一個嗎？"] = "036da6474362e31b5c5b8714997221d3",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "41e7446de8a99d017f4dbbef7255bc13",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "b85a4524b031030828761221440ff4cd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "0696ddb759f36db8a31b0de8dfe773e6",
            ["厄運之槌位於菲拉斯的中部。"] = "8bcc27057464ad8295116b381b58f4c4",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "adddbf128dedf6f6ca7aac8e3be5bf92",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "d0b8820f2e1f29977d61ec36fbba4c37",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "7f5e67249a1d4971841ece6127c8d749",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "387741cc6b9473695e470695f72c685c",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "dfbf5c158793a5d635b039bb99fbcd86",
            ["奧達曼位於荒蕪之地最北端。"] = "e395d0b7e6c95518344f6330e935cace",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "c7a772d767a66660e5da8715a151a796",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "e74b227d686c3a09c784a937420b00fc",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "8fb15b22af529953dc80e7257f2df256",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "252356bb3f6f7907c717b8af0e9450c5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "672d1e8529c61b7cd4745f6b33011c68",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "64973aa51308c04b55be79da97ac51f1",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "334b73436ddc4b1bda745af5eb1e4f32",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "327242bcd711775eb7720e35cac612af",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "ecab747cb61959b39b57ef0de545ae6e",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "e9e63692c2220a4c865d9adef19b35e9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "bddcb2f11ff849b592a1d76b4d46b5d1",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "0de78051c05d635c0f53d505687c9a11",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d590cc10020ce147fee1519be78c0e51",
            ["滿上一杯啤酒，拉一張凳子過來坐坐。我們要暢飲一番，同時還要分享我們的故事。"] = "c3684d8296958c5935a2740fa7611b74",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "722216dcb64e2fd4e0adfbec7f5a169e",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1c36c2f9f75af3f1994be97e3fa76600",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "490f61093d0ec9e8887f5611d0dde3c6",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "a6db9e7560aabbf0956453b311a6e920",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "09a72d48b06490f955cd61ccf3e6a038",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "be509dfb481fe127dfd82ad17e93b19e",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "e303428e45f8504ab95951e7cf3b15a5",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "3ca87dd2a1766fe3430d6ece60a54be7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "b5a78d9a4eb2335b05dc3e74b7bf93d2",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "a8a237543c2ca2b43003dda93eb3bc66",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "637ea23cab1a47898f266b7ddbe033ca",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "b1f375bae193622f365bfe78f36e26a6",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "77aa9a2034ff610f83189bb1b5922172",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "e0678027d988e76f5db5e0b28bd5fded",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "d4c8367f7e096bd61f9f2c15a639c5d5",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "b81280ccbca7aa10e3280895aec17ea5",
        },
        [5113] = {
            ["你不是戰士……你在我的訓練課程中會連一天都堅持不下去的！$B$B認為$g他是:她是;一個戰士的$c。哈！"] = "64a04066374cb355ff1adeae11f4ae82",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "31ab172e1a375db1c9157d594eb608d9",
            ["雖然現在是和平時期，但是我們可不能荒廢了我們的戰鬥技能！"] = "ce85977b0f1b155023ca49641a927acd",
        },
        [5114] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "a9083a5c3e3237e00bd856dcc0fd400d",
            ["很好！你達到了要求的參數和規格。我可以為你做些什麼嗎？"] = "bb5e78178b059f89784b631f64c36858",
            ["由於職業的不同，因此我對你缺乏技能的現狀無能為力。"] = "43a1a5f8d367e470a976ff4bba7a35ed",
        },
        [5115] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "125a186cc1dc5f89644a87549bcf2140",
            ["我可以為你做什麼?"] = "9c3f9e8bac3e32fdbb42974f695b0203",
            ["我無法訓練你。你該去找$c訓練者。"] = "50c3dde9457501168f44f5feeb295930",
        },
        [5116] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "31ab172e1a375db1c9157d594eb608d9",
            ["如果你是來接受狩獵技巧訓練的，那你就來對地方了！"] = "41e50470745e1b7a8b43f620b97501b4",
            ["我無法訓練你。你該去找$c訓練者。"] = "65ffa984c80ec793cab656acd848ac8c",
        },
        [5117] = {
