        [5150] = {
            ["倍受尊敬的古斯塔夫·范沃森醫生能進一步訓練你。他就在塞拉摩的兵營裡治療傷兵。"] = "199504472bb3974f17f406ea4b61db6d",
            ["我可以訓練你急救技能。"] = "8af3c5ccd98580aeb1ba4bd7aa80e766",
            ["我聽說藏身在激流堡的德尼布·沃克有一本書，這本書一定能幫助你提高急救技能。"] = "dd4639950203b6deff95ea3d06de8b2e",
        },
        [5153] = {
            ["啊，這件達納蘇斯織品品質最好！"] = "5eab0d76d4ff9ea837e56c38ac2add13",
            ["嗯……看來還有點希望，我會把那個給你的。那好吧，我們在哪裡？"] = "fc2e2e0ae153eab86ed8c1d8e1012b1d",
            ["嗯，你這個聰明的傢伙！我可以明確地告訴你，你知道的比我多！你可別為此自負，如果你想繼續學習的話，就去暴風城找喬吉奧·波利羅談談吧。聽說他是個很好的裁縫！"] = "852840d250a1d2a2cf4c3f13dd2cdfdf",
            ["我可沒時間跟小孩子耗！去跟我的助手阿斯拉談談！"] = "5f5302a774fbbd3527130d5ba986e049",
        },
        [5157] = {
            ["你在開玩笑，是嗎？我認為你在尋找那個矮傢伙，索恩斯·火石。他就在樓下。現在快逃吧！"] = "b10770dd7a0519306cbaf4e55d6acf9f",
            ["你是誰？你想從我這兒得到什麼？"] = "8632fa71e51a2117b8aea60d681a69cd",
