        [5174] = {
            ["你的訓練已經非常深入了。只有一個導師可以進一步地訓練你。找到加基森的巴茲克·布拉斯溫！"] = "7fd261ac07f2ec746da51fd338facc6e",
            ["很好，你已經證明了你自己！現在進入下一階段的授課……"] = "3f10866c8c4a33701d0af2dbef824694",
