        },
        [5938] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "85322120ed7dcca1297d4aab61c178ea",
            ["我可以教你一些釣魚技能。"] = "40d6df5ee6a68543af15fab16ad8ee8e",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "3754efa5bf514e289af226829e49e360",
        },
        [5939] = {
            ["塵泥沼澤蕨牆村的格魯克卡恩在賣指南書，你需要好好研究它來提高自己的技能！"] = "ae13783d5fa12defb8f6b3abb812bdf9",
