        },
        [5953] = {
            ["你可以試著在奧格瑪解決你的問題，就在這裡的北方。或許某個奧格瑪步兵可以幫你。"] = "86bee557234aefc08dffcd603a3140f5",
            ["你在尋找勞迪克。你會在南面的森金村外的暗矛海灘找到他。"] = "bf50f48d66f33ab47551f76d9412f407",
            ["你在尋找米什基。她在森金村南面有一間小屋。"] = "788e53903ca8bd09c088bd1d27efa397",
            ["你在找什麼？"] = "11f7e88f267338a9a8803626e9eb30be",
            ["你得去奧格瑪。出了剃刀嶺沿著北面的道路走，就能到那兒了。跟那兒的守衛談談，他們會給你指明方向的。"] = "a8f60edf1e35fe995876160fbe01d53e",
            ["你應該去找斯瓦特。到剃刀嶺東邊的兵營裡找找看。"] = "96d985b616d9e1814e6fa750a01f0e85",
            ["你應該是在尋找泰金。在城鎮東面的兵營裡可以找到她。"] = "e72ab783318fd9303c927b656da1917d",
            ["你是個獵人？你會發現索塔爾為了躲避太陽就藏在城鎮西南角上的洞穴裡。"] = "1481902397825d866ef861434702b11b",
            ["你會在奧格瑪找到雙足飛龍管理員的。沿著公路向北走到那裡去，並向一個奧格瑪步兵詢問更多指示。"] = "21b93df5517191e6ac378bd3f35e2e19",
            ["你沒看到我很忙嗎?沿著路向北走到奧格瑪並詢問那裡的步兵。你不會錯過的。"] = "1c4d2642c8dbafb4181f864054a4636a",
            ["你為什麼想找卡普拉克談談？沒關係。到剃刀嶺西南角的洞穴頂部找他。不過你一定不要把手放錯地方！"] = "ee3cff8c1213239b77f4d4ebd853af5b",
            ["你能在剃刀嶺東面的兵營後找到杜格魯·血怒。"] = "470b3f07f965638e1e086daec3b41a7d",
            ["你要找什麼技能的訓練師？"] = "bb48a6496b0f939b97d651fb87555c27",
            ["到剃刀嶺東面的兵營裡找到塔紹爾·鋸痕。給部落的年輕人帶去驕傲和榮譽！"] = "abc57ca8b9afe5891d11b478b0678324",
            ["到村莊西南方的洞穴頂部找到卡普拉克。"] = "3f06598ffd8c9999b7f3e6b16011dfc5",
            ["去南方的森金村找米奧贊。"] = "1531e56848a97f6caf0707bde10714be",
            ["去南方的森金村，找安蘇瓦談談。"] = "0dcfd534ad129cf3f8457b6c1054259a",
            ["去城鎮東面的兵營找塔紹爾·鋸痕。"] = "352ae89eeeaac61dcc6845cd9f983cbd",
            ["呃？你可以在奧格瑪找到銀行。沿著道路往北走，跟那兒的守衛談談。"] = "63df14ac6b0e503a51930d85a9b327bd",
            ["呸，那是哥布林的東西！在剃刀嶺有一個獸人可以教你如何製作這些物品。去熔爐附近找穆德拉克吧。"] = "fe9dd394ba942b3b46f201e888e073ce",
            ["哪一項專業？"] = "539255a3b21365ed1ab0beecd22e319f",
            ["嗯……食物。旅途並不遙遠，你需要朝北走，去奧格瑪，問問那兒的守衛。"] = "f3be329749bffcc3c219519d18dac377",
            ["因為我們經常戰鬥，我們當然有一個急救訓練師在剃刀嶺。在城鎮東面的兵營裡可以找到拉烏克。"] = "7a5f9a5c9e1af6b938e8d6fdb50d0765",
            ["在剃刀嶺居住著一名工程學訓練師。他名叫穆德拉克，你在熔爐附近就能找到他。"] = "88e7460445b466f2393737512b4cace7",
            ["在奧格瑪有一名剝皮訓練者。出了剃刀嶺往北走，當你到達奧格瑪時問問那兒的守衛，他們會為你指明方向的。"] = "fa4b7059d45bf0250381ea6aab634c1f",
            ["在奧格瑪有你要找的人。朝著北方走，跟那兒的守衛談談。"] = "e9ff9ec36b22276710cd8fde9ba0ca1f",
            ["在奧格瑪有你要找的人。那兒的守衛會為你指明方向的。朝著北方的道路走，應該不會錯過的。"] = "0e41adb6a7e141e297a7a7af38a7a151",
            ["她名叫泰金，你可以在剃刀嶺東面的兵營中找到她。她會教你如何尊敬神靈的。作為回報，你必須向她表示尊重。"] = "c1a5522c52594a0f7383273d3f3d052b",
            ["如果你認為自己有能力為部落打造武器，就去剃刀嶺西北部，炙熱的熔爐旁找杜克。"] = "a2a68134eb6ead66dec0ff1ea26a3473",
            ["我可以喝點東西，稍事休息。到剃刀嶺西北角，替我向旅店管理人羅斯克問聲好。"] = "5a86f360c8ddfe8d0e1d5b8e50ba194b",
            ["我曾見到一個名叫勞迪克的食人妖在暗矛海灘南部釣魚，就在森金村的週邊。"] = "f531065fd60a051974df176bb74830f1",
            ["我聽說杜洛塔的採礦業極為發達。我們在剃刀嶺有一個採礦訓練師，你可以去城鎮西北角的大熔爐附近尋找克魯恩。"] = "28da34a7dcc4893620bc3f9b17dbed6e",
            ["我聽說森金村的食人妖中有個名叫米奧贊的藥劑師。去那兒找他吧。"] = "252d6ae280f65f0827b5d62b61125ec5",
            ["拉烏克就在剃刀嶺東邊的兵營中。"] = "bab9ae7a3d5ab170b5e4373908683d46",
            ["據我所知，附近沒有這些訓練師。你最好去北方的奧格瑪看看，去問問那兒的守衛。"] = "bad0c10059d93b0ba507c84cd442cad6",
            ["是的，我自己也需要放置一些東西。要找到它你需要向北沿著去奧格瑪的路一直走，然後找那裡的步兵詢問一下。"] = "97ef6bb6459a1144372decbaa9f48cf8",
            ["杜格魯·血怒在城鎮東邊的兵營後面。不要讓我發覺你跟燃燒軍團是一夥的！"] = "14afad71e6f43ebd4897a73651c3acd5",
            ["沿著北邊的道路去奧格瑪。你可以問問那兒的守衛烹飪訓練師在哪兒。"] = "bb526804502f2666b56f5808503d68f7",
            ["為此你需要到奧格瑪去。只需沿著從剃刀嶺出去的路穿過峽谷就會到達那裡。到了那裡,你可以問問步兵以得到進一步的指引。"] = "1c20bee54f940a7ee25ae9b08ddc5bc7",
            ["獵人訓練者名叫索塔爾。去剃刀嶺西南部的洞穴中找他吧。"] = "e71cc318705554503a1fc94f2fb2cf27",
            ["當然，當然。城鎮中有一名採礦訓練師。在旅館旁西北角可以找到克魯恩。"] = "c63f56c09345cbf81c450bfc0e570916",
            ["花？在這片荒蕪的土地上？如果有人能教你如何找到它們，那就是南方的森金村的米什基。"] = "96442a667845894083d0f2231cb79543",
            ["蘇亞米在旅館前面。去吧，我正忙著呢。"] = "95ec5023f7dcbcb96b665624348b5662",
            ["要學習如何處理皮革，你得去北面的奧格瑪。那兒的守衛會告訴你如何找到製皮訓練師的。"] = "480dcbe4bcc183db295991cfcf3e04ef",
            ["要照料寵物嗎？你得確保它的清潔！去旅館前面找蘇亞米吧。"] = "48c83d364a53dcd5c109f0279ac8ef23",
            ["那是剃刀嶺的一幢大建築，而不是兵營。去跟旅店老闆格羅斯克談談。明白了？"] = "0e0f2725e989891e3b1b209b00b6c6ef",
            ["那是杜克。去城鎮西北角炙熱的熔爐附近找他。"] = "68932fb0ffa48a7c03ec6bce0aa873db",
            ["那是食人妖的事兒。去南方的森金村找安蘇瓦。"] = "c09f94f3738012af627ee0ca8e140589",
            ["酋長進行的變革將幫助部落取得勝利！去城鎮東邊的兵營找斯瓦特吧。"] = "12e3380832481755103357bd8e4274e5",
        },
