        [6382] = {
            ["你不是術士而且我沒時間理你。走開！"] = "abe46b983f8b3369ae786ab9b4565c64",
            ["想讓你的惡魔變得更強大嗎？這需要花錢的，但是你來對地方啦。"] = "3b59c956dcfc2045fa9cad04b8290ca9",
        },
        [6497] = {
            ["你要做什麼，$c？我快要遲到了，我的雇主不會給遲到的人好臉色看的。"] = "4d9d8b2efc14201a6e931c1e0c7c9c54",
            ["是的，我是阿斯托·哈德恩。你是？"] = "75ff43dd97408c7355a214344f6383ba",
        },
        [6546] = {
            ["你的使命一定意義非凡，$c，它需要你深入沼澤……"] = "92da45dc1acf7bf8b75facfe52c3b52c",
        },
        [6548] = {
            ["小心一點，$c，我有一個為你準備的變形術……"] = "580054d04eb523be430e4750bc42907f",
        },
        [6566] = {
            ["經瓦里瑪薩斯大人批准，亡靈哨兵的數量增加了。我們將進一步加強打擊敵人的力度。"] = "d727a9a6c19bda725fe90de6453f386d",
        },
        [6568] = {
            ["如果你是個裁縫，維茲格裡克肯定有你想要的東西！隨便看看，$N，想要買什麼東西就和我說！"] = "910ba4b855e200d5675b3e6eabb50a83",
            ["收拾你的行裝，$N！我從灼熱峽谷那邊的尼莉絲·洛克拉夫收到消息說，有個被稱作「黑市組織」的團體正在大熔爐一帶運作。到灼熱峽谷去找到尼莉絲·洛克拉夫，然後把那個黑市組織連窩端掉。"] = "9b4127810f51260020b2c2688447edd5",
        },
        [6586] = {
            ["看啊，竟然有個年輕的$c來看像我這樣的老農夫？"] = "9bf55e6c6132c78f689d4a846edbc4fd",
        },
        [6706] = {
            ["你想要飛往什麼地方？"] = "8ee9e2b8b1fbeba82851331d36cb251c",
        },
        [6707] = {
            ["你是來學習的嗎？"] = "ebd6fd62c633a7ae3b195e93921fd027",
            ["你看我像是個$c嗎？在我決定用你的血洗我的刀之前，趕緊逃吧。"] = "398d385a4c5ff3a4608c1d2ae16a7833",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
        },
        [6726] = {
            ["你想要飛往什麼地方？"] = "008491a7c8f31e3556f00e8c3fdc3190",
        },
        [6727] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "54899ff43d9fa3680bd5231fd54eae44",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "6cc5772934f51d4bcf44e66f9cb19266",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "639f5e4137099522e1302487ff27f679",
            ["你有興趣探索這些地下城中的一個嗎？"] = "9211a5a83384bc6bf667f9e87661f2b5",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "4855c8dab63ff7e92429d6df87b7b3cd",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "ae45cd449d9b601c1faa2ad7d470e04a",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "ae6bac71d95fa9cc576583cb12b00b0a",
            ["厄運之槌位於菲拉斯的中部。"] = "863a0466292f35423e25fb6b1e18e872",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "58d9f5adb0c15d9e359abb8b40a54a91",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "7dc247370c0f46388922e4ad2824f973",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "13d77ffe00e095b4ad42eef5a8aaebfb",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "b69ededa6dbdfe26a15fda5121e90a20",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "97a393e1ef12dc1fe4a4b55e63c2c620",
            ["奧達曼位於荒蕪之地最北端。"] = "4324821d63a3f73937dd5abffe6fdf7f",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "a25c5d7842af31618a063b3d3ce15fed",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "8e4dcb74091e2e615d506f3ec7d147ca",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "17d13be0366794572061fb3fbb409ee6",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b960d46bc6e1afd8a8048e75631efeb5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "4a0636d96305a16097c01ed6971f7971",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "cd40129110d4c4917a537fef57180329",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d9516bdeb534c80940a3be1f4600bf04",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "4bcf2a35fd98e48b3cd346ec97dccde8",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "0f7f53045dc845e1ab759203cc598d30",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8b063ee787233090be02c8d7fc8e58a7",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4d1835c423b0ee4a6773a1481ea2d03e",
            ["歡迎來到我的旅店，疲憊的旅行者。我能為您做點什麼嗎？"] = "db570f1f51f6fd3b1a42e5953bafd049",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "cce75935af7718f82fcb4c3d13f23020",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "75ed2903e0af8abe0c91025f4d1a631e",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "b32b2b77a0839ff8c1415be4d2623dd9",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "44f65d16974643e3b29f727a67787ad0",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "0838f3fe0e3c17a16a7ff7d504eec929",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "9f470e7a9c62fa04faeb58fd3b1d6de9",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "9f8d7c84b3cbfc322f53a0a242de804e",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "5521f2e5d2e37d7012ea87b75badcb01",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "fe604977d24d31743e5481d5dcda2e88",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2da51ca0be53ce695776bbe3e3eea8c7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "1e16c8ae0545b101ebc5ad4d9c69c248",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "e118425d7cca455fae7064446900535b",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "44fdd52098e4ecaeddc946e101d7c60f",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "4414ebedf67147d4801e58071b11c237",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "2d41c6e84da0f60aa520a4acc8919f87",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "7beb3ee244d9c85c277537d4ba4a2fe1",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "e4835262a6e71a36692d90aedbb66c42",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "3644fa36f35ecdc5947046c71b54837a",
        },
        [6729] = {
            ["我以前曾經追尋過暮光之錘的道路。為了找到復活上古之神的方法，我隻身深入這座巢穴，想要找到從那個該死的惡魔阿庫麥爾身上抽取能量的方法。$B$B在看到無數無辜人白白地犧牲之後，我慢慢恢復了理智。$B$B我被困住了一段時間，但是現在我自由了！不幸的是，這裡離我的家鄉卡茲莫丹太遠了！$B$B勇敢的冒險者，我現在可以將你傳送到一個特別的地方，然後回來幹掉阿庫麥爾。如果你願意的話，我現在就送你到達納蘇斯去。"] = "4057eacacb0243ce014c6ce4af544682",
        },
        [6734] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "e76319f8e0a3393f78b709a653ebd046",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "a4d0603824a832576cec3e3d0e01eb3a",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "970d265673ae5fad5a5c1dc628457490",
            ["你有興趣探索這些地下城中的一個嗎？"] = "036da6474362e31b5c5b8714997221d3",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "41e7446de8a99d017f4dbbef7255bc13",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "b85a4524b031030828761221440ff4cd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "0696ddb759f36db8a31b0de8dfe773e6",
            ["厄運之槌位於菲拉斯的中部。"] = "8bcc27057464ad8295116b381b58f4c4",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "adddbf128dedf6f6ca7aac8e3be5bf92",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "d0b8820f2e1f29977d61ec36fbba4c37",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "7f5e67249a1d4971841ece6127c8d749",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "387741cc6b9473695e470695f72c685c",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "dfbf5c158793a5d635b039bb99fbcd86",
            ["奧達曼位於荒蕪之地最北端。"] = "e395d0b7e6c95518344f6330e935cace",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "c7a772d767a66660e5da8715a151a796",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "e74b227d686c3a09c784a937420b00fc",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "8fb15b22af529953dc80e7257f2df256",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "252356bb3f6f7907c717b8af0e9450c5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "672d1e8529c61b7cd4745f6b33011c68",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "64973aa51308c04b55be79da97ac51f1",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "334b73436ddc4b1bda745af5eb1e4f32",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "327242bcd711775eb7720e35cac612af",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "ecab747cb61959b39b57ef0de545ae6e",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "e9e63692c2220a4c865d9adef19b35e9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "bddcb2f11ff849b592a1d76b4d46b5d1",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "0de78051c05d635c0f53d505687c9a11",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d590cc10020ce147fee1519be78c0e51",
            ["滿上一杯啤酒，拉一張凳子過來坐坐。我們要暢飲一番，同時還要分享我們的故事。"] = "c3684d8296958c5935a2740fa7611b74",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "722216dcb64e2fd4e0adfbec7f5a169e",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1c36c2f9f75af3f1994be97e3fa76600",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "490f61093d0ec9e8887f5611d0dde3c6",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "a6db9e7560aabbf0956453b311a6e920",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "09a72d48b06490f955cd61ccf3e6a038",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "be509dfb481fe127dfd82ad17e93b19e",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "e303428e45f8504ab95951e7cf3b15a5",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "3ca87dd2a1766fe3430d6ece60a54be7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "b5a78d9a4eb2335b05dc3e74b7bf93d2",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "a8a237543c2ca2b43003dda93eb3bc66",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "637ea23cab1a47898f266b7ddbe033ca",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "b1f375bae193622f365bfe78f36e26a6",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "77aa9a2034ff610f83189bb1b5922172",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "e0678027d988e76f5db5e0b28bd5fded",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "d4c8367f7e096bd61f9f2c15a639c5d5",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "b81280ccbca7aa10e3280895aec17ea5",
        },
        [6735] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "3334d2c3be49af24ec80966cd3044afb",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "90657c7dd9fc98c4960a8c613e7e0841",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f3dc300ddc1883b724afefb742b27c54",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f70c987e98c43a9ac4f1ef6eb271008a",
            ["你看起來很疲憊。在我們的屋裡休息一會兒吧，讓伊露恩引領你進入甜美的夢鄉。"] = "88ed28bad52992326e81df54efce5146",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "25a80704f18ee56676b132bdded0fe94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "9cdbd4512dccbc458675c5216058ddcd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "bbbb6f1884cdacec9af6cb67e3e1abd4",
            ["厄運之槌位於菲拉斯的中部。"] = "89054fe6fb8e52df563c9e80702c264a",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "d34171a9fbd911b8f1bf818f71cc3f32",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4b24ea6b391a2efd0be7d84cc947d159",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "310fe6a22db0bf2928c1ff8e5c70cd20",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5d076554d313584aa1c5611cf0129a23",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "24cd799771f287be14f8060e5444dfa5",
            ["奧達曼位於荒蕪之地最北端。"] = "36de161eff379c5060e7c2e31cdc975a",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "cac489d41abedaef7c5d7041fd7492e3",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "136e146f620b6e7197755a682b68ce84",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "6f1db228470e4b9d299edd3c7168c063",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "7bef92afa79765ff95f06d3660786a79",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "530c2f46cebb57733cec5f86ad8383d3",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "8d0c3e032d49fe079017a90965f53922",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "fd70ec87881856186158a19c159addb7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "94fa40981e2a4d5c4b4b0b68b37f782c",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8f49377bcf39a38a76d2cf7cbacbefb0",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4352ca0c9a3782df4f9b0a23c9c7f9d7",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "c14eefa9bf01ea21ee6c512a62f5270c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "e33d4e6573f24d17efcc2b0ecf76516d",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "6679f691680afda8b76a2dd04f2e7144",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1d59940e7ccbee60370a304b33835f99",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "b19764fa4b6d3a891fa5f750b3dd2517",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "f9432ed28b2dabcd595eddb702af9ca1",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "10e3746148a7f37b2c1af2d199833368",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "927f2bfc50de1f03c38ac6ec3198f4a7",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "78e6008fbf1d737dce7812540853511c",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "54bd2c1a937b1392327adbdf92ce5e6d",
            ["諾姆瑞根在丹莫洛的西邊。"] = "a4f613548f3f5a63415a978d891ce475",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3b08e6def8fe2881c84a302e3f4c7fea",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "03ee214820f246ccc4e751c56c822ace",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "7eddf733901dbca29a5a21752dd1ceb4",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "0e3148ee13bdc4aad5af84663b24d1ce",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "aab40b74860886caa96dcfdaf979e180",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "9c2b22f32a137854d984166b2aaded4b",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "8f57f5e81f55defd22e287d36b233496",
        },
        [6736] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "0789e7725e4ff57368345676b97c69e0",
            ["你看起來很疲憊。在我們的屋裡休息一會兒吧，讓伊露恩引領你進入甜美的夢鄉。"] = "148fa5ae499d6ca296b84150cc89d456",
            ["你能在旅店裡幹什麼？$B$B當你待在旅店裡的時候，你就可以好好地休息。因此,你可以比留在野外更快地恢復到充分休息的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以通過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你綁定的旅店裡了。"] = "c7e55aa073464fb6fc032bafb7831820",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "3313dba78a012ba4676cf839b5eb1d01",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "1bffe8fb139ab3981216edf20a4c8dc6",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "19fc47266ecfc50f255dedad859cb0f3",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "c2155d74f1f593e4a89afbbf967b68b1",
        },
        [6737] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "3334d2c3be49af24ec80966cd3044afb",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "90657c7dd9fc98c4960a8c613e7e0841",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f3dc300ddc1883b724afefb742b27c54",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f70c987e98c43a9ac4f1ef6eb271008a",
            ["你看起來很疲憊。在我們的屋裡休息一會兒吧，讓伊露恩引領你進入甜美的夢鄉。"] = "88ed28bad52992326e81df54efce5146",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "25a80704f18ee56676b132bdded0fe94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "9cdbd4512dccbc458675c5216058ddcd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "bbbb6f1884cdacec9af6cb67e3e1abd4",
            ["厄運之槌位於菲拉斯的中部。"] = "89054fe6fb8e52df563c9e80702c264a",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "d34171a9fbd911b8f1bf818f71cc3f32",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4b24ea6b391a2efd0be7d84cc947d159",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "310fe6a22db0bf2928c1ff8e5c70cd20",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5d076554d313584aa1c5611cf0129a23",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "24cd799771f287be14f8060e5444dfa5",
            ["奧達曼位於荒蕪之地最北端。"] = "36de161eff379c5060e7c2e31cdc975a",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "cac489d41abedaef7c5d7041fd7492e3",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "136e146f620b6e7197755a682b68ce84",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "6f1db228470e4b9d299edd3c7168c063",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "7bef92afa79765ff95f06d3660786a79",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "530c2f46cebb57733cec5f86ad8383d3",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "8d0c3e032d49fe079017a90965f53922",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "fd70ec87881856186158a19c159addb7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "94fa40981e2a4d5c4b4b0b68b37f782c",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8f49377bcf39a38a76d2cf7cbacbefb0",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4352ca0c9a3782df4f9b0a23c9c7f9d7",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "c14eefa9bf01ea21ee6c512a62f5270c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "e33d4e6573f24d17efcc2b0ecf76516d",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "6679f691680afda8b76a2dd04f2e7144",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1d59940e7ccbee60370a304b33835f99",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "b19764fa4b6d3a891fa5f750b3dd2517",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "f9432ed28b2dabcd595eddb702af9ca1",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "10e3746148a7f37b2c1af2d199833368",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "927f2bfc50de1f03c38ac6ec3198f4a7",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "78e6008fbf1d737dce7812540853511c",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "54bd2c1a937b1392327adbdf92ce5e6d",
            ["諾姆瑞根在丹莫洛的西邊。"] = "a4f613548f3f5a63415a978d891ce475",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3b08e6def8fe2881c84a302e3f4c7fea",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "03ee214820f246ccc4e751c56c822ace",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "7eddf733901dbca29a5a21752dd1ceb4",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "0e3148ee13bdc4aad5af84663b24d1ce",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "aab40b74860886caa96dcfdaf979e180",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "9c2b22f32a137854d984166b2aaded4b",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "8f57f5e81f55defd22e287d36b233496",
        },
        [6738] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "3334d2c3be49af24ec80966cd3044afb",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "90657c7dd9fc98c4960a8c613e7e0841",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f3dc300ddc1883b724afefb742b27c54",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f70c987e98c43a9ac4f1ef6eb271008a",
            ["你看起來很疲憊。在我們的屋裡休息一會兒吧，讓伊露恩引領你進入甜美的夢鄉。"] = "88ed28bad52992326e81df54efce5146",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "25a80704f18ee56676b132bdded0fe94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "9cdbd4512dccbc458675c5216058ddcd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "bbbb6f1884cdacec9af6cb67e3e1abd4",
            ["厄運之槌位於菲拉斯的中部。"] = "89054fe6fb8e52df563c9e80702c264a",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "d34171a9fbd911b8f1bf818f71cc3f32",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4b24ea6b391a2efd0be7d84cc947d159",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "310fe6a22db0bf2928c1ff8e5c70cd20",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5d076554d313584aa1c5611cf0129a23",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "24cd799771f287be14f8060e5444dfa5",
            ["奧達曼位於荒蕪之地最北端。"] = "36de161eff379c5060e7c2e31cdc975a",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "cac489d41abedaef7c5d7041fd7492e3",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "136e146f620b6e7197755a682b68ce84",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "6f1db228470e4b9d299edd3c7168c063",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "7bef92afa79765ff95f06d3660786a79",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "530c2f46cebb57733cec5f86ad8383d3",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "8d0c3e032d49fe079017a90965f53922",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "fd70ec87881856186158a19c159addb7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "94fa40981e2a4d5c4b4b0b68b37f782c",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8f49377bcf39a38a76d2cf7cbacbefb0",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4352ca0c9a3782df4f9b0a23c9c7f9d7",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "c14eefa9bf01ea21ee6c512a62f5270c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "e33d4e6573f24d17efcc2b0ecf76516d",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "6679f691680afda8b76a2dd04f2e7144",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1d59940e7ccbee60370a304b33835f99",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "b19764fa4b6d3a891fa5f750b3dd2517",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "f9432ed28b2dabcd595eddb702af9ca1",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "10e3746148a7f37b2c1af2d199833368",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "927f2bfc50de1f03c38ac6ec3198f4a7",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "78e6008fbf1d737dce7812540853511c",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "54bd2c1a937b1392327adbdf92ce5e6d",
            ["諾姆瑞根在丹莫洛的西邊。"] = "a4f613548f3f5a63415a978d891ce475",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3b08e6def8fe2881c84a302e3f4c7fea",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "03ee214820f246ccc4e751c56c822ace",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "7eddf733901dbca29a5a21752dd1ceb4",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "0e3148ee13bdc4aad5af84663b24d1ce",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "aab40b74860886caa96dcfdaf979e180",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "9c2b22f32a137854d984166b2aaded4b",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "8f57f5e81f55defd22e287d36b233496",
        },
        [6739] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "a1c3340c748bfd2a378997d42cba3570",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "f6e7182f2b831d3e98ea00acd3a557b4",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "3f25eaca37dd5ce3380c10c71eac60c2",
            ["你有興趣探索這些地下城中的一個嗎？"] = "488213bad6a40fbf7079b51dde4826ad",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "2391b5317315d4d4a8941b336ba01d82",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "a92e7dde31e809f1b96a4d8f50c2d96e",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "df15192a7814812aa87b737075049c7f",
            ["厄運之槌位於菲拉斯的中部。"] = "69d5225f370d5873a20086b12494e196",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "19478f299bf1f913ecdd844a7b1ec37c",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4af8645fc89247fb0892c4705462e74d",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "c57a00c42fdfecf52c42b66d787bc1cd",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5561946a80fa1778f731cd1da49a7f21",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "fa92810b103689a5e9744a90f05b45f4",
            ["奧達曼位於荒蕪之地最北端。"] = "d3b374cc078d522b47d39d918bf336ae",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "4bad438e187701f17fab5db0369bfa7e",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "2531cc395d4ced6a637c04f1ab1619dd",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "b2f4c438fc5d7bb524d33db32a8d464d",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "2f5d6341d44b8829dd7f6f1dd2237ef3",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "c27212ba1429be052be892df280bdc70",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "acf39d2dcbeb2bb9768b8299a999e831",
            ["放鬆一下自己疲倦的身心。"] = "cf5c0c6563faca35ab89050ffaff07a3",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "0815aba74c3a70d73e32cc5365b4babf",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "7daf3bd91cab3bbe4b086b50a641371d",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "4d9fe927578f203ba1f939866e8eb07f",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "70c1e67468aaeaa3a549f39f40b0750e",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "5a0c8734a5baf412a3c8a6ea7f840971",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "cc9cfe1577ac40fdf30626ca38853f4c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d23384c474fd5420239b53802a4cb878",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "355f0eaf3e41bbd9ac2b4927dd3ae00d",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "465cf8b7ffede50d2c9d078908c27ebf",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "81a3af904e5e838f33cd0c337609ca1e",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "febd2c30f0ceec03812a46456d34b870",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "cec5376f55346bfe3dc2c2cc3e7250df",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "35f023a0322674670e5742c64f6dde74",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "918ba333b33ba169bd8203f33cbfdeb1",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2bd1ba7a047b7f12cd181339448588cc",
            ["諾姆瑞根在丹莫洛的西邊。"] = "45400c7ff98d6669e16f6f738a544da2",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "ffbcb214f8bde35165c1e81f0262353a",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "a99bd805ffc7f479b01c1f060c183d80",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "990feb669a320e4a8ee851b5411d8ac2",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "95e0ef5ee5d277942310d2636ab0068b",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "14d2c5e49f0b36f12cb7480a8300476a",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "f3796e44c383e2f2dab079058435a9e6",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "e8cfd96680fc3ab29c2ca67c5e6131f3",
        },
        [6740] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "54899ff43d9fa3680bd5231fd54eae44",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "6cc5772934f51d4bcf44e66f9cb19266",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "639f5e4137099522e1302487ff27f679",
            ["你有興趣探索這些地下城中的一個嗎？"] = "9211a5a83384bc6bf667f9e87661f2b5",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "4855c8dab63ff7e92429d6df87b7b3cd",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "ae45cd449d9b601c1faa2ad7d470e04a",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "ae6bac71d95fa9cc576583cb12b00b0a",
            ["厄運之槌位於菲拉斯的中部。"] = "863a0466292f35423e25fb6b1e18e872",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "58d9f5adb0c15d9e359abb8b40a54a91",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "7dc247370c0f46388922e4ad2824f973",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "13d77ffe00e095b4ad42eef5a8aaebfb",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "b69ededa6dbdfe26a15fda5121e90a20",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "97a393e1ef12dc1fe4a4b55e63c2c620",
            ["奧達曼位於荒蕪之地最北端。"] = "4324821d63a3f73937dd5abffe6fdf7f",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "a25c5d7842af31618a063b3d3ce15fed",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "8e4dcb74091e2e615d506f3ec7d147ca",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "17d13be0366794572061fb3fbb409ee6",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b960d46bc6e1afd8a8048e75631efeb5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "4a0636d96305a16097c01ed6971f7971",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "cd40129110d4c4917a537fef57180329",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d9516bdeb534c80940a3be1f4600bf04",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "4bcf2a35fd98e48b3cd346ec97dccde8",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "0f7f53045dc845e1ab759203cc598d30",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8b063ee787233090be02c8d7fc8e58a7",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4d1835c423b0ee4a6773a1481ea2d03e",
            ["歡迎來到我的旅店，疲憊的旅行者。我能為您做點什麼嗎？"] = "db570f1f51f6fd3b1a42e5953bafd049",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "cce75935af7718f82fcb4c3d13f23020",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "75ed2903e0af8abe0c91025f4d1a631e",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "b32b2b77a0839ff8c1415be4d2623dd9",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "44f65d16974643e3b29f727a67787ad0",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "0838f3fe0e3c17a16a7ff7d504eec929",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "9f470e7a9c62fa04faeb58fd3b1d6de9",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "9f8d7c84b3cbfc322f53a0a242de804e",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "5521f2e5d2e37d7012ea87b75badcb01",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "fe604977d24d31743e5481d5dcda2e88",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2da51ca0be53ce695776bbe3e3eea8c7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "1e16c8ae0545b101ebc5ad4d9c69c248",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "e118425d7cca455fae7064446900535b",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "44fdd52098e4ecaeddc946e101d7c60f",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "4414ebedf67147d4801e58071b11c237",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "2d41c6e84da0f60aa520a4acc8919f87",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "7beb3ee244d9c85c277537d4ba4a2fe1",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "e4835262a6e71a36692d90aedbb66c42",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "3644fa36f35ecdc5947046c71b54837a",
        },
        [6741] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "a1c3340c748bfd2a378997d42cba3570",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "f6e7182f2b831d3e98ea00acd3a557b4",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "3f25eaca37dd5ce3380c10c71eac60c2",
            ["你有興趣探索這些地下城中的一個嗎？"] = "488213bad6a40fbf7079b51dde4826ad",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "2391b5317315d4d4a8941b336ba01d82",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "a92e7dde31e809f1b96a4d8f50c2d96e",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "df15192a7814812aa87b737075049c7f",
            ["厄運之槌位於菲拉斯的中部。"] = "69d5225f370d5873a20086b12494e196",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "19478f299bf1f913ecdd844a7b1ec37c",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4af8645fc89247fb0892c4705462e74d",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "c57a00c42fdfecf52c42b66d787bc1cd",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5561946a80fa1778f731cd1da49a7f21",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "fa92810b103689a5e9744a90f05b45f4",
            ["奧達曼位於荒蕪之地最北端。"] = "d3b374cc078d522b47d39d918bf336ae",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "4bad438e187701f17fab5db0369bfa7e",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "2531cc395d4ced6a637c04f1ab1619dd",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "b2f4c438fc5d7bb524d33db32a8d464d",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "2f5d6341d44b8829dd7f6f1dd2237ef3",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "c27212ba1429be052be892df280bdc70",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "acf39d2dcbeb2bb9768b8299a999e831",
            ["放鬆一下自己疲倦的身心。"] = "cf5c0c6563faca35ab89050ffaff07a3",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "0815aba74c3a70d73e32cc5365b4babf",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "7daf3bd91cab3bbe4b086b50a641371d",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "4d9fe927578f203ba1f939866e8eb07f",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "70c1e67468aaeaa3a549f39f40b0750e",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "5a0c8734a5baf412a3c8a6ea7f840971",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "cc9cfe1577ac40fdf30626ca38853f4c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d23384c474fd5420239b53802a4cb878",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "355f0eaf3e41bbd9ac2b4927dd3ae00d",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "465cf8b7ffede50d2c9d078908c27ebf",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "81a3af904e5e838f33cd0c337609ca1e",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "febd2c30f0ceec03812a46456d34b870",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "cec5376f55346bfe3dc2c2cc3e7250df",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "35f023a0322674670e5742c64f6dde74",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "918ba333b33ba169bd8203f33cbfdeb1",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2bd1ba7a047b7f12cd181339448588cc",
            ["諾姆瑞根在丹莫洛的西邊。"] = "45400c7ff98d6669e16f6f738a544da2",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "ffbcb214f8bde35165c1e81f0262353a",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "a99bd805ffc7f479b01c1f060c183d80",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "990feb669a320e4a8ee851b5411d8ac2",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "95e0ef5ee5d277942310d2636ab0068b",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "14d2c5e49f0b36f12cb7480a8300476a",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "f3796e44c383e2f2dab079058435a9e6",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "e8cfd96680fc3ab29c2ca67c5e6131f3",
        },
        [6746] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "67e679105237aa46ee7a3409ef1a68c5",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "42f5d7a2dd2fde374bdefa0c10701256",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "90068fa43ca357ef9462599be9d006a4",
            ["你有興趣探索這些地下城中的一個嗎？"] = "ccda04db92cbf011d170b7cae60f408c",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "5a6a13f324242e75a6382d99c516cc94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "12c27bc52b107697f8de364f8dae7e3c",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "18f70be5c25cb2ea163cd8d518bfdc66",
            ["厄運之槌位於菲拉斯的中部。"] = "ce805aa1448186ce4794258c3cdc704e",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "af31a346608dbddcecea7edc85e314ff",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "331713e1070e9f4f3576819f670ae53d",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "87b9ad9eca23dfe66c987d93b54bc51b",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "c08a11a40b198a8cdf5e21127dad1408",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "4b98c70ede6bd8cb80bc9ebb78fd4f9a",
            ["奧達曼位於荒蕪之地最北端。"] = "556878b84c0292b45d666060cb90b770",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "bc7a0c38334a3cb0cabf4faf3d793a87",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "7baa3037efa4e58f77af6f15cb527593",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "fb940c5b0393c3fd43e9e2df8f5562a8",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "d332f132dad158e7271d0f14c19ec73d",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "c2be634e5a50af657e4346af05a183dc",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "9d86f89304affdeae5264f879da84304",
            ["我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。"] = "980ce6cc828845cb13bcbd8cd0b6917e",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "3124bcbc877a9654486099bdcbfb0eef",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "1dafad1d0d57bc8653d5c2c7d35c4a07",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "d9ac47630828a00f0b09464fc66c51ec",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "298b92e58115d14cb1cd1b4ff6278556",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "af82564cf7ae1fe402a33ef253cb74cc",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "4c620133d97c2f350972b761b3dc491d",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d33cc3248fefbb1f1925c215048cf29b",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "7f40e2c7a99505ba4995ee282dfc6836",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "4c47373b8dd57eabb9791705a594084f",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "63f35b75e396252f797a4186f1286bee",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "9160ee289a277af5bf427091078afc51",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "a704e4b5607d1ef64f5d23e8fd7983c1",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "7bf5800aefb381b3ab9369dbae519ad1",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "6197d9bec6a3e8059bca553e1ceac8b1",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "86adf50ebffcdaae0b2e044333b6e69a",
            ["諾姆瑞根在丹莫洛的西邊。"] = "d44d297c2cca8733f4d13c8c8c1f28d5",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "dd975c8f89f30ab9b769be5964cf632f",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "d7a63e33070adb319c75b51cca5b23b6",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "0b35ae40cc764b63340a0d3431fca136",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "55c6bd57311ef599eca95a97025087e1",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "06eb7bd37fd0c212607efd69ff668e03",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "4b2a582cee1f20d593eae9a388287135",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "a8ecc7056b89cefc7b67cdb06c5db362",
        },
        [6747] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "a70be99ff08d4df4c93b09b77588a051",
            ["你能在旅店裡幹什麼？$B$B當你待在旅店裡的時候，你就可以好好地休息。因此,你可以比留在野外更快地恢復到充分休息的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以通過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你綁定的旅店裡了。"] = "cd4dc163ef49a6f5e9f2e1e9c61ec79f",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "d208c04226b80a24f1f58b9d6011d18c",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "f108787b96326f0485800f2468879b89",
            ["我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。"] = "a98c33cf2b0c65fb09a0b00d67122e46",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "84004ad843c4e25945ff9c41c2c64e48",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "40835d72adb6d19a66d4db7eaf7b44e6",
        },
        [6766] = {
            ["你並未得到拉文霍德公爵的認可，$c。"] = "e414479d7e112a24e4ee47c568f2914a",
            ["你好，$c。你找法拉德談過了嗎？"] = "5fc8a171cfb31942883d032ece558b20",
            ["你真的變得狡猾多了，$n。"] = "21bb13a7f298a61dbf47d64106d4e6ac",
            ["很榮幸再次看到你，$n。"] = "0554addc6a4f76eb2e7ded959562d585",
            ["很高興再次見到你，$n。"] = "f425284ed646293e04e52dadcab348c5",
            ["我想之前西蒙尼找過你，$N。你跟她談過了嗎？"] = "d519fc238c0d5762c8390aa9c05d3188",
            ["辛蒂加工會的成員都是些平庸的傢伙——缺乏組織性、技能拙劣、懶惰……"] = "2d46251ef009b85c2f7a0d08c926ed85",
            ["陌生人，小心身後。"] = "81d62566a55e8b5a5e0eb06e933d7a75",
            ["魯莽的傢伙。拉文霍德公爵可不喜歡這樣的人。"] = "7c18a505d74d7f81d3aa7e4a1fdefca5",
        },
        [6771] = {
            ["不借助刀具或是毒藥離開這兒就算完成任務。"] = "b56f7d7e17228c7846fd0614b535f631",
            ["不可思議。太不可思議了。你給了我們啟迪，$n。"] = "043d2239097f1a9dd04f652e7f01f075",
            ["你一直進行得不錯，$N。我聽到好消息了……"] = "e5da524ba41d32170463455cafed48e5",
            ["你敢踏入拉文霍德莊園，可憐蟲？"] = "356d2f6aeda9087735082d9d27eccbf0",
            ["你該與溫斯頓談談。我聽說他在尋找一個與你有相同技能的盜賊。"] = "6c7ad021c0414bbc450d1003829fa86b",
            ["我真羡慕你，$n。你做得太出色了。"] = "d6853e06cead9ccc1834d2216de22df7",
        },
        [6790] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "54899ff43d9fa3680bd5231fd54eae44",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "6cc5772934f51d4bcf44e66f9cb19266",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "639f5e4137099522e1302487ff27f679",
            ["你有興趣探索這些地下城中的一個嗎？"] = "9211a5a83384bc6bf667f9e87661f2b5",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "4855c8dab63ff7e92429d6df87b7b3cd",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "ae45cd449d9b601c1faa2ad7d470e04a",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "ae6bac71d95fa9cc576583cb12b00b0a",
            ["厄運之槌位於菲拉斯的中部。"] = "863a0466292f35423e25fb6b1e18e872",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "58d9f5adb0c15d9e359abb8b40a54a91",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "7dc247370c0f46388922e4ad2824f973",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "13d77ffe00e095b4ad42eef5a8aaebfb",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "b69ededa6dbdfe26a15fda5121e90a20",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "97a393e1ef12dc1fe4a4b55e63c2c620",
            ["奧達曼位於荒蕪之地最北端。"] = "4324821d63a3f73937dd5abffe6fdf7f",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "a25c5d7842af31618a063b3d3ce15fed",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "8e4dcb74091e2e615d506f3ec7d147ca",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "17d13be0366794572061fb3fbb409ee6",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b960d46bc6e1afd8a8048e75631efeb5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "4a0636d96305a16097c01ed6971f7971",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "cd40129110d4c4917a537fef57180329",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d9516bdeb534c80940a3be1f4600bf04",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "4bcf2a35fd98e48b3cd346ec97dccde8",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "0f7f53045dc845e1ab759203cc598d30",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8b063ee787233090be02c8d7fc8e58a7",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4d1835c423b0ee4a6773a1481ea2d03e",
            ["歡迎來到我的旅店，疲憊的旅行者。我能為您做點什麼嗎？"] = "db570f1f51f6fd3b1a42e5953bafd049",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "cce75935af7718f82fcb4c3d13f23020",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "75ed2903e0af8abe0c91025f4d1a631e",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "b32b2b77a0839ff8c1415be4d2623dd9",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "44f65d16974643e3b29f727a67787ad0",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "0838f3fe0e3c17a16a7ff7d504eec929",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "9f470e7a9c62fa04faeb58fd3b1d6de9",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "9f8d7c84b3cbfc322f53a0a242de804e",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "5521f2e5d2e37d7012ea87b75badcb01",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "fe604977d24d31743e5481d5dcda2e88",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2da51ca0be53ce695776bbe3e3eea8c7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "1e16c8ae0545b101ebc5ad4d9c69c248",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "e118425d7cca455fae7064446900535b",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "44fdd52098e4ecaeddc946e101d7c60f",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "4414ebedf67147d4801e58071b11c237",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "2d41c6e84da0f60aa520a4acc8919f87",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "7beb3ee244d9c85c277537d4ba4a2fe1",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "e4835262a6e71a36692d90aedbb66c42",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "3644fa36f35ecdc5947046c71b54837a",
        },
        [6791] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "75ea614fc57c253ef85a8ca820840f01",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "c2f38f12a7e864fbd106f38b24ac9ae5",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f72872aa3c1f9640babf7c3e4bffc628",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f4fe586e247e052e76cecae1d47adb94",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "20a4628b9b8b27f0e7e3e970ab291b7e",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "bc464d5efb2c3497f6fed7199c1cfaab",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "882eca086e7584677b84ddb2508635b3",
            ["厄運之槌位於菲拉斯的中部。"] = "a2a75e750e7c08308d8d391046fdb1f3",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "c19593e4ca62db318364bbe01231c7b4",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "7d5abd50243eecd2ff36633a9410b8ea",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "9bf1215eec4b2029ecbc5375d28c476f",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "1a6bf101d9b37ef4919e0a556e52c071",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "e22278d3fcd3a8f181fc314a3cf6a9a5",
            ["奧達曼位於荒蕪之地最北端。"] = "588ff0a57842e20c72269ee0501523fb",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "7a683a98c8dc49d9ba4f01f8fc2b2c11",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "64465cd067c291e811a60e365d036a07",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "d37fad5160b1ce1e446d89683995346f",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b46ab47e855a9968ec405b35a8255b41",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "ccdd31e5c57e00ec629ea21dfbac34e0",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "10c9748e8a8c0c5f22f50c95108b8101",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "3fec7afe1fa52e91615f06103d743c2d",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "de30340f0f1e3452d19e8b3db3520427",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "13f411422b98e7aa9efa1bd8d0fe3cc0",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "48f006ccf62588c28676790cb39677d9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "f82b5fb869ffa62d622507892591005c",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "925eb79c2a5840bebb65045e96e8b3a9",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "f3d998a9d0f165f6d8fa11bdb08d17f4",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "2d0ff7282384f166fee8f5812a46b907",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "87ceed08e7766069a0854b8bfeb59834",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "cbf722b9bc6acfc449c54911b738ba7a",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "0bee11bcb44ddba0c9f3d82fe4a7f412",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "53641f8a6d8703d5b32055eeae035202",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "a740ad34c3f45ba2e78f50e08ca1f1a2",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "d474a00379211864f62928a7a5408575",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "aaac33ca3b463f55c01e35a907d1d27e",
            ["請進，請進！不要坐得離火爐太近。它今天還沒爆炸，但是為了安全起見，我想你還是坐在別的地方比較好。"] = "4254fccc29e33d29bc22201a35c7d40d",
            ["諾姆瑞根在丹莫洛的西邊。"] = "7a98a6957f6b0f4f5b616f085bcbbc4f",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "4686c688bccad5e4e3600624db8e96a6",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "ff8b1db8360117b5bdb53aab8beec5c0",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "6abc40b0f13fa9364f217f02b8debe3c",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "a9c1b950e4ae1b02f42877ff18e4c1d9",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "c137bec18fa851ba9519cbc0582526a8",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "be2a049bfff27090d42fa86864cded42",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "5a436be58dba22f48b69234cde719196",
        },
        [6807] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "75ea614fc57c253ef85a8ca820840f01",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "c2f38f12a7e864fbd106f38b24ac9ae5",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f72872aa3c1f9640babf7c3e4bffc628",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f4fe586e247e052e76cecae1d47adb94",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "20a4628b9b8b27f0e7e3e970ab291b7e",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "bc464d5efb2c3497f6fed7199c1cfaab",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "882eca086e7584677b84ddb2508635b3",
            ["厄運之槌位於菲拉斯的中部。"] = "a2a75e750e7c08308d8d391046fdb1f3",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "c19593e4ca62db318364bbe01231c7b4",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "7d5abd50243eecd2ff36633a9410b8ea",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "9bf1215eec4b2029ecbc5375d28c476f",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "1a6bf101d9b37ef4919e0a556e52c071",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "e22278d3fcd3a8f181fc314a3cf6a9a5",
            ["奧達曼位於荒蕪之地最北端。"] = "588ff0a57842e20c72269ee0501523fb",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "7a683a98c8dc49d9ba4f01f8fc2b2c11",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "64465cd067c291e811a60e365d036a07",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "d37fad5160b1ce1e446d89683995346f",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b46ab47e855a9968ec405b35a8255b41",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "ccdd31e5c57e00ec629ea21dfbac34e0",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "10c9748e8a8c0c5f22f50c95108b8101",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "3fec7afe1fa52e91615f06103d743c2d",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "de30340f0f1e3452d19e8b3db3520427",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "13f411422b98e7aa9efa1bd8d0fe3cc0",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "48f006ccf62588c28676790cb39677d9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "f82b5fb869ffa62d622507892591005c",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "925eb79c2a5840bebb65045e96e8b3a9",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "f3d998a9d0f165f6d8fa11bdb08d17f4",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "2d0ff7282384f166fee8f5812a46b907",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "87ceed08e7766069a0854b8bfeb59834",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "cbf722b9bc6acfc449c54911b738ba7a",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "0bee11bcb44ddba0c9f3d82fe4a7f412",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "53641f8a6d8703d5b32055eeae035202",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "a740ad34c3f45ba2e78f50e08ca1f1a2",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "d474a00379211864f62928a7a5408575",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "aaac33ca3b463f55c01e35a907d1d27e",
            ["請進，請進！不要坐得離火爐太近。它今天還沒爆炸，但是為了安全起見，我想你還是坐在別的地方比較好。"] = "4254fccc29e33d29bc22201a35c7d40d",
            ["諾姆瑞根在丹莫洛的西邊。"] = "7a98a6957f6b0f4f5b616f085bcbbc4f",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "4686c688bccad5e4e3600624db8e96a6",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "ff8b1db8360117b5bdb53aab8beec5c0",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "6abc40b0f13fa9364f217f02b8debe3c",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "a9c1b950e4ae1b02f42877ff18e4c1d9",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "c137bec18fa851ba9519cbc0582526a8",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "be2a049bfff27090d42fa86864cded42",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "5a436be58dba22f48b69234cde719196",
        },
        [6826] = {
            ["嗯，你好！如果你是來徵收費用或者投遞傳票的，那你一定是將我認作別人了。非常抱歉！"] = "d4c9e9254b58f83f6eca1b0cbdffb037",
        },
        [6928] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "bf1f16f2143ef5e7d61ef40727a86228",
            ["你能在旅店裡幹什麼？$B$B當你待在旅店裡的時候，你就可以好好地休息。因此,你可以比留在野外更快地恢復到充分休息的狀態，這樣就可以獲得更多的經驗值。$B$B另外你還可以通過和旅店老闆交談來獲得一塊爐石，以後就可以使用這塊爐石快速回到你綁定的旅店裡了。"] = "2c1d9480e123f8e1e386e141a695f2a7",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "7c8c35f7332064fb990b18d3a0864176",
            ["如果我們要成為這塊新地區的主人，那麼我們就必須要找個地方好好休息。把你的斧頭放在火邊，讓大家分享你英勇戰鬥的故事吧。"] = "5a6da618c793e9258ef0c0f097380291",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "205467c00f8ce22c4506e988def469d8",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "ab1b05dce1379cc50a508ec75bc5fecf",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "14c79166424db4748000943061c77fa3",
        },
        [6929] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "608e80af556ec1f3d3baef7e57f6be28",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "0276ff49074261ee804b38342793bf84",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "799c250c21ae02bcb1dbb537a38580f9",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f3aba6e9ee464fd9569a3498cd66780a",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "22e76f151640be474a52357149eab9fa",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "5bb22872b7638f5085ca2059018cc5ff",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "d204a8a00341a429174e0dbb644ab882",
            ["厄運之槌位於菲拉斯的中部。"] = "59afccdff32f76ae9879d7192bc79e60",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "73249f674e33dc5e663d9bf0dc9c96b6",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "356949e6616d911ef559b61355e02894",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "f92aaab1f1d5835cf040d33a901f8ac6",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "12f0b7117e82d1920705e38b1acbd4d3",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "c2a3a1e19674bf1fea64aea4440edb67",
            ["奧達曼位於荒蕪之地最北端。"] = "72fd07384c9cf3d35d09b60e74ac757b",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "533b295b436d39d2d08b9a0010da7943",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "11667b0ff9532331158f6482eeb8d71d",
            ["如果我們要成為這塊新地區的主人，那麼我們就必須要找個地方好好休息。把你的斧頭放在火邊，讓大家分享你英勇戰鬥的故事吧。"] = "99898ce989e2387123a310f8e8bb7094",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "149d727e2252ad2d21626074d67ae0be",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b589ee74b06baa0850c27cb5b2dced61",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "470d4f471ff0e0a695c417d93294115b",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "65a26145712718ab736d0dff25b7ea3a",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "50d79c7aeabf3cffea9b701bf10738f2",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "04642b49605c1905f8c4ec074ed814b2",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "1362d50a99d5220c57eabff16d1c603a",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "5a680486b1eed5318ac671810b927e65",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "c5bb28585e4ec2284a09cc538e5ea938",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "45dbe29f976fe7758380dadfd1b0d5ec",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "839365eaa1b7bc650b1f66d477413bef",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "ba011425ec6ef2499c76a0df8538827b",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "73717c12f946e4832d3760a4ce017d6e",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "598c9e84f0150f5804083fb81cddb144",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "661c2fbcff67197ca647909d6eff45c0",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "39d92fa9357e241705910cea426d1baf",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "bac84ba209bd32f334399053e2f4b16f",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "3549cdf0ffdc4b960c88a13a92c251c5",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "b4ca0c190cfd0a68f67e69a9ad1ec76b",
            ["諾姆瑞根在丹莫洛的西邊。"] = "2a62241f7676852d758c2bff35cb1c86",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3ea6a13fe8e0d78eb57bd98488901e1a",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "210c73367be3bd7fff9c76683b08beeb",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "e68483a569e848b8cb7bca2cf17765d1",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "31b8782bafa771a039b08f6726b827a8",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "42c37076d3ae3863acfdd2d0f5533f7a",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "1a4b0ce90f4422503651666ac7f00711",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "12696642ffca20488693f012a1332369",
        },
        [6930] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "bf1f16f2143ef5e7d61ef40727a86228",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "28b7a10d1e6ce776b39a99b0bc3c5729",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "ceb9382c049e7883f6c2dc8d6da3a10f",
            ["你有興趣探索這些地下城中的一個嗎？"] = "5e09760e17cbc670577373cc3a58f914",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "b70df0c6d8237e82e8eab2e2cee97a1c",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "1cdc3bb3780b30bc1ddb25b3e96eeb14",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "bcc93e0f69a610e26e8a585d15e236ca",
            ["厄運之槌位於菲拉斯的中部。"] = "bdfe4126b453f140f54062473872a072",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "05939f53ff53a01d686ad496340f942e",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "f4ce8cc991dc9b8e53cbf5bafea7a20e",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "d564123ed4c19b647a19fe0e225ccf19",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "b710141cbfed33e4215f9f02e57b1285",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "a2cdf3bd1e979b72e72bfd012d8e4475",
            ["奧達曼位於荒蕪之地最北端。"] = "1e99d4a52530cf7eb53974fecc40f331",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "249672700d6d8eaf3dddfa4944dabb7e",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "7c8c35f7332064fb990b18d3a0864176",
            ["如果我們要成為這塊新地區的主人，那麼我們就必須要找個地方好好休息。把你的斧頭放在火邊，讓大家分享你英勇戰鬥的故事吧。"] = "5a6da618c793e9258ef0c0f097380291",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "d75d5996d34c833b6779a3d6dd1d88f9",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "36de4eae7af9c2c85092cd5d9a784b46",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "cc776f517441c1a0c836afb225bdd955",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "205467c00f8ce22c4506e988def469d8",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "c91ac29b4dfab5d21de4af780478b04c",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "b338594106da41470eef31ea3c010d21",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "8cdbbc96d739b730ea3dd0482497fe79",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "468d4c8dd235c155a2382b74b82c2fa9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "53cfb8044c1292d233012d45237f180d",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "0bf530934f14695fb55ada3fb2991a79",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "695bffa496e17bf3ace18949095a965e",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "ffe6e6b7dd79a36fe035046b6c7524ad",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "dd38277dbccc541afb09092db925b6ab",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "ab1b05dce1379cc50a508ec75bc5fecf",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "14c79166424db4748000943061c77fa3",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "8ac7e0587a2cc50e68b7e657694ea364",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "bb800825ab4ca9a41793034fb343efdc",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "1ea4f7d4103e7f106c8b166cdb5e3649",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "de7e05a695ddb55f1f262b0dbebab57a",
            ["諾姆瑞根在丹莫洛的西邊。"] = "a28655b7a8d174f6fdec53c01d3eecef",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "aabd6bce4c7708c67d5b606f86e7331d",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "ef2ed86b87eea6787b3f9ed237bc7e6d",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "f67a76e0fd2826ef6fe57add373eec1e",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "ff16bb066f168df220edae5bdae69e4f",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "3b1d31e904b1fb9f4e2857c66fa8c682",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "727cf38438acf58ee35c39f6a28aa289",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "fa04ae9ff435e1e999be4418d11dc7a4",
        },
        [7010] = {
            ["現在是危險時分，$r。遠古的邪魔復活了，他可不會管你是部落還是聯盟。"] = "9fdec023d3ece5864f7f1093641f767e",
        },
        [7207] = {
            ["我能幫忙嗎？"] = "c51c67b1156baa959f6271d3c07c8740",
        },
        [7230] = {
            ["$n，我已經看到了你的潛力。現在拿上錘子準備開工吧，你需要大量的練習才能提高自己的水準。"] = "1504f6272a4a6bdb32cf07a5ac0a1ca4",
            ["我不會訓練一點水準都沒有的鐵匠，等你覺得自己達到我的要求之後再回來找我。"] = "be96c2d28873ad67329f21c88b5b2951",
        },
        [7231] = {
            ["什麼事？你沒有看到我很忙嗎？"] = "9bcd5c13bc9092dc86335cce9a910f76",
        },
        [7232] = {
            ["你真的那麼笨嗎？你鍛造出來的是什麼東西？那最多算得上是一把水果刀罷了。我可不會花時間來訓練一個菜鳥。"] = "ad3e0242a5d45f7ec83537662ced020e",
            ["難道你看不出我現在很忙嗎？有什麼事？"] = "e6c5b185db0ab91fad6f55b0165ec6de",
        },
        [7311] = {
            ["你好。我是一個食人妖法師訓練師，而你不是一個法師。"] = "a00980ecb8395b0505372dca056eaa2c",
            ["你好。我是一個食人妖法師訓練師，而你是一個法師。"] = "6b1a193f6fbb18a8cee6d3dd3a706b63",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "5016339405f25a1000a29e26a0caf19c",
        },
        [7312] = {
            ["你好。我是一個地精法師訓練師，而你不是一個法師。"] = "a3abb68c7dc7f0e59d1317d10b3a97cd",
            ["你好。我是一個地精法師訓練師，而你是一個法師。"] = "89ebbfb158e8bcf8fa80f49f22684c37",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "a9083a5c3e3237e00bd856dcc0fd400d",
        },
        [7315] = {
            ["你好。你想要學一些戰鬥技巧嗎？"] = "45a2136a6992d2a4bd174e0b70ed104b",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "30ee103c545f987ab518c70f6d3e640e",
            ["孩子，我看不出你具備戰士的精神。我不會訓練你這樣的$c的。"] = "cc54bded9c0ad342e3ec1eb23083d5f2",
        },
        [7406] = {
            ["你好，$g小夥子:姑娘;……我是奧格索普，你擁有的某件地精設備很可能就是我發明的！如果它爆炸了，那它就不是我發明的；如果它給你帶來了財富，那我們可以討論一下版權金的問題！$B$B哦，對了，如果你來自諾姆瑞根，那你可以走了。我沒有什麼跟你好說的。"] = "47c3755d412dea585d1a4ce936b47720",
            ["哦，這不是$N嘛！很高興再見到你，我無法表達我對你的感激之情，你幫我及時完成了發明。$B$B我能為你做什麼事嗎？"] = "5943501ff09a6c083506a7484daf7d10",
        },
        [7410] = {
            ["希望你是來奧特蘭克山谷作戰的，$n。我們會竭盡所能，利用一切援助。"] = "42f1caebaf844b8ea5857f33ff4dbb1d",
            ["很抱歉，$c，但是在你變得更有經驗之前，我不能讓你去奧特蘭克山谷送死。"] = "f78c3c41a85a94fe125292149c2763de",
        },
        [7427] = {
            ["很抱歉，$c，但是在你變得更有經驗之前，我不能讓你去奧特蘭克山谷送死。"] = "28e0c95afd7e31800b8af63190876fb8",
            ["我們在奧特蘭克山谷的軍隊需要運用謀略才能獲勝，$c。你看起來是個不錯的領導者。"] = "0a2b21f41e7f09ad9d22fa7dc12ffe45",
        },
        [7564] = {
            ["$N，你好。"] = "1d3cd34903e040de6b0c73c1aa2fb0df",
            ["嗯，既然你提及了這一點，不錯，昨天下午我確實看見了奇怪的事情！$B$B當我從東南方的食人妖廢墟處跑過時……好吧，我其實不是跑過去的，應該說是跳過去的……沙地真是太燙了！$B$B總之，當我從廢墟旁跳過的時候，我注意到那兒有一座營帳。我不得不說，在那兒設立營帳是件可笑的事兒……我本來要到那裡去看看的，但是一隻瘋狂的大禿鷲把我趕走了。"] = "2240dd2ff7335d7ff456813bd7964a8f",
        },
        [7572] = {
            ["作為索爾手下最強大的二十名戰士，我們被稱為索爾近衛軍。$B$B在等待奧格瑪的命令時，我要求在詛咒之地邊境建立一座營地。但是數星期過去了，酋長那裡還是沒有任何消息傳來，我們開始變得有些焦躁不安了。$B$B$N，那是個錯誤的決定。我曾經年輕而又雄心勃勃，無所畏懼。這支部隊在我的指揮下開進了詛咒之地。$B$B不久之後我就開始後悔了。"] = "246b857180cfb8d95954fa06f7183c80",
            ["你和我都無法想像當他們的靈魂被強行從軀體中剝離出來的時候有多麼痛苦。他們沒有死，但是他們也不是活著的。他們成為了一具具行屍，只會聽從主人發號施令。$B$B幹出這些慘絕人寰的事情的就是這裡的惡魔首領拉瑟萊克，他把我的戰友都變成了奴隸。其中的九個被他綁定在黑暗之門附近，其餘的九個則被他的爪牙們瓜分。"] = "e80fa3ad4ec81953dd42b32b58f4bb3d",
            ["你能相信作為精英戰士的我居然失敗了嗎？$B$B我們的部隊被無法抗拒的力量徹底摧毀，我所記得的一切就是不顧一切地逃跑，我所聽到的一切只有我的戰友撕心裂肺的慘叫和我自己的心跳。$B$B過了不久，我又回到了詛咒之地，希望能拯救我的夥伴。但是我被抓住了，最後被活活打死。$B$B這段日子中，我所能感受到的只有恐懼。"] = "7e860e6ffee6f60c2945a58e828890a1",
            ["大法師奧利斯塔，術士瑟溫妮，還有巨魔戈洛爾，他們各自分配到了三個。$B$B$N，你要知道，如果沒有靈魂，我的戰友是無法被殺死的。他們現在都處於一種無敵的狀態。幸好的是，他們不能離開禁錮之石太遠的距離。"] = "7c2918df60afd41688a7500c519a965f",
            ["很難想像如此多的死亡和恐懼會彙集在那麼小的一塊地區中。在這些門後是一塊充斥著混亂和毀滅的大陸。$B$B冒險者，你要非常小心謹慎才行。詛咒之地中到處都是可以讓你喪命的強大生物。"] = "3df1e6bc0bb085364a05607f4fcd932b",
            ["後悔。這就是現在我所能感受到的一切。一個錯誤的決定導致了如此災難性的後果。我多麼希望當時能多等幾天，直到命令傳來。也許那樣我們就能事先知道這片被詛咒的土地上到底有多少恐怖的東西等著我們！也許這一條命令就能指引我們去另外一個方向！無論怎麼樣，這都是我的錯。所有的一切都是我造成的。"] = "bde2d9c0c5ebfdc5d27951fa01622b41",
            ["我想你真的可以幫我，$N，但是單憑你的力量是無法和拉瑟萊克以及他的爪牙抗衡的。$B$B你一定要找到一支足夠強大的隊伍來解救我的戰友，讓他們脫離無盡的痛苦！你總共要摧毀十八塊石頭。$B$B努力地去戰鬥吧，$n。"] = "5e971f209953fa012b86635a05f6932d",
            ["我被抓之後遭受了非人的虐待，$n。他們輪番拷打我和基利斯中尉，而且在虐待一方的同時讓另外一個在旁邊看著。我們不斷被折磨，直到有一天基利斯告訴把戰友們的遭遇告訴了我，還有他的拯救計畫。$B$B他們所遭受的痛苦比我和基利斯所遭受的還要多，他們真的是生不如死。"] = "17112182a94dae91af72cf8bb58dde4b",
            ["那些禁錮之石就是你要去摧毀的東西！正如我剛剛所說的，基利斯有一個完整的計畫。$B$B每個被奴役的戰士都有一個弱點，你必須儘量攻擊他們，直到他們的實體形態幾近瓦解。這時禁錮之石就會變得非常脆弱。你一定要抓緊時間摧毀禁錮之石，否則不久之後，那些奴隸又將獲得新的力量，並再次變得刀槍不入了。"] = "3a9fc293da7b2666f2755c04e234a703",
        },
        [7683] = {
            ["歡迎你，$c。如果你有什麼問題，儘管來問我。"] = "e64b23275f5f92fd2f9a00db491593ba",
        },
        [7714] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "a70be99ff08d4df4c93b09b77588a051",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "5d58291140199149e578fcbfbeed18cf",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "2d70ab98f838e1bb06030fcf93158968",
            ["你有興趣探索這些地下城中的一個嗎？"] = "a61f3b373d7747d0767475c1b5dab2f6",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "b07c8c68897f70867bbb75e49138b18d",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "8960494e8735de52e731bccc5622764d",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "1efdcf0d1f0182cadd7e556c2271b952",
            ["厄運之槌位於菲拉斯的中部。"] = "3e983a22901faae3beabe07a57c404e1",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "473bac4f85c8b79c1dd5b392e510c6c1",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "5f4d64e508e2e540625383eeae8529e5",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "a3c3d767ea37682d4d5d32cdda15eb9e",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "131cac36cbe3c50c8b0b73b5a5cc8e31",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "a5bb313bf3bd25a50fb0157cbb68e362",
            ["奧達曼位於荒蕪之地最北端。"] = "af158d110faf65cf2c8cfe5981eddc3e",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "991c35a1c8f32e2d36fef5a051a928bf",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "d208c04226b80a24f1f58b9d6011d18c",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "15cc28e6650ead1cf3c24a21428162eb",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "5699ecf40556711f57d029b802122744",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "579d342215c9b859125b292dde81b3dd",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "f108787b96326f0485800f2468879b89",
            ["我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。"] = "a98c33cf2b0c65fb09a0b00d67122e46",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d3df88e9b21fb13e7181cf562fb15e42",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "a68c695060e8db92a6407dbd039e03c7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "134711fa5dcb6d2514b7dd12cb58353f",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "5d241a73257b83bfb3f2a35e6c559cb8",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "1631876c10990f6b69fb643f319f15da",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "2761a549194820781531b07e3ccf0a6f",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "ec90c3b20200ec711da3c83a7d439020",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "ee0633ddb8208d730c4a1f7e2f75724f",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "b08c334deb14a22220d649a65f3c74fa",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "84004ad843c4e25945ff9c41c2c64e48",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "40835d72adb6d19a66d4db7eaf7b44e6",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "97df9679462d394c9c8acea3163a1db4",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "f469edb565c0b095a0fc47a970c24323",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "9d99c94eab41fbb7d5d8577ea1ef5b17",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2669d18d8bca0062b048b5b892ff56be",
            ["諾姆瑞根在丹莫洛的西邊。"] = "3a31427822c5fa1a87c7a675bd12855e",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "7f35f35703d028305ee4d76b181b5fac",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "2ace78d92e3daa88d503880d61a8825e",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "4d0ece2f2228a1a4c22ff7047c560d51",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "421a85045f22b0366436f5c512836a4b",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "105703cf3292f20db785559210529138",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "d1d167264b852e04dcc247504cad2f84",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "9607305c9027305933951bfdb21a86f2",
        },
        [7731] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "608e80af556ec1f3d3baef7e57f6be28",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "0276ff49074261ee804b38342793bf84",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "799c250c21ae02bcb1dbb537a38580f9",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f3aba6e9ee464fd9569a3498cd66780a",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "22e76f151640be474a52357149eab9fa",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "5bb22872b7638f5085ca2059018cc5ff",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "d204a8a00341a429174e0dbb644ab882",
            ["厄運之槌位於菲拉斯的中部。"] = "59afccdff32f76ae9879d7192bc79e60",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "73249f674e33dc5e663d9bf0dc9c96b6",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "356949e6616d911ef559b61355e02894",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "f92aaab1f1d5835cf040d33a901f8ac6",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "12f0b7117e82d1920705e38b1acbd4d3",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "c2a3a1e19674bf1fea64aea4440edb67",
            ["奧達曼位於荒蕪之地最北端。"] = "72fd07384c9cf3d35d09b60e74ac757b",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "533b295b436d39d2d08b9a0010da7943",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "11667b0ff9532331158f6482eeb8d71d",
            ["如果我們要成為這塊新地區的主人，那麼我們就必須要找個地方好好休息。把你的斧頭放在火邊，讓大家分享你英勇戰鬥的故事吧。"] = "99898ce989e2387123a310f8e8bb7094",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "149d727e2252ad2d21626074d67ae0be",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b589ee74b06baa0850c27cb5b2dced61",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "470d4f471ff0e0a695c417d93294115b",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "65a26145712718ab736d0dff25b7ea3a",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "50d79c7aeabf3cffea9b701bf10738f2",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "04642b49605c1905f8c4ec074ed814b2",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "1362d50a99d5220c57eabff16d1c603a",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "5a680486b1eed5318ac671810b927e65",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "c5bb28585e4ec2284a09cc538e5ea938",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "45dbe29f976fe7758380dadfd1b0d5ec",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "839365eaa1b7bc650b1f66d477413bef",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "ba011425ec6ef2499c76a0df8538827b",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "73717c12f946e4832d3760a4ce017d6e",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "598c9e84f0150f5804083fb81cddb144",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "661c2fbcff67197ca647909d6eff45c0",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "39d92fa9357e241705910cea426d1baf",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "bac84ba209bd32f334399053e2f4b16f",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "3549cdf0ffdc4b960c88a13a92c251c5",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "b4ca0c190cfd0a68f67e69a9ad1ec76b",
            ["諾姆瑞根在丹莫洛的西邊。"] = "2a62241f7676852d758c2bff35cb1c86",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3ea6a13fe8e0d78eb57bd98488901e1a",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "210c73367be3bd7fff9c76683b08beeb",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "e68483a569e848b8cb7bca2cf17765d1",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "31b8782bafa771a039b08f6726b827a8",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "42c37076d3ae3863acfdd2d0f5533f7a",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "1a4b0ce90f4422503651666ac7f00711",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "12696642ffca20488693f012a1332369",
        },
        [7733] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "75ea614fc57c253ef85a8ca820840f01",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "c2f38f12a7e864fbd106f38b24ac9ae5",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f72872aa3c1f9640babf7c3e4bffc628",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f4fe586e247e052e76cecae1d47adb94",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "20a4628b9b8b27f0e7e3e970ab291b7e",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "bc464d5efb2c3497f6fed7199c1cfaab",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "882eca086e7584677b84ddb2508635b3",
            ["厄運之槌位於菲拉斯的中部。"] = "a2a75e750e7c08308d8d391046fdb1f3",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "c19593e4ca62db318364bbe01231c7b4",
            ["啊,一個來訪者！肯定是一個冒險家，沒有多少遊客會走這條路的。坐下來喝一杯飲料吧，隨便些。嗨，你看起來好像還有些肉。你想參加比賽嗎？"] = "74292ac4ab48ee5809d5e8f84bf11e28",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "7d5abd50243eecd2ff36633a9410b8ea",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "9bf1215eec4b2029ecbc5375d28c476f",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "1a6bf101d9b37ef4919e0a556e52c071",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "e22278d3fcd3a8f181fc314a3cf6a9a5",
            ["奧達曼位於荒蕪之地最北端。"] = "588ff0a57842e20c72269ee0501523fb",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "7a683a98c8dc49d9ba4f01f8fc2b2c11",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "64465cd067c291e811a60e365d036a07",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "d37fad5160b1ce1e446d89683995346f",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b46ab47e855a9968ec405b35a8255b41",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "ccdd31e5c57e00ec629ea21dfbac34e0",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "10c9748e8a8c0c5f22f50c95108b8101",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "3fec7afe1fa52e91615f06103d743c2d",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "de30340f0f1e3452d19e8b3db3520427",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "13f411422b98e7aa9efa1bd8d0fe3cc0",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "48f006ccf62588c28676790cb39677d9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "f82b5fb869ffa62d622507892591005c",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "925eb79c2a5840bebb65045e96e8b3a9",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "f3d998a9d0f165f6d8fa11bdb08d17f4",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "2d0ff7282384f166fee8f5812a46b907",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "87ceed08e7766069a0854b8bfeb59834",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "cbf722b9bc6acfc449c54911b738ba7a",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "0bee11bcb44ddba0c9f3d82fe4a7f412",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "53641f8a6d8703d5b32055eeae035202",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "a740ad34c3f45ba2e78f50e08ca1f1a2",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "d474a00379211864f62928a7a5408575",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "aaac33ca3b463f55c01e35a907d1d27e",
            ["諾姆瑞根在丹莫洛的西邊。"] = "7a98a6957f6b0f4f5b616f085bcbbc4f",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "4686c688bccad5e4e3600624db8e96a6",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "ff8b1db8360117b5bdb53aab8beec5c0",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "6abc40b0f13fa9364f217f02b8debe3c",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "a9c1b950e4ae1b02f42877ff18e4c1d9",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "c137bec18fa851ba9519cbc0582526a8",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "be2a049bfff27090d42fa86864cded42",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "5a436be58dba22f48b69234cde719196",
        },
        [7736] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "3334d2c3be49af24ec80966cd3044afb",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "90657c7dd9fc98c4960a8c613e7e0841",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f3dc300ddc1883b724afefb742b27c54",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f70c987e98c43a9ac4f1ef6eb271008a",
            ["你看起來很疲憊。在我們的屋裡休息一會兒吧，讓伊露恩引領你進入甜美的夢鄉。"] = "88ed28bad52992326e81df54efce5146",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "25a80704f18ee56676b132bdded0fe94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "9cdbd4512dccbc458675c5216058ddcd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "bbbb6f1884cdacec9af6cb67e3e1abd4",
            ["厄運之槌位於菲拉斯的中部。"] = "89054fe6fb8e52df563c9e80702c264a",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "d34171a9fbd911b8f1bf818f71cc3f32",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4b24ea6b391a2efd0be7d84cc947d159",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "310fe6a22db0bf2928c1ff8e5c70cd20",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5d076554d313584aa1c5611cf0129a23",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "24cd799771f287be14f8060e5444dfa5",
            ["奧達曼位於荒蕪之地最北端。"] = "36de161eff379c5060e7c2e31cdc975a",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "cac489d41abedaef7c5d7041fd7492e3",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "136e146f620b6e7197755a682b68ce84",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "6f1db228470e4b9d299edd3c7168c063",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "7bef92afa79765ff95f06d3660786a79",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "530c2f46cebb57733cec5f86ad8383d3",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "8d0c3e032d49fe079017a90965f53922",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "fd70ec87881856186158a19c159addb7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "94fa40981e2a4d5c4b4b0b68b37f782c",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8f49377bcf39a38a76d2cf7cbacbefb0",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4352ca0c9a3782df4f9b0a23c9c7f9d7",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "c14eefa9bf01ea21ee6c512a62f5270c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "e33d4e6573f24d17efcc2b0ecf76516d",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "6679f691680afda8b76a2dd04f2e7144",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1d59940e7ccbee60370a304b33835f99",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "b19764fa4b6d3a891fa5f750b3dd2517",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "f9432ed28b2dabcd595eddb702af9ca1",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "10e3746148a7f37b2c1af2d199833368",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "927f2bfc50de1f03c38ac6ec3198f4a7",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "78e6008fbf1d737dce7812540853511c",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "54bd2c1a937b1392327adbdf92ce5e6d",
            ["諾姆瑞根在丹莫洛的西邊。"] = "a4f613548f3f5a63415a978d891ce475",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3b08e6def8fe2881c84a302e3f4c7fea",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "03ee214820f246ccc4e751c56c822ace",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "7eddf733901dbca29a5a21752dd1ceb4",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "0e3148ee13bdc4aad5af84663b24d1ce",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "aab40b74860886caa96dcfdaf979e180",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "9c2b22f32a137854d984166b2aaded4b",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "8f57f5e81f55defd22e287d36b233496",
        },
        [7737] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "67e679105237aa46ee7a3409ef1a68c5",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "42f5d7a2dd2fde374bdefa0c10701256",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "90068fa43ca357ef9462599be9d006a4",
            ["你有興趣探索這些地下城中的一個嗎？"] = "ccda04db92cbf011d170b7cae60f408c",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "5a6a13f324242e75a6382d99c516cc94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "12c27bc52b107697f8de364f8dae7e3c",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "18f70be5c25cb2ea163cd8d518bfdc66",
            ["厄運之槌位於菲拉斯的中部。"] = "ce805aa1448186ce4794258c3cdc704e",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "af31a346608dbddcecea7edc85e314ff",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "331713e1070e9f4f3576819f670ae53d",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "87b9ad9eca23dfe66c987d93b54bc51b",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "c08a11a40b198a8cdf5e21127dad1408",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "4b98c70ede6bd8cb80bc9ebb78fd4f9a",
            ["奧達曼位於荒蕪之地最北端。"] = "556878b84c0292b45d666060cb90b770",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "bc7a0c38334a3cb0cabf4faf3d793a87",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "7baa3037efa4e58f77af6f15cb527593",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "fb940c5b0393c3fd43e9e2df8f5562a8",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "d332f132dad158e7271d0f14c19ec73d",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "c2be634e5a50af657e4346af05a183dc",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "9d86f89304affdeae5264f879da84304",
            ["我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。"] = "980ce6cc828845cb13bcbd8cd0b6917e",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "3124bcbc877a9654486099bdcbfb0eef",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "1dafad1d0d57bc8653d5c2c7d35c4a07",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "d9ac47630828a00f0b09464fc66c51ec",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "298b92e58115d14cb1cd1b4ff6278556",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "af82564cf7ae1fe402a33ef253cb74cc",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "4c620133d97c2f350972b761b3dc491d",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d33cc3248fefbb1f1925c215048cf29b",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "7f40e2c7a99505ba4995ee282dfc6836",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "4c47373b8dd57eabb9791705a594084f",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "63f35b75e396252f797a4186f1286bee",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "9160ee289a277af5bf427091078afc51",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "a704e4b5607d1ef64f5d23e8fd7983c1",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "7bf5800aefb381b3ab9369dbae519ad1",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "6197d9bec6a3e8059bca553e1ceac8b1",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "86adf50ebffcdaae0b2e044333b6e69a",
            ["諾姆瑞根在丹莫洛的西邊。"] = "d44d297c2cca8733f4d13c8c8c1f28d5",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "dd975c8f89f30ab9b769be5964cf632f",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "d7a63e33070adb319c75b51cca5b23b6",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "0b35ae40cc764b63340a0d3431fca136",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "55c6bd57311ef599eca95a97025087e1",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "06eb7bd37fd0c212607efd69ff668e03",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "4b2a582cee1f20d593eae9a388287135",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "a8ecc7056b89cefc7b67cdb06c5db362",
        },
        [7744] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "e76319f8e0a3393f78b709a653ebd046",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "a4d0603824a832576cec3e3d0e01eb3a",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "970d265673ae5fad5a5c1dc628457490",
            ["你有興趣探索這些地下城中的一個嗎？"] = "036da6474362e31b5c5b8714997221d3",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "41e7446de8a99d017f4dbbef7255bc13",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "b85a4524b031030828761221440ff4cd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "0696ddb759f36db8a31b0de8dfe773e6",
            ["厄運之槌位於菲拉斯的中部。"] = "8bcc27057464ad8295116b381b58f4c4",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "adddbf128dedf6f6ca7aac8e3be5bf92",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "d0b8820f2e1f29977d61ec36fbba4c37",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "7f5e67249a1d4971841ece6127c8d749",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "387741cc6b9473695e470695f72c685c",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "dfbf5c158793a5d635b039bb99fbcd86",
            ["奧達曼位於荒蕪之地最北端。"] = "e395d0b7e6c95518344f6330e935cace",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "c7a772d767a66660e5da8715a151a796",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "e74b227d686c3a09c784a937420b00fc",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "8fb15b22af529953dc80e7257f2df256",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "252356bb3f6f7907c717b8af0e9450c5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "672d1e8529c61b7cd4745f6b33011c68",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "64973aa51308c04b55be79da97ac51f1",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "334b73436ddc4b1bda745af5eb1e4f32",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "327242bcd711775eb7720e35cac612af",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "ecab747cb61959b39b57ef0de545ae6e",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "e9e63692c2220a4c865d9adef19b35e9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "bddcb2f11ff849b592a1d76b4d46b5d1",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "0de78051c05d635c0f53d505687c9a11",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d590cc10020ce147fee1519be78c0e51",
            ["滿上一杯啤酒，拉一張凳子過來坐坐。我們要暢飲一番，同時還要分享我們的故事。"] = "c3684d8296958c5935a2740fa7611b74",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "722216dcb64e2fd4e0adfbec7f5a169e",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1c36c2f9f75af3f1994be97e3fa76600",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "490f61093d0ec9e8887f5611d0dde3c6",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "a6db9e7560aabbf0956453b311a6e920",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "09a72d48b06490f955cd61ccf3e6a038",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "be509dfb481fe127dfd82ad17e93b19e",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "e303428e45f8504ab95951e7cf3b15a5",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "3ca87dd2a1766fe3430d6ece60a54be7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "b5a78d9a4eb2335b05dc3e74b7bf93d2",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "a8a237543c2ca2b43003dda93eb3bc66",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "637ea23cab1a47898f266b7ddbe033ca",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "b1f375bae193622f365bfe78f36e26a6",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "77aa9a2034ff610f83189bb1b5922172",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "e0678027d988e76f5db5e0b28bd5fded",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "d4c8367f7e096bd61f9f2c15a639c5d5",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "b81280ccbca7aa10e3280895aec17ea5",
        },
        [7763] = {
            ["你好！如果你想要接受一些挑戰的話，我這裡有個建議給你！$B$B我正在利用我發明的超級測蛋器幫助夜精靈的德魯伊們拯救鷹角獸。他們受到菲拉斯廢墟中的戈杜尼巨魔影響，數量正在迅速減少。$B$B我收集各種不同類型的蛋。你能幫我找到一些嗎？"] = "a275ba473c8cc813159847ce18ab05ae",
            ["這裡西邊有一處叫做菲拉斯的地方，那一帶的角鷹獸是夜精靈長久以來的同伴，他們正處於危險的境地中。$B$B我需要你從菲拉斯南部的伊斯迪爾廢墟中給我帶回角鷹獸的蛋，超級測蛋器會分析你帶回來的蛋，並判斷它是否可以孵化。然後我可以把蛋送給德魯伊們，避免它們受到戈杜尼巨魔的黑暗魔法影響。$B$B請記得一點，$n，有些被拯救的蛋是壞掉的，永遠也不會孵化。"] = "49f43fc55d3582737bf410646dd05a11",
            ["龐大的戈杜尼巨魔部落控制了菲拉斯森林的很大一塊區域。他們的黑暗魔法已經滲透了周圍的環境，從而直接對那裡的其他生物造成了毀滅性的打擊。$B$B如果你去菲拉斯的話，可得小心那些巨魔——他們非常骯髒，而且很多都會使用強大的黑暗魔法。"] = "0c6e66b796bf9729d8e0c65c441711d3",
        },
        [7766] = {
            ["你必須耐心一些，$N。我的間諜機器人正在進行非常精密的操作，馬上就幫你搞定。$B$B哦，幫我個忙，儘量不要讓萊斯科瓦看到你……我們要伏擊他。"] = "63ffa6f99e7677f212b497febf231182",
            ["嗯，如果我能用樹枝做掩護的話，那些守衛是看不見我的。"] = "07770c2ddd975789dc652f86f33ee458",
        },
        [7771] = {
            ["我知道，我知道，我知道我根本不知道自己在哪裡！$B$B我的家在棘齒城，不過既然我的飛艇在這兒墜落了，那我不如現在就開始進行我的研究項目了！"] = "012cba0ea4f7f602188cc6eee3493caa",
        },
        [7772] = {
            ["為了讓上來觀光的旅行者安全地下去，我可以為你提供翅膀。"] = "095e13d4bc42c0c93f1c874f146d577f",
        },
        [7773] = {
            ["菲拉斯的土地經歷了歲月的洗禮，$r。大地、樹木和生物，它們改變著菲拉斯的現狀和未來。$B$B跟這兒所發生的一切相比，雙塔山可以算是亙古不變的了……"] = "c848f51b35187eedb6b472e16b737fa5",
        },
        [7775] = {
            ["呵呵呵呵……你是個相當好奇的傢伙，不是嗎，$n？嗯，我來告訴你該怎麼做。$B$B在此地以北的古老廢墟中居住著一個名叫米布隆·亂齒的令人厭惡的豺狼人。他日夜守護著靈根草，好像從不睡覺似的！$B$B你必須把他引開才行。我可以賣給你一些他喜歡吃的東西——把食物放在他附近，引他過來，然後你就可以趁機拿走靈根草啦。祝你好運！"] = "f3df391ade7879f97d794ce7af5fee06",
            ["嗨！我名叫格雷甘。我能為你做什麼呢？"] = "7673b1e1c1aee85187bd33011e028202",
            ["當然，$N。看起來你是個值得信任的$r！我在一裡開外就發現了……$B$B總之，說正經事。我需要一株靈根草才能製作視靈藥劑。藥劑所需的其他成分都是小菜一碟，但是靈根草就不是那麼容易得到了。"] = "f6ad8c672faab789040d554fb2b0b5a6",
        },
        [7776] = {
            ["聽一聽長者的故事吧，$N。我有許多話要說……"] = "fe919449930ea179336d16a22b457806",
        },
        [7783] = {
            ["$n，他們的意識已經被污染了。是的，情況越來越嚴重。他們現在只會為拉瑟萊克而活。他們手中的護符碎片就是召喚惡魔之王的鑰匙。但問題是，他們已經對於常規的攻擊方式完全免疫了。"] = "8d0a66ad0cd5f9f1896db2efcf7f3e6d",
            ["你看到他們了嗎？當然沒有……我認為你是看不到的。以你的資質，即使有眼睛也和瞎了沒有什麼區別。"] = "f00870b9a046eed91eb4d0128f2dcee7",
            ["可悲的是，正是因為索爾的智慧才導致了惡魔之王和其他勢力聯合起來，特雷博的軍隊促成了惡魔之王、陰影議會和巨槌巨魔之間的聯合。對於力量的無盡渴求使得他們簽下了血契，對惡魔效忠。"] = "3726dcf3467f198a1a4e87d1350ab5d0",
            ["在抵抗燃燒軍團時期，污染者拉瑟萊克是卡札克麾下最強大的將領之一。當燃燒軍團被擊退，卡札克的勢力被壓制之後，拉瑟萊克接受了詛咒之地的事務。$B$B當聯盟和部落在詛咒之地以外的地方打得天昏地暗的時候，拉瑟萊克則在召集陰影議會的教徒，以及野蠻的巨槌巨魔。"] = "d1af7e5517ae83c4c66dff4c1ff060ca",
            ["瑟溫妮、奧利斯塔和戈洛爾都沒有意識到，其實他們和那些奴僕一樣，都被永遠禁錮在這片土地上了。他們所獲得的不朽之力其實就是要永遠為拉瑟萊克賣命。狡猾的拉瑟萊克又一次獲得了勝利。"] = "1d4b8f39810a29599c94b8d4568dc49f",
            ["那麼讓我們假設你即將開始這段漫長而又艱辛的任務，你要做的是就是想辦法摧毀這三個傢伙的防禦結界。然後呢？去污染者拉瑟萊克的巢穴挑戰他？$B$B<洛拉姆斯大笑著。>"] = "f7c5603af9e4752420d6a1a348affa8e",
        },
        [7804] = {
            ["分久必合，合久必分。那兩把劍被隱藏在祖爾法拉克城中。$B$B蘇薩斯會在兩把劍都被發現時重生。"] = "eea29ec80661302d9837db9ce53a5f5a",
            ["蘇薩斯……第一次聽到這個詞的時候，我還和你一樣大。那個時候這個詞對我來說沒有什麼意義，就好像現在它對你沒有什麼意義一樣。但是當一群食人妖從祖爾法拉克來到這裡肆意妄為之後，這個詞就變成了恐懼的代名詞。$B$B這裡的人都會告訴你那把劍並不存在，那只是一個神話，一個用來嚇唬小孩子的故事。但是，$c，請相信我，它確實存在。$B$B<說到這裡，特倫頓不禁開始用手撫摸自己臉上累累的傷疤。>"] = "e3c1562e647215741d05193021f0ffd6",
        },
        [7823] = {
            ["你想要飛往什麼地方？"] = "43540ff7458382b18eb66468d4ff2856",
