        [7852] = {
            ["你好，$c。如果你在尋找皮革製品和製皮物資的話，來問我這個半退休的聖騎士就算是找對人了。"] = "f4227fc6249932f3aa71dc28e89d87cf",
            ["我發誓……如果奎恩特膽敢在把一個飛蟲放在我這裡的話，我會立即去用鋒利的劍把他的樹給砍了。"] = "850288efe4dccb31f59391e76405f2b9",
        },
        [7853] = {
            ["你好，$N！我是一名熟練的技師，我叫斯庫提。"] = "22c7e447f05eaff769b8cae4f2f6e0c9",
        },
        [7854] = {
            ["勇敢的$c，歡迎來到莫沙徹營地。我能幫你什麼忙嗎？"] = "e40a5faf56ab3503cf189bed6d939698",
        },
        [7866] = {
            ["如果你到這兒來獵龍，那你就是我的客人了。我應該去哪裡表示我的哀悼？"] = "ecd8f490207aa548a5bde5be21a12239",
        },
        [7867] = {
            ["你的臭氣會把數英里內的所有龍都招來的。告訴我你想要什麼，快些。"] = "0249ed1756f9b7c5b5603fe23f7cb456",
        },
        [7868] = {
            ["哦你好！我的名字是薩拉。我能為你做什麼嗎？"] = "96e5d4c05909d0400168329dbcfac193",
        },
        [7869] = {
            ["靈魂告訴我說你會來的，你會出於某種原因來此尋找我，但是你也許自己都不清楚這個原因。那麼，你知道你為什麼會在這兒嗎？"] = "f7eb9170dcfaa7e5f749986588580ced",
        },
        [7870] = {
            ["森林告知我你的存在，但是沒有說你為什麼在這裡。那麼，告訴我真相吧。"] = "df2b761c9ca25bf3b7cf64efc2e5e6e8",
        },
        [7871] = {
            ["你做得怎麼樣啦！"] = "6e6caea26767043589a962c9cf10b835",
        },
        [7875] = {
            ["我們必須不惜一切代價保護這個營地的安全，$c！我們不能允許敵人再前進一步了！"] = "4d92317d28a869a2e22ffb04c657ac98",
        },
        [7879] = {
            ["你好，$c。我這個羽月要塞的僕人可以為你做些什麼呢？"] = "9bd1329116de10f1184fdf255ad9ce76",
        },
        [7916] = {
            ["你好，$n。我在這裡訓練和照料年輕的角鷹獸，你可以隨意看看。"] = "de300aecfe64e2c0dd5018d277df9334",
            ["德魯伊對世界上所有生物的生存狀況都非常敏感。當我們知道這些鳥處於危險之中時，便設立了一套營救系統，防止它們遭受菲拉斯的墮落氣息的影響。$B$B一個名叫克格爾·曲藤的地精負責這項工作，她收集鳥蛋並將其交給我照顧。$B$B我們總是在尋求更多的幫助，$n。或許你該前往加基森找克格爾談話。"] = "b19ba63af1bb1e807752e1767b2f0b9c",
        },
        [7944] = {
            ["你好！如果你是來購買地精工程學圖紙的，那請你準備好地精工程學會員卡以備驗證。"] = "899cfe761a6d79c6bdef221e3006e527",
            ["我是大工匠歐沃斯巴克，現代地精工程學領域的頂級設計師。我的工作就是用我們的閃亮嶄新的扳手確保新的發明能夠付諸執行！$B$B要是你碰巧懂得製造消除輻射污染的裝置，那你算是來對地方啦……"] = "7b5fc421a7124f4ac3dff2f5ae6ae20e",
        },
        [7948] = {
            ["你是來接受藥水配製這一技能的訓練的嗎？要是你認為能從我這兒不費吹灰之力地學到東西的話，你就大錯特錯了。走吧，在你沒有掌握更高技能之前別來找我。"] = "4856907d89101ae05bd0436fae2b8d02",
            ["你的技能顯示你一直喜愛我們的藝術，但是我想看到你所做承諾的進一步證據。我會分配給你一項任務。完成它就會令我滿意。"] = "7c26a76054cb4a99357c700203091c0b",
            ["從前我歡迎過黑暗，因為它是夜晚的姐妹。現在總是漆黑一片，甚至在白天也是這樣，而森林迫切需要給養。除非我們快些行動，否則這擴散的瘟疫就會遍佈整個世界。"] = "d20db83d74494178c900eb4e6a102125",
        },
        [7949] = {
            ["如果你在尋找一種真正回報豐厚的事業，那麼附魔行業正在等待著你！"] = "ce24b2e19a5dadecf917c1c4f4fd4ee8",
            ["我知道很多事，陌生人，但是你的知識與我的不相上下。想更深入研究的附魔師要去阿祖拉之塔，那裡住著一個叫做基塔·費溫德的工匠。"] = "eaade2c05b8910f296a765c4ce125adc",
            ["為什麼不讓我們見識一下你的能耐呢？如果你完成任務我會很高興對你繼續深造！"] = "71b3c8878ca9d907574fab21af50df1a",
        },
        [7951] = {
            ["你好，$C。看來你最近在進行一項秘密的收集工作？你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段代碼。把代碼告訴我，我就會給你一份特殊的獎勵作為回報。"] = "28755471b38e6eb285e0d80db6c9498a",
        },
        [7952] = {
            ["很抱歉$g兄弟:姐妹;，但是在確定買主是暗矛部落的貴族之前，我不會將迅猛龍賣給他的。當你證明自己是部落貴族之後，我才會把迅猛龍賣給你。"] = "24ae77aab73cc857fb3bef8cc78e74d1",
            ["祝你好運，勇敢的$c。我知道你在尋找一匹好戰馬。告訴你吧$g兄弟:姐妹;，在你所在的區域沒有什麼比迅猛龍更好的坐騎了！看看我的這些迅猛龍吧——他們的祖先曾經是極其兇猛的野獸。"] = "2429cd9dc5d70eefd9b0308799bd8d64",
        },
        [7953] = {
            ["在我教你騎術之前，你必須達到被暗矛部族的食人妖所崇拜的聲望才行，$c。"] = "b3696ab9380b9a74f4dbfea7f6fda446",
            ["我不想教牛頭人騎乘迅猛龍。"] = "991e17bc5cedbda60de365b1ffa51bb6",
            ["我可以教你騎迅猛龍的技巧，只要你有足夠的金幣支付學費！"] = "3b10621402a461476ec028521e9fb4e0",
        },
        [7954] = {
            ["在我教你騎術之前，你必須達到被諾姆瑞根逃亡地精所崇拜的聲望才行，$c。"] = "4a0058f7e90fd806fca67dea42c579d6",
            ["我可以教你操縱機械陸行鳥的技巧，只要你有足夠的金幣支付學費！"] = "144516c0f69573ee3346350d1c8751f1",
            ["要教你學會駕駛機械陸行鳥，那簡直就是在浪費我的金錢和時間，$c。你的體形太龐大了！"] = "8793a1e3bacd16171e597a2e6e349f3b",
        },
        [7955] = {
            ["呃……很抱歉，我真的不太瞭解你。我是說，作為公認的機械陸行鳥經銷商，我只能跟高貴的地精做生意。要是你是諾姆瑞根的地精貴族，我會很高興地為你提供服務的。"] = "19b68fb6acf9660f5027bc5ba4f9e9ad",
            ["嗯……我認為你體型過大，不能乘坐機械陸行鳥，$g先生:女士;。你很可能會壓碎這些精美的機器！"] = "65e354785b26bc4ab909aec7cd4f43eb",
            ["如果你是為獲得快速而安全的產品而來，那麼這兒就是你的目的地了！今年的機械陸行鳥模型已經到了，我將為你展示其性能！"] = "299711f9bfc91cd6e18b4f2a9bc2baae",
        },
        [8018] = {
            ["你想要飛往什麼地方？"] = "646a52da6f00e2b6b680741da2aab13f",
        },
        [8019] = {
            ["你想要飛往什麼地方？"] = "8ee9e2b8b1fbeba82851331d36cb251c",
        },
        [8020] = {
            ["你想要飛往什麼地方？"] = "26d3fb863cf374254276fad4c4fb1b43",
        },
        [8115] = {
            ["和我們戰鬥的那些生物的靈魂，或者說「靈魂精華」中存在著不可思議的力量。$B$B這個地區的許多生物都是夜精靈的盟友，夜精靈可以隨時利用它們的力量。部落也應該享受到同樣的權利，我相信一定有辦法可以掌握這些力量，使其為我們所用。$B$B我說的都是事實，$n。幫助我，你會發現自己獲得了不可思議的力量。"] = "48f9d9ec946770bdc62b7cf862bfbd1f",
            ["這個地區有許多生物都是夜精靈的同盟。精靈們可以借助這些生物的能量來為自己效勞。部落也應該擁有這種能力。我想到一個方法，可以捕捉到這種能量並為我們所用。$B$B不要懷疑我告訴你的事情，$n。幫助我，你就會知道我所說的都是實話。"] = "da8a1f5eba022a30ad8c3b4a69e03d12",
        },
        [8125] = {
            ["我們可能遇到強氣流了，但是並不缺乏肉食！想看看我的貨物嗎？"] = "544365d47c60f2584b894bd2faf796b0",
        },
        [8126] = {
            ["你好！如果你是來購買哥布林工程學圖紙的，那請你準備好哥布林工程學會員卡以備驗證。"] = "e814cc2694856d5e9fb32efcf2ea7186",
            ["寶貝，讓我來教你一個簡單的加法守則：「哥布林」+「工程學」=「萬事通」。告訴你其他演算法的傢伙肯定數學不及格。"] = "cc919cf47bdafb636ea5a25ac2f0b460",
        },
        [8140] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["願光明保佑你。"] = "0635f703e43c62457aadee823a30493b",
        },
        [8141] = {
            ["你與塞拉摩衛兵一起訓練過嗎？"] = "0507fea60d7059874621212e7d11d203",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["雖然塞拉摩以它特有的武士培訓聞名，我恐怕還是不能幫你。"] = "04ac79bf79b4a0fe7bbe614f88b668d0",
        },
        [8142] = {
            ["$N，我如何才能在大地之母的心目中繼續你的深造呢？"] = "f316fce98de9499e71406388009e60c4",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "9ccfbeb35c89e4770c3695a5c842eef7",
            ["這些都是大地之母走過的道路。願你的祖先保佑你們$c。"] = "b6f4bdc2a8d3684c359c1880591a1f0c",
        },
        [8153] = {
            ["這些棲息在這片荒地上的科多獸的獸皮最為堅韌。"] = "67523c45386916357dd48fdb7eb1a7d6",
        },
        [8256] = {
            ["你好啊，$N"] = "1339cf526a755cc8690cf68d8fc70027",
        },
        [8306] = {
            ["加基森的迪爾格·奎克里弗對廚藝非常精通。要想提高自己的能力，你就去找他吧。"] = "fa94f3b2a7756a7206f2d739132e099b",
            ["我可以教你如何烹飪！"] = "3c5599de03c8689a7c59e4a9c7e86daa",
            ["烹飪是我一生的追求，我覺得我們倆有共同的愛好！"] = "6b8ea29137624c8512925cd734b18e4f",
            ["葬影村的烏蘭可以賣給你「高級烹飪教材」。如果你想要提高烹飪技能的話，就需要這本書。"] = "178749ad5f34e7d82d4f95b09e30304c",
        },
        [8308] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "30ee103c545f987ab518c70f6d3e640e",
            ["我不能訓練你這樣的$c。"] = "f2c2c7d6984ce15c597fe07b1c728e29",
        },
        [8359] = {
            ["你好。如果你是來找皮件的，那麼你會看到我的貨品做工精細。"] = "03925a7b505107b23b456755061ec21a",
        },
        [8380] = {
            ["你必須給我一點時間，$c，納迦正在攻擊我們。搞定他們之後再來找我！"] = "577b34a2009f6599e2e71e1f5ebe9a56",
            ["嘿，$N！這場景不甚美觀，是吧？地平線輕帆號沉在海底，我的手下狼狽不堪，我們的貨物和乘客如同碎片一般到處都是，你也許會認為暴風城曾在這兒舉辦過節日慶典。$B$B麻煩事兒還不止這麼點……"] = "1b039b3e7e1c17e0186d14836df84d01",
        },
        [8399] = {
            ["你好，$G先生:小姐;。我是克希雷姆大人的學徒尼瑞爾。如果你們有任何問題，請隨意向主人詢問。$B$B當你準備下山的時候，就過來找我吧。"] = "c25da7aea73e13a714910fc2805f839f",
        },
        [8403] = {
            ["想買蟑螂嗎？"] = "7693cb63c5c8e9a15a4c651d5eb5c5f7",
        },
        [8436] = {
            ["作為黑海岸的一名年輕的夜精靈，我遇到了一隊暮光之錘的成員。他們待我如同親人，因此我背叛了對伊露恩的信仰，聽信了他們的蠱惑之言。$B$B直到伊露恩的幻影從我眼前閃過，我才幡然省悟。$B$B我滿懷悔恨，開始向伊露恩祈禱。"] = "ee6ad66a7dc56723278340ce7fc9aaca",
            ["我的自責、羞愧、懊悔和悲傷全都刻在這塊純金石板上。不幸的是，暮光之錘找到了石板，並認定我是詛咒者。我被立即處死，而那時我對伊露恩的禱告還沒有做完。現在我已經成為了一個遊蕩的幽靈，無法降入扭曲虛空；我被關在籠子裡，用來警告那些試圖背叛暮光之錘的人。"] = "19289f6d38df9ab14e68557b881b1054",
            ["讚美伊露恩！好些年都沒有人來拜訪我了。"] = "f479d49557864313202d2081a17b0dc5",
        },
        [8479] = {
            ["我父親被大熔爐中的惡棍殺害了。我懇求暴風城給予援助，但是他們根本沒有理睬。不僅如此，他們甚至不願意承認這個地區的存在，更不要說派遣軍隊來匡扶正義了。$B$B我要報仇，$c。這世界上還有比這更強烈的理由嗎？"] = "8abf64ca79d3bfbfd5e67c8a51929983",
            ["我要復仇。"] = "49fd111b49093990741931455047f8fb",
            ["正如你所見的一樣，我只不過是單槍匹馬。黑鐵矮人和拉格納羅斯的爪牙可以輕鬆把我擺平，但是我對於像你這樣勇敢的冒險者充滿了信心，你一定可以把大熔爐裡的那些東西全部搞定的。如果你願意幫助我，我會給予你豐富的獎勵，那些獎勵將是你做夢也想不到的。"] = "ef7bb97afba3c7564c9dafde000ac6fb",
        },
        [8496] = {
            ["你好！這間工廠不是我的，不是！但是終有一天當我完成訓練後，我將成為一名發明家，就像我崇拜的英雄瑪爾馮·瑞文斯克那樣。$B$B你從來沒有聽說過他嗎？哦，碰巧他已經離開好長一段日子啦，他去研究遠古食人妖廢墟啦，他是乘坐地精飛艇走的……我也不是很清楚他究竟去了哪兒……$B$B塔納拉辛？坦克利斯？塔納里薩尼？$B$B<莉芙搖著頭。>$B$B不，名字不是這樣……"] = "2ef43f4e9d19efefdd1007bc696621b9",
            ["嗨。不，瑪爾馮一定不在這兒，他還要好些時間才能回來呢。實際上，我有些擔心他……$B$B我希望他能很快回來。有人寄了一隻大箱子給他，我可沒力氣把這東西拖進去！我只能把它放在門口……"] = "1810af4305cc03fe960af01e95020439",
        },
        [8509] = {
            ["我活著的目的就是為主人服務。"] = "a78bfb1ca9baf31083c2a2913d0f9ec6",
        },
        [8576] = {
            ["我們在艾薩拉度過的這段日子並不是輝煌而又燦爛的，但是我們仍然年輕而且熱血沸騰——我們最終會獲得勝利，這只是一個時間問題。"] = "aab9a312cf4a0b71e47a29a0f34763ec",
        },
        [8579] = {
            ["你好，$c。雖然長期飲用烈酒已經讓我的感覺變得遲鈍了，但我的心靈之眼依然十分強大。"] = "bfbfb8887e0db34733a0a6ad237b1e46",
            ["通過研究，我發現在哈卡的化身被擊敗之後，他的力量也會隨之減弱。但是哈卡的大部分力量仍保留在扭曲虛空的深處。$B$B你曾經擊敗過哈卡的化身，$N。或許再次擊敗他的話就可以進一步削弱他的力量，也許有一天我們就將面對他的真身。$B$B我為你準備了一張卷軸，你可以用它在墮落之神的聖地中再次召喚哈卡的化身。你敢再次迎接哈卡的挑戰嗎？"] = "aa551472a784dfcc7f33fa069f619438",
        },
        [8587] = {
            ["我不是為了榮耀而來這裡的，$N。我來這裡是為了獸人的驕傲。$B$B如果我沒有拒絕貝爾戈洛姆的提議，那我肯定現在還在奧格瑪料理真正的生意。$B$B他對女人的渴望在杜洛塔的女性戰士中盡人皆知，但是那仍然沒有影響他成為大眾情人。$B$B很幸運他並沒有騷擾我太長時間——否則他會被砍成肉醬的。"] = "6e8ee30a60a965991f527856399387d7",
        },
        [8609] = {
            ["你想要飛往什麼地方？"] = "f6ea55ad6f6344693225294350de4559",
        },
        [8610] = {
            ["你想要飛往什麼地方？"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [8659] = {
            ["安戈洛環形山在卡林多南部，位於塔納利斯沙漠的西面。去尋找巨大的浮空石……它們是環形山入口的標誌。但是要小心，那裡可是很危險的，迅猛龍就在入口附近徘徊。"] = "396471ddf6b6b14abe39c3cd741bf23e",
            ["我和碎手都向你致敬，$c。$B$B別這麼驚訝，$N。連奧格瑪最高的地方也會有陰影——一定有什麼東西隱藏在那兒。碎手欣然接受了那項任務。索爾也承認要確保獸人和食人妖的安全，他是不可缺少的。$B$B但是你到這兒來不是談論我的事兒吧，你一定另有目的。"] = "300f5696e7561e85ca08484375c77012",
        },
        [8696] = {
            ["不錯，我確實知道一種罕見的煉金術配方。讓我來教你吧！"] = "8bd69da5c8875db363f8ca049bf10cf2",
            ["你的烹飪水準實在是太低了。再去訓練一段時間，也許我就可以教你一些我所知道的東西。"] = "59c157459d6c37182d6e0335633c83ea",
            ["你的煉金技能還不足以理解我所傳授的知識。也許你應該晚些時候再來找我談談……"] = "7927759d8b72b02485457ac0d2c022e0",
            ["嗯……對，我這裡確實有一些挺有用的菜譜。讓我來教你吧！"] = "9a1a67bf16978dd21ee48e13a42ce8c5",
            ["謝謝你救了我！$B$B我是一名來自暴風城的廚師兼煉金師。我到這兒來是要幫我叔叔安古斯尋找草藥和食物的，但是這些野豬人將我抓了起來。要不是你趕過來的話，我想我已經被它們煮著吃了。"] = "f252a63ef02f49f36892505401561fee",
        },
        [8736] = {
            ["我一直在研究在大城市間通過地下通道運送石油的方法，但是每個人都認為我是在做白日夢。"] = "d607877befae4fc8560330345158b290",
            ["我從不拒絕那些已經準備好跟我一同訓練的人。不幸的是，你不是！你還像個小孩！"] = "d61a0a53b1b257362de2e3db7be1604d",
            ["給你看看你得到了什麼！我承諾，你不會有遺憾的！"] = "65e704bf14c873956aafc6447de33e25",
        },
        [8737] = {
            ["付錢給我，我就說……$B$B哦，是你，$N！別介意……"] = "b6b61d53c84c4166df1b5f956114aa9f",
            ["你聽說過我的名字嗎？或許我們倆很早就相識了……$B$B我認為我得名於某個重要人物……"] = "de7708324e7d052ec52f6108981bb2a8",
            ["嗨！很高興你回來啦，$n。告訴我，你完成我給你的第一項任務了嗎？如果完成了，我會給你第二項任務的……"] = "a34ff43e735f0935b3153721bdb9bdf7",
            ["對任何人而言……包括我，這都是一個秘密！$B$B很高興你找到了我——我沒躲藏在樹叢中或是岩石下，挺幸運的，是吧？"] = "c1f7d0e54a5d6f4ffd50c716ddb1a124",
            ["很久之前，在我的旅途之中，我遇到了一個人，他告訴我：「掌握它的使用方法，你就可以擁有它。」$B$B你覺得那是什麼意思？那時我還不知道，而且現在我還是不知道，真的……"] = "4882d4a03c1208355c763c1a0bc07069",
            ["我……我真的不知道自己是怎麼到那兒的……$B$B我依稀記得用的是……木筏……$B$B"] = "7604f31c3f3ca5119c647e30d4073393",
            ["我在火山口遊蕩了許久，後來我想起曾有人告訴我……「繼續往前，到山上去。」這個聲音在我的腦海中出現。$B$B聽了這話之後我就來到了這裡，$N！"] = "6c0ca67e97b5ad3215ba128332af2f28",
        },
        [8738] = {
            ["你好！如果你是來購買哥布林工程學圖紙的，那請你準備好哥布林工程學會員卡以備驗證。"] = "e814cc2694856d5e9fb32efcf2ea7186",
        },
        [8879] = {
            ["你好，$N 。你是來學習鐵爐堡的歷史的？"] = "c953388b7de863c335ced6fcb4fac55f",
            ["我們不知道。$B$B活下來的黑鐵矮人們躲入深山，並開始重建他們的城市。$B$B索瑞森的廢墟上又出現了黑石塔和新的黑鐵王國。他們在灼熱峽谷內建立了新的防禦工事，就在眾所周知的大熔爐地區。$B$B一個關於遠古邪惡力量控制黑鐵王國的故事開始流傳。"] = "3fcf709a27150e930f5c92364ba9d425",
            ["我們需要一些冒險者的幫助，$N。你能幫我嗎？"] = "a851590e6c0cd1d2105749d6e3f4f117",
            ["數百年前，偉大的索瑞森城驕傲地矗立在富饒的大地之上，那裡現在已經變成了荒蕪的燃燒平原。$B$B索瑞森城是黑鐵矮人的家鄉，它那時正處於一場矮人的內戰中。$B$B你知道，那片土地曾是赤脊山的一部分——直到有一天，索瑞森被一場大爆炸吞噬。城市變成一片廢墟，周圍的地區也被夷為平地。"] = "d0574bdb32ceed44b19308184401ca58",
            ["最近，黑鐵矮人更加頻繁地出現在地表上。他們在荒蕪之地建造了堡壘，並派遣了龐大的探險隊到奧達曼深處尋找古代的知識，他們甚至侵入了我們的祖國，攻擊我們的巨石水壩。"] = "c58041c0e998cc37148ac9980716a3cb",
            ["當你準備聽我講述故事的時候就告訴我。"] = "adf38cda6fa6748990bab76d2b44d039",
        },
        [8888] = {
            ["你好，$r。我是弗蘭克羅恩·鑄鐵。你是來瞭解黑石塔和黑鐵矮人的嗎？"] = "ee11d419f725f323959cf1466840e61b",
            ["我沒有選擇，至少我是這麼認為的。我會忍受索瑞森的毀滅並與我的國王和同胞站在一起。$B$B在拉格納羅斯的統治下，達格蘭·索瑞森國王開鑿了山脈的中央，並建立了黑石塔。我們不知疲倦地工作著，發誓要建立一座比以前的任何城市或堡壘都要堅固的矮人城堡……甚至將來也不會有能與之媲美的建築。"] = "17e21be1e50dc9c08937a3456cfb470b",
            ["我眼睜睜地看著拉格納羅斯的墮落滲透了整個黑鐵矮人社會，使這個曾經榮耀的民族變得瘋狂……變得邪惡。$B$B當黑石塔建造完畢時，我與同胞們共同生存下去的意願也消失殆盡了。我作為新的黑鐵矮人的英雄而死去。這座墳墓就在我親手建造的城門處，作為對我的成就的敬意。"] = "42970ea1c51bac4df67fd4dc66fc91bf",
            ["我那柄巨大的戰錘——鐵膽之錘，被交給了新的建築大師弗諾斯·達克維爾。這個傢伙人品低劣，才疏學淺。$B$B這點就是你需要知道的，$N。我想阻止他。他無法將鐵膽之錘的力量發揮到極致，但是如果他的後續者有這個能力的話，他們就會毀掉一切的，而這必將帶來災難性的後果。"] = "2c2818dcbcbdbda227ed1e41d7b52a77",
        },
        [8931] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "54899ff43d9fa3680bd5231fd54eae44",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "6cc5772934f51d4bcf44e66f9cb19266",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "639f5e4137099522e1302487ff27f679",
            ["你有興趣探索這些地下城中的一個嗎？"] = "9211a5a83384bc6bf667f9e87661f2b5",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "4855c8dab63ff7e92429d6df87b7b3cd",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "ae45cd449d9b601c1faa2ad7d470e04a",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "ae6bac71d95fa9cc576583cb12b00b0a",
            ["厄運之槌位於菲拉斯的中部。"] = "863a0466292f35423e25fb6b1e18e872",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "58d9f5adb0c15d9e359abb8b40a54a91",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "7dc247370c0f46388922e4ad2824f973",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "13d77ffe00e095b4ad42eef5a8aaebfb",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "b69ededa6dbdfe26a15fda5121e90a20",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "97a393e1ef12dc1fe4a4b55e63c2c620",
            ["奧達曼位於荒蕪之地最北端。"] = "4324821d63a3f73937dd5abffe6fdf7f",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "a25c5d7842af31618a063b3d3ce15fed",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "8e4dcb74091e2e615d506f3ec7d147ca",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "17d13be0366794572061fb3fbb409ee6",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b960d46bc6e1afd8a8048e75631efeb5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "4a0636d96305a16097c01ed6971f7971",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "cd40129110d4c4917a537fef57180329",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d9516bdeb534c80940a3be1f4600bf04",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "4bcf2a35fd98e48b3cd346ec97dccde8",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "0f7f53045dc845e1ab759203cc598d30",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8b063ee787233090be02c8d7fc8e58a7",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4d1835c423b0ee4a6773a1481ea2d03e",
            ["歡迎來到我的旅店，疲憊的旅行者。我能為您做點什麼嗎？"] = "db570f1f51f6fd3b1a42e5953bafd049",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "cce75935af7718f82fcb4c3d13f23020",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "75ed2903e0af8abe0c91025f4d1a631e",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "b32b2b77a0839ff8c1415be4d2623dd9",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "44f65d16974643e3b29f727a67787ad0",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "0838f3fe0e3c17a16a7ff7d504eec929",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "9f470e7a9c62fa04faeb58fd3b1d6de9",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "9f8d7c84b3cbfc322f53a0a242de804e",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "5521f2e5d2e37d7012ea87b75badcb01",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "fe604977d24d31743e5481d5dcda2e88",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2da51ca0be53ce695776bbe3e3eea8c7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "1e16c8ae0545b101ebc5ad4d9c69c248",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "e118425d7cca455fae7064446900535b",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "44fdd52098e4ecaeddc946e101d7c60f",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "4414ebedf67147d4801e58071b11c237",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "2d41c6e84da0f60aa520a4acc8919f87",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "7beb3ee244d9c85c277537d4ba4a2fe1",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "e4835262a6e71a36692d90aedbb66c42",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "3644fa36f35ecdc5947046c71b54837a",
        },
        [9021] = {
            ["<卡蘭歎了口氣。>$B$B我想……我想你是對的。$B$B哥沙克告訴我你的酋長有個大計畫，一個可能會改變聯盟和部落關係的計畫。關於這點你知道些什麼？"] = "2a2b5ea32d04677b8b6c1b4d28f1a377",
            ["<卡蘭清了清喉嚨。>$B$B我們艱難地穿過灼熱峽谷的隧道，進入了這片飽經蹂躪的荒地。現在回想起來，這事情十分蹊蹺。我們所遇到的危險只不過是在這個地區生存的一些野生動物，我們很容易就趕走了它們。$B$B我們輕鬆地抵達了黑石山，並毫不費力地穿過了這座由巨石砌成的堡壘。"] = "e1e6605df1bc6199e98f74408dedd4c1",
            ["一切都完了……"] = "bc07b7581d2615d19b9330c3df7eb939",
            ["你看我像個傻子嗎，$r？我可以簽署她的死亡證明書！我為什麼要信任你呢？"] = "db7ed4a5a553fd42836a5513fd9c8d2a",
            ["在我們穿越燃燒平原時遭到了敵人的伏擊，有上百個黑鐵矮人！他們從城牆內、平原上的岩石後面、還有岩石的裂縫中突然出現。他們包圍了我們，很快就解決了那些答應幫助我們完成任務的英雄和守衛。$B$B很明顯：這是一次早有預謀的伏擊。他們似乎知道我們的每一步計畫……"] = "09b00faf9376acf6a5163297eb7f4701",
            ["她現在就在索瑞森大帝身邊。他對她施加了某種可以改變思維的強大法術……而我只能待在這兒，束手無策。"] = "32931a4effdc1fa04623fd283e5a7e38",
            ["快動手吧，骯髒的$r。$B$B<卡蘭低下頭，露出他粗壯的的脖子。>"] = "581c2c35bf04fb2d52fc1f0b35728cc0",
            ["我說到哪裡了？哦，對，我們被抓住了。我的夥伴被當場處死。他們沒有殺我，但用山羊把公主帶走了。我被帶到了熔渣之池的拘留所，然後又被轉送到了這座監獄裡。$B$B也許他們是想用我這條可憐的小命勒索一筆贖金。或者他們只是想讓我永遠回憶那些繚繞在我腦海裡的殘酷事件。悔恨是最殘忍的獄卒，$c。"] = "8b0aeb3f8c3d9ef518842fbbf79e2a64",
            ["還會有別的原因導致這種結果嗎？一定是有人向黑鐵矮人告密了。$B$B<卡蘭在你面前揮舞著拳頭。>$B$B幫幫我吧，如果我能離開這裡，我發誓一定會把那個叛徒抓出來的。"] = "8aa1b4bf97916334997cc9a3311863e8",
            ["那麼聽好了，$c。$B$B幾個月前，湖畔鎮的鎮長派遣特使來到鐵爐堡，懇求國王一同抵抗入侵赤脊山的黑石獸人。$B$B鐵爐堡公主茉艾拉自願前去援助，於是國王就指派了20個精英守衛，確保公主由洛克湖前往湖畔鎮的途中一路平安，我也在衛隊中。"] = "93b9b434b02f7bb9a2588ae09d531eae",
        },
        [9022] = {
            ["救命！！！！"] = "205640ebbf618a0e2d0dc454a288eec9",
        },
        [9034] = {
            ["我們肉體的死亡標誌著我們靈魂和神聖使命的重生。"] = "0405c22f55463a7f397c51b6f191c435",
        },
        [9035] = {
            ["去找我們的領袖杜姆雷爾發出挑戰吧。"] = "a372bc64e7ea57b0c42f74c9c3cd93a4",
        },
        [9036] = {
            ["去找我們的領袖杜姆雷爾發出挑戰吧。"] = "a372bc64e7ea57b0c42f74c9c3cd93a4",
        },
        [9037] = {
            ["你已經表明了你的願望，也支付了珍貴的石頭。我會教你的……"] = "0480ea8d1ae32be6156e9b1979fcbcb9",
            ["你想要學習這項古老的手藝？你希望冶煉黑鐵？$B$B給我一樣祭品我就會考慮的！"] = "269bfbd42c1bcdce2bcd3a30b4a4916d",
            ["你的意志很堅強，而且你的意圖很明顯。$B$B可能你的確有資格……"] = "489bc8fef34e87ae96a0127590c52249",
            ["我永遠都不能再觸摸石頭了。我永遠都無法再體會鋼鐵的榮譽了……"] = "fd6c52e798e64559f12964acfc65a412",
            ["有趣，真有趣……我知道有個德魯伊居住在哀嚎洞穴上方的山頂，$N。她也許能告訴你有關這塊碎片的更多資訊。$B$B現在，我必須工作了！"] = "59bb63aa72266fa9deea86b21a7dc575",
        },
        [9038] = {
            ["你不能通過。你不是我們的人，也沒有發出過挑戰。"] = "971e819fd97d3c38bbc1d8b2cdaa3944",
        },
        [9039] = {
            ["挑戰火焰之王的下場就是我們現在的樣子。"] = "f0457cce2f9f2f1bd8cea54c70a5306c",
        },
        [9040] = {
            ["我們的懲罰也是我們的祝福。"] = "b402e32cb7eddbc1a8b5f35a4ed01673",
        },
        [9047] = {
            ["什麼？我在幹什麼？你眼睛不好是嗎？我是一個夢想家，親愛的$g先生:女士;，我夢想我們的將來會更加美好。很明顯，我是個夢想家。$B$B然而，有些人卻在想盡辦法把我們困在平庸的泥沼裡。我告訴過他，我是一個夢想家，而范達爾卻回答說，「哦，我們似乎還缺一些挖水溝的。」$B$B我會幫助塞納里奧議會弄走周圍的泥堆，直到平庸的枷鎖從我們身上卸下的那一天。"] = "912dd407768fd71b3934d051423f5235",
            ["我感覺到處都是陰謀。還有那些對我所做的事情缺乏理解的傢伙，他們想要把我關起來！$B$B你最好不要牽扯進來。"] = "af91358e01b26b90df86916c42d32ec1",
        },
        [9076] = {
            ["考慮清楚，$g小子:姑娘;——我可沒心情聽你廢話。我在這裡的工作是確認大德魯伊的研究工作正在按計劃進行，而不是跟那些不願為塞納里奧議會效勞的傢伙聊天。"] = "8e2b442664f11c1d603c1dbdef886718",
        },
        [9077] = {
            ["<高圖斯啐了一口唾沫。>$B$B我是部落的勇士，$N。讓我憤怒的是得知我們的敵人正坐在離卡加斯不到一天路程的堡壘中，密謀著要對我們發起攻擊。$B$B我渴望擺脫責任的束縛，以酋長的名義將他們消滅。$B$B但是，我們都有各自必須承擔的職責。"] = "9932a76da45813ab365ef10fee5256c9",
            ["你能以部落的名義衝鋒陷陣，我可真羡慕你。我的職責是指揮部落的軍隊，而不是親自上陣。$B$B當然，我年輕時也曾夢想著能安度晚年。現在，我癡迷於勝利的榮耀和失敗的苦楚——這些都取決於我所指揮的士兵們。"] = "bb2d2d3e107f276b6034eab77a1e8ed1",
            ["我做夢了，$N……對，我做夢了。在夢中，我以上千種不同的方式死去。有人會認為這是噩夢，但我不這樣想！在夢中，我在戰場上死去。每次死亡之前我都會讓一萬名部落的敵人倒在我的腳下。這是無上的榮耀！"] = "f2a689f6928cda5b485631c437fdedaa",
            ["我絕不會懷疑你的，$n。$B$B這些是給你的命令，$n。我知道你是不會讓我失望的。"] = "66291fe6e28957f2782fd84cde920f65",
            ["是的，看到你我就想起來了，$n。你讓我想起往日的時光，我曾是部落的一名年輕的戰士。$B$B毫無疑問，你將在你的一生中遊歷四方，征戰沙場。$B$B<高圖斯向你敬禮致意。>"] = "eedd82a4cd718223e93161292acc7b63",
            ["謙虛點吧……或許現在是時候了，$N。你做好進入黑石要塞的準備了嗎？你做好發動一場戰爭，摧毀他們大本營的準備了嗎？"] = "9b39a53a6dd75e2567cc0a1d62d913d7",
        },
        [9080] = {
            ["我可沒時間停下來。"] = "9da1b7ac9439c020560017306b57106d",
        },
        [9087] = {
            ["您好，尊貴的$c。我這個塞納里奧議會的謙卑的僕從願祝福與您同在。"] = "09eb7b06ec44bcb0a43d2256da983d80",
        },
        [9099] = {
            ["今天不太開心？嘗嘗這些櫻桃餡餅吧。"] = "d624f8a342f7b15a346a8164b8a05964",
            ["嘗嘗櫻桃餡餅吧，它會令你開懷大笑的。"] = "c4d447b7e05edffe18bf3bcb19354c50",
            ["奶奶總是說世界上沒有比一塊自製的、鮮美的櫻桃餡餅更好的東西了。"] = "73d13905cab099e18703a50ba5f9359e",
            ["我喜歡餡餅。"] = "c927831e286d4bf0f00bc791d24f0020",
            ["新鮮的櫻桃餡餅！香味撲鼻，讓你的眼睛發直！"] = "ea78d8c34142c49947facd4181a8e935",
            ["櫻桃餡餅是我在整個艾澤拉斯最喜歡的食物。"] = "d3411cffc21c4955c2412b95aba6b187",
            ["這塊櫻桃餡餅真美味，它可以讓長大的地精喜極而泣。"] = "2f19051795d51dc9463970ccd43e85b3",
            ["這餡餅真好吃，你要嘗嘗嗎？"] = "f6507323af9a61767666f452dc437353",
        },
        [9116] = {
            ["翡翠議會試圖治癒費伍德森林受傷的大地。儘管這片大地是以腐蝕它的東西命名，我們還是希望有一天我們能從這片土地中將腐敗清除。"] = "2a8913e6bf69413a4a09dcd8251c2340",
        },
        [9117] = {
            ["你大概沒想到會在洞穴中找到我，是嗎？$B$B我叫科琳，我實在沒法告訴你我是怎麼到這兒來的，但是我可以告訴你，這個洞穴現在就是我家了！$B$B我在這兒研究環形山裡隨處可見的奇怪水晶。"] = "66c50614a3cd2fe2f25a9eca3db0579c",
            ["北方的水晶塔接受黃紅綠三種顏色的水晶構成。$B$B而關鍵是使用黃水晶所產生的能量作為主要的力量來源。有兩種可能的效果：一種會製造破壞，一種會消除破壞。$B$B爆炸水晶需要紅水晶和黃水晶。這將產生劇烈爆炸，足以震懾你的敵人。$B$B恢復水晶需要黃水晶和綠水晶。這將給你提供治療光環。"] = "01bcaf00553bb38fb333b6db2f3cb425",
            ["東方的水晶塔接受藍色，黃色，還有綠色的水晶。$B$B它專注於使用藍色水晶作為主要力量之源而產生的能量。有兩種可能的效果：一種對精神有益，而另一種產生一種破壞性的護盾。$B$B精神水晶需要藍色和綠色的水晶。這將會增加你的勇氣。$B$B尖刺水晶需要藍色和黃色的水晶。這會產生一個對攻擊者造成傷害的護盾。"] = "7aacb8eb88afd4147515454792ecbd73",
            ["當然的事情，$n。還有一個給你。"] = "b7e24ad85062cc0dc304ed055246d2fe",
            ["西方的水晶塔接受紅色，綠色和藍色的水晶。$B$B塔門關鍵是要用紅色水晶作為力量源泉而產生的能量。可能有兩種結果：一種能提高你的防禦力，而另一種則是削弱敵人的防禦。$B$B防禦水晶需要紅色和綠色的水晶。這將會使你的裝甲更完備。$B$B破甲水晶需要藍色和紅色的水晶。這將會削弱即定目標的裝甲防禦。"] = "7ea1ceb93d20d721898ef917ff378fda",
            ["謝謝你，現在我們能解開水晶和神秘的水晶塔的秘密了，$N。要是你需要更多資訊，請隨時回來找我！"] = "22f26805022d0719d3460bfcb51e02f6",
        },
        [9118] = {
            ["啊……這些傢伙讓我整天都不得安寧！你看見他們了嗎？$B$B我真希望自己能藏到地下，避開他們……"] = "da1e790ce76a6ecf39767ddfb4578763",
        },
        [9270] = {
            ["嗯，見到你真好！我叫威利德·馬紹爾。我、我的姐妹以及同伴組成了馬紹爾探險隊——來自艾澤拉斯荒野的科學家和探險家們。$B$B我們在安戈洛環形山遇到了一點小麻煩，如果你有時間的話，就幫幫我們吧！"] = "e0280ea403de38a99d9f00704dc83cf8",
        },
        [9271] = {
            ["哦，你好！我是霍萊伊，馬紹爾探險隊的首席科學家和生物學家。我的兄弟和我，還有我們的同伴，一起到艾澤拉斯去探索荒野和未被馴化的雄偉景象。真是太激動人心了……但是，嗯……我想這次我們陷入了太多激動中了！"] = "7b7f229cfbe32d4ee349cb68442a6c44",
        },
        [9272] = {
            ["是的是的，我知道達丹加不喜歡煙。但從它身上的氣味來看，達丹加好像還不喜歡洗澡。"] = "8bd505152491e64f21b57ed618cde404",
            ["為了所有神聖高貴的愛，請告訴我你是來把我們從這片被遺忘之地帶走的。雖然我是與馬紹爾探險隊一起的，我願給你我口中的金牙，只要你讓我爬進你的背包並離開這個地方。"] = "6af8b6ef78b561f72f6edeacc7a46816",
        },
        [9273] = {
            ["嗨，我是派提亞。在我右邊是科多獸達丹加。我們曾跟馬歇爾探險隊在一起——那已經是數年前的事兒了，那時達丹加還是只幼獸呢。$B$B要是你帶有火炬或是任何火種，請盡可能地把它們藏起來。達丹加不喜歡煙。"] = "867d631c8296e1e605606fc3dd0d84da",
            ["從我們待在環形山這裡開始，達丹加就喜歡上了遍佈這裡的巨大的血瓣花苗芽。$B$B我敢肯定她會喜歡，如果你願意帶給她一大堆花苗芽的話……"] = "3f5d4bc764114d94d0ff2b482cd2cd8d",
        },
        [9298] = {
            ["你好！是什麼吸引你來到冬泉谷？這片寒冷廣袤的土地或許顯得有些淒涼，但是它蘊含著無數的秘密……"] = "0b8f51a79876c6c5d2b0c15431dd36f8",
        },
        [9299] = {
            ["很少有人能找到我……我能為你做什麼嗎？"] = "dddedefbebc656d4bd061f2f18065149",
            ["請不要打擾古老的靈魂。"] = "75c7653932086fa3c6eb2d294f26bd7a",
        },
        [9356] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "bf1f16f2143ef5e7d61ef40727a86228",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "28b7a10d1e6ce776b39a99b0bc3c5729",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "ceb9382c049e7883f6c2dc8d6da3a10f",
            ["你有興趣探索這些地下城中的一個嗎？"] = "5e09760e17cbc670577373cc3a58f914",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "b70df0c6d8237e82e8eab2e2cee97a1c",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "1cdc3bb3780b30bc1ddb25b3e96eeb14",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "bcc93e0f69a610e26e8a585d15e236ca",
            ["厄運之槌位於菲拉斯的中部。"] = "bdfe4126b453f140f54062473872a072",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "05939f53ff53a01d686ad496340f942e",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "f4ce8cc991dc9b8e53cbf5bafea7a20e",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "d564123ed4c19b647a19fe0e225ccf19",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "b710141cbfed33e4215f9f02e57b1285",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "a2cdf3bd1e979b72e72bfd012d8e4475",
            ["奧達曼位於荒蕪之地最北端。"] = "1e99d4a52530cf7eb53974fecc40f331",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "249672700d6d8eaf3dddfa4944dabb7e",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "7c8c35f7332064fb990b18d3a0864176",
            ["如果我們要成為這塊新地區的主人，那麼我們就必須要找個地方好好休息。把你的斧頭放在火邊，讓大家分享你英勇戰鬥的故事吧。"] = "5a6da618c793e9258ef0c0f097380291",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "d75d5996d34c833b6779a3d6dd1d88f9",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "36de4eae7af9c2c85092cd5d9a784b46",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "cc776f517441c1a0c836afb225bdd955",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "205467c00f8ce22c4506e988def469d8",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "c91ac29b4dfab5d21de4af780478b04c",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "b338594106da41470eef31ea3c010d21",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "8cdbbc96d739b730ea3dd0482497fe79",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "468d4c8dd235c155a2382b74b82c2fa9",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "53cfb8044c1292d233012d45237f180d",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "0bf530934f14695fb55ada3fb2991a79",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "695bffa496e17bf3ace18949095a965e",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "ffe6e6b7dd79a36fe035046b6c7524ad",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "dd38277dbccc541afb09092db925b6ab",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "ab1b05dce1379cc50a508ec75bc5fecf",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "14c79166424db4748000943061c77fa3",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "8ac7e0587a2cc50e68b7e657694ea364",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "bb800825ab4ca9a41793034fb343efdc",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "1ea4f7d4103e7f106c8b166cdb5e3649",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "de7e05a695ddb55f1f262b0dbebab57a",
            ["諾姆瑞根在丹莫洛的西邊。"] = "a28655b7a8d174f6fdec53c01d3eecef",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "aabd6bce4c7708c67d5b606f86e7331d",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "ef2ed86b87eea6787b3f9ed237bc7e6d",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "f67a76e0fd2826ef6fe57add373eec1e",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "ff16bb066f168df220edae5bdae69e4f",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "3b1d31e904b1fb9f4e2857c66fa8c682",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "727cf38438acf58ee35c39f6a28aa289",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "fa04ae9ff435e1e999be4418d11dc7a4",
        },
        [9465] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "30ee103c545f987ab518c70f6d3e640e",
            ["歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B只要瑪法里恩還在沉睡中，我們便永遠是平衡的守衛者。別忘了這一點。"] = "95baad8c0ee127ac815bdd480620f4f4",
        },
        [9501] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "a70be99ff08d4df4c93b09b77588a051",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "5d58291140199149e578fcbfbeed18cf",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "2d70ab98f838e1bb06030fcf93158968",
            ["你有興趣探索這些地下城中的一個嗎？"] = "a61f3b373d7747d0767475c1b5dab2f6",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "b07c8c68897f70867bbb75e49138b18d",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "8960494e8735de52e731bccc5622764d",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "1efdcf0d1f0182cadd7e556c2271b952",
            ["厄運之槌位於菲拉斯的中部。"] = "3e983a22901faae3beabe07a57c404e1",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "473bac4f85c8b79c1dd5b392e510c6c1",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "5f4d64e508e2e540625383eeae8529e5",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "a3c3d767ea37682d4d5d32cdda15eb9e",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "131cac36cbe3c50c8b0b73b5a5cc8e31",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "a5bb313bf3bd25a50fb0157cbb68e362",
            ["奧達曼位於荒蕪之地最北端。"] = "af158d110faf65cf2c8cfe5981eddc3e",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "991c35a1c8f32e2d36fef5a051a928bf",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "d208c04226b80a24f1f58b9d6011d18c",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "15cc28e6650ead1cf3c24a21428162eb",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "5699ecf40556711f57d029b802122744",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "579d342215c9b859125b292dde81b3dd",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "f108787b96326f0485800f2468879b89",
            ["我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。"] = "a98c33cf2b0c65fb09a0b00d67122e46",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d3df88e9b21fb13e7181cf562fb15e42",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "a68c695060e8db92a6407dbd039e03c7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "134711fa5dcb6d2514b7dd12cb58353f",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "5d241a73257b83bfb3f2a35e6c559cb8",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "1631876c10990f6b69fb643f319f15da",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "2761a549194820781531b07e3ccf0a6f",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "ec90c3b20200ec711da3c83a7d439020",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "ee0633ddb8208d730c4a1f7e2f75724f",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "b08c334deb14a22220d649a65f3c74fa",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "84004ad843c4e25945ff9c41c2c64e48",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "40835d72adb6d19a66d4db7eaf7b44e6",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "97df9679462d394c9c8acea3163a1db4",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "f469edb565c0b095a0fc47a970c24323",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "9d99c94eab41fbb7d5d8577ea1ef5b17",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2669d18d8bca0062b048b5b892ff56be",
            ["諾姆瑞根在丹莫洛的西邊。"] = "3a31427822c5fa1a87c7a675bd12855e",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "7f35f35703d028305ee4d76b181b5fac",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "2ace78d92e3daa88d503880d61a8825e",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "4d0ece2f2228a1a4c22ff7047c560d51",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "421a85045f22b0366436f5c512836a4b",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "105703cf3292f20db785559210529138",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "d1d167264b852e04dcc247504cad2f84",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "9607305c9027305933951bfdb21a86f2",
        },
        [9528] = {
            ["「達納蘇斯語？」$B$B夜精靈德魯伊滿懷期望地看著你，但是你顯然無法跟她溝通。她微笑著指向自己，然後指著你。最後她向北面的道路指了幾下。$B$B或許她是在說v疑鉿陳鉊穨A進行交談的德魯伊？"] = "60d3b613b0964e6b175fb809f8530f6c",
            ["我已經觀測到有四種植物受到了腐蝕術的影響：輕歌花、迎風花、鞭根草和夜龍植物。輕歌花和迎風花是費伍德森林中常見的植物，而鞭根草和夜龍植物就不那麼常見了。所有這些都是費伍德森林生態系統的重要組成部分。"] = "6f24888eac412dbfa5d0a5e430b3a3e5",
            ["費伍德的某些植物或許能因為塞納里奧植物藥膏的效用而避免墮落。我知道如何從幾種不同的東西中獲取這種藥膏，憑藉你的能力，你會發現有多種方法可以協助我製造藥膏。$B$B首先，你需要一盞塞納里奧信標，它是一種能讓你看到肉眼所看不到的墮落和腐爛力量的裝置。"] = "cd511841051bab517382934a36722298",
            ["這片美麗的森林受到了可怕的詛咒！腐化的力量將這兒變成了一片恐懼之地。如果你跟他們不是一夥的，或許你能幫助我奪回費伍德森林。"] = "fa07b8641ac6fc01719221caf46a9c3c",
        },
        [9529] = {
            ["「牛頭人語？」$B$B牛頭人德魯伊滿懷期望地看著你，但是你顯然無法跟她溝通。她微笑著指向自己，然後指著你。最後她向南面的道路指了幾下。$B$B或許她是在說v綵埵陳鉊穨A進行交談的德魯伊？"] = "0c05fe78c90faea203cc74d0db442095",
            ["費伍德的某些植物或許能因為塞納里奧植物藥膏的效用而避免墮落。我知道如何從幾種不同的東西中獲取這種藥膏，憑藉你的能力，你會發現有多種方法可以協助我製造藥膏。$B$B首先，你需要一盞塞納里奧信標，它是一種能讓你看到肉眼所看不到的墮落和腐爛力量的裝置。"] = "15b30f30284e6f8e6208980bb0c02d9e",
            ["這片美麗的森林受到了可怕的詛咒！腐化的力量將這兒變成了一片恐懼之地。如果你跟他們不是一夥的，或許你能幫助我奪回費伍德森林。"] = "9e0a1e0a2edfadef02d6ac0c504feebf",
        },
        [9543] = {
            ["你好！你正是我要找的人。坐下來聽我說，我有個可以讓咱們兩個都發家致富的計畫！"] = "84844fb1528038e49e3a68b7904bc912",
        },
        [9544] = {
            ["需要物資供給嗎？"] = "f28b9e7e4d01f9e539abe90f4d336ee3",
        },
        [9545] = {
            ["喝點東西吧，$c。這可能是你最後一次喝東西啦！"] = "5ef4543b47e41607c5262c9bd45be597",
            ["我聽說水元素中的貴族海達克西斯發動了對火元素的戰爭。真希望他戰敗！"] = "e6aaf0a5e40d69ade99a9420f809af6e",
            ["拉格納羅斯將擁有至高無上的統治權！"] = "fdda7a3b845dd1fad7eeb2a04301d3d1",
            ["水元素正在跟火元素交戰，也就是說他們也在跟我們作戰。他們的領袖之一，海達克西斯正在召集士兵……"] = "dc9fa668ac5349906d636b678a132bab",
            ["水領主海達克西斯公爵躲到了艾薩拉風暴海灣的某個島嶼上。那些傢伙能從那裡聚集什麼威脅？"] = "71d0fe83bfcaabb9c727ec622e2c8f4a",
            ["要不是因為黑鐵酒吧，我大概會用我的空閒時間來剝龍鱗。"] = "721ddf9aee8d38be1e406ccfabede9a7",
            ["要是海達克西斯招募了新兵，就可能使力量的平衡發生變化..."] = "47f7cce3de520c5508a34ffded05d078",
        },
        [9547] = {
            ["你喝過雷霆啤酒嗎？那可是好東西！"] = "591c33205f87d8b8a04f0848826ff374",
            ["我一個小時以後還要去值班，但在那之前……喝個過癮吧！"] = "e5940ea614a92eb97e63caf9aa1b863e",
            ["我父親告訴我：有一天，會有一個陌生人跟我交談，我必須控制住自己，不能殺了$g他:她;。"] = "68be82e6e85048cb5a920f993ea55b98",
            ["槍炮與硝煙彌漫，直到某一方被摧毀。"] = "abf0280c9a560d25936f42186fd8a258",
        },
        [9554] = {
            ["你在看我嗎，$g小夥子:姑娘;？"] = "655a713e625a9c8aa562c139e3b108c5",
            ["在我參加聚會時別騷擾我……"] = "f6084500090ca7d12e2c66378cd5aa82",
            ["我要來一杯黑鐵啤酒。哦，你不是侍者？"] = "ece4d3768034c645ef33751734b2eff2",
            ["我認為普拉格把桶裝得太滿了。你瞧，簡直都要炸開了！"] = "b0838447478eb4443855f138adb0edf6",
        },
        [9558] = {
            ["看來你需要通過無盡之海的通道。那你算來對地方了，這兒就是少女之愛號的停泊處，她是這片水域上最好的客船。當船到達後，你就登上甲板，然後用不了多久你就可以躺在荊棘谷的沙灘上曬太陽了。"] = "7384674c38fa1ede1c57e9601476e82b",
        },
        [9559] = {
            ["我必須承認，藏寶海灣有南海最好的雜燴蚌肉。哦，對烹飪不感興趣？那麼歡迎你投宿少女之愛號——在東部王國和卡林多之間航行的最好的客船。很快她將馳往棘齒城，在她到達之前好好享受吧。"] = "892299cedeab9a28288583ccf9e05af2",
        },
        [9562] = {
            ["你好，$c。"] = "0793fb444e9e3f6785a013caab465dd1",
        },
        [9563] = {
            ["$N$g先生:女士;，如果我不是很瞭解你的話，我就會以為你也是那些石齶怪中的一員。$B$B黑鐵矮人沒有把溫德索爾怎麼樣，畢竟他的老祖父的最好最好的朋友就是一個黑鐵矮人，這可能也就是黑鐵軍隊到現在還沒把他幹掉的原因。"] = "f6bdcd30db90e55d9637e3c9987ea927",
            ["你想要什麼？*嗝兒*"] = "d504ffea27d7eb3e97b337b0d8f9216c",
            ["你為什麼總說他死了？誰告訴你他死了？我從來都沒那麼說過。$B$B他只是不知去向而已。$B$B你看，很明顯，我們已經捲入了某個獸人對抗黑鐵矮人的戰爭中。獸人是一群骯髒又卑劣的雜種，他們設計了一些圈套和你可能永遠搞不明白的邪惡裝置！"] = "c177645f150a04089a48ce3fee8d7d40",
            ["嗯。你從來沒有聽說過反對者？那把傳說中的令獸人聞風喪膽的戰錘？對，對，那是溫德索爾的錘子。他說是弗蘭克羅恩·鑄鐵親自為他偉大的父親製造了那把錘。弗蘭克羅恩·鑄鐵，就是那個建造了巨石水壩之類的……黑鐵矮人。他還說有一把與反對者一起鑄造出來的戰錘被弗蘭克羅恩自己留著用了。他好像叫它鐵膽之錘什麼的。"] = "962d026487cbf6125cf85c23c70b9258",
            ["好吧*嗝兒*……嗯，你看起來很眼熟*嗝兒*。我有跟你說過我和溫德索爾一起跟，呃，一，一百萬個獸人戰鬥的事兒嗎？$B$B哦，坐下來吧，朋友，這個故事非常棒的！"] = "fa6b094aa05e38c070b4b21733b2104d",
            ["好吧，好吧。總之，從某種意義上說，我退到了一個不起眼的角落裡。$B$B溫德索爾似乎並不安分，看看他那歇斯底里的樣兒。他拿著反對者戰錘沒命地亂揮，像發了瘋一樣對獸人咆哮著。"] = "690c5b30094325d484e5543404f35a46",
            ["很願意……只是讓我再多回味一下這一刻。"] = "8354aacf86057a0a57136055524c8b80",
            ["我單挑50個獸人？我可不是傻子，$N。我爸爸常說「卑鄙是卑鄙者的通行證」這類的話，我突然之間就明白了那是什麼意思。"] = "1be7208d0ab559b4aa9516a496480d4f",
            ["我說到哪裡了？哦，獸人突襲了溫德索爾，溫德索爾呢？他是山崩於前而面不改色，從容應對。只見反對者擊起沖天血光，鮮血四濺，持續了數個小時，沒准是數天。我記不得了。但是最終，殺戮停止了。"] = "7aa6ffbdd145e15c81d0c2d28f414376",
            ["放慢速度！就快接近了！$B$B他在那兒，全身血肉模糊，連內臟都流出來了，是誰把他弄成這樣的？$B$B黑鐵矮人！你記得我說過的話嗎？？$B$B嗯，黑鐵矮人比黑石獸人更為狡猾。他們是有備而來的。人數有300之多……*嗝爾*。"] = "e6876b6097ccfbc4b0d22b4131e86a41",
            ["最後！用手指堵住你的耳朵，你的腦子有可能會變得有五倍大，事實上，我甚至擔心你的腦子會泄出來。$B$B那麼，黑鐵矮人們饒了他的性命，但把他囚禁了起來。他們的首領，某個叫做索什麼森的妄自尊大的，愚蠢的，自負的傢伙，把反對者留作己用。那是我最後一次見到溫德索爾了……*嗝兒*"] = "0118ec1267be1c85077cb16e372ddb82",
            ["死了？你在開玩笑吧，$N？搞清楚，$n$g先生:小姐;$N！溫德索爾絕對不會死於區區50個獸人之手，這就跟塞爾薩瑪血腸是世界上最美味的食物一樣不容置疑，他被獸人層層包圍，但是他確實還活著……而且他非常非常憤怒。"] = "6bfdc528f1baabb880a6dd91bc9d22f8",
            ["溫德索爾那天特別愛跟人爭吵——相信我，對溫德索爾來說，那是一個有紀念意義的偉大成就。他一直在跟我說「感覺有些怪異」。他不是在開玩笑！$B$B當那些骯髒的野獸出擊時，我們還在黑石山脈的中央。當然，我指的是獸人。你別分神，好嗎？一時之間，叫喊聲和鐵器的敲擊聲四起。"] = "024d63b41f43523cad602cd53f29373c",
            ["矮人可不會喝醉，$g先生:小姐;。我只是有些邋遢。$B$B無論如何，溫德索爾？我猜他在黑石深淵的某處。對你們這些未受教化的傢伙來說，就是一座黑鐵矮人的城市。"] = "cd9aecdc57c1469285fe9725899dd1cd",
        },
        [9564] = {
            ["氦彈點火和爆炸的過程是沒有危險的。跟船隻相比，這寶貝能更為快速安全地將你送達幽暗城，途中的景色真是驚心動魄。說到這，在地精飛艇上是不允許吸煙的，旅途中也不允許使用火的法術。"] = "e687cf35c3296cb3a216d85b708a86fb",
        },
        [9566] = {
            ["我兄弟說我們能在這條商貿路線上賺到更多的錢的，但是他沒告訴我要獨自應對。要是你乘坐地精飛艇沿著這條路返回的話，你能幫我帶點吃的嗎？在奧格瑪，有人出售最好的肉類，當然我還能以那些苟延殘喘的動物為食的。"] = "29ab1815cf6aff3f41bd5f69c7535753",
        },
        [9584] = {
            ["在光明與黑暗之間，還有陰影……而那些陰影有些你未曾見過的力量。"] = "b004638e71ea2dd674f8a6129b70bb5d",
        },
        [9616] = {
            ["一個純淨的樣品就是在非故意情況下未被腐蝕的樣品。我們需要盡可能在最基本，最正常的環境中找到這樣的生物。$B$B這意味著某個全無文明痕跡或是未受艾澤拉斯某個種族所影響的地方。某塊……處女地。"] = "f2a8da67c8ee4c6d3a3393f105fc59f6",
            ["不可思議，不是嗎？所有這些神器和殘骸。$B$B我不清楚是什麼給我留下了更為深刻的印象，它們的規模，還是它們背後的故事。要學習的東西還很多。我們能找到其中的關聯……$B$B你知道那個傳聞嗎，聽說許多種族與夜精靈有著相同的遺產。"] = "42caaa998442825e5b9fbce4fbeebb15",
            ["不，我並不清楚。似乎那主要與地域有關。有些種類稱為泥漿怪，有些稱為泥漿怪。似乎這屬於個人偏好。$B$B每次我遇到軟泥怪、淤泥怪或泥漿怪時，它們從根本上都是一種生物。不同之處在於它們的環境，這也是我們需要一份純淨的樣本的原因。"] = "b987f43f6e42e054381a65cb49093b00",
            ["看看這些樣本！這意味著什麼？這意味著什麼？我需要時間來解讀這些資訊。我還需要更多我無法獲得的資訊……該死！好好想想，拉裡斯，好好想想！$B$B你要做什麼？什麼？！$B$B必須得有解決的方法！"] = "325202f61bd075f89ee398965028ddbf",
            ["那絕不是東部王國的任何一個地方。$B$B一定是在卡林多大陸的某處，但是距離部落和其他種族仍有相當遙遠的距離。還沒有受到分裂影響的某個地方——遠離夜精靈文明的地方。$B$B我猜有人守護在那兒……就像守護山谷或是環形山一樣；我不確定。我只是猜測。很抱歉我不能提供更多的幫助了。"] = "5064c5f5065d6cee4390d39aafdd640a",
        },
        [9618] = {
            ["你見過安戈洛環形山的所有奇景了嗎，$N？真是令人驚訝。雖然它們沒有我製造出的東西那樣精密，但這裡所有的東西都是天然而成的……這就真是太奇特了。$B$B我的叔叔雷塔維就喜歡這樣的地方。我正沿著他的腳步前進——我還想從滅絕的文明中找到新的知識！"] = "8b0d0bd7e2e4900b54439fe456de6f0c",
        },
        [9619] = {
            ["你好，$c。對於某些人來說，獵人是一種生活方式，一種所選的職業。對於其他人來說，這是用來消遣的東西，一個勇氣的徽章，或是依照你的部族的某種通過儀式。$B$B對於我來說，種族和職業什麼都不是--我所尊敬的是對你的靈魂和心智的測試。因為對自然力的抵抗和他們的技能的測試是真正榮譽的標誌。$B$B如果你希望檢測自己並贏得我的尊敬，那就跟我多談談。"] = "302082b5cf2a5247bbde060d031b8f3d",
            ["你正行進在一條光榮的道路上，$N。我的祖先尊敬你的意願，但你在完成我所交付的任務之前我不會對你有任何認可的。$B$B如果你希望證明在精神層面是一個獵手的話你該知道你必須做什麼。"] = "4684810582123d33350ebde21f845247",
            ["安戈洛這裡的暴掠龍看起來與貧瘠之地的猛禽有關--非常聰明，十分靈活，還有一種行為的感覺或是守則。其中我所遇到的最偉大的是拉克維。他是我所見過的最危險的動物之一。在牛頭人語，拉克維的意思是「鋒利的爪子，」但那對他並不公平。$B$B如果你計畫獵殺拉克維的話，千萬不要低估他，但如果你決定要這樣做，無論如何我都會幫你的。"] = "9b861526235ee45fafee1db50791036f",
        },
        [9620] = {
            ["你好, $c。我今天情緒很差，所以除非你能幫我，否則我更願意自己一個人待著。"] = "2e2206ddcfb46257589dd619b5ae7118",
        },
        [9676] = {
            ["或許這會令你震驚，但是近來的事情不是那麼順利……"] = "df99ffe8f4307e58e2877badedf13a55",
        },
        [9679] = {
            ["是誰派你來的？"] = "7594596aad831a20598b3e166ad2bda1",
        },
        [9990] = {
            ["這兒就是那場聲勢浩大的戰爭的遺址。那些偉大的戰爭啊。"] = "f9fe6067b476d43bd34c6ff1b4e89b22",
        },
        [9997] = {
            ["歡迎來到避難所，$N。有些人來這裡是有目的的，其餘的是湊巧路過……但是每個到這裡的人好像都有一個奇特的故事要講。"] = "291d560fcee6b61965630c94cc231833",
        },
        [10043] = {
            ["你在看我嗎，$g小夥子:姑娘;？"] = "74fec410f05cdc4e4f0a9e7100a7ad5d",
            ["在我參加聚會時別騷擾我……"] = "be9d61d931560a93f3074abf148cd50d",
            ["我要來一杯黑鐵啤酒。哦，你不是侍者？"] = "e52f59e5f53cbdeeadfe575ab9f95b1a",
            ["我認為普拉格把桶裝得太滿了。你瞧，簡直都要炸開了！"] = "f85bd951c3aa0755cff0ab158e1d261b",
        },
        [10086] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "aa7ffa0f57cad7bf854f0f5b49d0d64f",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "99ae018db8b20fbf298b816ac77acd9c",
        },
        [10088] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "3e8648aa82161723a67251338bf73c39",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "219bae0db1dc3bac08b33887cbea7f96",
        },
        [10089] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "89218c24a0eff1fa5c10022467769ef7",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "4c9a93178a8bd81be46f856336284914",
        },
        [10090] = {
            ["你來接受訓練為的是把它傳遞到你的寵物身上？"] = "12e2351404174f85aa98fa3a3524bcd0",
            ["啊朋友，我只幫助獵人和他們的寵物。"] = "b439ced1ada35971e9ff2706f428bff0",
        },
        [10118] = {
            ["泰達希爾海岸邊的魚兒又大又精神。有傳言說那是因為我們新的世界之樹的快速增長而引起的。"] = "79a80086c60f1ce491ae229891c58ed9",
        },
        [10136] = {
            ["希瓦娜斯女王已經下令對艾澤拉斯的某些自然現象進行調查。她覺得能從艾澤拉斯神秘的歷史中學到更多的知識。$B$B我不知道要如何才能學到這些知識，但是我完全相信她，因此我會盡力而為的。所有的生物看起來很相似，但是周圍的環境對它們的影響是不容忽略的。$B$B我需要你幫我收集生物樣本。"] = "33c6ef2aac8ebd35c760b534ba1417d9",
        },
        [10162] = {
            ["你是不是想要我在萬能的$N之前畏縮？$B$B你對我不算什麼。什麼都不是。如果我想要你的頭顱，那它就會被插在長毛上呈送給我。$B$B你犯了所有凡人都會犯的錯誤。$B$B<奈法利斯歎了口氣。>$B$B如果你像花錢一樣花費你的時間，那就會發生一些奇怪的事情。"] = "5283b76d0c71a7568935cb1ce8af6973",
            ["在你匆忙追尋榮耀的過程中，你有沒有想過你的行動對於遊戲的節奏影響。你是否感覺我說的話很荒謬！我所說的話都是如此哲理化，這讓你頭顱裡那花生大小的東西感到十分迷茫。"] = "747904c03bd92809a1a0c31aba9a13d5",
            ["這是真的。請允許我總結一下……"] = "130699ec6a671fa53155b654690ba9cb",
        },
        [10182] = {
            ["你好，$c。我是部落的勇士雷克薩，是索爾的僕人，是野獸與野性之王。"] = "af40e357c59edbf15d948e3c6f65eeb5",
        },
        [10216] = {
            ["你好。我是古博·布拉普。"] = "363e9a32646c220ede74b874d124997b",
        },
        [10219] = {
            ["願月神與你同在，$c。月亮神殿已經來幫助奧伯丁飽受煎熬的公民了。"] = "35f3abb9c514c878d528d18c9e29c073",
        },
        [10266] = {
            ["你學得很快，這是件好事。但要注意按照工作的要求適當地完成工作。現在，我恐怕必須要把你送到斯納爾那裡多學些東西。你要學會所有他能教的，但不要聽他的氣話。當薩魯的女兒笑話他時他就變成那樣了。"] = "24f51d17fe915ec4494f6d0e34a9f697",
            ["我可以告訴你你想知道的一切，但是你必須要有耐心。去練習打鐵吧，摸索用錘的力度。當你熟練後，自然也就掌握啦。"] = "1292f9db32a49a3e54c9f232d6642515",
            ["斯納爾因為我動作太慢所以說我很笨。我只是想做好工作罷了，這得花時間的。"] = "fcb888f0ece4f405f7b532de65cab6d0",
        },
        [10267] = {
            ["燃燒平原是個危險的地方，但是我這樣的學者將不惜一切代價來獲取新知識。"] = "0129a1932545fbd6f1207e37cb4938aa",
        },
        [10276] = {
            ["你是個有天分的學生，而且還是個有潛質的鐵匠。我可以在本週任何時候宣佈你可以從我這裡畢業了。但是我覺得你還有東西要學。去找本古斯·深爐談談，他是個嚴厲的人，但他也是最出色的。"] = "6ff1f5911fd79355d3991c42c4b661fa",
            ["很抱歉，$g小夥子:姑娘;，你還不夠資格在我這兒求學。去找我的兒子 格魯姆，他會收你做學生的。"] = "bd72d5e5581d2bb7837469dfbe7b0df0",
            ["是的，很高興能教你如何鍛造。繫上圍裙，拿起鐵錘，看看我們能鍛造出什麼來？"] = "d0ab183a7e4df704c1fbf1106d87c75f",
            ["鐵匠的生活可不輕鬆，但是它能讓你體格健壯，充滿熱情。我的父親是一名鐵匠，我的祖父曾經在格瑞姆巴托的煉鐵爐工作。現在，我的兒子也跟隨著我們的腳步，他讓我倍感自豪。"] = "d8e60ce5ca29731c4ca9356a1d489a59",
        },
        [10277] = {
            ["你知道的比我還多，這一點很肯定。我告訴你接下來該怎麼辦，去和我的爸爸談談。他是個好的老師，但是他會要求你證明自己的實力。他的名字叫洛特加斯，你可以在本古斯的鐵砧旁邊找到他。"] = "8cb31fa91b233530a009b37757a52a1c",
            ["你確實有點本事。我打賭你的技術足夠讓你學些東西了，我們來看看我有什麼能教給你的，好嗎？"] = "e7e02c3d3ac0a13d76cb2cf9dc565fb0",
            ["嗯？我沒時間聊天，我父親要我完成這個使命。"] = "23e45eee692218bf280d545a69ead14a",
        },
        [10278] = {
            ["卡恩說我們需要聆聽熔爐和鋼鐵的靈魂之聲，它們會指引我們的。我只聽見一陣鈴聲。拿起鐵錘，讓我們一起試著聽它們在說什麼。"] = "d6fbe05e48c6cf06d03257121d657e86",
            ["我在聽，我在聽，但是聽不見卡恩所說的那些靈魂的聲音。"] = "e471095c7b88ecc0041ea59e5ff3c266",
            ["我猜那些靈魂更加喜歡你，我還沒有聽到他們的召喚但是你看起來已經上過他們好多課程了。去找卡恩談談，他會很高興看到一個像他一樣聽到它們聲音的人。"] = "ddd1000f31cef4a50e6a1ff257a17c4e",
        },
        [10296] = {
            ["你必須在這座要塞下層部分的那些邪惡生物裡找到一個擁有原始晉升印章的傢伙。對於那些劣等生物來說，得到這枚物品是一個至高無上的榮譽，這是邁入堡壘上層，進入奈法利安的精英軍團——黑手軍團的第一步。找到這麼一件東西，把它交給我，讓我來檢查一下它，然後我就會知道下一步該怎麼做了。"] = "3665f98f37757be019cc201ddc735e97",
            ["你要知道，這樣的物品是非常罕見的。你可能需要進行數年的搜索才能找到一枚印章。我建議你對這些邪惡的生物毫不留情，把他們全都殺掉。"] = "c68826894514cd6d1e1162359ae8dbdd",
            ["別再靠近我了，$n。我已經可以感覺到印章中流淌著的邪惡力量了。$B$B給我一點時間，讓我來檢查檢查——你要緊緊地握住它。"] = "0958c9f61564c247675031fbb4a44632",
            ["在被放逐之前，死亡之翼曾試圖產下混血的後代。混血的龍不僅無法獲得守護巨龍天生的力量，也無法被死亡之翼控制。$B$B似乎奈法利安在他父親失敗了的事情上取得了成功——至少是一些進展。$B$B夢境之神伊瑟拉預見到了這種混血龍類的存在，我們必須殺死那些「彩色」的龍。"] = "7e08d0e98d66a73f420ce04d31cf6d67",
            ["很久以前——我們的種族經歷了無數戰亂和衝突，幾乎到了滅絕的邊緣。我們承受了太多災難，$c。$B$B燃燒軍團的進攻，惡魔之魂，巨龍軍團的分裂，死亡之翼的崛起，我們的女王雅立史卓莎受到龍喉氏族的奴役。$B$B經過種種磨難，我們擁有了不可動搖的意志——那是努力生存的大無畏力量。"] = "70ff6628453819c5b1c1d6d5eed119e7",
            ["我以你所能接受的形態站在你面前。顯然，你無法接受一條名叫瓦拉斯塔茲的龍。$B$B<維埃蘭笑了起來。>$B$B我可以繼續嗎？"] = "8333270249e46a72656aa0258ec27a0a",
            ["或許我應該告訴你為什麼我會在這兒。$B$B你知道死亡之翼或者他的後裔，奈法利安和奧妮克希亞嗎？"] = "8e2703518fe6096cd0cf2fb34cc39fc7",
            ["是的。最終惡魔之魂被摧毀了，剩餘的四條守護巨龍聯合起來，幾乎取了死亡之翼的性命。沒人知道死亡之翼現在到底在哪裡。但是，我們知道他的一名後裔奈法利安正統治著這座要塞，希望能繼續他父親未竟的事業。"] = "283edf106300c079a0397d8d37162308",
            ["死亡之翼，曾被稱為奈薩里安，它是代表世界的力量的守護巨龍——世界的締造者卡茲格羅斯賦予了他無盡的力量，讓他保護這個世界。$B$B但是這個卑鄙的傢伙欺騙了其他四條守護巨龍，讓他們使用自己的力量製造了惡魔之魂——這使得他們的力量大為減弱，巨龍軍團於是就分裂了。"] = "aad11ec70dd5748c7f88eda6509fec54",
            ["這不是我們做事的方法，也不可能是。奈法利安受到遠古結界的保護，這些結界與守護巨龍本身一樣古老。正是它們阻止我進入這座要塞的內部。除非……除非得到授權，否則黑暗魔法會永遠把我們擋在外面。"] = "cfcdfa8b51b68b1a378949e2188ddecc",
            ["除龍族之外的任何人都可能獲得晉升印章並通過那層保護屏障，但是這樣的東西肯定會要了我的性命，或許你能使用它，想辦法破除屏障。"] = "6df067091aa33b9e13c67c654d250c87",
        },
        [10300] = {
            ["你好！我剛剛探索凱斯利爾廢墟回來，就在西南方。現在我決定調查在這個山脈之上的梟獸，在梟翼樹叢內。$B$B你與魯瑟蘭村的艾瑞拉斯·琥珀談過話了嗎？他要求我來這裡，或許他還有任務給你。"] = "17dd87ec78f0ac1fa26bdd906869278d",
            ["再次感謝你，$n！我對我們所發現的東西感到很高興。$B$B祝你好運！"] = "3c5d2a9611ce5bf150c04f924634e640",
            ["我準備出發了，$N。我需要一些幫助——你願意跟我來嗎？"] = "1e3795fa61eca0a3ad809d0994bcae39",
        },
        [10301] = {
            ["作為探險者協會的一員，我曾在這片區域搜尋古代器物。據說冬泉谷有許多不可思議的物品……很多物品都受到嚴密的保護。"] = "f694c689e77899c4faf5ac919d971f4f",
        },
        [10305] = {
            ["我們這裡天氣真是好啊，你說是嗎？"] = "63b0c2ab50bf6fff81cba4b99f297a2e",
            ["我會贏得最後的勝利……等著看吧他們！喔，嗨，$c，我沒看到你在那。"] = "688e7a178f4c5a3e69d6b3cd086d6fdf",
            ["為什麼當你需要發條式同步協調陀螺儀時永遠都找不到它呢？"] = "60bef144ff90534acfd671fd7d8e653e",
            ["發明，我親愛的$c，是百分之二瓶裝的靈感，百分之四太陽的曝曬，百分之六被正午清除的大雷雨，和百分之九十三的烏米。$B$B等等，這樣加起來一百了嗎？我把我的筆記放在這附近了。"] = "ce950915a538ac6011289e41f41d81a8",
        },
        [10307] = {
            ["啊，$r……我瞭解很多關於這個世界的知識，以及如何製造巨大能量的符咒的方法。"] = "ee0118c262f4f0767f51f3c02deccad3",
            ["我很驚訝一個如此粗心的人竟然能走到這裡……$B$B是的，你可能還有一個符咒，但是瑪艾里對你的行為很生氣！$B$B現在趕緊離開。"] = "55736486d43a06033535e44262d7f497",
            ["瑪艾里的容器有很多秘密……用來製作它的碎片是可以反光的，你可以使用它的反光面從其他事物身上吸取能量然後反射到自己身上。$B$B將護符放在你的背包裡可以讓你聚集魂精，也就是與你戰鬥的野獸的靈魂力量。一旦你找到魂精，你把它帶給瑪艾里。"] = "8c3856d3ea60f4a2ad63d70c66960253",
            ["瑪艾里知道你為什麼找她……$B$B帶給我你找到的魂精，我就會為你轉換它。"] = "f66cef306e49f3c3da47f92b03dae4eb",
            ["魂精是每個生物都有的能量。我為你做的護符使你能以物理形態來抓到它。$B$B我知道一個可以轉換你發現的魂精的咒語，並把它轉換成魂能。$B$B你然後可以得到瑪艾里的容器，並使用它把魂能的能量轉換到自己身上。$B$B來吧，試一下。把瑪艾里的魂精帶來我們開心一下。"] = "10bf42d80d54731cc56b1129871564d4",
        },
        [10360] = {
            ["$N，銀翼哨兵必須被消滅！你做好進入戰歌峽谷的準備了嗎？"] = "11e58e60ca0813ec5ce983fe8d5fbd5f",
            ["很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。"] = "7fe3331e4b1c06adee7ab9eb667d175d",
        },
        [10378] = {
            ["今天要我送你去哪裡，$c？"] = "a281fc87589677c9d7b3b3b6c436891c",
            ["善待這頭雙足飛龍，牠將會搭載你到達目的地。願你的祖先與你同在，$n。"] = "a2429122d1ceeaef4fd2594c4ed06f2b",
            ["這些道路都是大地之母走過的道路。無論你決定前往何方，願大地之母與你同在。"] = "6d3a93f6d75f5ea11db68e9fab66c95f",
            ["雖然十字路口似乎是貧瘠之地的活動中心點，但是我更喜歡陶拉祖營地的安靜。你想去哪兒？"] = "ab5956b42af65d0c546a7454fb3339dd",
        },
        [10431] = {
            ["你好，朋友。願黎明在這個亂世之中保佑你平安無恙。"] = "9ec1c2021f5f1a32200d3ff28474b403",
        },
        [10433] = {
            ["你的未來烏雲密佈。集中精力，再問一次。"] = "401299a0cacc697ae0842c601a4e1272",
            ["你的精神不夠集中。你對我隱瞞著什麼嗎?"] = "6fe04378d0356a133c01252fdf1a5069",
            ["你看起來不像是個學生……"] = "9a65e2620d90d094df252c8038ca632a",
            ["我感覺一場動亂潛伏在你周圍……"] = "18a7c71660d684204d4641014512c4b6",
        },
        [10445] = {
            ["一個很好的問題！我們馬戲團這裏有很多東西出售。如果您對食物和飲料感興趣的話，那麼您可以去斯塔姆和塞蘭妮亞的小店看看。我最喜歡的就是暗月特別套餐。  如果您想要購買一些特別的東西，那麼蘭拉出售的貨物將會很適合您。她擅長於從世界各地收集稀有的東西。  另外從到處跑來跑去的弗里克那裏購買可以用於投擲的球和寵物青蛙。"] = "f65ade535c8771bc0c01fd7cb18abc05",
            ["很高興您問到這個問題。暗月馬戲團獎券是我們鼓勵大家幫助馬戲團所推出的，您可以使用這些獎券來兌換特別的獎品！  首先您可以找克洛諾斯、克莉·希克斯和亞布·尼比蓋爾談談來看看您有什麼可以幫他們的。他們總是需要幫助。  當您有足夠的獎券時，和吉瓦斯·格里加特談談，他有很多獎品可供選擇。"] = "0e05415896b51970c2f2c4b32e27f456",
            ["您好，$c，歡迎來到暗月馬戲團。在馬戲團這裏有太多可以做的事情了，所以第一次來的客人可能感到有些不知所措。這就是我在這裡幫忙的原因。您有什麼問題嗎？"] = "c4a44b124e903ad1e0ee8d803578a09a",
            ["我們最新的產品，我不會多收你的錢，就是這些小型坦克，可以受馬戲團裡的任何坦克控制臺所控制。$B$B你所要做的就是啟動一個可用的控制臺。每輛坦克會裝備一批儀器，還有可以隨意對你的敵人釋放的特殊能量。$B$B和你的朋友一起打場史詩戰，四處逛逛，或是去試試它的威力……隨你想怎麼作都可以！"] = "28afbc56bae96b9816c3cd75972b3548",
            ["我強烈建議你去賽吉那裡算個命。我知道，我知道……他是一個豺狼人。但是他是一個擁有特別力量的豺狼人，他可以預知你的命運！$B$B而且我們不斷在增加新事物擴展我們的馬戲團！"] = "0e3b200f99409d7e38d9ee962e90629f",
            ["沒有人知道誰製作了暗月卡片，或者他們真正的意圖是什麼，但是我可以告訴你，在艾澤拉斯各地都可以找到它們，那些試圖揭開它秘密的邪惡怪物手中都可能有卡片。  一共有四種類型的暗月卡片；野獸，元素，入口和督軍，每種有8張卡片。如果你收集了所有8張一套的卡片，那麼你可以把它們交給我們的薩杜斯·帕雷教授，兌換一件強大的飾品。"] = "5ae37073953338396beb228494dde0c8",
            ["衝擊者5000型超級大炮是一種最先進的單人拋射儀器。他以龍的速度運送裝載，這個大炮是布拉斯坦海默家的驕傲與喜悅，他們的航空與彈藥技術是出了名的！$B$B如果你想和鳥一樣在空中翱翔，就去雷霆崖獵人高地南方邊緣找瑪克希瑪·布拉斯坦海默。她會在石牛湖南方的目標向你瞄準！"] = "87b09a922c391e38efa252e8ee6d8551",
        },
        [10578] = {
            ["啊是的，我就是加德林的助手。在這裡的志願工作就是我通過巫醫學校課程的方式。既然你幫了他，我就免費幫你。需要修理什麼嗎？"] = "c47613e829659c77c1817810ed8fa886",
            ["嗨。去那邊跟我們的加德林大師談談。小心札拉贊恩的發狂，我也會好好照管你的。"] = "5c340bf8d079d06c25dc98c4fde2c2c0",
        },
        [10618] = {
            ["旅行者，你好。很少有人以這種方式找到我。$B$B我叫雷沃，我在寒冬之泉馴化霜劍虎，使它們成為坐騎。$B$B這些貓科動物非常兇猛，極難馴服。只有那些最值得信賴和最受人尊敬的人才可能騎上它們。$B$B我是不會隨意出售這樣的坐騎的，你必須用行為來證明，讓我和霜劍虎都接受你。"] = "36c8e9c4ac3bcc7350a02ddb82c11cbc",
        },
        [10637] = {
            ["對我這樣的工匠來說，製造的流程本身是很簡單的。$B$B困難之處在於獲得原料。如果你能為我取回一塊完美的比斯巨獸的皮，我就能用它製作出一些強大的裝備。"] = "5c51b2b4d2e369e2c9b1c95f23c50db1",
            ["我估計獲得這樣一件東西的概率是百萬分之一！一件讓你終身受用的獸皮！即使是技藝最高超的工匠也不一定能剝出一張完美的皮來！"] = "8a0cd35a24d37645220db16398cde660",
            ["瑟銀兄弟會是不會在螞蟻身上浪費時間的。快滾開！"] = "807f545aa510396b39fd74ed72c9abcb",
            ["要是你真的帶來了那張皮？嗯……讓我為你展示一番吧……"] = "dcf2194937d4f71a8dcd75edc4a3df89",
        },
        [10667] = {
            ["你好，$N。我是克羅諾木，但是你可以叫我克羅米。我覺得叫我這個名字舒服些。$B$B現在——你問我是怎麼知道你的名字的？我是青銅龍的一員，永遠與時間的消長相合。你可以認為我們以前遇到過。到最後，我們還會再次遇到。$B$B我希望我的行為不會打擾你；雖然我有可能作為一個悲傷之地的哨兵被起訴，我還是選擇離開那個傷心的地方。"] = "5fbeeb1ccae7f0a6c91aa94af815dd14",
            ["嗨，又見面了，$N。我感覺時間流仍處在強大力量的威脅之下。青銅龍始終歡迎你不斷地提供幫助。$B$B雖然過去的事情已無法改變，但是將來卻變化莫測。你此刻做出的決定將改變未來。"] = "a1aab080f67d3f1164b33c4dc1a8628b",
        },
        [10668] = {
            ["你把屍體翻過來然後看到她武器上的標誌——她的護甲已經都損毀了，她的頭髮披散在她的臉上。$B$B根據曼寇里克對於她的描述，你可以確定這就是她的妻子。$B$B他一定會為這個消息而感到悲傷，但是你相信他還是希望知道真相的。"] = "234801d843bf8cf2c310d7552c3d58d3",
            ["這具屍體屬於一個女性獸人戰士。$B$B很明顯她是在戰鬥中死去的，或許是在對付這片地區的野豬人時死亡的。"] = "3b33513dae45313b3f3adfa0fe9a92e2",
        },
        [10739] = {
            ["「……」$B$B牛頭人德魯伊的屍體靜靜地躺著，看起來他好像終於離開了這個世界。"] = "08f10ccaf3a2c6de55534ebff038dd0f",
            ["我的$g兄弟:姐妹;幫幫我吧……$B$B我很快就將離開這個世界了，雖然我飽受苦楚，但是我知道死了之後所有痛苦都將解除。但是，那些野生生物，我的$g兄弟:姐妹;……也歷經折磨，永無止境。在我生命的最後一刻，我請求你的幫助。"] = "67169b2421921ed2ab7e41cf84226c3c",
            ["是的，我講的語言你聽得懂$r。我們不是動物，然而你們中大多數卻仍然把我們像動物一樣對待！可是我們的分歧比起降臨到這片土地上的悲劇來顯得微不足道。懇請你們把與我們存在的分歧擱置一邊，傾聽一下我臨死前的請求。$B$B我來到這片土地盡我所能改善狀況，而現在除非你能幫我，否則那即將要化為泡影。我用我生命的最後一息請你幫這個忙。"] = "fc72657a0b7757c758fbe98a28b4863d",
        },
        [10776] = {
            ["吆……我需要一根煙和找個好看的地精女人摸幾下--倒不必非要按那個順序！$B$B我被困在那個東西的肚子裡已經有幾個月了。今天幾號了？啊，不要緊。重要的是我終於出來了。$B$B嗚呼！"] = "5f1f0e28e348cf72010f73f014cb9b70",
            ["嗯，或許報酬這個詞不是最合適的說法。當我在那東西的肚腹之中時，我在想：$B$B這傢伙生活在灼熱的岩漿中，火焰卻不能傷害它一絲一毫！$B$B如果我能找到這樣一塊獸皮的話，我就把它交給我在永望鎮的朋友瑪雷弗斯·暗錘。如果說有人能處理這種獸皮的話，那個人就是他。"] = "12bce043b0d0ba91f429d223b8e97e54",
            ["好吧！我在熔岩之橋的熔岩坑測試熔岩服。一切進展順利。我甚至能在熔岩中毫髮無損地游泳！$B$B我在那兒做自己的事，有時仰泳一會，突然之間它把我一口吞沒！若不是有了熔岩服和可攜式食物機，我一定會就此交待了！"] = "7e23ebd49115fad0274189ded663c258",
            ["幫我送個信怎麼樣？"] = "22ee28d189fa3b49336e5fd6ae19e0a2",
            ["怎麼進去的？？嗯，這故事真長。"] = "6e90d3077653ad699d905c6ebe2aaf4e",
            ["我才從這野獸的肚腹之中出來還不到兩分鐘，就有人問起我如廁的問題？？？$G先生:小姐;，如果你不是救我的那個人，我一定早就把你敲傻掉了！$B$B無論如何！我很感謝你的幫助。或許我能回報你？"] = "71b68e27db937dc7dcf4766a94966110",
            ["我說，我感覺你對此充滿懷疑——但是，那就是事情的經過。"] = "1d5dcce8ac2f04731c454fbfd07ec7a4",
        },
        [10778] = {
            ["噓……你聞到什麼了嗎？"] = "bd316b134b1553f8c2812e88e1ed7879",
            ["我有很多要做的……在瘟疫來之前有很多……"] = "97cae01d2b74c64090dbea405e8078cc",
            ["我的時間不多了……我們的時間都不多了……"] = "05b52a89d74994808cbdc88b48f34216",
            ["每個人都是怎麼了？我感到……很冷……"] = "691a1b43d1fe9daf4969e06a4e0f3a05",
            ["精靈用一種從前沒有過的審視感覺看著你。$B$B「我感到一個大負擔從我的靈魂中消除。很快我就可以永遠平靜的休息了。我現在知道這一點，而且我耐心的等待著這一時刻。$B$B謝謝你，陌生人。」"] = "c662992bcd429b04031c68f128e25b7f",
            ["約翰,親愛的,你在哪裡?"] = "8af79abbc20fb247ba4adbcf556582a3",
        },
        [10781] = {
            ["我是這座城市的官員，從事幽暗城的人口普查工作。自從我們從天譴軍團中解脫出來以後，我們就盡力對我們的城市人口做出精確的記錄。通過一些祕法方式和聰明的方法，我才得以弄到這些記錄。如果你需要有事找我的話，請繼續。你應該知道你是否有事需要我的幫助。"] = "24e7ef74fe54cfa4f4d5f92d6d6644ab",
        },
        [10782] = {
            ["歡迎來到暴風城！我是城市的一名長官，幫助城市的人口調查局登記居民。如果你想找人的話，我也許能幫上你。我能運用祕法和智慧拿到這些記錄。$B$B如果你找我有事的話，那就開口吧！"] = "8954229236666e51889cd5c64bc6eeb5",
        },
        [10837] = {
            ["歡迎來到前線，$c。雖然他們的政客在暗地裡密謀，但是他們會發現自己的計畫在這裡是行不通的。這兒是亡靈壁壘，我們會日以繼日地為生存而抗爭的。$B$B如果你想證明自己是個英雄的話，你會在這兒找到數不清的機遇的……特別是在我們向安多哈爾和控制著那兒的天譴軍團的邪惡力量推進的過程中。"] = "4ac4718c375b9ac2eb798b72c74e2c6a",
        },
        [10838] = {
            ["歡迎來到前線，$c。暴風城及其盟國派我到這兒來對抗天譴軍團。在冰風營地，我們日復一日在抗戰中求生。$B$B如果你想證明自己是個英雄的話，機會是很多的……特別是在我們向安多哈爾和控制天譴軍團的邪惡勢力進軍時，你可以好好把握。"] = "7204425271757ed24a2756a3d1593f28",
        },
        [10839] = {
            ["很高興見到你，朋友。我是軍官加魯什，是銀色黎明這一世界性組織的成員。我們的任務是毫不留情地消滅艾澤拉斯大陸上所有邪惡的勢力。銀色黎明不是一個政治機構，我們也不願意成為政府機構。我們的目標很簡單，我們將部落和聯盟都看作自己的朋友——以剷除邪惡為目標的朋友！$B$B我的$g兄弟:姐妹;，為了黎明而戰！"] = "571e467e9d1b4d0f258ad53d2287f355",
        },
        [10840] = {
            ["你好，朋友。我是普爾哈特，隸屬於銀色黎明這個世界性的組織。我們的目標非常簡單——與艾澤拉斯的一切邪惡力量進行頑強而持久的戰鬥。我們不是一個政治團體，也不想成為那樣的團體。為了銀色黎明的偉大目標，我們將聯盟和部落的成員都當作並肩作戰的朋友來看待！$B$B為了黎明而戰，我的$G兄弟:姐妹;！"] = "416f0c810cb85e70c452b0f0339d2874",
        },
        [10856] = {
            ["銀色黎明向你致敬，$c。我是哈薩娜——銀色黎明為數不多經過授權的裝備和軍品軍需官之一。$B$B既然你在我們委任下作戰——同時贏得我們的尊敬和信任——你會從加魯什軍官那裡得到英勇勳章。它們有兩個作用：在我們的隊伍中贏得地位，或者作為交換得到某些特殊物品。$B$B隨著你在銀色黎明地位的升高，你會發現你能夠得到更多物品。"] = "8374ed6b128278940b30ec8fc660dbff",
        },
        [10857] = {
            ["銀色黎明向你致敬，$c！我叫萊斯巴克，是銀色黎明委派的裝備和物資軍需官。$B$B當你接受任命，同邪惡力量作戰時 - 以此搏取得我們的尊重和信任 - 你會從軍官普爾哈特那兒獲得勇氣勳章。勳章有兩個用途：可增加自己的聲望，或是用於獲取特殊物品。$B$B隨著你在銀色黎明中地位的提高，你會發現有更多的物品能讓你挑選。"] = "d2e97bc13412a95addc1ab18ef657784",
        },
        [10877] = {
            ["向你致敬，英雄！我有來自大陸和島嶼的最新消息，供你參考。"] = "c94ca2feeaad2ed6fcb17744b822fad7",
        },
        [10878] = {
            ["向你致敬，英雄！我有來自大陸和島嶼的最新消息，供你參考。"] = "3725afd9871a58ee99a7d026e3563aeb",
        },
        [10879] = {
            ["向你致敬，英雄！我有來自大陸和島嶼的最新消息，供你參考。"] = "c42d03e178578b6a44439fb32f8365a9",
        },
        [10880] = {
            ["向你致敬，英雄！我有來自大陸和島嶼的最新消息，供你參考。"] = "cef7b238bc3c92479b26bc56a061585a",
        },
        [10881] = {
            ["向你致敬，英雄！我有來自大陸和島嶼的最新消息，供你參考。"] = "ed86d1f63d2d45272ce63c2046fb4084",
        },
        [10897] = {
            ["你想要飛往什麼地方？"] = "e9f2c6ae11c08606a3e902729508a45b",
        },
        [10917] = {
            ["別管我。我傷得很重，可能會丟掉性命。謝謝你，$N。我將死在這兒，但是因為你……我能在平靜中死去。"] = "1459e6358a1d64d948e842c494640010",
            ["很高興看到又有人在斯坦索姆城中和天譴軍團抗戰，在這裡他們的力量是最強大的。$B$B，你好。我是奧里克斯。我曾經是銀手騎士團的一名騎兵，但是跟其他信念發生動搖的騎兵一樣……我墮落了。天譴軍團誘惑了我，差點使我成為一名死亡騎士！$B$B最終，我感覺到自己的危險處境，我逃到了這個教堂。這是個神聖的地方，第一個聖騎士光明使者烏瑟就是在這裡成為銀手騎士團的首領的。"] = "838b9927288bcbb1e762b2ef266b1a9d",
            ["我的時間不多了，但是聖光依然照耀著這個世界，它可以幫助我完成我的宿命。當你面對瑞文戴爾男爵時，我便與你同在。"] = "a30c5c705bd6b70241922ce37f6afcdb",
        },
        [10922] = {
            ["歡迎你，$N。翡翠議會也歡迎你。$B$B我們很有可能一起恢復並保護這片曾經繁茂的森林。許多勢力試圖從外部和內部毀滅它。$B$B不要被這裡的力量征服——那只會腐蝕你，就像整個這片土地一樣。"] = "508c0975d055f561070f14c8877581b1",
        },
        [10930] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "31ab172e1a375db1c9157d594eb608d9",
            ["我可以為你做什麼?"] = "ff4c1db50d39977890db3fe889ea21ae",
            ["我無法訓練你。你該去找$c訓練者。"] = "65ffa984c80ec793cab656acd848ac8c",
        },
        [10936] = {
            ["我的眼睛被黑暗所蒙蔽，但是你把我從邪惡的幻想中拯救出來。你救了我，$N。$B$B現在我求你……原諒我。"] = "7569cb8195d1c1c3681b86ecac8beb6b",
        },
        [10945] = {
            ["戰爭結束了，達隆郡的人民得救了。$B$B他們得救了，$n，這都歸功於你。你是達隆郡的英雄。"] = "80b02e86f5960caaa7b74c0bed1f6bcf",
        },
        [10993] = {
            ["恐怕你得離開我了，朋友！你該去找奧格瑪的諾格，他將帶你進入下一階段!"] = "f87c37944192073e24d10f1a070e94b4",
            ["我不能幫助你！你會遇到比我更精於此道的人！你是聯盟的人，你得跟暴風城的利廉姆·火軸談談。"] = "1389ded94ec799fa553e34c3557ac12c",
            ["是的，我有些東西要給你看看。我們來看一下你做得怎麼樣，或許你會令我吃驚的！"] = "af9ccb95467b25c6dc0eaa8a4d0cf1cf",
            ["（吸氣聲，吸氣聲）你聞到了嗎？你難道不是只喜歡油脂的氣味嗎？"] = "6b44a3e2d494f59d83f14e5c3fd90e85",
        },
        [11016] = {
            ["你已經為我做了很多事情，$N。謝謝你。$B$B現在我至少可以告訴你，我是怎麼來到這裡的。我和我的好朋友特雷·萊弗治潛入加德納爾調查暗影議會，然後就在毫無準備的情況下被他們抓住了。他們把特雷帶到暗影堡的深處，並把我關在這裡，他們把我們所有的裝備都拿走了……我仍然可以聽到他的慘叫，$n。他們……簡直喪心病狂。我不知道他們都對他做了些什麼，但他們會為此付出代價的。"] = "625edf901382c61c77256e280f0ab6f6",
            ["真冷……我很餓。$B$B我可憐的朋友，希望你已經安息了。我不忍心去想他們會對你做什麼。$B$B你！嘿，就是你！請你一定要幫我逃跑。他們之中的某個人身上肯定有鑰匙，你能找到它嗎？我知道他們有鑰匙。如果你弄到鑰匙，就可以幫我離開這裡了。特雷可能已經死了，但是我還心存希望！求你了，幫幫我吧！"] = "a202c1efc29e7b10a54e9f8ac2c470f2",
        },
        [11017] = {
            ["很好的嘗試，但是在訓練之前，你還需要進行更多的鍛煉！回到戰壕！"] = "1b37830fe8480ed6bd57b3d834cd2310",
            ["很好！無論其他人怎麼說，我想我對你的看法是正確的。哈哈！我是開玩笑的！好吧，開始上課？"] = "a551611cff75484f9e317ceaee4ba354",
            ["我沒有什麼可以教你的啦！如果有人比我知道得多……等等，有啦！去加基森找巴茲克·布拉斯溫吧。"] = "bef0adf1ca4f95d60744bcfb2d4e9e99",
            ["有時，連我自己都感到驚訝！"] = "a33d076d120978aaaececdda45031962",
        },
        [11019] = {
            ["你好，$c。我是傑希爾·月弓。我從達納蘇斯來尋找兩個朋友，他們是來尋找費伍德森林暗影議會的蹤跡的。$B$B看起來那些宣稱對獸人種族的苦難負大部分責任的卑鄙的生物正試圖重獲一些能量。$B$B我的兩個朋友進入加德納爾搜尋證據來證明有事情發生。$B$B我希望我來時他們在這裡，但是他們已經晚了數天了。"] = "01ed61117dd6f345c1893b55ba7c3e87",
        },
        [11025] = {
            ["我希望組建隊伍。當然，我更希望擴大隊伍！"] = "0ff75e91e3efa274b411fe43479cec98",
        },
        [11026] = {
            ["你需要開始學習一些我的專門技術之外的東西！跟那邊帳篷前面的利廉姆·火軸談談。他會讓你步入正軌的！"] = "d5f2814d5a55821ff686f1fc3f40349f",
            ["啊，多麼美好的一天啊！真該炸點什麼東西。"] = "33cde2d2626cb83407a65d6383443dda",
            ["這種工作膽小鬼做不了的。我有個叔叔丟了一隻手！可憐的老胖子……無論如何，如果你還感興趣我或許能給你看些東西？"] = "484e047646ecf6f5c9b180d85bf2aa4a",
        },
        [11028] = {
            ["呃……雖然我不願承認，但是你要想繼續訓練的話就必須跟我的姐妹談談。目前來說……我知道的沒她多！她乘坐火箭車四處巡查。"] = "bc4c0de7e227a1661c90d7b622f3e02f",
            ["我聽說新型的極速6000型很快就要開下生產線了。我幾乎不能抑制激動的心情！"] = "2b87e1e15de666a355e9344472dc0289",
            ["我願意教你！要讓我的姐姐看看她不是唯一瞭解工程學的人……"] = "40798c8f61800bb3be5e40fd48e87515",
        },
        [11029] = {
            ["不要告訴任何人我說過，就當我什麼都不知道！如果你還想學習，你應該與店主賓斯匹德談談。"] = "58028e040ad547397597dff9ea8af0ec",
            ["對一個初學者來說還不壞！我猜給你看些東西也不會對我有什麼損失……"] = "62d2d87d23e9ece0d60ac1d48a8e7fe5",
            ["我的二十英尺高的火雞烤肉架的計畫快要完成了！現在我需要的就是一隻二十英尺高的火雞了……"] = "8f27820c6e9709cbaaa1634504f18beb",
            ["靠近點，但是不要抽雪茄！我恐怕你必須得先跟我的妹妹潔娜談談。當她領你復習完基礎知識再回來找我，我那時就會讓你見識真正有趣的東西！"] = "274e65db536d36aab805a57c6a0b4076",
        },
        [11031] = {
            ["你認為我能教給你什麼？羅克希克比我更適合做你的老師。你可以在奧格瑪找到他。出發吧。"] = "d0ae4b28fa408acb398c05a214d1bb97",
            ["我們彼此都在浪費時間！如果你想接受訓練的話，就去找格拉哈姆·範·塔倫吧！他就站在右邊。"] = "3c86418f99690dcbc3d2abc483df7c97",
            ["我可沒時間閒談，我是個專業人士！"] = "4f9bce54372fe3d983c0ce382b780af9",
            ["讓我們看看你的能力，好嗎？要是你按要求完成任務，我會樂意教你的！"] = "dca6d9a909bc13f7a4499f00b5850587",
        },
        [11033] = {
            ["我就是你口中的資本家，$r。"] = "4249b5e676f6809f52f9c6f458cc5ae7",
        },
        [11035] = {
            ["瘟疫之地是對付天譴軍團絕佳的地方！"] = "28182dcd5f66af0c7447e4efb15d0c5c",
        },
        [11037] = {
            ["你好！我的名字是潔娜！你呢？"] = "7d443120bf24605ece221852345da227",
            ["你想學習？跟著我？太棒了！唯一比裝配子彈和炸藥裝置有趣的事情就是與別人分享那種知識！我們開始吧！"] = "a441f79503ac8fed306628690a06aa0f",
            ["哦，你還有很多東西要學。我會教給你我所學的全部知識，但是我自己也在學習！你為什麼不找鐵爐堡的特裡克希談談，她會幫你進修的！"] = "b14de01992948f1b0553a6de31fee1d3",
        },
        [11038] = {
            ["他們將屍體交給了我，他將屍體投進了深坑。"] = "3afbafbdc7a6269b97c1bd93f678955c",
        },
        [11040] = {
            ["你見過守夜人巴庫斯嗎？很勇敢……$B$B我想他是所有守夜人中最兇猛的一個。我懷疑他是否看到我就在周圍……"] = "dfbe088859a137835afb8337482b93f2",
        },
        [11041] = {
            ["不幸的是，對於擁有像你這樣經歷的人來說我沒有什麼可教的，我的朋友。去找夜精靈希爾瓦娜·林月，她住在達納蘇斯的工匠區。"] = "ecd83d20e2f098bc5add3914f93110a4",
            ["人們從森林植物中製造的東西難道不令人震驚嗎？說真的，月神對我們已經很慷慨了。"] = "2e7aa0040d2afc72a1b0f9bae685d34d",
            ["月神--我崇拜你，我的$g兄弟：姐妹；。你在這裡很受歡迎。說吧，我會盡力幫助你的。"] = "a854580ba8ca58d56fc2b87f8ed84c66",
        },
        [11042] = {
            ["即使輕微地改變藥劑的成份也能使它發生根本的變化。耐心和精確，年輕人：他們會讓你在所有行業都受益匪淺。"] = "f70bb9d40494b7b9d4c5e313cc9f435a",
            ["啊，又回到年輕的時候了，還有第一次發現藥劑的時候。謝謝你恢復我的記憶，$n。去跟那邊的米拉·法拉科納分享那份年輕的熱情吧。"] = "9bbd69aca397498d004508fd7ad19163",
            ["我已經用多年學會了很多藥劑知識，$n，而那些知識都由你支配。你只需提要求就可以。"] = "9f32bd308165fadcfae13b5b7ce6688a",
            ["我製造藥劑的技能在你之下。你應該與那邊的安尼希爾談談。她會明白你需要進一步的培訓。"] = "2b08b8a8d1cc4135fd5dab22809bb623",
        },
        [11044] = {
            ["你對藥劑的知識已經遠勝於我，但你還有很多要學的。上樓去到東南面見見馬許醫生。他會交給你真正的苦痛——啊咳。他是一個被遺忘者，他能進一步訓練你。"] = "b7269b9e677d42ed7131e6719a1f24ca",
            ["很好。從這些標本上再切下一塊肉來。讓我們看看你學到了什麼，我們可以由此開始。"] = "8e532ac34ab9bb5262ee3ed4d514db22",
            ["這是真的，我曾經是人類。缺點是可能轉換為我們的優勢的，$n，因為我對人類的劣勢瞭若指掌。"] = "f8d646bc5e246662bfd10d01a3e55223",
        },
        [11046] = {
            ["不能幫你。你比我更懂藥劑。還有，我還要看著罐子。去找那邊的耶爾瑪克談談。他懂得很多藥劑的知識。"] = "a6fce2f8c4b47202a170ae54b00fdde8",
            ["他們說我愚蠢，我要證明自己的實力。我要關注所有的罐子，證明它們都能煮東西。我的好運就要來了！誰是愚蠢的人，嗯？嗯！？"] = "5aeba2ee94183ab7088af2ae15c03a01",
            ["桌上的所有瓶子中都盛有今天配製好的藥水。心急吃不到熱豆腐。哈哈！"] = "3acb15be9a5e8a5571335dcfcf05d155",
        },
        [11047] = {
            ["你學習的能力已經超過我了。你需要找那邊的貝娜·冰蹄談談以獲得更多指示。但請不要佔用她太多時間。她需要休息。"] = "16e14575c243b22108364e8f2d7ebf81",
            ["在我首次開始配製藥水時，我一定打碎過成百個瓶子。我笨手笨腳，瓶子在我手中極易破碎。希望你比我更為小心。"] = "27bb4a92d481d7e2bb454ad5137ab13d",
            ["貝娜就像著魔一樣工作。她日以繼夜地調製這些藥劑，不吃不睡。我知道我們的不死族盟友需要幫助，但是我擔心她這樣會傷身體的。"] = "98efca988aa70ef4d3d5510095903801",
        },
        [11048] = {
            ["到我們這兒來的客人可不多。你對我感興趣？"] = "5d1d54fe06f83ab0d94d3657a2656351",
            ["我只是個學生。雷安諾才是專家。她站在那邊的箱子旁。你可以從她那兒學到很多東西。"] = "b3ce892e3e9d7520713df2a64935ea72",
            ["是的，我認為你有潛力。或許我可以給你看看一兩樣東西？"] = "667d01f5431aa66becfa107bd97d1b6b",
        },
        [11049] = {
            ["你已經完成了？是時候見見老闆了。找到喬瑟夫並告訴他你準備好了。"] = "c53c4d2d827cfe2a748ce5b3b062c6bd",
            ["好極了，你很有勇氣！我很滿意。那麼，我們就出發吧！"] = "d6877ad93174a1c14b6b0dbbb153fbb8",
            ["我怎麼能把我的秘密告訴一個初學者呢？先試著跟博文談談。"] = "0638cab49daffdf96bf1ac788edc45a1",
            ["裁縫可以派得上大用場。我從前就不得不把我的胳膊縫上。"] = "77c219389146b4ffabb25acd8f094702",
        },
        [11050] = {
            ["你不會失望的，旅行者。裁縫是一種充滿樂趣的工作。"] = "e1ccf40d7d245683a5cca2f1001e49b0",
            ["你的教育正在繼續，而你的知識已超越了我。如果你還想繼續學習你就必須找邁裡恩談談。她會指引你的。"] = "c453788c146e8b0170bf3c9d3740b16d",
            ["沒有比編織更好的寧神方法了。"] = "5b50f9a0624a9cfe928cbc1729b09550",
        },
        [11051] = {
            ["你尋求更高級的知識。坦帕擁有這種知識。她應該就站在附近……"] = "8ad7eccb4b49cd7d5405cd10a2652680",
            ["帶著大地之母的祝福，我們要開始了。"] = "a25b3302ffe572a2b66ceb81dc6c8089",
            ["我們沒有浪費狩獵而得的動物的任何一部分。"] = "9a3119143d987293762c854224943bc0",
        },
        [11052] = {
            ["我給國王提供過裝備。如果有正確的訓練，你也可以。"] = "e8371e1cc30433d550a506007485f833",
        },
        [11053] = {
            ["因為大熔爐被打開了缺口，我們現在能夠把反作用劑釋放到外界。這應該能讓天譴軍團嘗嘗他們自己藥物的滋味，可以這麼說！$B$B向煉金師阿爾比頓詢問一下有關在大熔爐中所需要使用的試劑這方面的資訊。我會處理所有的資訊報告，以便於我們決定怎樣把瘟疫用來對付天譴軍團！"] = "a399af1c21d429a0c89525c83777d4d9",
            ["天譴軍團帶來的災難就快結束；一場難以控制的顛覆行動會將我們推向頂峰！你務必要幫助我們！"] = "cdbc784d0f00f4659ccee11833a3128b",
            ["天譴軍團帶來的災難還在這片區域蔓延，在扭轉局面，摧毀天譴軍團之前，我們要走的路還很長。收集必要的資源，盡力幫助我們吧！"] = "58b0554b4eb137e72abec05c73e93452",
            ["我們已經用天譴軍團的瘟疫反攻他們了，但是我們撐不了多久了！去摧毀他們的鍋爐吧！"] = "a26eb8b0ce0bb0171f1b4303aac09ecc",
            ["我們正控制著天譴軍團——瘟疫至少還會侵擾它們一整天時間！但是我們得對此有足夠的把握，因此你要盡可能地破壞鍋爐。"] = "335dcfc9ba7e7b8a587e1d82f288ba64",
            ["時機成熟了，我的$g兄弟:姐妹;們，武裝起來，從天譴軍團手中奪回屬於我們的夜晚！"] = "89e1bb2564e68691fb9f0db64f2c6d96",
        },
        [11055] = {
            ["因為大熔爐被打開了缺口，我們現在能夠把反作用劑釋放到外界。這應該能讓天譴軍團嘗嘗他們自己藥物的滋味，可以這麼說！$B$B向煉金師迪瑟斯詢問一下有關在大熔爐中所需要使用的試劑這方面的資訊。我會處理所有的資訊報告，以便於我們決定怎樣把瘟疫用來對付天譴軍團！"] = "8e9bed9d1ef172b3688e72d1279f5695",
            ["天譴軍團帶來的災難就快結束；一場難以控制的顛覆行動會將我們推向頂峰！你務必要幫助我們！"] = "9db7de5508eaac9e5611e0a7f2fbf9bc",
            ["天譴軍團帶來的災難還在這片區域蔓延，在扭轉局面，摧毀天譴軍團之前，我們要走的路還很長。收集必要的資源，盡力幫助我們吧！"] = "ce824b41cf0a6db8b1c15559f577b9fb",
            ["我們已經用天譴軍團的瘟疫反攻他們了，但是我們撐不了多久了！去摧毀他們的鍋爐吧！"] = "6af5c07f82dbfe714f7cc1dce270aea0",
            ["我們正控制著天譴軍團——瘟疫至少還會侵擾它們一整天時間！但是我們得對此有足夠的把握，因此你要盡可能地破壞鍋爐。"] = "8d077777e6b7bc9aa577494538df1334",
            ["時機成熟了，我的$g兄弟:姐妹;們，武裝起來，從天譴軍團手中奪回屬於我們的夜晚！"] = "1ad4fc3d07a7873ab9512c5aa3f5ce4f",
        },
        [11056] = {
            ["好吧，$N，讓我們來看看怎麼對付這些瘟疫之鍋！如果你要收集所需的成分，就帶上一個玻璃聚焦裝置吧。在鑒別從天譴軍團的爪牙身上獲取的資源時，你會用得著它的。$B$B你還需要找一份祕法催化劑。這東西可不便宜，而且也非常不穩定。一旦你得到藥劑，就必須在15分鐘內使用它，否則藥劑就失效了。所以你可得留神別亂買。"] = "43c03850150a3e4e888a3fe9f7573555",
            ["根據你提供的毒素樣本，我們認為你需要下面這些東西：一份祕法催化劑、五份細胞增強劑和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的殭屍或食屍鬼身上獲取細胞增強劑！$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。"] = "d3820c153c571b0cfaad41a0a05ec90b",
            ["根據你提供的毒素樣本，我們認為你需要下面這些東西：一份祕法催化劑、六份骨質分離素和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的骸骨亡靈身上獲取骨質分離素！$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。"] = "723e3c269896ab473c0e0fd6cc82fc87",
            ["根據你提供的毒素樣本，我們認為你需要下面這些東西：一份祕法催化劑、四份外膜震盪體和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的鬼魂或怨靈身上獲取外膜震盪體！$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。"] = "abd3fe4179f9ea234823347956f30f4a",
            ["這份工作明顯不值16500的年薪。"] = "9f10ddfe7f58036336e7a82a8fa46da3",
        },
        [11057] = {
            ["一場猛烈的風就要來了——我可以透過我裸露的膝蓋的疼痛來判斷。我只希望我們不要被狂風困住。"] = "59f242ffa4d6ec58e93b6c528f93c8b6",
            ["好吧，$N，讓我們來看看怎麼對付這些瘟疫之鍋！如果你要收集所需的成分，就帶上一個玻璃聚焦裝置吧。在鑒別從天譴軍團的爪牙身上獲取的資源時，你會用得著它的。$B$B你還需要找一份祕法催化劑。這東西可不便宜，而且也非常不穩定。一旦你得到藥劑，就必須在15分鐘內使用它，否則藥劑就失效了。所以你可得留神別亂買。"] = "81092dc339c3d0ea4e5820ba963ada18",
            ["根據你提供的毒素樣本，我們認為你需要下面這些東西：一份祕法催化劑、五份細胞增強劑和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的殭屍或食屍鬼身上獲取細胞增強劑！$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。"] = "e1e7ab73ecacefd961be671612257673",
            ["根據你提供的毒素樣本，我們認為你需要下面這些東西：一份祕法催化劑、六份骨質分離素和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的骸骨亡靈身上獲取骨質分離素！$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。"] = "4aeb94df07f39cf3ca98b1e6d3fecb8e",
            ["根據你提供的毒素樣本，我們認為你需要下面這些東西：一份祕法催化劑、四份外膜震盪體和四塊符文布。你可以使用玻璃放大鏡從瘟疫之地的鬼魂或怨靈身上獲取外膜震盪體！$B$B一旦你獲得了這些物品，就可以把它們放進瘟疫之鍋裡了。"] = "8d39568ba38ddd9cb3af31818419ca9e",
        },
        [11063] = {
            ["我們都親眼目睹了無數可怕的災難，但是我們不能由此絕望。$B$B記住這些往事，總有一天，我們會進行報復的。"] = "c507517029d417a2e6d13173fcac6bfe",
        },
        [11064] = {
            ["哦，謝謝你！我已經深陷惡夢多時了……"] = "f480a00fa10e5310e4267f26515d167f",
            ["啊！如果你見到一個達隆郡的倖存者，請告訴他們我自由了！"] = "fed623f87b4b87634f238ffb546b2df7",
            ["我的靈魂終於自由了。"] = "564b4c2f337c2199f444b5155ea4d428",
            ["謝謝你！你讓我自由了！"] = "7f54e67830fe9b610107dcc6ef833396",
            ["謝謝你！我註定會在達隆郡之戰中身亡，但是你讓我獲得了自由！"] = "f2c5356ea5dc812ceaca823c305a9fb8",
        },
        [11065] = {
            ["你確實是個不錯的附魔師！現在你該繼續了。我想讓你與樓上的吉布·草鬚談談。他人有些古怪，但是他會繼續指引你！"] = "83749af325a71443ad1a44975ed8101c",
            ["啊，你是個好奇的人，是嗎？太好了！聽仔細了，這也許能在惡劣的環境下保護好你的皮膚！"] = "dc163f9438b05414bdaa5d6916d428ff",
            ["年輕的流浪者，有比鐵錘和熔爐更能使鋼鐵堅固的方法。想學學嗎？"] = "8cc1c83d42500e373b5a2c8618ec792f",
        },
        [11066] = {
            ["你來錯地方了。去找那邊的專家古丹談談。你可以從他那兒學到更多東西。"] = "f3fe4e0fa8ddc09f54cc1056650576fe",
            ["你好！陌生人，你在找什麼？"] = "2da316ac003f21ca893f1a240bf23d23",
            ["戰死沙場是件光榮的事兒！但是，若是你能利用我教你的東西，或許你不會死得那麼快，嗯？"] = "4e6679b868c39b4cf04876157b3c3a99",
        },
        [11067] = {
            ["你看起來不怎麼像我，但誰知道呢，可能有一個附魔師藏在那裡的什麼地方！"] = "61487ac6146fba1f9b5c99729ccb3322",
            ["呃，你進展到這個程度了嗎？去那邊的書架找拉文尼亞·克洛文。要是你沒把事情搞糟，或許你能學到更多知識。"] = "ef5041ab92f8b0bb4ee9644254c363c9",
            ["陌生人，我沒有時間浪費啦。說說你的事兒吧，要麼就離開！"] = "5326a24ee0ea6449c67c18d4327bde5d",
        },
        [11068] = {
            ["嗯……你看起來很有能耐。如果你真想學習的話，那麼沒有什麼能阻擋你！我會指引你通過漫長而碩果豐盛的道路上的第一步。"] = "b2a1b013783e1c798aeab08ef2f0e133",
            ["我擔心對有你這樣經驗的人沒什麼可教的。但是你還有其他方法。去找那邊櫃檯後面的魯坎·考迪爾談談。他會指引你通過旅行的下一個階段。"] = "9bc79cc1d6dfa8f4429bb0862cd5cb14",
            ["歡迎，旅行者！是什麼風把你吹來的？"] = "a3b77b8ddab9ff1b046bb5107711d6a3",
        },
        [11070] = {
            ["你的技能已經非我能及。現在你該接受新的挑戰了。塔蘭丹會幫你準備。他就站在那裡的桌子旁邊。"] = "8f4b95140c7a58c303b176c5542cc921",
            ["女神已經賜予我智慧，陌生人。如果那是她的意願，我將會把它傳給你。"] = "bc70c44f8b7482fbb065577cfb4d784f",
            ["我會盡我所能教你。每一節課都是女神親自給你的禮物。正確使用她的禮物，你就會無往不勝。"] = "49cf4b5dbf7897550054ed6265ce60a4",
        },
        [11071] = {
            ["只要有耐心和決心，很多秘密都是有可能解開的。現在，讓我們開始吧……"] = "070204bf722544f25415a86e05271b64",
            ["我不能再教你什麼啦。但是，我父親的知識遠勝於我。進去跟他談談。祝你好運！"] = "893d18665c3f26a3bbd2c4c36ee7c554",
            ["我最不願放棄的就是在這樣的日子裡到開闊的大草原上……但是，我的職責所在不容許我那樣做。"] = "164d32099002118fe8d2117ec015ba57",
        },
        [11072] = {
            ["你差不多已經達到訓練的頂峰了。為了成為你能做到的最偉大的附魔師，你還需見一位導師。她的名字叫做安諾拉，而你或許能在奧達曼找到她。"] = "4e871ac5191a2e28d130bc6bb359535b",
            ["你很熱心，這很好。然而，你還不夠資格接受像我這樣的人的培訓。"] = "c254c720247272106277a7b95c241623",
            ["你的技能正變得非同尋常。現在，繼續你的訓練……"] = "f721840f336ebbf959238b5f76ad37ab",
            ["是什麼使你來到塔樓的？"] = "9783209f3bb38d5991e290c9a6e8377d",
        },
        [11074] = {
            ["你在成為大師的道路上又創了新高。讓我們看看能不能讓你更上一層樓？"] = "ff0f85bd4afcbb0d62acee55989f25cf",
            ["你是來學習赫加斯部落的知識的嗎？"] = "6f9b492efa4ba7e9bee73d386e576b92",
            ["安諾拉是唯一一個在技能上勝過我的人。你得去……奧達曼找她，學習更多知識。"] = "e7e497823ef13d404b637cf7a64a6385",
            ["日復一日地堅持訓練吧。當你熟練掌握所有技能的時候，再來找我。"] = "dfb21e7f73c6748b529e34123ab87cb8",
        },
        [11081] = {
            ["你得及時準備好接受我的教學，$n。到那時，找達麗亞娜談談，他會幫助你訓練的。"] = "6492b5a570e6859c5b995d9408c55800",
            ["如果你來這兒是為了得到進一步的訓練，那你是高估我的能力了。跟泰龍尼斯談談；他應該能幫助你。"] = "08fd93ddedad6346d0a253b6fb302639",
            ["我們可以從死去的動物身上獲得原料。別無視它們的犧牲，$n。帶著尊敬來處理這些皮革。"] = "07dddb1848993b2c42d35c0967501a16",
            ["達麗亞娜答應了，但是她的精力如此充沛，很難讓她安靜下來仔細的聆聽。她氣力十足又機靈敏捷，我恐怕她不久就會被叫去參加戰鬥。我們必須快點教她。"] = "c6e9bfb1e8766c8a77060344db3714dd",
        },
        [11083] = {
            ["如果你對皮革縫紉感興趣，那你算來對地方了。法多恩和泰龍尼斯都是真正的藝術家，而我希望能從他們那裡多學些知識。"] = "ce221bcf9ee4474099d2525c5ca9f11a",
        },
        [11084] = {
            ["你的技藝不足以學會我所教授的。去找那邊的瑪克談談。他可以幫你直到你準備好學習更高級的課程。"] = "66dbd86739dd2ec82e0cfbfbffbc174b",
            ["我不能為你提供更多的訓練啦：你的製革技能已經超過我啦。你應該去那兒找猶納談談。如果需要的話我會為你擔保的。"] = "5c5208df1740c7347ba2459a64901adc",
            ["我的斧頭經歷過多場戰事，我喜歡將它帶在身邊。敵人曾數次入侵我們的首都，但是別怕：我們總能擊退他們。"] = "90523fefc8ff6a90b77c9ac08d9b6530",
            ["我目前對你的進步感到很滿意。很顯然大地之母已經賦予你的雙手以靈感了。"] = "03f43797d0905acbb229b4ebc7eed8a9",
        },
        [11096] = {
            ["我已經瞭解到很多關於時尚的東西。現在那不過就是掌握製革技巧罷了。西蒙能幫助學習製革的。"] = "1308cc62e8033d85625722f0011e1e98",
            ["這套裝備真的讓我眼前一亮，你覺得呢？顯然，我有多種技能可以使用，我可以將貿易的一些訣竅與你分享。聽好了。"] = "65cbb6b9c7b22c69fa4cf09268afee79",
            ["除了對色彩和細節的鑒別能力外，我沒有什麼可以教你的。跟西蒙·坦納爾談談；他知道很多製皮的高級技能。"] = "44f2dd6bc6a05014e239cdf105eec1d8",
        },
        [11097] = {
            ["我不是來教那些剛離開搖籃的寶寶的。你離我對學生的要求還差遠了。你不過是個年幼的$g小夥子:姑娘;，你最好別在這兒煩我了。"] = "ae30154a118ba87fdf6f4a2c62f6344f",
            ["我可以利用在這兒找到的材料製作有趣的東西。這些山林中有許多奇怪的生物！去殺死它們，$N。"] = "ad4a6b6d0badc2d4fe6a7a1d542a117b",
            ["我喜歡機會；你不喜歡嗎？啊，當然你也喜歡。這就是你要按我說的去做的原因。"] = "ce752e682ab8f0d0c23c727db53bbcf4",
        },
        [11098] = {
            ["你來找我求學是浪費了你我的時間，$n。我沒時間教授基礎技能。我們在這裡戰鬥，而這裡是一處前線。在你準備充分之前不要再來找我。"] = "28f0b9de574960b8c0ef465e0f717dec",
            ["我所有的作品都必須由買主親自來訂購。奧爾文常常要我改變這個習慣，但是我就是不改。看看你周圍吧，無數戰士還指望我給他們打造裝甲呢。"] = "d5ab20385b55a01835bedf887cdb59fe",
            ["我真希望有更多像你一樣的學生。很少有人會冒險深入敵境。我佩服你的勇氣。"] = "01054e0f81cd813f7dd94d9b5ab20dcc",
        },
        [11103] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "3334d2c3be49af24ec80966cd3044afb",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "90657c7dd9fc98c4960a8c613e7e0841",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f3dc300ddc1883b724afefb742b27c54",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f70c987e98c43a9ac4f1ef6eb271008a",
            ["你看起來很疲憊。在我們的屋裡休息一會兒吧，讓伊露恩引領你進入甜美的夢鄉。"] = "88ed28bad52992326e81df54efce5146",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "25a80704f18ee56676b132bdded0fe94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "9cdbd4512dccbc458675c5216058ddcd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "bbbb6f1884cdacec9af6cb67e3e1abd4",
            ["厄運之槌位於菲拉斯的中部。"] = "89054fe6fb8e52df563c9e80702c264a",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "d34171a9fbd911b8f1bf818f71cc3f32",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4b24ea6b391a2efd0be7d84cc947d159",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "310fe6a22db0bf2928c1ff8e5c70cd20",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5d076554d313584aa1c5611cf0129a23",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "24cd799771f287be14f8060e5444dfa5",
            ["奧達曼位於荒蕪之地最北端。"] = "36de161eff379c5060e7c2e31cdc975a",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "cac489d41abedaef7c5d7041fd7492e3",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "136e146f620b6e7197755a682b68ce84",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "6f1db228470e4b9d299edd3c7168c063",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "7bef92afa79765ff95f06d3660786a79",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "530c2f46cebb57733cec5f86ad8383d3",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "8d0c3e032d49fe079017a90965f53922",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "fd70ec87881856186158a19c159addb7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "94fa40981e2a4d5c4b4b0b68b37f782c",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8f49377bcf39a38a76d2cf7cbacbefb0",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4352ca0c9a3782df4f9b0a23c9c7f9d7",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "c14eefa9bf01ea21ee6c512a62f5270c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "e33d4e6573f24d17efcc2b0ecf76516d",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "6679f691680afda8b76a2dd04f2e7144",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1d59940e7ccbee60370a304b33835f99",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "b19764fa4b6d3a891fa5f750b3dd2517",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "f9432ed28b2dabcd595eddb702af9ca1",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "10e3746148a7f37b2c1af2d199833368",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "927f2bfc50de1f03c38ac6ec3198f4a7",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "78e6008fbf1d737dce7812540853511c",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "54bd2c1a937b1392327adbdf92ce5e6d",
            ["諾姆瑞根在丹莫洛的西邊。"] = "a4f613548f3f5a63415a978d891ce475",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3b08e6def8fe2881c84a302e3f4c7fea",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "03ee214820f246ccc4e751c56c822ace",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "7eddf733901dbca29a5a21752dd1ceb4",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "0e3148ee13bdc4aad5af84663b24d1ce",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "aab40b74860886caa96dcfdaf979e180",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "9c2b22f32a137854d984166b2aaded4b",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "8f57f5e81f55defd22e287d36b233496",
        },
        [11106] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "67e679105237aa46ee7a3409ef1a68c5",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "42f5d7a2dd2fde374bdefa0c10701256",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "90068fa43ca357ef9462599be9d006a4",
            ["你有興趣探索這些地下城中的一個嗎？"] = "ccda04db92cbf011d170b7cae60f408c",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "5a6a13f324242e75a6382d99c516cc94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "12c27bc52b107697f8de364f8dae7e3c",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "18f70be5c25cb2ea163cd8d518bfdc66",
            ["厄運之槌位於菲拉斯的中部。"] = "ce805aa1448186ce4794258c3cdc704e",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "af31a346608dbddcecea7edc85e314ff",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "331713e1070e9f4f3576819f670ae53d",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "87b9ad9eca23dfe66c987d93b54bc51b",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "c08a11a40b198a8cdf5e21127dad1408",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "4b98c70ede6bd8cb80bc9ebb78fd4f9a",
            ["奧達曼位於荒蕪之地最北端。"] = "556878b84c0292b45d666060cb90b770",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "bc7a0c38334a3cb0cabf4faf3d793a87",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "7baa3037efa4e58f77af6f15cb527593",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "fb940c5b0393c3fd43e9e2df8f5562a8",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "d332f132dad158e7271d0f14c19ec73d",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "c2be634e5a50af657e4346af05a183dc",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "9d86f89304affdeae5264f879da84304",
            ["我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。"] = "980ce6cc828845cb13bcbd8cd0b6917e",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "3124bcbc877a9654486099bdcbfb0eef",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "1dafad1d0d57bc8653d5c2c7d35c4a07",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "d9ac47630828a00f0b09464fc66c51ec",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "298b92e58115d14cb1cd1b4ff6278556",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "af82564cf7ae1fe402a33ef253cb74cc",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "4c620133d97c2f350972b761b3dc491d",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "d33cc3248fefbb1f1925c215048cf29b",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "7f40e2c7a99505ba4995ee282dfc6836",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "4c47373b8dd57eabb9791705a594084f",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "63f35b75e396252f797a4186f1286bee",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "9160ee289a277af5bf427091078afc51",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "a704e4b5607d1ef64f5d23e8fd7983c1",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "7bf5800aefb381b3ab9369dbae519ad1",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "6197d9bec6a3e8059bca553e1ceac8b1",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "86adf50ebffcdaae0b2e044333b6e69a",
            ["諾姆瑞根在丹莫洛的西邊。"] = "d44d297c2cca8733f4d13c8c8c1f28d5",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "dd975c8f89f30ab9b769be5964cf632f",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "d7a63e33070adb319c75b51cca5b23b6",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "0b35ae40cc764b63340a0d3431fca136",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "55c6bd57311ef599eca95a97025087e1",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "06eb7bd37fd0c212607efd69ff668e03",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "4b2a582cee1f20d593eae9a388287135",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "a8ecc7056b89cefc7b67cdb06c5db362",
        },
        [11116] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "a70be99ff08d4df4c93b09b77588a051",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "5d58291140199149e578fcbfbeed18cf",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "2d70ab98f838e1bb06030fcf93158968",
            ["你有興趣探索這些地下城中的一個嗎？"] = "a61f3b373d7747d0767475c1b5dab2f6",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "b07c8c68897f70867bbb75e49138b18d",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "8960494e8735de52e731bccc5622764d",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "1efdcf0d1f0182cadd7e556c2271b952",
            ["厄運之槌位於菲拉斯的中部。"] = "3e983a22901faae3beabe07a57c404e1",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "473bac4f85c8b79c1dd5b392e510c6c1",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面，來到了悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "5f4d64e508e2e540625383eeae8529e5",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "a3c3d767ea37682d4d5d32cdda15eb9e",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "131cac36cbe3c50c8b0b73b5a5cc8e31",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "a5bb313bf3bd25a50fb0157cbb68e362",
            ["奧達曼位於荒蕪之地最北端。"] = "af158d110faf65cf2c8cfe5981eddc3e",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "991c35a1c8f32e2d36fef5a051a928bf",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣…然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "d208c04226b80a24f1f58b9d6011d18c",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "15cc28e6650ead1cf3c24a21428162eb",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "5699ecf40556711f57d029b802122744",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "579d342215c9b859125b292dde81b3dd",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "f108787b96326f0485800f2468879b89",
            ["我們一直歡迎你的到來，就像我們歡迎平原上吹過的風。"] = "a98c33cf2b0c65fb09a0b00d67122e46",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d3df88e9b21fb13e7181cf562fb15e42",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "a68c695060e8db92a6407dbd039e03c7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "134711fa5dcb6d2514b7dd12cb58353f",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "5d241a73257b83bfb3f2a35e6c559cb8",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "1631876c10990f6b69fb643f319f15da",
            ["死亡礦坑位於西部荒野南端月溪鎮的地下。"] = "2761a549194820781531b07e3ccf0a6f",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "ec90c3b20200ec711da3c83a7d439020",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "ee0633ddb8208d730c4a1f7e2f75724f",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "b08c334deb14a22220d649a65f3c74fa",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "84004ad843c4e25945ff9c41c2c64e48",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "40835d72adb6d19a66d4db7eaf7b44e6",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "97df9679462d394c9c8acea3163a1db4",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "f469edb565c0b095a0fc47a970c24323",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "9d99c94eab41fbb7d5d8577ea1ef5b17",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2669d18d8bca0062b048b5b892ff56be",
            ["諾姆瑞根在丹莫洛的西邊。"] = "3a31427822c5fa1a87c7a675bd12855e",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "7f35f35703d028305ee4d76b181b5fac",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "2ace78d92e3daa88d503880d61a8825e",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "4d0ece2f2228a1a4c22ff7047c560d51",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "421a85045f22b0366436f5c512836a4b",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "105703cf3292f20db785559210529138",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "d1d167264b852e04dcc247504cad2f84",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "9607305c9027305933951bfdb21a86f2",
        },
        [11118] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "353a8e93b02e9c49ae94b3a5011588bb",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "fdb62b0e3003d60d76ddfff91eeaa1ba",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "b2211c64d47ca8c3d8e615dafe91b495",
            ["你有興趣探索這些地下城中的一個嗎？"] = "6fcd8a8f723f26e9218624439fe88db7",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "6bffe49eafcf8df1848c2509da86730a",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "aeb1408df68552c8f9bfc1ebc2831f47",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "3ab3c8765d0c52d13b2628e8c4babaa6",
            ["厄運之槌位於菲拉斯的中部。"] = "12cbfbf2c2f790dffa2c20463b3e2b63",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "30f1c9a2f2f0f5fe8c8ce03164fe3f80",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "ab4e58f01968879f7f1069e0186c3f57",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "db2d76d7b455d886696d89b8e8e48c20",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "11c3ea2689d0fd9a04ddb9557a48b4c4",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "c411cbef5df180ccd890bef475112e69",
            ["奧達曼位於荒蕪之地最北端。"] = "ed7ede5fd80672340015462249d28fe0",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "c741d06e3ae26604a28606c05c568df5",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "e762061ba8bf75781dc6a8a400d88e13",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "3ef6a7990ed58b98f707df1ff450c6ec",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "314b29b747fa859ad91de3785a93d808",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "bc8c50bfc1d8ed1c75ba7dd8b90fd912",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "9d9bce9e257f45dd17522274f40eb90a",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "49ed8576dd0786e236dd87d0f38c8c20",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "9ea36275dbd35e366c4dd3e17bacd2a3",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "0a14977b923b0be3640ccdeb0c310ca4",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "5e32b11a014d38435309852c50df4593",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "b500cf9cb16697efa215b17db7bcfb10",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "850aeceef030ff968b8c47af9519d1e5",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "3019461d07288487531039345321867b",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "3d50b3c8523fd4e14848a3a53be149bf",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "4f23f6d9a9625031dc0f071d896ef815",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "1634a5dccbea47f39276cf79744035f6",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "b3cbd3b34c12301e130d6d8c71c79640",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "33365e24098ac326d7a02842b80c9ece",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "f1ed33547ad09d7d0d14fc037e5a34b2",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "87368fc74f08705c08ae578c168c55d4",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "dd9f3d64c827838e795e0a03f9ef713a",
            ["請進，請進！不要坐得離火爐太近。它今天還沒爆炸，但是為了安全起見，我想你還是坐在別的地方比較好。"] = "bc1b3f439e8fd0f9f2ac5ff43c880695",
            ["諾姆瑞根在丹莫洛的西邊。"] = "88767c2b09612db177541d67e62643f6",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "2a9d5a7861378398b5f5ded83395f794",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "a81545312fb538a27d48e6796f1f8cb9",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "a2c336cefa994f850e7628145aef6230",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "2c36f4b85f081ffa0059501012a47ad9",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "305d2bb0a0ec6f8c4279ffe77b2405cc",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "80c7791d0f726c6038424e4e9ec88b2e",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "4240b0e9386c847bf7610e5cbd0a98db",
        },
        [11138] = {
            ["你想要飛往什麼地方？"] = "e9f2c6ae11c08606a3e902729508a45b",
        },
        [11139] = {
            ["你想要飛往什麼地方？"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [11145] = {
            ["你在鍛造方面的技術已經非常高超了，$N。該做出決定了。有兩條路你可以選擇：武器製造工匠或是裝甲製造工匠。$B$B注意，當你做出決定以後，就不能回頭了。每個方向的守則都不允許你三心二意。"] = "2f8c9ab139c42a81d62532751c158627",
            ["你好，$N。我是米洛爾·怒斬，大鍛爐的看守者。"] = "ea87f9213413c02d4186b43c3b1f15ad",
        },
        [11146] = {
            ["你好，$c。"] = "ff6b7b64cb17b855134fc86b013b44ba",
        },
        [11176] = {
            ["我是克拉索克，這些工匠的監工。"] = "7e9d679addb34d3d0807c78bae52c702",
            ["當一個鐵匠達到了你們專家工藝水準的時候，我會提供給他們一個選擇。$B$B雖然沒有要求你做出選擇，但建議你最好還是做出抉擇——畢竟，你想永遠的當一名新手嗎？是專家級的護甲鍛造師和武器鑄造師給我們軍隊提供補給，從而贏得戰爭的勝利並獲得稱讚！$B$B注意，$N。一旦做出了決定並完成了要求的任務--就沒有回頭路了。一個人只能沿一條路走到底。"] = "96173540913b1a1b1f52b21095a0971e",
        },
        [11177] = {
            ["你想要什麼？"] = "a9064d83aa3ba7a86a2ff7346ed99f64",
        },
        [11178] = {
            ["嗨，$c！"] = "fd41c7dea4e93768079bd2529e97c608",
        },
        [11191] = {
            ["不要靠得太近，$n。我有可能失誤將我的錘子敲到你的腦袋。"] = "e2dd7fbda6eda67036e13d4fbe105755",
            ["我會教你斧系專精之道。你只需要恭恭敬敬地問我就可以了。"] = "36713901087518deca258af947863cc9",
        },
        [11192] = {
            ["啊，一個經歷豐富的冒險者。基爾拉姆讓你來這裡了。我知道你具有相當的能力，你只需要詢問我，我就會教你斧系鐵匠的知識。"] = "6d7eb7644ad83f313e5d689284fb3b48",
            ["我是基爾拉姆，斧系大師。"] = "9bd36faf52beb6ae72539e0731c74b9d",
        },
        [11193] = {
            ["如果你希望成為一名鑄劍師，那就問問我吧。"] = "f6dd091cd31c13e889f5415aa70a5dd6",
            ["退後，否則我會把你一下子砍成兩半的。"] = "06af0379d0a4f27cb78f8ccab80db4c6",
        },
        [11216] = {
            ["你好，年輕的$g主人:女主人;。我是艾瓦·薩克霍夫，這是我的丈夫 盧森。很高興認識你。"] = "719242cbbf2aa59d701d86713c8c3252",
            ["去哪裡？我們過去、現在和將來所知道的全部就是這些。$B$B最終，我們與巴羅夫失去了聯繫，並從房子裡被趕了出來。我們不知道其他僕人出了什麼事，只聽到有尖叫聲,痛苦的尖叫聲。$B$B知道我們無路可逃，盧森和我被迫藏在了我們的住處。在白天，當學校相對安靜時，盧森會溜出去弄點食物和喝的東西。"] = "b065b568de2e8281a8a07ba46fb7e67a",
            ["喔真是太可怕了，$g先生:小姐;。巴羅夫的家裡從前充滿生機...充滿活力。這個莊園是巴羅夫家族在他們遙遠的王國裡主要的住所。$B$B盧森和我注意到隨著時間的流逝，巴羅夫家族變得抑鬱而沮喪。偏執妄想和暴怒籠罩著男主人和女主人。在夜裡，我們能聽到巴羅夫家族在房裡爭吵。根據我們瞭解，他們的貪婪毀了他們，可以這麼說。"] = "af8171848b9bed576fbbef9cbc14cfea",
            ["屠夫說起「無辜者的鮮血」和他的黑暗主人，「基爾圖諾斯」。以及他會如何滿v洛L主人的欲望。$B$B最後，這個怪獸完成了他的實驗。我們被耗幹了生命。我們的靈魂被打碎了。死亡的甜美的擁抱靠近了，我們張開雙臂歡迎它。但是在他極端的殘酷中，屠夫把我們從死亡之門中復活。$B$B我們要被活著扔進他貪婪的食屍鬼之中。他笑著看我們被魔鬼吞噬。"] = "a7270f1782361fe639b53192b48d3021",
            ["我們什麼都沒感覺到。我們的靈魂在這裡，在地獄。在找到我們的屍體並讓靈魂安息之前我們不能離開。"] = "edc58a5c1c56476d66c018d555211d77",
            ["我們最後弄清喊聲從哪裡傳來的了。屠夫讓我們見識到聞所未聞的痛苦。他把我們用於無數試驗中，試圖製造一場瘟疫。$B$B日子過去了數星期。要不是那個殘忍的混蛋用法術維持住我們的生命，我們第一天就已經死了。"] = "8a7ceb21fd9d2dc97d7ae354831bff4d",
            ["我們猜想，巴羅夫家族為了保護自己的財產以及生前死後對土地的所有權，他們與一個名叫科爾蘇加德的人類法師達成協定。$B$B<艾瓦戰慄起來。>$B$B協議中提及了巫術學校：這個成為詛咒神教的地方，變成他們的首府。$B$B隨著時間的推移，巴羅夫的房子變得越來越破舊...$B$B黑暗開始籠罩整個房子的各個部份。不重新維護是不可能...而且噁心的事。"] = "c5cf5c7edf079b63f339d577611fcc5e",
            ["我們這樣持續了六個月，看到房屋經歷了令人恐懼的變化。骯髒的怪物隨意在莊園裡漫遊。隨身攜帶著各種與儀式和祭祀相關的用具的黑暗信徒遍佈在每一寸地方。我們知道我們躲不了多久了。$B$B正如所料想的那樣，我們被發現並抓住了。他們剝掉了我們所有的衣服並把我們放到一灘鮮血中。我們坐在那裡長達數天，赤身裸體，膽戰心驚。"] = "70ebec19d6bac1a72ab166bf72b88a89",
            ["當然，$g先生:小姐;。我們曾是巴羅夫家裡的僕人：現在那裡被稱作通靈學院。$B$B我那時是女僕的領班而盧森是主人巴羅夫的男管家。$B$B我們為巴羅夫家族工作了數十年，直到……$B$B<艾瓦哭了。>"] = "756458ddc837d604fed920f729482517",
            ["限制？這世上有些東西比柵欄和鐐銬更加能夠限制住人，年輕的$g主人:女主人;。亡靈包圍著我們，不斷用恐怖的動作折磨我們。$B$B最終，他來了。他自我介紹叫瑟爾林·卡斯迪諾夫教授。我們都把他叫做「屠夫。」"] = "69e44cddca5438e4e1af0254c4b88beb",
        },
        [11277] = {
            ["你嘗過我們的麵包嗎？麵包師瑪斯特森是最具天才的烹飪師！"] = "f46f6654ac94eac82e2b0c3924d865e1",
            ["你沒看到我們正在準備迎接烏瑟的訪問嗎？現在別妨礙我，我有許多工作要做！"] = "4e2408ee8c09379d77525ec8b38e694d",
            ["我們美麗的島嶼迎來了新的一天。"] = "6ee2df979a0ec4486607c25f530d005f",
            ["陌生人，我們並不是粗魯的傢伙，只是大家都忙於在烏瑟到來之前確保一切順利。光明使者能來到我們的城鎮，這可真難得。"] = "3fd0ad73fe861332551fc4d9af524377",
            ["陌生人，歡迎來到凱爾達隆。"] = "7865da4630a47f9938f5a4dfce34dadf",
        },
        [11279] = {
            ["哎呀，你看起來就像是一個普通的街頭頑童！"] = "f4a68005ee615866bd6901fa901730b9",
            ["在凱爾達隆，你不能四處遊蕩、行乞、詛咒、鬥毆，也不能隨心所欲 。"] = "4c4f28300ec91dd44dcc6b9766779e5d",
            ["小心點，陌生人。別在我們的鎮子裡惹事。"] = "a97a57480f28e32779349ee115d11474",
            ["我憋了一肚子的火，別讓我朝你發火。"] = "8aefd7ed4734fdad575f3aa8cabd868b",
            ["我被你吸引住了，$r。"] = "98696987285136bfb07bf8b6b4ca71f2",
        },
        [11281] = {
            ["哎呀，你看起來就像是一個普通的街頭頑童！"] = "f4a68005ee615866bd6901fa901730b9",
            ["在凱爾達隆，你不能四處遊蕩、行乞、詛咒、鬥毆，也不能隨心所欲 。"] = "4c4f28300ec91dd44dcc6b9766779e5d",
            ["小心點，陌生人。別在我們的鎮子裡惹事。"] = "a97a57480f28e32779349ee115d11474",
            ["我憋了一肚子的火，別讓我朝你發火。"] = "8aefd7ed4734fdad575f3aa8cabd868b",
            ["我被你吸引住了，$r。"] = "98696987285136bfb07bf8b6b4ca71f2",
        },
        [11285] = {
            ["他們並未意識到自己已經死了，$r。他們受到詛咒，在頭腦中保留了這個城鎮被毀滅之前的記憶，大部分是這樣，還有一部分人更為不幸。$B$B你認為是天譴軍團所為？那時天譴軍團還不存在呢，就算是它們的話，我們也會與它們展開一場惡戰的。$B$B不，這場恐怖而極具破壞性的瘟疫源於通靈學院，它摧毀了整座城鎮，無人生還。$B$B讓我獨自承受這悲傷吧。"] = "313febb63dee5a7c62e6bd14ad042eb5",
        },
        [11286] = {
            ["他真的獲得了不朽之身。他很快從眾多信徒中脫穎而出，巫妖王隨即授予了他永生的權力。巫妖萊斯·霜語因此而誕生。$B$B你明白嗎？"] = "3f405996544104f75a50b759d3498828",
            ["停下來——不。放慢速度——或許這樣比較好。$B$B通靈學院是他們接受初級訓練和教育的地方。信徒們從那兒走出來，並最終進入我們的社會。$B$B這就是我們必須攻破通靈學院的原因。它是詛咒神教的中心！"] = "7bea42e5121470dc3f74c222342d2d9d",
            ["啊，我想我說得太快了。萊斯·霜語是通靈學院的管理者，他負責訓練所有的黑暗大師，他是科爾蘇加德最欣賞的學生和下屬。他曾經是激流堡的法師，一個從來沒有接受過達拉然正規訓練的流浪巫師。$B$B當科爾蘇加德開設詛咒神教的時候，萊斯就是首批加入其中的人，因為他知道通過黑暗魔法可以獲得不朽。"] = "51cb986edcfa270e6cc5822e28aea6d5",
            ["很好。為了實現我們的計畫，我們必須首先製造一塊生命徽章。你準備好了嗎？"] = "860337aafa61acb9bf89d39d7d7e5df9",
            ["放慢速度，$c。你要殺的人已經死了，對著屍體狂砍是無濟於事的。可以真正摧毀殭屍的方法極少，而且你我也無法使用這些方法。為此，我制定了一項計畫，這項計畫將對詛咒神教產生巨大的影響。"] = "3654a5858970316abe17dd3eeaa6ad6f",
            ["是嗎？這是他們一貫的操作手法。對科爾蘇加德和快速增長的天譴軍團軍隊來說，什麼東西擁有更大的價值？一個能成功潛入某個組織，然後釋放瘟疫使數千人喪命的狂熱追隨者，還是一個普通到掉渣的亡靈士兵？很明顯你不是那麼愚蠢。$B$B沒錯，$r，他們就在你周圍，生活著，工作著，密謀著。"] = "6ac3dfebce6f1d216515255cab46fcf0",
            ["有人沒有受到記憶的折磨。"] = "617c23db3203cf0d7bf17c56cc4f725a",
            ["詛咒神教正在迅速壯大。從小型村落到首都，從部落到聯盟，幾乎每座城鎮的居民中都有詛咒神教的信徒。$B$B別驚訝，他們只在儀式和慶典上面才身穿統一的服飾。你很可能已經跟他們的信徒碰過面了，只是你不知道而已。"] = "5531b0711b11aa45460840d0d2c1ab10",
            ["這很簡單，真的。從萊斯·霜語的身上奪走他的力量。將他變回普通的形態，然後果斷地殺死他。"] = "5ccab19ac455820f916fd02a08fcb67c",
        },
        [11316] = {
            ["也許你應該對著這些套在我憤怒的拳頭上的擴音器講話。"] = "cbac7251f7cadd2e49d055da41a352e5",
            ["啊，我心愛的白蘭地，我太思念她了！"] = "d0de32a7070d9141f53ed58970f3f5f2",
            ["巴羅夫家族讓我忙個不停。總有一些垃圾從那兒出來。"] = "03a7c357a0ab51cdaf720c6be5d6d491",
            ["我的頭銜是廢物管理專家。"] = "a7ed0b69c3f96a8b2db61ded1d58a42b",
        },
        [11317] = {
            ["嗨！你從來沒有過深海潛水的經歷嗎？我告訴你一個小秘訣，嗯。在海洋深處有許多冒氣泡的裂縫，當你在水下時可利用這些氣泡進行呼吸。這個秘密只限於你我之間。對我來說，貝殼到處都是……如果你懂我的意思的話！"] = "4e6ffc14d0d8a4483a2dcdfc8694ccbf",
        },
        [11397] = {
            ["伊露恩與你同在，$c。"] = "9f0b1ccaf183a8e36a2849671ae33e26",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
            ["我的智慧就是你的智慧，我的知識也一樣。我能為你做什麼，$N？"] = "7f25bf796f093ccde831db9e50079867",
            ["願月神與你同在，$c。"] = "9f0b1ccaf183a8e36a2849671ae33e26",
        },
        [11401] = {
            ["伊露恩與你同在，$c。"] = "9f0b1ccaf183a8e36a2849671ae33e26",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "002e3e2a721f2f5fb8a4b9da6cdeb661",
            ["我的智慧就是你的智慧，我的知識也一樣。我能為你做什麼，$N？"] = "7f25bf796f093ccde831db9e50079867",
            ["願月神與你同在，$c。"] = "9f0b1ccaf183a8e36a2849671ae33e26",
        },
        [11406] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "31ab172e1a375db1c9157d594eb608d9",
            ["願聖光保佑你，$c。"] = "852369f0d2fbc11e555e75fe5a433853",
            ["願聖光與你同在，$N。我能為你做什麼嗎？"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
        },
        [11407] = {
            ["我在找人，$c。請不要打擾我……這對我很重要。"] = "139d2506ed562303b66f560b7502291c",
        },
        [11486] = {
            ["我統治這個王國已經有一萬年啦。在那時，我從那些神聖的辛德拉家族成員那兒聽到很多令人著迷的故事。$B$B由於我必須待在這兒，所以我常常和訪問者溝通交談。你可以為我講個故事嗎，或許你想聽聽我的故事？"] = "fb9a6eb92214ce1abb9831293212112b",
        },
        [11536] = {
            ["你好，$c。我是軍需官米蘭達·布利洛克——銀色軍團為數不多的授權裝備和軍品軍需官之一。$B$B既然你在我們的委任下與邪惡戰鬥——同時贏得我們的尊敬和信任——你會從尼古拉斯·瑟倫霍夫公爵那裡得到勇氣勳章。勳章有兩個作用：用他們贏得在軍隊中更高的地位，或者作為交換得到特殊物品。$B$B隨著你在軍團中地位的升高，你會發現你會有更多的物品。"] = "76e62df07e05db88a7485a8b88c9987d",
            ["當然可以，$N。$B$B黎明陣營裡屬於友好聲望的冒險者必須交出60個徽章才能購買精良級的物品。如果想購買更加強大的史詩級物品，他們就必須交出220個徽章。$B$B我話先說在前頭，沒有獲得黎明好感的冒險者所需要付出的代價可是非常的高。"] = "9656dc4e19c25b00c359bd5324e01c23",
            ["當然可以，$N。$B$B黎明陣營裡屬於尊敬聲望的冒險者必須交出40個徽章才能購買精良級的物品。如果想購買更加強大的史詩級物品，他們就必須交出 150個徽章。$B$B我必須承認這些代價對在黎明中屬於尊敬聲望的來說仍然很高。"] = "c5a566d78a559292a57e527462eed009",
            ["當然可以，$N。$B$B黎明陣營裡屬於崇拜聲望的冒險者必須交出12個徽章才能夠購買精良級的物品。如果購買更加強大的史詩級物品，他們就必須交出54個徽章。$B$B黎明的崇拜聲望者享有最大的優惠。"] = "784b321e46fc302d5772086f42f3d4e4",
            ["當然可以，$N。$B$B黎明陣營裡屬於崇敬聲望的冒險者必須交出14個徽章才能購買精良級的物品。如果想購買更加強大的史詩級物品，他們就必須交出90個徽章。$B$B黎明的崇敬聲望者想獲得精良級的物品，這個代價是非常合理的！但史詩等級的物品仍需付出不少代價。"] = "dcf21ea6bba24a55d9157c1f031d42ef",
            ["當然可以，$n。你只要跟我說你想知道的是哪種聲望。"] = "95455c097e5501d0311f370c9de61cc0",
        },
        [11548] = {
            ["一個強大的人類魔法師傳聞就在北部生活；他為了某種不為人知的原因一直在看守著那片大地。我自己沒有親自去過，但是據說訪問者在那裡很受歡迎，如果他們願意為他辦些差事的話甚至可以贏得他的好感。"] = "ce97a3f0d9b87cbf8e4913c174a68681",
            ["上層夜精靈曾經統治這座城池，他們在此演練威力強大的祕法。現在他們受到詛咒，靈魂在這片土地上遊蕩，惡鞭軍官納迦侵佔了精靈的城市。納迦一定在廢墟中搜尋那些高等精靈的神器。"] = "177b136c703d996695ff9d9a6ee3304e",
            ["你好，$c。$B$B那邊的哨兵允許我住在他們的營地，只要我答應不會再有麻煩了——我敢肯定你能意識到對外交的需要，是嗎？$B$B我來調查這片土地的紊亂狀況，既然這也有助於他們的事業，他們同意我在這裡 只能協助艾澤拉斯各族之間脆弱的聯盟關係。如果你想幫我，那麼我會很感激，但無論如何，請不要引起任何麻煩。"] = "f54143d6861ddef271769d60b550b493",
            ["你幫助了我，我會告訴我所知的這片土地和生物的情況。我所瞭解的並不多，但是我可以告訴你一些你可能感興趣的事兒。"] = "898b582dd44193bf71686d4995bc5367",
            ["我對夜精靈的瞭解有限，但是據說很早以前——當夜精靈還掌握著神秘法術時——艾薩拉便是其中的佼佼者，她年輕美貌，是夜精靈的女王。不幸地是，正是她對魔法的癡迷才導致歷史上最具破壞性事件的發生。"] = "cadc0e431f4794433c9f20b321f3f84d",
            ["藍龍瑪里苟斯不在那兒，但是他的信徒在。我不清楚這是怎麼回事，但是我可以告訴你：藍龍所在的地方都有希望找到神秘的魔法。如果說龍人在這兒保護某種東西的話，我是不會感到驚訝的……或許是高等精靈遺漏的物品。"] = "ff66933a79e40c4363ca877e0bc40aab",
            ["過去數年來，我目睹了熊怪所經歷的種種可怕的事情——它們成為戰場上的無辜受害者。但是我不清楚這個部落現在怎麼樣了。它們被席捲費伍德森林的瘟疫腐化了嗎？或許它們對自己曾經和平的民族所遭遇的一切表示憤怒，正試圖自我保護？無論如何，它們中的大多數對進入這片領域的人都會表現出敵意。"] = "b660919fd15bb4acba5ab26eedc550ac",
        },
        [11608] = {
            ["你好，$c。我在亡靈壁壘設立營帳，準備進入瘟疫之地。不久之前，謠傳有一位偉大的人類巫師居住在壁爐谷。血色十字軍強迫他為他們的戰士和獵人製造新的弓箭和槍支。據說在十字軍殺死他之前，他鑄造了一件非比尋常的武器。$B$B我猜想他們對祕法越來越不信任了。"] = "bfa0aecd4815be32da4962b7c6f07ffe",
        },
        [11609] = {
            ["你好，$c。沒有多少時間談話——我在動身去壁爐谷之前只是把冰風營地作為暫留地休息一下。我曾聽到傳言在他們瘋掉之前，血色十字軍強迫一個法師為他們工作，為他們的士兵製造強大的弓箭和槍支。我不敢肯定他成功與否……十字軍在他們的成品製成之前殺死了他。或許他們殺死他為了保密……也可能他們不太信任祕法。"] = "ce388452c2e07ab97505e895497f397f",
        },
        [11610] = {
            ["你……你好，$N。對不起，我正從傷勢中恢復過來。$B$B那些血色十字軍比我料想的要兇猛的多。他們幾乎在裡面幹掉了我。$B$B你也應該多加小心。我不願看到他們先發制人。"] = "5255d112e3f4d77633395a63b892be9f",
        },
        [11615] = {
            ["我的家人過去在北山伐木場工作，那裡現在被稱作西瘟疫之地。他們曾忠於杜馬家族，而現在血色十字軍把一切連同壁爐谷全都佔領了！$B$B在把那些狂熱分子從艾澤拉斯驅逐出去之前，我是不會停止行動的。"] = "14f0d1fdd7afc2ea46056b354eced4c0",
        },
        [11616] = {
            ["在最後一次大戰之前，我父親經營著北山伐木場。那是他的命根子，他把所有的精力都投到了伐木場。戰爭爆發時，我們忍痛逃到了暴風城。$B$B那些日子裡，我們失去了無數朋友，而我們的伐木場也被血色十字軍佔領了，我對此感到非常心痛。$B$B這就是我回來的原因。"] = "09280c8a100dbf6ab274fcbdf0803b69",
        },
        [11625] = {
            ["啊……一名顧客！看看我最偉大的發明，貿易機器人1000型！它擁有你所需的一切商品……其中的一些稀有物品更是在卡林多的其他任何市場上都找不到……更不用說它的設計不支持任何討價還價的廢話了，因此你看到的價格就是你要支付的價格。"] = "4de54f822df981ac699c8e0f5d6eaca4",
        },
        [11626] = {
            ["今天碰巧是你的幸運日；我完成了超級商人680型的維護工作，因此有大量物品以超低的價格出售。你自己去看看吧……我的兄弟考克認為他的貿易機器人1000型會勝過我的。"] = "f3da952cbd390a3e587b455be7a2577f",
        },
        [11798] = {
            ["你不是德魯伊！"] = "5cfd7206f10c06184a22b230f17e7e9b",
            ["你必須去西部荒野的海洋搜尋，朝正西方西——金海岸礦坑與海岸交接處往西北方向。海岸邊有一隻錨，看來附近一定有艘沉船。水下的壓力很大；如果游得太遠的話，即使是最優秀的潛水者也可能死於疲勞。$B$B去找一處適宜的自然環境吧，$N——這附近有起泡的海底裂縫，能在深海潛水時提供氧氣。"] = "58917c8c3ab49673db3986c9f9ce7b31",
            ["你需要飛往雷霆崖嗎?"] = "155c5f7fcaa47599e5718aa28c430db2",
            ["在銀松森林北流海岸邊緣，海灘上擱著一艘廢棄的船。船隻以西有你要找的東西；遊得太遠的話，你會因疲勞無法遊回海岸的。海床上有一隻上了鎖的箱子，等著你去取呢。$B$B要是沒有人幫忙的話，潛到這樣的深度會受到極大的壓強，要小心；海床上有一道裂縫，能釋放出氣泡，有助於你尋找那半塊墜飾。好好利用吧。"] = "8f4726b4aaa640c64d970e27f5507d9f",
            ["如果你想飛回魯瑟蘭村，就該找夜精靈希爾瓦·菲納雯斯談談。"] = "e06e352070d1d0f09e52dc97d8a078e5",
        },
        [11799] = {
            ["對我們這些在月光林地塞納里奧議會的人來說，雷姆洛斯神殿是個神聖的地方……所以請你的表現符合訪客的身份。$B$B我想你不願讓我用彎刀殺死你，那就是了。"] = "2e8e186a35fdbdc4167c9a2d1cbd23c8",
        },
        [11800] = {
            ["你不是德魯伊！"] = "b6d7af778c178854770fdd337d5b015a",
            ["你想飛回塞納里奧議會的魯瑟蘭村嗎？"] = "cfbd485026f0de1a03206ff943a27ce2",
            ["在貧瘠之地的東北部，有一處受到嚴重污染的水池。當地人稱它為淤泥沼澤；風險投資公司將水晶般幽藍的水域變成工業副產品和廢棄品的泥潭。在沼澤的中心有你要找的東西，$N。$B$B要小心，風險投資公司絕不容許有人入侵，他們將不為其工作的人都當作入侵者。你作為自然的保護者，更是他們極力對抗的目標。"] = "94a4bfe6c74514d3611a508fc1a3f472",
            ["在黑海岸的北面流淌著壁泉河，發源於現今的費伍德森林。隨著河流流出並匯入薄霧海，一直蜿蜒到海洋北部最深處。一處被人們稱為石爪的地方有你要找的東西。$B$B要當心——蛇頸龍聚集在石爪那裡，會攻擊侵入他們領地的人。"] = "3d6d602f1e2f055fef17cf3368d58ec6",
            ["要是你想要飛回雷霆崖，就該跟我的牛頭人搭檔布瑟恩·草風談談。"] = "cbbd89806b3ea7f79bc9dbdcee8cdcb8",
        },
        [11801] = {
            ["別聆聽來自世界的心聲——答案就在你心中，你知道真相的。"] = "f4177bd0951c2f715a697139a8a7c918",
            ["唉，事情似乎總是這樣。和塞納里奧議會的其他人一樣，我也認為是米利的創作物在遠古戰爭中毀掉了。但是我已經認識到，這種觀點是錯誤的。$B$B豐碩的果實並未被摧毀……儘管現在它被稱為惡魔之藤。它被埃德薩拉斯的魔王奧茲恩污染了。"] = "7eb5b4d204e4e905b3fc4a03671e7928",
            ["塞納里奧議會的人已經瞭解埃德薩拉斯的近況了。我陷入僵局，不知如何是好。我很可能向那些體格強健、善於作戰的人尋求幫助。$B$B但是，要對埃德薩拉斯採取行動，就要瞭解關於豐碩的果實的知識。"] = "7a3713e922465a73a16446086589817a",
            ["多年前，埃德薩拉斯是魔法師的集中地，居住在那些神聖的大廳中的人都能使用強大的魔法。米莉仙·瑟琳就是這樣一名夜精靈——她是個博學者，能將自然本身的力量灌輸到她鑄造的神器中。$B$B豐饒之果便是她的傑作……她利用特殊的月井製造出一種奇異的葡萄酒，具備保護和生長的效力。埃德薩拉斯在葡萄酒的滋養下日益繁華起來。"] = "308540acd4522979045cee37918c6a8c",
            ["我……我無法開始想像，$N。我只知道我不能讓這件事發生。它會被摧毀的——就算不毀在我們對巨魔的防禦上，也會毀在米莉仙·瑟琳的記憶上……米莉……$B$B我的朋友，這就是我希望你伸出援手的事情。"] = "a9d5f6215316701664aa2f69863fa29a",
            ["是的，我知道埃德薩拉斯。多年前，那兒曾是夜精靈的魔法要塞。$B$B你知道埃德薩拉斯嗎，年輕人？也許有人會說這跟我目前的處境一致……但是我可不相信巧合這回事。"] = "888a945f04773f48531be690856af34d",
        },
        [11802] = {
            ["你好，$c。歡迎你來到永夜港，還有整個月光林地。塞納里奧議會歡迎所有尊敬大自然的權威和支配力的生靈。$B$B當你在這裡的時候，請一定要保持所有事物的平衡。這裡不喜歡受到打擾，而我們的看守所受的訓練就是無條件地停止所有的敵對行為。"] = "628e4025e875b588722edea856c7e595",
        },
        [11811] = {
            ["<納里安將一封未打開的信貼到他的前額。>$B$B這是什麼……嗯……天鵝絨！$B$B是嗎？"] = "225eafda96d1c24ae14477251f082c90",
            ["不要告訴我！噓！你是為灰燼之劍而來的嗎？！？對……呃……不對！不好意思。$B$B我能幫你什麼忙嗎，$r？"] = "2e27a2e4cf3cdc84c5efe6482fb8f345",
            ["納里安為您效勞！退隱的工程學專家和占卜大師！我敢打包票！"] = "2494fd01fbbcaa3067f0f6bde8276ef1",
            ["這……這霧好濃啊，$N！我什麼都看不見啊！等……等一下，我看到……我看到維維爾的藏身之處了。對……沒錯！我確信他一定握有書的其中一章！$B$B讓我調整一下望遠鏡，這樣可以看得更清楚些。$B$B(納里安看的都快鬥雞眼了。) $B$B啊！我看到了，原來是奧卡茲島！那邪惡的壞蛋就在奧卡茲島上！"] = "fe83661210697890e5faa8788183a890",
        },
        [11833] = {
            ["你隨時都可以跟我交談，$n。你對瑪加薩忠心耿耿。我想將來她會召見你的。"] = "eeabcd657e17f9388ad202c9e2e118d7",
            ["很高興見到你，$c。除非你和我的女主人瑪加薩之間有直接交易關係，否則別找我說話。$B$B我幫她處理大部分的事務，讓她能集中精力處理更重要的事情。或許在你拜見她之前我們可以談談。"] = "d3cf6d45a6ea3ef19313a80754b85210",
        },
        [11835] = {
            ["你好，$n。"] = "384ac0a49aebaacce2b295d67b189472",
        },
        [11860] = {
            ["恐怕我已不再是個文雅謙遜的人了。年齡和無數戰爭讓我的皮膚和靈魂變得堅硬無比。或許這就是凱恩派我來烈日石居的原因……和煦的暖風和溫暖的陽光無法減輕我的痛苦。"] = "e07000c6839ce000b1b16c6b15d0533f",
        },
        [11861] = {
            ["石爪山脈在這片區域擁有許多危險的洞穴。若干冒險家願意冒著生命的危險到這些洞穴中探險。$B$B$C，也許只要你全心全意地尋找，會找到財寶的。"] = "09ad1d72371134696f00bc0ad18afa09",
        },
        [11865] = {
            ["你想學習如何使用武器，是嗎？嗨，$g小夥子:姑娘;，別在站在那兒發呆啦，大聲說吧！"] = "944b95dab7611ca743debffc47ea0d42",
            ["地精武器管理人比克斯在這商店附近遊蕩。她可以教你使用十字弩、匕首和投擲武器。  暴風城維勒武器店的人類武器管理人吳平可以教你使用十字弩、匕首、單手劍、雙手劍、長柄武器和法杖。  居住在達納蘇斯戰士區的夜精靈武器管理人伊琳尼雅·月火  可以教你使用弓箭、匕首、拳頭武器、法杖和投擲武器。"] = "907cb6456b6c5ff065e865380e9b9180",
        },
        [11866] = {
            ["我可沒法教你戰鬥時如何保持優雅姿態，我只能教你如何使用武器。"] = "2e514c1eb9b20edc5d2084e30fe9df15",
            ["鐵爐堡密林武器店的矮人武器管理人布里維夫可以教你如何使用拳頭武器、槍、單手斧、雙手斧、單手錘和雙手錘。  鐵爐堡密林武器店的地精武器管理人比克斯  可以教你如何使用十字弩、匕首和投擲武器。  暴風城維勒武器店的人類武器管理人吳平可以教你如何使用十字弩、匕首、單手劍、雙手劍、長柄武器和法杖。"] = "d360ac04210d718276dddc83f8708938",
        },
        [11867] = {
            ["你是來學習如何作戰嗎？"] = "da8269ec529338fb71da4bda52aa2d08",
            ["居住在鐵爐堡密林武器店的矮人武器管理人布里維夫可以教你使用拳頭武器、槍、單手斧、雙手斧、單手錘和雙手錘。  居住在鐵爐堡密林武器店的地精武器管理人比克斯可以教你使用十字弩、匕首和投擲武器。  居住在達納蘇斯戰士區的夜精靈武器管理人伊琳尼雅·月火可以教你使用弓箭、匕首、拳頭武器、法杖和投擲武器。"] = "0cf4036d40658806b00933ae705fa922",
        },
        [11868] = {
            ["到這兒是學習如何使用新武器，還是來浪費我時間的？"] = "ac6104deed8fed0d5a86bb3bee66c1bd",
            ["居住在雷霆崖低處山峰的牛頭人武器管理人安塞瓦可以教你使用單手錘、雙手錘、棍和槍。  站在我旁邊的哈納什可以教你使用弓箭、單手斧、雙手斧、棍和所有的投擲武器。  居住在幽暗城戰爭區的亡靈武器管理人阿基巴德可以教你使用十字弩、匕首、單手劍、雙手劍和長柄武器。"] = "6fbe1caacff7fcf16cc0478c2dccd149",
        },
        [11869] = {
            ["塞尤克是獸人武器管理人。他居住在奧格瑪的榮譽谷。他可訓練弓箭、匕首、拳頭武器、單手斧、雙手斧和投擲武器。  居住在奧格瑪榮譽谷的食人妖武器管理人哈納什可訓練弓箭、單手斧、雙手斧、棍和所有投擲武器。  居住在幽暗城戰爭區的亡靈武器管理人阿基巴德可訓練十字弩、匕首、單手劍、雙手劍和長柄武器。"] = "abac3599f5c7bf1790a96604da9b81dc",
            ["如果你有能力學習的話，我是很榮幸教你如何使用武器的。"] = "c180df78a79d05ea8d63a60886eb2a84",
        },
        [11870] = {
            ["塞尤克是獸人武器管理人。他居住在奧格瑪的榮譽谷。他可訓練弓箭、匕首、拳頭武器、單手斧、雙手斧和投擲武器。  居住在奧格瑪榮譽谷的食人妖武器管理人哈納什可訓練弓箭、單手斧、雙手斧、棍和所有投擲武器。  居住在雷霆崖低處山峰的牛頭人武器管理人安塞瓦可訓練單手錘、雙手錘、棍和槍。"] = "1e08fa1b1a06707d7772a9d8bffbb01c",
            ["我猜想你到這兒來是訓練如何使用新武器的？快點，我很忙的！"] = "cebc5bda58373eb38beb32738253fcd6",
        },
        [11872] = {
            ["你需要幻象嗎？$B$B要是在執行任務的過程中幻象失效，回到我這兒來，我將重新對你進行偽裝。$B$B如果你盡力而為還是失敗了，別放棄！回到我這兒來。我將助你完成目標。"] = "326d109a3f8c03ee97228b860a23d901",
            ["現在是危險時期，冒險者。多加小心。"] = "6010e5908eacadb88d4696fee457da3a",
        },
        [11878] = {
            ["毫無疑問，你是黑暗女王派來接受訓練的又一個無能的白癡。$B$B<納薩諾斯歎息著。>$B$B我每次都得把你們的屍體運回去給她，我想這次也不會有什麼例外。$B$B但是，我並不會問什麼，我只按照黑暗女王的吩咐辦事。"] = "36ceb7cebed57b0d09e09d90cea831c6",
        },
        [11899] = {
            ["你想要飛往什麼地方？"] = "0edd3c73540d735f036ac6e027466523",
        },
        [11900] = {
            ["你想要飛往什麼地方？"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [11901] = {
            ["你想要飛往什麼地方？"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [11939] = {
            ["如果你想在塞納里奧議會中找尋某些檔案的話，我就是那個你要交談的人。你首先要知道要尋找的確切資訊，那樣我才能幫你。$B$B看看那個，真是光彩奪目呀！"] = "310c9f80926c7ac56d95a59b469ade54",
        },
        [12031] = {
            ["我應該尋求某些幫助；我不喜歡整天坐在這兒賣魚。我更願意去釣魚，然後再賣掉。"] = "6c9f3fe4497da2c378cdd9d41104d24e",
        },
        [12032] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "191f9771bbe3c0dfd9d726fd4f02d760",
            ["我可以教你一些釣魚技能。"] = "7709fb559a1b486ad6fbaec0f8f6f8ff",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "0e953fd8dfbfe1414c60a2989878d380",
        },
        [12042] = {
            ["即使在冰冷的石頭牆內，就像庇護這座城鎮的牆一樣，人們仍舊可以找到寧靜與和平。事實上，你可以在你所在的任何地方找到他們……只需在你體內尋找這種平衡。"] = "922a94a8f826437fe0370bdcd6a587ac",
            ["歡迎你，我的$g兄弟:姐妹;。如果你想接受訓練，我會很樂意教你的。$B$B來自翡翠夢境的召喚將很快佔據你的心靈。你將冬眠數年，在最純淨的環境中生活。你將在那兒接受最終的訓練。"] = "1d12fd8e421d229eea70c7677a2daeca",
        },
        [12136] = {
            ["$g嗨，帥哥，你想去格羅姆高嗎？我聽說那裡的叢林整日霧氣騰騰的，也許我們可以一起度個短假，我讓你看看真正的叢林虎怎麼樣？:來吧，參觀一下奇妙絢麗的荊棘谷叢林。你可以在水晶般的藍色海岸線上愜意地洗日光浴，而我卻站在這難以忍受的高溫下整天傻看著我的兄弟弗雷薩！盡情享受你的旅程吧！;"] = "808af6c85a55d2308db805b9fb00b368",
        },
        [12137] = {
            ["將一枚硬幣塞到首領手中，看看你會得到什麼。我喜歡自己的工作。但是，如果我能設法讓斯納爾克重新分配給這個飛行點的話……那樣就好了。但是我敢打賭，你到這兒來不是要幫我進行職業訓練的，而是尋找地精飛艇前往幽暗城，對吧？那很好，因為它會停泊在我後面。如果你看見斯納爾克，代我向他問好，行嗎？"] = "c021420a6f84c190718c0e399aad7e67",
        },
        [12196] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "608e80af556ec1f3d3baef7e57f6be28",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "0276ff49074261ee804b38342793bf84",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "799c250c21ae02bcb1dbb537a38580f9",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f3aba6e9ee464fd9569a3498cd66780a",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "22e76f151640be474a52357149eab9fa",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "5bb22872b7638f5085ca2059018cc5ff",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "d204a8a00341a429174e0dbb644ab882",
            ["厄運之槌位於菲拉斯的中部。"] = "59afccdff32f76ae9879d7192bc79e60",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "73249f674e33dc5e663d9bf0dc9c96b6",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "356949e6616d911ef559b61355e02894",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "f92aaab1f1d5835cf040d33a901f8ac6",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "12f0b7117e82d1920705e38b1acbd4d3",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "c2a3a1e19674bf1fea64aea4440edb67",
            ["奧達曼位於荒蕪之地最北端。"] = "72fd07384c9cf3d35d09b60e74ac757b",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "533b295b436d39d2d08b9a0010da7943",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "11667b0ff9532331158f6482eeb8d71d",
            ["如果我們要成為這塊新地區的主人，那麼我們就必須要找個地方好好休息。把你的斧頭放在火邊，讓大家分享你英勇戰鬥的故事吧。"] = "99898ce989e2387123a310f8e8bb7094",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "149d727e2252ad2d21626074d67ae0be",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b589ee74b06baa0850c27cb5b2dced61",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "470d4f471ff0e0a695c417d93294115b",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "65a26145712718ab736d0dff25b7ea3a",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "50d79c7aeabf3cffea9b701bf10738f2",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "04642b49605c1905f8c4ec074ed814b2",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "1362d50a99d5220c57eabff16d1c603a",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "5a680486b1eed5318ac671810b927e65",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "c5bb28585e4ec2284a09cc538e5ea938",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "45dbe29f976fe7758380dadfd1b0d5ec",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "839365eaa1b7bc650b1f66d477413bef",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "ba011425ec6ef2499c76a0df8538827b",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "73717c12f946e4832d3760a4ce017d6e",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "598c9e84f0150f5804083fb81cddb144",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "661c2fbcff67197ca647909d6eff45c0",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "39d92fa9357e241705910cea426d1baf",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "bac84ba209bd32f334399053e2f4b16f",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "3549cdf0ffdc4b960c88a13a92c251c5",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "b4ca0c190cfd0a68f67e69a9ad1ec76b",
            ["諾姆瑞根在丹莫洛的西邊。"] = "2a62241f7676852d758c2bff35cb1c86",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3ea6a13fe8e0d78eb57bd98488901e1a",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "210c73367be3bd7fff9c76683b08beeb",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "e68483a569e848b8cb7bca2cf17765d1",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "31b8782bafa771a039b08f6726b827a8",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "42c37076d3ae3863acfdd2d0f5533f7a",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "1a4b0ce90f4422503651666ac7f00711",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "12696642ffca20488693f012a1332369",
        },
        [12197] = {
            ["$N，你對我們在奧特蘭克山谷的處境有什麼想法？你準備好跟霜狼氏族作戰了嗎？"] = "fe70eb05a6a384f2150bdbcaad041ebd",
        },
        [12198] = {
            ["你認為你能摧毀阿拉索聯軍嗎，$c？希望如此。你究竟想要幹什麼呢，還是你根本就是來浪費我的時間的？"] = "59736d80c4279b69db8e94d24074d17a",
            ["很抱歉，$c，在你變得更加強大之前，我不能讓你去阿拉希盆地送死。"] = "5d7befc434c3b284ff699c9b717bf554",
        },
        [12340] = {
            ["如果你想獵殺納迦，你需要所能獲得的所有幫助。水底有裂縫，能產生足夠的氣泡供你在水下呼吸。向水面遊動，就能利用這些氣泡了。"] = "3c57610ceaac598ea2221dac45d2551c",
        },
        [12384] = {
            ["嗨$N！你是來購物的，還是來出售物品的？$B$B如果有比這兒更便宜的物品，我就不叫精神失常的奧古斯圖斯！"] = "337f7913cf78a0dd090124d95e4642d6",
            ["在天譴軍團來臨之前，我是一名大商販。我出售所有商品。所有！$B$B價錢都極其便宜！$B$B你隨便問問那些沒死的人，看看我說的是不是真的。"] = "9735b7ad56c5248bbce82ee64ea4959d",
        },
        [12577] = {
            ["你想要飛往什麼地方？"] = "8ee9e2b8b1fbeba82851331d36cb251c",
        },
        [12578] = {
            ["你想要飛往什麼地方？"] = "e9f2c6ae11c08606a3e902729508a45b",
        },
        [12596] = {
            ["你想要飛往什麼地方？"] = "4a4d46597b846228dbd070932127a575",
        },
        [12616] = {
            ["你想要飛往什麼地方？"] = "0edd3c73540d735f036ac6e027466523",
        },
        [12617] = {
            ["你想要飛往什麼地方？"] = "43540ff7458382b18eb66468d4ff2856",
        },
        [12636] = {
            ["你想要飛往什麼地方？"] = "99afa7bbff40b3ecca37eb15b8c29387",
        },
        [12656] = {
            ["你可以在北部碼頭搭船前往魯瑟蘭村和達納蘇斯。你可以在南部碼頭發現穿越無盡之海通往卡茲莫丹的米奈希爾港的道路。祝你一路平安！"] = "69d07a52e02e6c2a801dd6309215b6e6",
        },
        [12657] = {
            ["這個碼頭？你可以乘船前往夜精靈的領地。地名？嗯，我想是奧伯丁。我不太確定，我只是一名搬運工。"] = "ca7d18cf048257b8138d41171774e437",
        },
        [12658] = {
            ["你可以從這個碼頭找到去塞拉摩的路。記住我的話，那些地方對從聯盟去的人們是非常不安全的。一定要小心謹慎。"] = "0330eb47812f7e68da55bc38f1165206",
        },
        [12696] = {
            ["作為梣谷獵場最強大的野獸，沙普塔隆可以在這片大地自封的衛兵——夜精靈的陪伴下自由的漫步。沙普塔隆在這裡南部尋找獵物，盡情的撕裂著毫無防備的旅客。$B$B要想殺死這樣一個野獸需要極大的努力，$N。我希望你在獵殺這個野獸時運氣好一點！"] = "dab92356ed8e0a6f55c5ecdea69948a1",
            ["你聽到狩獵的召喚了嗎，$c？你必須仔細聆聽，但是召喚從你的內心傳來。他從我們所有人內心傳來。"] = "d6db8cda45395ece303eac030d3ff6f3",
            ["這只熊漫步在一條靠近石爪小徑的路上，在密斯特拉湖和聯盟的銀風避難所正西方。雖然他是你在梣谷遇到的三個動物之中最好對付的一個，對他也不能掉以輕心。他的出現對於逗留在梣谷和石爪山脈之間的旅客來說是一個巨大的威脅。"] = "d1f866875591d687da8e4a807ff8fed2",
            ["這只黑豹傳言在夜精靈和他們的同盟面前很馴服，這使她成為一個更有價值的對手。薩杜布拉的獵殺路線把她從瑞恩伍德居所趕到了我們的西方，最終在那裡的正西方登陸。她的皮毛是瀝青一般的顏色，而她的速度也不能低估。"] = "12b6c7a941e965437e30f09d3a14b002",
        },
        [12716] = {
            ["我確實很喜歡坐在這裡，聽著大海的聲音。哦，什麼？是的，有一艘船會把你帶到米奈希爾港。它有時會停在這裡。"] = "3999a32253abe70964154c372f32bc5f",
        },
        [12724] = {
            ["這片森林容易使人迷路！要小心。"] = "6021998ac094693ef86cf366f8e389f8",
        },
        [12736] = {
            ["元素在跟我們講話，$c。他們分享著我們必須掌握的知識以及不能洩漏的秘密。"] = "0a8aa26eccc0242964a89762467e5241",
        },
        [12737] = {
            ["如果你想知道碎木崗哨的商旅來往情況，我恰好就是你要找的獸人。不幸的是，我不喜歡人類。$B$B要是你想要什麼的話，就快些。"] = "0d07f0a4ca3a5cd318acb1ed5b17e3de",
        },
        [12740] = {
            ["你想要飛往什麼地方？"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [12757] = {
            ["你好$c--歡迎來到我們征服梣谷的前線！如果你在找事做的話，那麼你算來對地方了。我總是在尋找體格健壯的人來給部落帶來榮譽！"] = "373a32e64da03908f74c18135f0f399a",
        },
        [12776] = {
            ["你不是術士而且我沒時間理你。走開！"] = "200fc4a4b57ca0db7de99023c501ea23",
            ["想讓你的惡魔變得更強大嗎？這需要花錢的，但是你來對地方啦。"] = "4e1a9fddd86d3d21099d60aa02fea747",
        },
        [12807] = {
            ["你不是術士而且我沒時間理你。走開！"] = "1cb32f6470dcf1a2f6a434cc66bea835",
            ["想讓你的惡魔變得更強大嗎？這需要花錢的，但是你來對地方啦。"] = "7890c2b1ae34d8a5d70574f03c64ac95",
        },
        [12863] = {
            ["什麼事，$c？你在彙報嗎？"] = "ecb5c5765055132283e8f669c19aa1d7",
        },
        [12866] = {
            ["我不會傷害你的。我在監視野豬人並記錄他們的活動。我的人民注意到了某些奇怪的事情——黑暗的彌漫——從這個地區來的。我是來調查的，而我的發現很令人不安。$B$B似乎有一個很善於祕法的亡靈外交官。我不相信他也是被遺忘者……我認為更壞。"] = "87ac0e81bb9a372fa977ea14e6844f6c",
        },
        [12919] = {
            ["你需要一種特殊的臭泥魚誘餌來捕捉加茲蘭卡。這些魚餌是我親自製作的！$B$B但是除了魚餌之外，你還需要臭泥魚……你得把臭泥魚放入誘餌，讓它充滿臭味！$B$B將做好的誘餌放到祖爾格拉布中的帕格漁場……然後就坐下來喝酒等待……你無需等太久，因為加茲蘭卡肯定會迫不及待地上鉤！"] = "bb7840ac1ccbf51d87e9a44ee1a98d48",
            ["再次感謝你找回了我的幸運捲尺，$N。這東西能幫我捕到更大的魚呢！"] = "4b8c6e9b9c6223f29c6ee50817bd5289",
            ["在我看來，釣魚的美妙之處在於其緩慢的節奏。人們可以在釣魚的過程中思考、回想過去和計畫未來。$B$B哦，當然這也是用來大醉一場的絕佳理由。"] = "9d7745f7746667248f72319a9c4794ef",
        },
        [12920] = {
            ["你好，$N。我是格里高利·維克托醫生，部落的首席外科醫生。"] = "2638fdc24fed03d3d2affc64eca0bf76",
            ["你已經學會了我現在能教你的所有知識，$n醫生。當你獲得更多經驗的時候再來找我吧，我會傳授給你更多高級的醫學知識的。"] = "283509ff38d5fe49b3dd45d5e0947aad",
            ["很高興再次見到你，$n醫生。我看著你逐步成長，我敢說現在是你學習更高的繃帶技能的時候啦。$B$B一旦你的技能得到提高，就回來找我，我會把我所知的一切都教給你的。"] = "adcbd8c041c99ea585dd49cda036f459",
        },
        [12939] = {
            ["你好，$n。我是古斯塔夫·范沃森醫生，聯盟的首席外科醫生。"] = "0ba18a644f30676df3277200c1ada92e",
            ["你已經學會了我現在能教你的所有知識，$n醫生。當你獲得更多經驗的時候再來找我吧，我會傳授給你更多高級的醫學知識的。"] = "b4c40d18e1bc694e2ebd862b96fbe637",
            ["很高興再次見到你，$n醫生。我看著你逐步成長，我敢說現在是你學習更高的繃帶技能的時候啦。$B$B一旦你的技能得到提高，就回來找我，我會把我所知的一切都教給你的。"] = "f4e3a2c79c79518799f91abcc4d1c545",
        },
        [12944] = {
            ["你所要做的就是鑄造薩弗隆戰錘和找到薩弗拉斯之眼。將薩弗拉斯之眼和薩弗隆戰錘結合在一起就能成為薩弗拉斯！我不會告訴你任何關於薩弗拉斯之眼的資訊。我想你自己能找到的。在這張合約上簽字，讓我們達成交易。"] = "436fa6a143302d46598f8cf4299ea9d9",
            ["我願意用薩弗隆戰錘的設計圖換取一塊薩弗隆鐵錠。$B$B現在，你大概正在暗自盤算吧，「我要那種戰錘來做什麼，我現有的裝備比這東西高級多了！」$B$B嗯，讓我告訴你吧，$g先生:女士;，沒有什麼武器比薩弗隆戰錘更高級了！"] = "2d38739dd99aac211a82868d39e682e5",
            ["瑟銀兄弟會懂得如何製造火焰之王的神聖武器，但是我們缺乏人力，無法獲得製造武器所需的材料。$B$B我，羅克圖斯·暗契，兄弟會賦予我強大的力量，用珍貴的藥方來交換從熔火之心收集的材料。$B$B給個價吧，$r。"] = "30d968320ab86521f066be7db8986c04",
            ["瑟銀兄弟會是不會在螞蟻身上浪費時間的。快滾開！"] = "807f545aa510396b39fd74ed72c9abcb",
            ["薩弗隆鐵錠？！？？！不可能！我必須得到它！必須！必須！$B$B$R，我會花大價錢購買鐵錠的。或許你會對炎魔拉格納羅斯之手之謎感興趣？就是薩弗拉斯，白癡！傳說中火元素之王使用的鐵錘。"] = "ffe6ef04a13e4da40d3147386221790a",
        },
        [12961] = {
            ["你需要去塵泥沼澤找納特·帕格接受訓練，提高自己的能力。"] = "191f9771bbe3c0dfd9d726fd4f02d760",
            ["我可以教你一些釣魚技能。"] = "7709fb559a1b486ad6fbaec0f8f6f8ff",
            ["我沒什麼可以教你的了。我聽說藏寶海灣有個名叫海明威的老頭，他在出售《鱸魚與你》這本書，它對你提高釣魚技能大有幫助。"] = "0e953fd8dfbfe1414c60a2989878d380",
        },
        [12996] = {
            ["一個烹飪培訓師？那好吧，你到大鍛爐東北方的銅壺鐵罐店去。達瑞爾·瑞克努索會教你製作極好的菜肴，那肯定會讓你獲得新生的！"] = "f62abc611ce83aa205cd0e2b5918cc10",
            ["一個術士，嗯……好吧，如果你想在附近繼續做那種事情，你最好管好你的惡魔，$g小夥子:姑娘;。我不喜歡惡魔，但是我喜歡殺死他們。你明白我的話了嗎？  現在你不要再煩我了，馬上消失去荒棄的洞穴。你會在那裡找到那個術士，瑟斯哈特。"] = "8dd3f0d79f6df157dda9178efcf166dd",
            ["任何與部落——特別是獸人——交戰的機會都是不容錯過的。你可以在戰歌峽谷中得到充分的歷練，到武器大廳去找萊蘭迪斯談一談吧，她會送你去戰歌峽谷的。"] = "fa89dafc6960a6d66ea3bc3288a08a03",
            ["你具有成為一名熟練獵人的潛質嗎？嗯，$g年青人:姑娘;，時間會告訴我們一切的。在與軍事區的雷格努斯交談之前，別對著別人的眼睛射擊。"] = "4ee53decdddf5b8264e87b7865aae7ab",
            ["你可以在武器大廳找到我們的常駐馬廄管理人烏布雷克·火拳。他將替你餵養和照料寵物。"] = "8417670da6e88a3c0046fbf19a284faf",
            ["你在尋找一個煉金術老師是不是？我也剛從那裡回來。你會在地精集會的工匠區找到漿泡小姐的。  ：：歎氣：：……為什麼我沒有服下藍色藥劑呢。"] = "10124c09c298bee683297933e30e1865",
            ["你在找哪個專業的訓練師？"] = "cf38911600ac02c04cb72aafa6596e66",
            ["你在找哪個職業訓練師？"] = "cf38911600ac02c04cb72aafa6596e66",
            ["你想去哪裡？"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["你想學習工匠的手藝嗎？那你就得去工匠區找賓斯匹德。  從鐵爐堡大門一直往正東方向走，或者朝著傳來爆炸聲的方向走。"] = "6edc9f2da8079aff91202f55fb3e3dc7",
            ["你想學習怎樣使用一種新武器是嗎？那麼，你就應該與那邊的密林武器店武器商店的比克斯和布里維夫談談，$g小夥子:姑娘;。他們對從斧頭到……嗯……雙手武器都非常瞭解。"] = "fc659204f3f853f42dd60c81107e99b8",
            ["你想找哪類職業訓練師？"] = "dcadd0f33e63218ef70a191c145117f6",
            ["你想要煉金訓練者嗎？嗯，我剛從那兒過來呢，真的。你可以在地精的聚集地地精區找漿泡小姐。"] = "76c8e36d99bf968b0318157d711f4ce3",
            ["你或許不知道，除了是一個嫺熟的裁縫之外，約莫德還是一個巨人殺手！為什麼說當他大喊他一拳打死了七個的時候可以斷定他一定偷聽到我們在一起講的東西！  你應該到大鍛爐北面他的店鋪去拜訪他一下，並看看他是否會在跟你講他的傳奇故事！"] = "c8b7cc29723f78c9a33d40dd94b43a31",
            ["你是問我鐵匠在哪兒？你沒聽說過大鍛爐嗎？所有最好的鐵匠都聚集在那兒鑄造武器和護甲！  在鐵爐堡中心都是敲打鐵器的聲音，你能在那兒找到最出色的鐵匠本古斯·深爐。"] = "79bd37ced9c62943a531dbe47af6053b",
            ["你會在那邊的石火旅店旁邊找到一個郵箱。那就在鐵爐堡大門的北面。"] = "164f8858641d9fa2782d051756979421",
            ["你有需要保管的財寶嗎？去找鐵爐堡銀行的石衣兄弟吧。  從鐵爐堡的入口往東北方向走，銀行就在那邊。"] = "d3430aba4fb0b400b8dca87cf1df8b15",
            ["你確定不想做鐵匠嗎？嗯，如果你真心想學製皮，最好去大鍛爐西北角找費布·鋼軸談談。"] = "a3b00fdf92a61d7b9b93fae27791e95f",
            ["你算來對地方了，$g小夥子:姑娘;！人們從世界各地來此學習成為一名鐵匠。你會看到本古斯·深爐在我們漂亮的城市中央的大鍛爐的鐵砧上埋頭工作。"] = "2ffc912f1ac294a9f6bb188522b88c70",
            ["你需要什麼方面的指引？"] = "411e9efc17c0fa67fa3a65ddbceb693f",
            ["你需要找哪個職業的訓練師？"] = "dcadd0f33e63218ef70a191c145117f6",
            ["克斯塔姆是個大嗓門、愛吹噓的人……他也是你所能見到的技藝最為純熟的戰士之一！  我告訴你，如果你想成為一名戰士的話，就去找他談談吧。他肯定在鐵爐堡大門以東的軍事區中。"] = "cbf2a15cc62d3fbd23d5f088837de2bf",
            ["剝皮？能不能學成只有看你自己了！哈哈！你為什麼不去找巴爾薩斯·裂石呢，他能教你如何剝皮。他在大鍛爐北面的皮甲用品店。"] = "5a0adca7c8c31d843cea219178821576",
            ["去鐵爐堡大門以北的祕法大廳，你會在那兒受到魔法訓練的。朱莉·雷線總是在那兒埋頭苦讀。"] = "7e98ceebc9414083a4cc3fb3ae42f394",
            ["呸！郵箱……最近我收到的全都是垃圾郵件！  增加這個的尺寸……減少那個的尺寸……現在是免費的屠龍劍。我得每隔一個月就要更改郵箱號碼才行！  嗯，你可別說我沒警告過你。郵箱就在石火旅店外面。"] = "cc8d5bdde66d34c96aeda15e29b244e5",
            ["哦！$g小夥子:姑娘;，當你選擇附魔時，你得非常小心。我讓自己的杯子附魔，使杯中的水不灑出一滴，但是我也不能喝到裡面的水了！這真是個悲劇。  當你看到吉布時，一定要記得我的叮囑。他在大鍛爐獅鷲獸管理員右邊的商店中。"] = "5906a29765d2173d53b9ab776005d62b",
            ["哦！你想接受戰士的訓練，是嗎？克斯塔姆·碎石會幫你實現夢想的！去鐵爐堡東門的武器大廳吧。"] = "740a72f70d8805a7b803e0d29dbe0d05",
            ["哦！達瑞爾·瑞克努索是個技藝高超的廚師！他的紅辣椒如此辛辣，幾乎可以鍛造鋼鐵了！我想他不會將菜譜傳給你的，但是他肯定能幫助你成為一名好廚師。你可以在大鍛爐東北角的銅壺鐵罐那找到他。"] = "5a9c20e893c2fd018c67b13bea773ae2",
            ["哦，你想學習採摘雛菊是吧？哈哈！我只是開個玩笑，$g小夥子:姑娘;。  這是個很好的職業，雷納·石枝會教你的。她在大鍛爐南邊的 鐵爐堡醫師協會工作。"] = "9ba6396c2f8ca0fde5f32bf5810ac783",
            ["哦，你是在找賓斯匹德吧。為什麼那個小地精和他的裝備……讓我告訴你吧，如果你想去他在地精區的商店，管好你的手，別去撫摸他的機械綿羊！  爆炸綿羊……為什麼你要做這樣的事情！？"] = "cb4411cf05a5193ed1592cf994d7a1e6",
            ["哦，地鐵，地鐵……每個人都想乘坐地鐵。那些乘坐獅鷲獸的好時光，那種在高空中飛翔時緊握韁繩的情景，它們到哪兒去了？  啊！你還是坐地鐵去吧……地鐵就在地精區，那兒還有地精的其他精妙設計呢。"] = "b6f01b7cfb83b6af6ea28d402cd03b91",
            ["啊，奧特蘭克山谷，我的美好回憶啊。<歎息>嗯，我不能與你同行，但我同樣感到驕傲！你得跟鐵爐堡武器大廳的格羅杜姆·鋼鬚談談。"] = "e06fd55d9c7b155fdb8e8ed8c2d4b286",
            ["啊，布萊納·火崖。她能使用魔法。她主管牧師事務。  你要穿過鐵爐堡大門，向北走，前往祕法大廳。她就在那裡。"] = "59e9a008fc9fe41cf912bf06861683df",
            ["啊，布蘭度爾·鐵錘。毫無疑問，他能為你提供指導，$g小夥子:姑娘;。在鐵爐堡大門以北的祕法大廳中能找到他。"] = "63f213a9fe7d396bded4b0fcdb6f51b1",
            ["啊，沒有什麼比獅鷲獸更好的坐騎了，對吧？夜精靈偏愛角鷹獸，而我還是喜歡乘一隻獅鷲獸穿梭雲端！  好吧，我不跟你嘮叨了，到大鍛爐東邊的格萊斯·瑟登那兒去吧，他會幫你上路的。"] = "cb6734d0257007705c4566a44b980164",
            ["啊，沒有誰比牧師更擅長治療病痛了。當然喝得酩酊大醉也能解除痛苦，但是我想布萊納·火崖並不懂得釀酒。我認為你該在祕法大廳進行一些牧師的培訓。"] = "c813addf44eeb3041f9442747e4f19b7",
            ["啊，要是你想成為一名附魔師的話，我想你需要找吉布·草鬚。他在大鍛爐獅鷲獸管理人右邊的商店草鬚魔法用品店裡。"] = "6e1942115134fa4728a8bd01469f0ee2",
            ["嗯！說到學習採礦的話，你來對地方啦，$g小夥子:姑娘;！吉爾弗拉姆·石趾居住在深山礦工協會。沒有比他更好的老師了。"] = "57c3f67ebbf0020b5e1987aa2869782f",
            ["嗯，你在找哪個戰場？"] = "495cb758f46f91069a540dc47968d5b3",
            ["在阿拉希盆地跟被遺忘者作戰的人類需要你的幫助。去武器大廳找他們的代表杜納爾·奧斯古談談。"] = "a551a630e051c403297c7c5b9ebba84b",
            ["巴爾薩斯·裂石是一名剝皮師，他會教你如何剝皮的。去大鍛爐北邊的皮甲用品店找他吧。"] = "19d7a62aa644748c5d13eaad7341a221",
            ["布蘭度爾·鐵錘就是你想找的人。你可以去鐵爐堡大門以北的祕法大廳找他。"] = "31c78e407d6e78277f84d7122edc2533",
            ["幾天前，我無意中聽雷格努斯·雷石在武器大廳中吹噓他獸穴中的一件新飾品。要是你想成為一名技藝純熟的獵人，就去找他吧。"] = "d93d0f3b1e5ea15a5dd989a27017ef56",
            ["急救是一種有價值的技能。我們的常住的培訓師，尼莎·火石，會教你該怎麼做。到大鍛爐南邊的鐵爐堡醫師協會可以找到她。"] = "aa54bc8510198f4330f29e9a0b3eae00",
            ["急救？但你看起來不像受傷的樣子。如果你真的對學習急救有興趣，那麼就去找尼莎·火石。到鐵爐堡醫師協會去，就在大鍛爐旁邊。"] = "acbd5104f14dbadffa1e4f40e28a6ffd",
            ["想要乘坐獅鷲獸，是嗎？你得去找格萊斯·瑟登。  你可以在鐵爐堡中心的大鍛爐東邊找到他。"] = "818c80ba62a6062182774f0d488d44b8",
            ["我聽格瑞諾爾說他曾經釣起過一柄劍。或者那是一條旗魚？這該死的 格瑞諾爾，他對我講了太多的關於魚的故事，我都分不清了。嗯，你幹嘛不去荒棄的洞穴找他，讓他告訴你那究竟是什麼。"] = "b4e38865182ec7942e86379c3c9fcdf9",
            ["戰歌峽谷？好吧，你應該去跟武器大廳的萊蘭迪斯談一談。"] = "65538115404a72c45137bf80f3f5572c",
            ["所有的盜賊都居住在鐵爐堡以北的荒棄的洞穴。我敢打賭芬斯維克也在那兒，正在數著偷來的錢包中的硬幣呢。我總有一天會抓住他的！  同時，我也會好好看著你的，$g小夥子:姑娘;。"] = "9528aea502ae9f7db96fe57bfe2c7e48",
            ["拍賣場在哪兒？當你進入我們美麗的城市時它就在鐵爐堡大門旁邊。你會在銀行的正對面找到它。"] = "d6e64cdc436665776809311fd999e5cd",
            ["旅館？啊，你是來尋找鐵爐堡出產的美酒的？你該去石火旅店。$B$B如果你在鐵爐堡之外，它就在鐵爐堡大門的左邊；反之，則在大門右邊。"] = "886fa9ce5bf2e50d6df39dca00c5e72c",
            ["是的，每個人都想坐礦道地鐵，那真是酷斃了。嗯，你可以去鐵爐堡大門以東的地精區找礦道地鐵。"] = "e151e5a6629ea4a4c716bafbf9cf9641",
            ["格瑞諾爾·石印會告訴他曾經碰到許多脫鉤的超級大魚，但他仍是附近最好的漁夫之一。他在荒棄的洞穴開有一家叫做旅行漁具店的商店。"] = "0ddcbbb7af1ef15099416e16690edff4",
            ["比克斯和布里維夫的武器沾滿了獸人的鮮血。如果你想學習的話，就去密林武器店找他們吧。"] = "96990add552d311d4fe9f5b1e0e496d4",
            ["沒有什麼地方比鐵爐堡最黑暗的荒棄洞穴那裡更適合尋找那些陰暗的傢伙了。你在那裡肯定會找到瑟斯哈特，就像是召喚一個行徑卑劣的動物去照他的吩咐辦事。"] = "205d885c660f13d010f41ecd69423cc6",
            ["為什麼我們需要這樣的服務？荒棄的洞穴的盜賊霍夫丹·黑鬚已經給我們惹了一大堆麻煩，我是不是還要留意你一下？"] = "36ac17a15ff106629b6c52dbefcd7203",
            ["烏布雷克·火拳總是極其認真地照顧動物。如果你想讓他幫你照看寵物的話，就去武器大廳找他吧，他通常跟那些獵人在一起。"] = "02f503b66aaa06ff7cf2372c215ba1f0",
            ["秘法大廳的法師彬克也許能幫忙解決你的一些魔法需求。  秘法大廳就在鐵爐堡的北部。"] = "8d292d1b067d993333147a509e6e409c",
            ["約莫德·石眉對縫紉有獨到之處，真的。如果你想接受訓練的話，就去大鍛爐北邊的石眉布衣店找他吧。"] = "759b920689d00afab4a880a03c8bd208",
            ["花和種子以及類似的東西？那是雷納·石枝的專業領域。你能在大鍛爐南面的鐵爐堡醫師協會處看到她料理她的植物。"] = "9341074330c1dbc19f8fdf714badbebf",
            ["要建立公會的話是需要相應文件的，喬多·鋼眉能幫助你處理這些程式。如果你都準備好了的話，就去鐵爐堡訪客中心找他吧。"] = "7b31a92e46c77d8643368a8d82916e89",
            ["要是你想組建公會的話，那你首先需要通過鐵爐堡訪客中心的喬多·鋼眉的認同。穿過鐵爐堡大門往東南方向走，你就能找到他。"] = "67bc72e3f75682dc138f1d22ef089d92",
            ["要是你要找旅館的話，石火旅店是個不錯的選擇。若是你前往鐵爐堡的話，會在城門的左邊找到這個旅館；要是在鐵爐堡裡面的話，它就在城門的右邊。$B$B哦，要是你現在就去那裡的話，告訴他們為我準備好啤酒吧。"] = "9678dcc90aee99c0461684dd12aa5a6d",
            ["費布·鋼軸在大鍛爐西北邊開了一家商店。我打賭他能教你學會製作精良的護甲。"] = "e6b5bccb2a9112e11e11306a28cbcb09",
            ["這兒有採礦訓練者嗎？你認為你在哪兒！？  你將在大鍛爐北邊深山採礦公會找到丹莫洛地區最好的礦工。吉爾弗拉姆·石趾將為你展示真正的採礦藝術。"] = "75e0a88cc8fcf68c42a9c9a4f31ea193",
            ["那麼$g小夥子:小姑娘;，你認為你具有在奧特蘭克山谷幫助聯盟抵禦部落的能力？非常好，那麼你一定希望和鐵爐堡的格羅杜姆·鋼鬚談談。你可以在武器大廳的戰略地圖之前找到他。"] = "f0b32b90ead935933c43bb1468fa3f95",
            ["銀行？哦，你是說銀行！說到存儲貴重物品的話，沒有什麼比銀行更安全的地方了。它就在鐵爐堡大門的東北方。"] = "726ce72b8aa754ecf613d9315fa35780",
            ["阿拉索聯軍試圖從被遺忘者手中奪回自己的失地。$n，如果你想要幫助他們的話，就跟武器大廳的杜納爾·奧斯古德談談。"] = "44b04e19a4aa4b719b00c378a9acd900",
        },
        [12997] = {
            ["我名叫蒙提，老鼠是我的玩物。"] = "ca995c7f0f5f79ad1e87335c01749488",
        },
        [13000] = {
            ["我的資料分析師認為這次我們會比上次的紀錄提高二十秒！"] = "29cb9f241b67a6bd58f46757f27f6f9e",
            ["我給我們的車裡安裝了新的矩陣式調節器，它可以使賽車的引擎轉速提高至少百分之十五！"] = "bb2e2ac84fdaea93b4cb5f24ace4d539",
            ["我那兩歲的兒子設計的賽車都比那些可笑的哥布林造出來的破爛跑得更快！"] = "5a9bf6255acd34e980aebcd04a7a6def",
            ["約翰森？我認為他在附近的某個地方……"] = "5d227c61a514e3f0b41f912efe022c52",
            ["膽大的約翰森？我聽說塔頂的部落主科魯克萊德知道他在哪兒。"] = "288dfdbe6b0b08a6f2781e22dc5d8ce0",
            ["要不是哥布林的狗屎運，他們每次都會把車撞進山裡去！"] = "413ec8412f752d13ea7d3bc09e39592d",
            ["這些天提爾斯和他的助手都變得怪怪的。"] = "329639fd7e8c50ac0b798afe6c0f563e",
            ["這種車賽是展現我們高新科技的大好機會！"] = "88d6d4700d0a9435deac731bbef17f8c",
        },
        [13018] = {
            ["你在卡茲莫丹不會找到更好的老鼠肉燒烤店的！"] = "d070931d907bc8487f4f4b1378bf8ea4",
        },
        [13084] = {
            ["嗨！你是來這兒學習新武器的嗎？"] = "aca797c5fc53636876bb9796d70dee29",
            ["密林武器店的矮人武器管理人布里維夫可以教你如何使用拳頭武器、槍、單手斧、雙手斧、單手錘和雙手錘。  暴風城維勒武器店的人類武器管理人吳平可以教你如何使用十字弩、匕首、單手劍、雙手劍、長柄武器和法杖。  達納蘇斯戰士區的夜精靈武器管理人伊琳尼雅·月火  可以教你如何使用弓箭、匕首、拳頭武器、法杖和投擲  武器。"] = "24fbc29bbfa684d547e89fb18cc02719",
        },
        [13177] = {
            ["你想要飛往什麼地方？"] = "f686b3319d4af5004c6ee3403aea3f5e",
        },
        [13220] = {
            ["死者在這片荒地長眠，$c。我們必須小心，別驚動他們。"] = "72d9e590ddf6bf219b208c8b157ddb5c",
        },
        [13283] = {
            ["你看起來像是那種手腳不乾淨的人。有什麼我可以幫忙的嗎？"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["你看起來像是那種手腳不乾淨的傢伙。有什麼我可以幫忙的嗎？"] = "8ad40600a7b98e4dedc4ac4c244156c2",
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
            ["我想你不願意向我學習吧。你最好找個$c訓練師幫助你。"] = "0fac9f50e1fb5c48f7301ce81e131b5f",
            ["我跟你沒什麼好說的，你最好找個$c訓練師來幫助你。"] = "0fac9f50e1fb5c48f7301ce81e131b5f",
        },
        [13320] = {
            ["你是來學習戰役案例的吧？聽好了，我會為你講解那些顯赫的勝仗和恥辱的敗仗的。"] = "1b77224af068edacdc86b986bb6acf01",
        },
        [13417] = {
            ["在嚴格的訓練中，我必須除去那些學生先前所學的所有知識，以便傳授新知識。我所提供的服務越來越難以完成。為此，每次訓練的費用也越來越昂貴。你願意除去你先前學習的技能嗎？"] = "9ccfbeb35c89e4770c3695a5c842eef7",
            ["靈魂引導你來到我這兒。我要怎麼幫你？"] = "d96f407d05286ba207ff46bf75ef4510",
            ["願靈魂與你同在。"] = "1eec7529a102737979dbaf19908f6ac0",
        },
