        },
        [13444] = {
            ["一個神奇的冬幕節……啊……小$G男孩：女孩；。好孩子在燻木牧場當地的任何小賣部都有特別的，嗯，折扣。真棒。"] = "d521f35e8a2bb45f7ecec0bd6763edf2",
            ["不……你不能坐在我的膝蓋上，$g夥計:女士。"] = "d182853c15566b0e4b66ef86169f2b6a",
            ["是的，當然，去告訴冬天爺爺你都想從這個冬幕中得到什麼。$B$B趕緊些。"] = "a7303a484bddb8b02ffecc928c1f55f0",
            ["這輪結束後冬天爺爺會做什麼呢，我有一個很好的主意。我在包包裡有一瓶冬幕啤酒，而且我想喝光它。"] = "56e883add54dbdeee15af3096f46347a",
        },
        [13445] = {
            ["一個神奇的冬幕節……啊……小$G男孩：女孩；。好孩子在燻木牧場當地的任何小賣部都有特別的，嗯，折扣。真棒。"] = "565d707d3fae5619e5efa2bca426483b",
            ["不……你不能坐在我的膝蓋上，$g夥計:女士。"] = "66f90f5438555127b635f6c18ceba9ca",
            ["是的，當然，去告訴冬天爺爺你都想從這個冬幕中得到什麼。$B$B趕緊些。"] = "27687c305eeec6bfe1d1872f537fa192",
            ["這輪結束後冬天爺爺會做什麼呢，我有一個很好的主意。我在包包裡有一瓶冬幕啤酒，而且我想喝光它。"] = "0a5fc9eb27704fbbe32ca289b8ccbc8c",
        },
        [13447] = {
            ["$N，在戰場上看到你這樣經驗豐富的傢伙真好！很抱歉，我們軍隊的物資過低，無法發動對部落的大規模地面攻擊。$B$B跟我們的軍需官談談，他會給你供給任務的。"] = "be7b74ece350a6df351c868dce888f81",
        },
        [13616] = {
            ["士兵，你好。你是來幫我的嗎？"] = "b39eb5c882dee150f724b5b3066bf272",
            ["士兵，做得好。我們的馬廄將塞滿騎兵們的戰鬥坐騎！"] = "28607f3a0d29a8585b7a800ababa8406",
        },
        [13617] = {
            ["再有一些坐騎我們的馬廄就滿啦。士兵，讓我來保管它們吧。我會從這兒牽走一些。"] = "6f240a341cad715c1ce2f4322f7f0c15",
            ["奧特蘭克本地出產的山羊對我們的騎兵至關重要！"] = "089e884fad1004ecb78852e5b6c1ed36",
        },
        [13776] = {
            ["你是來學習的，嗯？我或許有些事情可以給你做。"] = "832d7cd84aaed062179a1a03bf687405",
        },
        [13777] = {
            ["<雷矛中士向你敬了個禮。>$B$B姓名，軍階和編號，士兵！這是你唯一需要提供給那些骯髒的霜狼走狗的資訊！"] = "91ec0e39bf7d8d69df78d4e9d0d5607c",
        },
        [13840] = {
            ["我負責霜狼氏族的軍隊招募工作。作為一名霜狼士兵，如果你的等級足夠高的話，就來向我報到吧。$B$B在冰冷的戰場上，你會獲得榮譽和尊重的。"] = "ce047d2a3dd6d9e301b393ee2954c796",
        },
        [13841] = {
            ["你好，$r！我是哈格丁中尉，是負責招募雷矛衛兵的官員。$B$B你在雷矛軍隊中獲得一定的威望後再來找我吧，我會升級你的徽章的。如果你丟失了徽章，我也能再給你一枚。"] = "3df9d5b384b97d45f30cd9ba4c8d25a8",
        },
        [14347] = {
            ["<德米提恩笑道。>$B$B愚蠢的傢伙，你的獎勵就是痛苦地死去吧！"] = "c6c892dcc9a95f0b111608dfcf84c37b",
            ["<德米提恩跪倒在地。>$B$B你已經找回了主人的永久牢籠！$B$B我期待這一天已經很久很久了，我的願望終於實現了。$B$B必須解放我的主人！"] = "c7d0d5f0497c7bbd94f17ecb262de67c",
            ["他們龐大的身軀在多年的戰亂中漸漸衰弱，被禁錮在地下世界——他們自己創造的地下世界中——墮落的泰坦締造者能滲透地表，污辱古老的神靈。$B$B兄弟反目。一場持續五千年的戰爭在世界的核心展開。"] = "c3df5cd0dcec466f8c0f5df4b18f5778",
            ["很久以前，在篡位者稱為創世之年代的時候，我的主人和他的同胞們統治著整個世界。是他們，是遠古的神靈創造了一切。$B$B他們最終被那些稱他們為締造者的傢伙推翻了。"] = "c09678227a9af6c89356887b10213442",
            ["必須摧毀拉格納羅斯的肉身。在屍體殘骸中將出現他的精華。在這個虛弱時期，被關押在桑德蘭監獄中的拉格納羅斯的護手將被釋放。精華本身就是鑰匙……"] = "367f05e456b6a76006091647e119a824",
            ["必須用源質來對複生之瓶進行加固。我只知道這種礦物的一種原料：位於世界核心的元素神域。$B$B塑地者對這種東西的瞭解比我多得多。你必須找到塑地者！"] = "df4e9cd871fca0c53d2e4b158280e34f",
            ["我有他的重生之瓶。一旦你準備接受這項任務，你必須保護好這個小瓶，要擺脫拉格納羅斯的控制！"] = "0ba174f63cc2f24d23e0cfd845eb7767",
            ["我知道很多，好好聽著吧，$r。"] = "7624b1b9032ec89ab17724443dfdadf7",
            ["拉格納羅斯、迦頓和加爾背叛了我的領主。桑德蘭王子在毫不知情的情況下被捕了。"] = "95a34dbc84fe0dbe175240f3ab72667f",
            ["桑德蘭王子對火焰之王的進攻毫不知情。在王子做出反應之前，傳說中拉格納羅斯使用的大錘薩弗拉斯就會無情地痛擊王子。桑德蘭倒下了，他完全被打敗了。$B$B火焰之王吸取了王子的精華，但這仍然不能滿足他的貪欲。"] = "e102fa0f9aa47c2f42746046e41a2b68",
            ["桑德蘭的精華的些許殘留物存儲在元素綁定護符中。拉格納羅斯將護符打碎成兩塊，分給了他的兩名士官……"] = "7c45d7a2e7d8583c1a973293c5feecd4",
            ["火焰之王拉格納羅斯在元素大災變中想要殺死我的主人桑德蘭，空氣的王子。$B$B<德米提恩低下頭，面部肌肉因憤怒而扭曲。>$B$B一旦你說出他的名字，我就會用你的內臟裝點這座被破壞的營帳。保持安靜，聽好了。"] = "3c68b84890ff85616d98587fcb79722c",
            ["看看這片被蹂躪的土地，你就知道元素的力量了，$r。"] = "c249a2eaed40f813e602ee17f9452029",
        },
        [14358] = {
            ["你所見到的那些在埃德薩拉斯的庭院和城牆附近遊蕩的高等精靈靈魂不是被戈多克巨魔或薩特所殺，而是死於王子之手！"] = "cfd3885a86b7bc793e61d415369d4a5b",
            ["你知道高等精靈嗎？你知道辛德拉古嗎？"] = "a2c774e84977d54bfaa18464053d8daa",
            ["汲取的能量能維持上層精神的魔力，使埃德薩拉斯的人民滿足他們對魔法無盡而持續增長的渴求。$B$B數千年過去了，用於監禁惡魔伊莫塔爾以及維繫埃德薩拉斯人民生命的力量開始減弱。監禁惡魔所需的魔法就要超過所能汲取的魔法。曾經的能量機制已經不復存在。"] = "deb78aef7ba1da9f9ee7748755557359",
            ["王子為了獲得永恆的生命和無盡的力量，殺死了許多人。曾經在數千人中分配的力量現在全部彙集到王子和辛德拉狂熱者身上。那些少數的倖存者不停地向水晶塔輸送能量來禁錮惡魔Immol'thar。$B$B一旦惡魔掙脫束縛，他一定會毀掉這片曾經繁榮的祕法之地。"] = "6aef1308be672c7e59f0132f5147cc61",
            ["王子策劃將擁有巨大力量的惡魔伊莫塔爾禁錮到一個巨大的力場中。水晶塔能將潛在的能量彙集到這個力場中。$B$B一旦被囚禁，惡魔將成為埃德薩拉斯人民的能量來源。"] = "e087723e4de9c3a7afc0a6f3ff26dd25",
            ["辛德拉古是艾薩拉女王最器重的祕法學家。女王最重要的物品都在這些高大的城牆內秘密製造完成。$B$B永恆之井被破壞後，高等精靈陷入渾渾噩噩的境地，一支較小的夜精靈氏族，埃德薩拉斯的王子托塞德林開始建造水晶塔，你可以在西側的城牆那兒看到那些分散在各處的水晶塔。"] = "6f0489b12a5ec110544130f0413137f8",
            ["陌生人，離開這兒吧，免得送命，它會吃掉它接觸到的一切東西的。"] = "7c332deda31bef9904009677b9d72a0d",
        },
        [14368] = {
            ["你必須明白，像我這樣活了一萬年的人，對生命有獨特的看法。現在你經受的考驗和磨難都是毫無意義的。"] = "6c366d266feb0eb999723d20a1d0371f",
            ["哦，年輕的主人製造的這一系列事件和慌亂。可以想像，世界的命運就掌控在他手中。只有人類才會對世界產生這種扭曲的看法。$B$B唉，他將祕法的秘密都告訴了我……聖契之類的無用之物。這種東西對我來說是一無是處，但是或許你對它們感興趣。"] = "33e9252b9e79f5d50346fb17553ee92a",
        },
        [14369] = {
            ["博學者是個古老的學者。他為我們偉大的女王服務！"] = "1bb37b5e2ce5b14590bd6d1f7ea818fa",
            ["我們可不能惹惱了他。他發起火來就沒有節制啦。"] = "4977781f15c9e77ab5e0dab144648ba9",
            ["我猜想那些小鬼在偷學知識。"] = "de92e3bf1b00e122ea4b943635de2b3a",
            ["最近書本丟失甚多。博學者和他的助手非常惱怒。他們懷疑在埃德薩拉斯有人妄圖不軌。"] = "9a159099d974832b62617bee56187359",
            ["王子不再講述灰燼之劍的故事了嗎？在他的故事中，我們最喜歡這個啦。他的愛好則是追隨灰燼之劍。當然，沒人能從他口中得知那個故事。"] = "0b91ae5b7eee6652c2cec68b923afa45",
            ["王子對奈法利安的巢穴非常感興趣。如果有誰能殺死巨龍及其屬下，並將戰鬥經過告訴王子，我敢打賭王子會非常滿意的。必須找到灰燼之劍！"] = "c1dcc591d8d16fba46b238ec1612e330",
            ["許多人來到這個避難所，少數人卻離開了。"] = "c4c85ae4efc99586586ab345d2d67fe2",
            ["陌生人，把你的聲音放小一點。你不是想打擾主人的沉思吧。"] = "d5151f42961aedaf4038bdc6a60aa9f2",
        },
        [14374] = {
            ["哦，真恐怖！這是個悲劇！我們就要突破啦，但也有可能遭遇全軍覆滅的慘劇。"] = "5fc4f209b2ef0137dc307256ecdd2a18",
        },
        [14381] = {
            ["擁有萬年曆史的知識卷軸將那些邪惡的傢伙吸引到圖書館。大量的書籍被盜，被找回之後再次被盜。"] = "cb6c6ca44638e05ae54e29542e26f374",
        },
        [14382] = {
            ["基爾達斯總是過分誇大。比如，「迦羅娜：潛行與詭計研究」已經被偷過400多次啦。$B$B雅典娜神廟的標誌保護著這本卷軸，防止任何人偷看。"] = "805f962da2b80257710186ac78724c01",
        },
        [14383] = {
            ["被偷啦，$r！我們最珍貴的三卷卷軸。如果你能找回來的話，一定會得到豐厚的報酬的。"] = "e5bc2020af21f8dc760efcc4b9b1641e",
        },
        [14392] = {
            ["我當然是來傳達酋長的命令的。我是部落的。"] = "9f1fc0f188303aa506b43d5e4203e697",
            ["盯著敵人，$r。看吧，強大的部落足以對付巨龍！所有跟我們做對的人都是這種下場！"] = "e84dc958c4a38bb68b73f260ddc8edec",
        },
        [14394] = {
            ["我活著就是為了為國王服務。"] = "9256c8087a9343192abe0385ab00858c",
            ["或許有一天，你對聯盟的貢獻會跟你今日所見的英雄一樣偉大。尊重英雄吧，$n。"] = "160d134552454e27460514c6f0827eab",
        },
        [14436] = {
            ["我們陷入生存危機。我們陷入困境，尋找答案，希望在黑暗中閃閃發光。$B$B那時，$n，就是我們邁向自由的第一步。"] = "5842c6675f139b38423a41749960a522",
        },
        [14437] = {
            ["你有蜘蛛或是甲蟲嗎，$C？它們速度快，但是如果你的速度更快的話，你會發現擁有它們是件樂事！"] = "767f180e80a535e7f390f3d311039337",
        },
        [14450] = {
            ["戰爭是有代價的，$c……這種代價常常被我們忽略。艾澤拉斯大地衝突迭起，到處都是失去雙親的孤兒。那些無家可歸的孤兒沒有別的地方可去，他們通常在這兒成長，到了自力更生的年齡才離開。$B$B聯盟將春季的某一週設為兒童週，為這些無辜的孩子贈送物品。"] = "9452bcf77b2d46636d57c6303688913f",
        },
        [14451] = {
            ["戰爭是有代價的，$c……這種代價常常被我們忽略。艾澤拉斯大地衝突迭起，到處都是失去雙親的孤兒。那些無家可歸的孤兒沒有別的地方可去，他們通常在這兒成長，到了自力更生的年齡才離開。$B$B部落將春季的某一週設為兒童週，為這些無辜的孩子贈送物品。"] = "a004a2e73880cb6882c600c406454b14",
        },
        [14463] = {
            ["你離家還遠著呢，$r。"] = "be880edf442fc7e0b0b1b9c84872c4c9",
        },
        [14469] = {
            ["別打斷我，你這個傻子！我會將你身上的肉刮下來，把你骨頭當作衣架。我在哪兒？哦，是的，克羅蘇斯的存活時間是普通地獄火的10倍。我不知道為什麼會這樣，但是我想通過足夠的研究，我會查明真相的。$B$B你得幫我找到克羅蘇斯的炎魔之心。"] = "71cbe27cb3eb26c72fce94d8e5036a76",
            ["卑微的傢伙，在我面前鞠躬吧！你能感受到我那強大的力量。"] = "283fc5c382b274b565983a110dfbcccc",
            ["在這座營地的東北面有一個名叫克羅蘇斯的強大的地獄火。這就是尼比 在這兒的原因。克羅蘇斯極其強大，前所未聞。小子，看吧，地域火以極大的速度墜落地面，但是生命卻很短暫。一旦火焰熄滅，地域火便崩潰了。"] = "1d846f3de3583986c12a82cbfed8b313",
            ["要想我教你召喚地獄火僕從，你必須殺死克羅蘇斯並從他燃燒的屍體中取出地獄火之心交給我。但是這項任務並不簡單。克羅蘇斯幾乎已經燒盡了。你必須重新點燃他的屍體，令他復活。你必須從其他惡魔那兒收集一些東西才能令他復活。$B$B我的孩子，準備上路吧。"] = "0f171e609c3286086cdc7254621214ab",
            ["這麼說，你是來找尼比學習如果從虛空中召喚地域火僕從的。$B$B肅靜！尼比什麼都知道！$B$B他可不會這麼輕易地將知識傳授給你。首先，你必須幫助尼比完成一項至關重要的任務。"] = "35284cfba5849c0b76c8dffde030b428",
        },
        [14494] = {
            ["<伊利斯點著頭。>$B$B那隻眼睛見證了許多恐怖和驚奇的事情。$B$B它會顯現出最適合注視者觀看的場景。"] = "ea4195ca47ef46305b7808f45ac77cdc",
            ["你必須完成我未做完的事情：保護逃離斯坦索姆的農夫。$B$B他們會走向光明，而你必須確保他們的安全。要是死去的人數量過多，我們將繼續生活在詛咒之下——你的任務也會失敗。$B$B這項任務將檢驗你學到的所有技能和法術。願光明保佑你，$N。"] = "6909641eaf442f591b64fd93dc501770",
            ["你知道你會的，$N。$B$B我也是一名女牧師，跟你不同的是，我已辭世多年。但是我的靈魂仍停留在此，跟這兒的數千靈魂一樣，我們是被瘋狂的阿薩斯·米納希爾王子和他的亡靈軍團殘忍殺害的。"] = "25632e7eb38d445fde6b26396d16d87d",
            ["我可沒說你是到這兒來救贖你自己的，$g牧師:女牧師;。你是來解救我和那些在試圖逃離斯坦索姆時喪命的無辜者的。$B$B我和那些無辜者的靈魂受到詛咒，被綁定在這兒忍受無盡的悲劇輪回。"] = "bb679b37c4c78f1616884c32f720a75d",
            ["是的。眼睛絕不會弄錯的。$B$B畢竟，你是一名$g牧師:女牧師;。如果眼睛中顯現處這段恐怖的記憶，你會是一名強大的$g牧師:女牧師;。$B$B你是來救贖的，但是你甚至還沒有意識到這一點……是嗎？"] = "39cfa2183772f467fc19e87da36d78a9",
            ["讚揚聖光，終於有人對召喚做出回應啦。"] = "39d90b0020ac23a8583fafa6411a8ed8",
        },
        [14508] = {
            ["啊！沒有比看人們在競技場中互相廝殺更好看的東西了。如果你來得是時候的話，那你也將是他們中的一員！"] = "25938481b6c048114f6758db91eca1de",
        },
        [14522] = {
            ["加德納爾行事隱晦奸詐。你在這兒幹什麼呢，$C，你的靈魂被敵人禁錮在此的……"] = "c0f2b93ae2639e64818da8383aafef89",
        },
        [14523] = {
            ["什麼？但是怎麼做呢？不！這不可能！我已經很小心了……他不可能知道的！$B$B你撒謊！你撒謊，你欺騙了我，去死吧！"] = "0895ca3a8270e33abe5027f593574c7e",
            ["來自貝恩霍勒的消息？是什麼消息？他需要偉大的導師和僕人Ulathek嗎？他需要我嗎？"] = "d02f8235c277c2ac91b7975819950acb",
            ["滾！我在跟恐懼魔王商量要事，我們討論的事情與你無關！"] = "09af5cd652b4864bff857c89022d0037",
        },
        [14531] = {
            ["在這麼偏遠的地方遇到人可真好啊。來吧，跟我一起。讓我們用身體互相取暖。"] = "592e299bd0edf1ea20bdb5dabf705526",
        },
        [14536] = {
            ["每年的這個時候我都會來希利蘇斯。這裡的氣候對治療我的拇指囊腫很有幫助。$B$B你應該跟我四處逛逛，朋友。欣賞一下風景什麼的。"] = "5e0b696d989d9f556038cd140846f661",
        },
        [14624] = {
            ["你已經完成我要求你做的事情，$N。我這裡沒有什麼需要你做的了。如果你想繼續為瑟銀兄弟會服務的話，和黑石深淵的黑鐵酒吧的羅克圖斯·暗契談談。$B$B再見！"] = "bff732f0c9b0a483ea8280c43a9f40de",
            ["博恩奈特是我的名字，我把鐵匠作為我的興趣……另外，呃……我還賣一些食物和水。來點肉類怎麼樣？"] = "cf73090a6937f1713ac6d2eb671f2040",
        },
        [14626] = {
            ["作為駐紮在這裡的現任工作管理員，我的職責就是確保在這裡所進行的所有事情，工作，休息和放鬆都包含一定令人厭煩的成分。$B$B如果你發現某件你被要求做的事情過於簡單或者沒有什麼好抱怨的話，請立即向我報告。"] = "793ee16511d200a9b8cd0eb76fa5bc51",
        },
        [14627] = {
            ["當洛洛爾不想撒掉他寶貴的酒或者弄髒他衣服的時候，我就被召喚而來。是的。漢瑟爾就是別人口中正義和痛苦的結合體。"] = "bd3faf4cde31a3db3276cfa61a84692d",
        },
        [14628] = {
            ["我們選擇了離開黑石深淵的保護和安居之所來進行探險……呃，我是說……嗯，我們這麼做是對的，我們要探索整個世界。"] = "26996ccc4e6778d1800c2c92dd4dc550",
        },
        [14634] = {
            ["是的，那是真的，我好像一隻蝙蝠一樣瞎了！而且還醉得……呃，醉得好像喝了很多酒。$B$B我會告訴這個感受的，$r。是酒讓我感覺靈敏。人人都知道如果你喪失了一種感覺，那麼另外一個感覺會變得更加靈敏。我的飲酒感覺這兩天非常靈敏。"] = "7dbd9d808230424267a5e8139bdbae10",
        },
        [14637] = {
            ["也許這裡不是最好的開店的地方……"] = "4878b6fdc757a0fa6ec3fdc0bd2136fd",
            ["很高興再見到你，$N！我不知道我還可以堅持多久來創建這樣一個店。現在，由於你對我的幫助，我會給你看一些你會感興趣的東西！"] = "35ce1445970071ba504febea09ce9bc3",
        },
        [14720] = {
            ["我是監查他們的人。我是懲罰之拳。我來鎮壓反抗。你敢挑釁酋長？那你敢不敢面對我無情的審判？"] = "ed0691b342e85f8155b2545fa09aff4c",
            ["看看這條被幹掉的龍的臉，$r。部落的強大是毋庸置疑的！"] = "5d36ebec7ba87ea72d8bc75fa1708950",
        },
        [14721] = {
            ["快點離開，市民。沒有什麼好看的。"] = "44f7bf8eff87d3a469dce6889fc22ef9",
            ["黑石領主從灰燼中升起！"] = "aa0728703583d7c72b23dd2cc8c351cc",
        },
        [14722] = {
            ["朋友——暴風城需要你的協助和慷慨解囊！$B$B我們曾經儲藏豐富的布料已經所剩不多了。暴風城現在需要大量的布料和繃帶！你的捐贈將能夠幫助暴風城度過難關，你還能贏得我們對你的尊重！"] = "57a0cf3e383340429113af3746750413",
        },
        [14723] = {
            ["啊，你！如果你想要贏得鐵爐堡矮人的尊重，那麼你可以開始為我們捐贈有價值的資源！鐵爐堡現在的布料和繃帶的存儲量很低！$B$B你可以捐贈各種你在冒險中得到的布料！這樣做你可以贏得鐵爐堡矮人對你的尊重中！"] = "c798a1ce537b25ff52e8a52d1ed3af2a",
        },
        [14724] = {
            ["諾姆瑞根的流亡者需要大量的布料資源！也許你可以幫幫我們，是不是？$B$B把你多餘的布料資源帶給我們。通過捐獻它們，你可以獲得所有地精的尊重。這是金錢無法換的的！好吧，布料可以幫助我們，但是它們意義絕不限於這些……"] = "6b524e6f63821d7aa775800797480d02",
        },
        [14725] = {
            ["嘿，朋友——請等一下，如果可以的話……$B$B我們在重建泰達希爾的過程中經歷了很多的痛苦。現在，我們不僅要忍受這些痛苦，而且我們還發現我們的布料存儲已經很少了。如果你有多餘的布料，那我希望你可以捐贈出它們。你一定因為幫助夜精靈贏得我們的尊重！"] = "f1bba8b8fe977e9469a2a2d8535cd5bc",
        },
        [14726] = {
            ["在這個艱難的時期，捐贈布料對於那些不幸的人是非常重要的幫助手段。布料還可以製作裝備和繃帶——這對於戰爭十分重要！$B$B如果你想要為奧格瑪的獸人捐贈布料的話，我會欣然接受它們，你一定會收到我們的親睞。$B$B為了部落！"] = "8c358b35413bf96fe889092366c26195",
        },
        [14727] = {
            ["啊，你！如果你想要贏得暗矛的尊重，那你可以向我們捐贈那些繼續的資源！你要知道，布料和繃帶不會從樹上長出來。$B$B我們需要你在冒險中得到的那些布料，把它們捐給我們吧！這樣你就可以得到暗矛部族的親睞！"] = "fcd9c2164c91cf223aef5987fbacf8ff",
        },
        [14728] = {
            ["嘿，$g兄弟:姐妹;……我希望可以打擾你一下，如果可以的話。$B$B我們在通過試煉和進行家園重建中經歷了很多。我們現在極度缺乏布料。如果你有一些多餘的話，我希望你可以捐獻給我們。你一定會為此贏得所有牛頭人的尊重的！"] = "804dac15ce73451780e4cf2e731b64fd",
        },
        [14729] = {
            ["就是你……在這迫切的時期是你幫助被遺忘者最好的時機。好好聽著，我不喜歡重複我說過的話。$B$B我們現在極度缺乏布料。繃帶和任何布料儲存量都很低，我們希望接受捐贈來補充庫存。你的捐贈不會有任何經濟補償——這就是捐贈的含義——你的捐贈一定會為我們所賞識。"] = "142f4365ed15cdab171cacd75afb66fc",
        },
        [14733] = {
            ["戰歌峽谷一役至關重要，我們必須獲勝。我們為了榮譽和國家而戰，獸人或是那些誤入歧途的盟友是無法打敗我們的！"] = "9701a4e7da22327ecb2b934e24b01980",
        },
        [14736] = {
            ["歡迎來到惡齒村，陌生人。我是族長托塔斯克，惡齒食人妖的領袖。"] = "b92a5565a1763e2abf60f5aa437da0c0",
        },
        [14737] = {
            ["如果它壞了，那麼斯拉提可以修理它！"] = "51031711691097d768356cfcd57947ae",
        },
        [14738] = {
            ["我這裡有你所需要的所有烹飪材料，夥計！"] = "c7327c44d6426ff5c6df14952cdcd98e",
        },
        [14739] = {
            ["我出售各種奢靡的貨物和商品，陌生人。"] = "bb2054685b1a042e53a7a2362476274c",
        },
        [14740] = {
            ["釣魚只是為了娛樂，夥計。你知道嗎？我是在向我的導師學習，世界上最偉大的釣魚者——納特·帕格。你聽說他沒有，夥計？$B$B如果你想要尋求啟迪，那麼納特·帕格會指引你前進的道路。"] = "3972c43d4381083fbd6f3734c680f4f3",
        },
        [14741] = {
            ["祖爾金有一天會回來的，$r。記住我的話。在那一天到來之前，我們會守住我們的位置並保護森林食人妖的數量。$B$B作為惡齒村的獵人頭領，我的責任就是保證我們的安全。$B$B我對這個區域周圍的野獸都要進行監控。$B$B你是不是來找些活幹的？"] = "a045bbb3ca0c9722e39090c24a9c5d87",
        },
        [14742] = {
            ["很高興有工程師能勇敢地製作這個裝置。我們哥布林工程師對於危險只會抱以大笑！"] = "8f5aefe9123fb8887c7b7bb32250448a",
            ["我剛剛完成了一次新的空間爆破，用它我可以變成最最富有的人，我做夢都無法夢到的富有程度！我所需要的就是找到一個熟練的哥布林工程師來製作一個空間撕裂器，然後將兩者連接起來！"] = "0c3633a7d4f6e9b798ba0e339ff2765c",
            ["這個機器所依據的理論就是通過一次大爆破將你完全摧毀，然後把你的粒子通過空間裂隙傳送到某個地點，再通過反爆破模塊將你在目的地重組。這是即時的傳送！它並不是百分之百有效的，但是你是個傑出的哥布林工程師！如果你把性命看得比發明創造更重要，那麼你永遠都無法成為一個真正的哥布林工程師！ 這是製作空間撕裂器所需的圖紙，你一定要試試看！"] = "dfd0c3400fd8ac2bb161ce6bba353f92",
        },
        [14743] = {
            ["一旦你建造了這個裝置，你就將被傳送到可愛的加基森！幾乎使用這個裝置的人都發現在其立即到達了這裡！$B$B有報告說，有別人試圖用一種壞的版本來替換我們的產品，但是我相信我們不久之後就可以解決這個問題……"] = "e8a1eedcacd3813cfc32fd8b1ec97266",
            ["如果你有辦法趕緊這個裝置，那就讓我們知道！"] = "34aa769372e7eb86724070a5f14c6f0a",
            ["通過在諾姆瑞根中的危險探險，我找到了製作一種偉大發明的方法：物質傳送器！我所需要的就是一個熟練的地精工程師，讓他製造一個信標連接在這個傳送器上。"] = "31e604263a5a40b23254a6b2433c24d0",
        },
        [14753] = {
            ["願夜之祝福永遠與你同在，我的朋友！我是艾蒂爾·月火，我是梣谷銀翼哨兵部隊的軍需官。隨著你在銀翼哨兵中的聲望不斷提升，我可以為你提供一些可在戰歌峽谷中使用的商品。如果你需要修理裝備的話，我也可以提供這樣的服務。"] = "195812b7e9f6837cc257437efd0f0dfd",
        },
        [14754] = {
            ["嘖嘖，我的朋友！我是哈古斯，戰歌偵察騎兵的主要供給商。隨著你在戰歌氏族中的地位不斷提升，我可以提供一些你可以在戰歌峽谷中使用的商品。如果你需要修理裝備的話，我也可以提供這樣的服務。"] = "f1ff3e9bb320c7a47da450367bb0e839",
        },
        [14757] = {
            ["拿到鑰匙，打開這些鎖鏈！鑰匙在守護者希坦亞手裡……就在洞的後面……"] = "927544d8493b455ed768889c4e29afa3",
        },
        [14781] = {
            ["要保護部落在梣谷的木材收集工作並不容易，但是我們從不畏懼戰鬥！夜精靈和他們的盟友必將失敗！"] = "79b85c8b9c23c4e542b6d52221827c9e",
        },
        [14823] = {
            ["你好！我的朋友，歡迎來到艾澤拉斯大陸上最偉大的博覽會！$B$B請往前走並享受我們所提供的一切。讓暗月馬戲團在這個巨大而神秘的世界上所發現的奇特事物為你帶來前所未有的驚奇！我們不收取任何費用，我們為你帶來無限驚喜，為孩子們帶來讓他們興奮的東西！"] = "bcc4137261fe1b6312ba537a58e54584",
        },
        [14828] = {
            ["票券兌換處在這兒！將你的票券兌換成獎品！趕快來吧！"] = "41e1418f674fe4ab79111719d0059787",
        },
        [14829] = {
            ["歡迎！歡迎來到亞布·尼比蓋爾的暗月珍奇館－－各種傳奇生物跟神秘物品的大集合！請盡情的參觀，朋友！$B$B但是請注意你的手摸到的東西！神聖的神器和可怕的野獸守護著這些展品！它們可能會燒掉過度好奇的參觀者那些討厭的手……"] = "7b6f88d5a16eec48ed71f32561eef2a6",
        },
        [14832] = {
            ["$N，很高興再次見到你！你玩得開心嗎？$B$B想要來比腕力嗎？不，當然不……你還想保有自己的手臂吧！"] = "c8136cab467bcb9f94304a861482c25d",
        },
        [14833] = {
            ["你好。我是克洛諾斯－－過目不忘的克洛諾斯。我的記憶力毫無瑕疵，而且連最微小的細節都記得一清二楚。$B$B相信我。"] = "26f2988f1c71f43761398daa16273de5",
        },
        [14841] = {
            ["你好！歡迎你！恐怕我的攤位還不能開張……有很多東西得修理……$B$B但是我仍然受制於血的詛咒，求你啦，笑一笑吧。如果你的臉上沒有笑容的話，我就得砍下我的手，並且在手掌再生之前不得食用任何肉類……"] = "dcf71fd938957989dca86c245fa95f64",
        },
        [14842] = {
            ["來吧！暗月馬戲團正式開始營業！記得來看全艾澤拉斯最刺激的表演！"] = "87545a17514f8d22ebc68ca9371a6f4f",
            ["暗月馬戲團來了！所有的孩子都可以在這裡找到好玩的東西！來吧，都來吧！"] = "8fe8aeb15ebe0e19bcdc798116ff01d4",
            ["暗月馬戲團來的時候一定要仔細的將所有的奇景都盡收眼底喔！"] = "8a8be9fb7609607a2a73503280292819",
            ["暗月馬戲團到艾爾文森林來了，就在閃金鎮的南邊。走過路過不要錯過！"] = "a3b2f7b279774ca4d85f4efbcc996fb0",
            ["暗月馬戲團到莫高雷的金色平原來了，就在雷霆崖的西南邊。走過路過不要錯過！"] = "7ad0b94ce2fae67cd34a632af8cd35cb",
            ["暗月馬戲團只會停留有限的時間。一定要在今天來看啊！"] = "864aaa5f97ede0b83eddc24aeea8facb",
