            ["暗月馬戲團在莫高雷開張的時候，我們會在雷霆崖的西南方搭建我們的帳棚！"] = "9be3351865c169e03d2d409a8d522ad0",
            ["暗月馬戲團已經來到鎮上了！不要錯過有史以來最華麗的表演！"] = "3aa015524426a84e50f001c38fa67af3",
            ["暗月馬戲團已經到鎮上了！走過路過不要錯過！"] = "0b8c021e068c941cfeacca0fdc06342d",
            ["男孩們女孩們－－所有的孩子們－－暗月馬戲團來了！哈哈！"] = "b4715bed2d4172b99afe64138b478e15",
            ["靠過來仔細聆聽整個艾澤拉斯大陸上最盛大的集會－－暗月馬戲團！哈哈！"] = "6d6ca23ecd5ae25cef66ba84f4d8acb5",
        },
        [14843] = {
