            ["暗月馬戲團只會停留有限的時間。一定要在今天來看啊！"] = "fc119632bedc0d61db36da2ac955a910",
            ["暗月馬戲團在艾爾文森林開張的時候，我們會在閃金鎮的南方搭建我們的帳棚！"] = "6846798e3704084cbf990bb534e12271",
            ["暗月馬戲團在莫高雷開張的時候，我們會在雷霆崖的西南方搭建我們的帳棚！"] = "1a25e293039b93cebbb2befb5b4159a9",
            ["暗月馬戲團已經來到鎮上了！不要錯過有史以來最刺激的表演！"] = "970860b74643126c14b1fc1d64669290",
            ["暗月馬戲團已經到鎮上了！走過路過不要錯過！"] = "64ed669f2c530fdee40a973f494727e3",
            ["男孩們女孩們－－所有的孩子們－－暗月馬戲團來了！哈哈！"] = "a61a6fccbff7a04c5809455eb91308ce",
            ["靠過來仔細聆聽整個艾澤拉斯大陸上最盛大的集會－－暗月馬戲團！哈哈！"] = "5a260aa92b38ae89795e971a54fac630",
        },
        [14844] = {
            ["出售好喝的飲料喔！用暗月馬戲團最高級的酒來舒緩你的渴望吧！"] = "3999eb39e5a6b4a8ebbe3d52dc37db02",
            ["別害羞，請這兒的每個人喝上一杯吧！"] = "05dd55fc3499fcacc3e60a02e7dbbfe6",
            ["剛做好的……另一批的暗月特調。趕快來吧，它們很快會被搶光的！"] = "a1cdb9f0073b916776c053aaf793a2bb",
            ["小費永遠不嫌多的，朋友。"] = "7fb4098049b4c3596d12b8795d24c345",
        },
        [14845] = {
            ["你有錢，我們有食物。你還在等什麼？！"] = "9719b872df7a6d658059c4efb6a6eab8",
            ["剛從架上取下的暗月熱狗。趕快趁熱來買喔！"] = "c3f265f9c79fe874218c75eeb60e795b",
            ["靠過來！來這裡買嗆紅辣翅！"] = "a0865f7e679cbc713d639fbb652b59b9",
            ["鬆脆青蛙只在暗月馬戲團有售，機會難得，限時供應哦！"] = "59d2d4fff147043a75626e0a7a8383d9",
        },
        [14846] = {
            ["你知道我花了多少心血才將這些無價之寶帶來此地銷售的嗎？來看看吧。"] = "094cace1e1f8bca5aca039f124ce8236",
            ["我出售的每項物品都是我自己取得的。我向你保證。"] = "29c5fcc54f30c3265fc0ea1499ea23af",
            ["暗月馬戲團卡片？你面前的教授就是來處理這些東西的。如果你是專門從事古董跟藝術品的買賣者，就來找我談一談吧。"] = "a18afdc5e96e5c4132424bf6058f6568",
            ["趁現在還有機會，過來看看我的貨物吧。我們會在這兒待上一整個禮拜，然後就要動身去遠方啦。"] = "1e3edd109eb58225d62d1478f6ff6d54",
        },
        [14847] = {
            ["如果你收集整套的傳送門套卡，你將可以獲得一張高級暗月卡：虛空作為獎勵。這張卡會偶發性的在你死後將你的靈魂拖回你的身體並讓你復活。"] = "cabe10467ba55951a39c5efc5b01e754",
            ["如果你收集整套的元素套卡，那你將可以得到一張高級暗月卡：漩渦作為獎勵。這張卡片會偶發性的對正在跟你戰鬥的敵人給予嚴重的傷害。"] = "6c0066e9c134f9932cf5d4baf797844d",
            ["如果你收集整套的督軍套卡，那你將可以得到一張高級暗月卡：英雄作為獎勵。這張卡會偶發性的在你進行近身戰鬥時治療你。"] = "5b4d4908a2259afea5d5edad7b0cb6e5",
            ["如果你收集整套的野獸套卡，你將可以得到一張高級暗月卡片：藍龍作為獎勵。這張卡片對於恢復魔法能量非常有用。"] = "f9fbc218ea70279123d05e8059b07a52",
            ["我們在世界各地散發暗月卡片，看看有沒有誰能集齊四套暗月卡片中的任何一套。若你設法集齊八張一套的卡片，我們就會獎勵你一張高級暗月卡，可拿來作為飾品或是暗月馬戲團的紀念。"] = "3f7bf1a688d937c820a4dd5e2b16b4e4",
            ["歡迎來到暗月馬戲團年輕人！我們從世界上搜集了各種奇珍異寶任你參觀。喔，如果你能夠集滿整套的小暗月卡，請讓我知道，因為我的主人……我是說我會對它們有非常非常大的興趣的。"] = "175e8b03efe27c1ffb0ce6644f4ac989",
        },
        [14849] = {
            ["你沒看到我正在忙嗎？"] = "28c0efd31165758238391b2842e87a69",
            ["別忘記買點飲料和紀念品！"] = "2eb716d676d0b1b4ecaffc7b58ade0d6",
            ["暗月馬戲團是全艾澤拉斯最盛大的事件！"] = "db5e85c0e8fc397c337679dce51d896c",
            ["沒錯，朋友！暗月馬戲團就快要來了。只要我把這些巨大的貨車上的東西都卸下來，架設好所有的帳棚，弄好場地，並把飲料都倒好就可以了。別忘了屆時過來看看哦！"] = "a9e923e95ef8c0e440880eb043666f7e",
            ["玩得開心嗎？"] = "597f943bfef4a0100928324418268a5a",
            ["距離暗月馬戲團開始的時間不會太久了。過一陣子再回來看看我們是否準備好了吧。"] = "81072962754c21f425b3445d9fbaa303",
            ["這附近的確有很多亂扔垃圾的傢伙。"] = "fe440344a9bf50366eead025b3f88505",
            ["馬戲團快開始了！"] = "3609745a4c6616a705cba94a32482147",
        },
        [14871] = {
            ["啾啾回來了！我太高興了！我只希望我的黑鐵啤酒不會很快又被喝光了了，不然我怕我的小青蛙可能會再一次偷跑出去的！"] = "e3a9bceac350c8d4521ba30052baa2de",
            ["我找不到我的寵物啾啾啦。她喜歡喝黑鐵啤酒，那是她唯一肯喝的飲料，但是卻很難取得！現在啤酒已經沒有了……啾啾一定是自己跑去找酒喝了！$B$B我希望她可以趕快回來……"] = "973e2ce5b84bdcdcff9a070880e9f347",
        },
        [14875] = {
            ["如果你是來拯救世界的，那麼你就來對地方了。無面者－－血神哈卡－－已經被帶回到我們的世界來了！"] = "36ed78ad0299f724a3f13e2686290432",
        },
        [14903] = {
            ["我是全知者阿塔比姆，拉斯塔哈王的特使。$B$B我通常只和牧師、法師和術士打交道。"] = "c28cac378192770c4a9166d049115821",
        },
        [14904] = {
            ["你想要什麼？$B$B梅維克只跟德魯伊和薩滿往來。"] = "170ffaa87dbcca087ef37ce1bfd1b76c",
        },
        [14905] = {
            ["我眼睛雖然看不到，但是我還擁有洞察力。$B$B我主要跟獵人和盜賊打交道，$r。"] = "ec7eecf7af72db521e56383587d7714a",
            ["權力珍寶是古代古拉巴什帝國的遺物。贊達拉部族正在尋找它們——它們不僅有著極大的收藏價值，而且我們相信它們還蘊藏著遠古帝國的魔法。$B$B你可以在祖爾格拉布找到三種權力珍寶：硬幣、珠寶和原始神靈的物品。收集到一定數量之後，把這些東西交給我們，我們就會送你一些贊達拉最好的工藝製品。"] = "4104bf10ba38b4cb6f760f7203397a71",
        },
        [14910] = {
            ["你好，$c。我是拉斯塔哈的僕從，伊克薩爾。"] = "e7cdb9be91ab5ee24261c54b7949c919",
        },
        [14921] = {
            ["冒險者，你好。我是贊達拉的商人林沃斯。我來自南海，從我的家鄉帶來了許多新奇的貨物。$B$B如果你能證明自己的價值，我會樂意與你交換物品的。如果你有我們部族的榮譽勳章，我這裡還有些更好的東西……"] = "aca6701e63f56de998a1cc492839d1c2",
        },
        [14942] = {
            ["很抱歉，$c，但是在你變得更有經驗之前，我不能讓你去奧特蘭克山谷送死。"] = "6f8cf301e3f0ef7063dfca782d98b50f",
            ["為了部落，$c！奧特蘭克山谷需要你。我可以把你加到名單上嗎？"] = "dab0c064dd61d01fde511ec075b693a7",
        },
        [14981] = {
            ["你好，$N。你希望我幫你前往戰歌峽谷嗎？"] = "7b7d94a359c45dac8bad00353884b2f8",
            ["很抱歉，$c，但是在你變得更加強大之前，我不能讓你去戰歌峽谷送死。"] = "c294a5b02c1f5243fbd10a47517dfdfb",
        },
        [14982] = {
            ["$C，戰歌峽谷需要援助。你能幫助我們攻打戰歌偵察騎兵嗎？"] = "d02d422dcd7131e686d6532177696d9a",
        },
        [14983] = {
            ["阿拉索聯軍發誓為激流堡和聯盟奪回阿拉希。這將是一場惡戰，但是是一場值得打的戰爭。"] = "8f58e6676f208553898ca627001b851f",
        },
        [14984] = {
            ["要贏得這場戰爭，我們不能坐在這裡，靜待戰爭之潮將我們淹沒。我們必須果斷出擊，否則阿拉希永遠也不會成為我們的囊中之物。"] = "2d10a0bf75c6c86698196a262967b949",
        },
        [14990] = {
            ["$n，阿拉希盆地急需增援。在這危急時刻，正是獲得榮譽、提升聲望的大好機會。我懇求你去城中尋找阿拉希盆地的戰場軍官。"] = "36449905f0bb8e68d581301b2d6574fb",
            ["你還不夠強大，$c。繼續努力吧。"] = "4976af9b251b6de3b310c96fc5968bd8",
        },
        [14991] = {
            ["感謝你的幫助，$c。不幸的是，你的經驗不夠豐富，無法承受阿拉希盆地的險惡環境。"] = "a7aeb4a623d4e606d380ae2595ce637e",
            ["阿拉希盆地急需增援，你能幫助我們嗎，$c？這是個獲得榮譽、提升聲望的大好機會。你的幫助定能扭轉局勢，幫助我們打敗污染者。我們能將希望寄託到你身上嗎？"] = "f89a0bf28da74e8eb8f97d6f99a54359",
        },
        [15006] = {
            ["人類和他們所謂的阿拉索聯軍想把我們趕出阿拉希盆地。我可不這麼想，$c！你得動身前往那兒，證明該離開阿拉希盆地的是他們而不是污染者，準備好了嗎？"] = "a5e0148cc17209a693ca01b5dc0f9844",
            ["很抱歉，$c，在你變得更加強大之前，我不能讓你去阿拉希盆地送死。"] = "1bd3c817720e43bbc720fa8704b7cdfe",
        },
        [15007] = {
            ["看看四周，$c。你身邊的朋友並不多，我想你需要證明自己的價值。嗯，或許我應該同意你幫助我們在阿拉希盆地作戰。你願意嗎？"] = "d434eab0594d28c2d08ea9dbd4f04fbe",
        },
        [15008] = {
            ["很抱歉，$c，在你變得更加強大之前，我不能讓你去阿拉希盆地送死。"] = "c3b7867dcd5ddb0aafe672da55946ea2",
            ["我一直在盼著你呢，$N。我們在阿拉希盆地的戰鬥需要你的幫助，你準備好了嗎？"] = "b727ba44e324145d664261f3c8ce9cc0",
        },
        [15011] = {
            ["你好，$c。現在正是收穫節－一個感恩與追思的時間。我們舉辦盛宴感激所有我們應該感激的人，追憶我們的祖先和英雄，感謝他們給我們留下的寶貴遺產。$B$B請盡情享受這盛宴吧。我還提供一些煙火來慶祝這個美好的日子。"] = "20a2672934e46dd87b9f9e585c09dd52",
        },
        [15012] = {
            ["你好，$c。現在正是收穫節－－一個感恩與追思的時間。我們舉辦盛宴感激所有我們應該感激的人，追憶我們的祖先和英雄，感謝他們給我們留下的寶貴遺產。$B$B請盡情享受這盛宴吧。我還提供一些煙火來慶祝這個美好的日子。"] = "07d82752c2b2a676dc03af347776f8b3",
        },
        [15021] = {
            ["我們絕不能讓聯盟在阿拉希擴張勢力！既便是小小的避難谷地，在將來也可能對我們形成威脅。"] = "a0cdf795929fa807da0b88c05e1206cd",
        },
        [15022] = {
            ["阿拉希盆地的戰鬥是一場謀略戰。木材、礦石、食物……所有這些物資對戰鬥來說都是必需品。$B$B摧毀敵方的物資跟在戰場上殺死他們一樣重要。"] = "903cc7768c784eb239105149e250dee2",
        },
        [15042] = {
            ["只要有正確的材料，贊札就能製造古老的食人妖附魔。這種魔法能幫助你打敗哈卡和他的爪牙。$B$B我只要你幫我找2種東西。"] = "422211fe9697e4c260bda5b4ed73aa57",
            ["我是贊達拉的贊札。我以靈體形態從贊達拉趕來幫助我的人民。哈卡不能控制我的靈魂。$B$B我是來幫助那些曾經有恩於贊達拉的朋友的。"] = "c8103fbcbe2d18f0cdfa4d909fa00e81",
            ["是嗎？這麼說你已經知道高等精靈所掌握的食人妖魔法有多麼淺顯了？$B$B高等精靈怎麼都想不明白，作為一個與魔法密切相關的種族，他們為何無法駕馭食人妖巫毒的力量。對這些白皮膚的生靈而言，這簡直難以置信。他們只好使用一種不純的食人妖法術來增強他們的魔法力量。我想他們稱其為「秘藥」。"] = "0f2be05ebc4b746b42891e97a2db2629",
            ["首先你得從強大的哈卡金度和血領主那兒獲得一個原始的雕像。$B$B第二是打孔的巫毒人偶。你可以在散落此地的霉運巫毒垃圾堆中找到。$B$B把這些物品都給我找來，我會為你進行一次強效的附魔！"] = "5951443b219460226c4b5ed7e2d1b85d",
        },
        [15070] = {
            ["在我身後是贊札祭壇，是贊達拉氏族的神聖之地。我們在此禱告，希望能充分做好對抗血神哈卡的準備工作。$B$B利用祭壇摧毀你在祖爾格拉布找到的任何哈卡萊寶石，以此證明你對氏族的價值。我會用贊達拉榮譽硬幣跟你交換祖爾格拉布的硬幣。找到我需要的硬幣，你將獲得豐厚的獎勵！"] = "146cded4f6f6a9fde55acea952be56eb",
        },
        [15076] = {
            ["我們，贊達拉食人妖長途跋涉來此，因為我們無法坐視即將到來的危機。$B$B我們的遠征隊首領莫托爾帶領我們來到荊棘谷海岸以北的尤亞姆巴島，儘管如此，依然有勇敢的英雄前來造訪這座古老的食人妖城市……祖爾格拉布。"] = "2b07aacfb7ec7aa8d2c6dc58fbefae37",
        },
        [15077] = {
            ["歡迎參加藏寶海灣釣魚比賽，每週我們都會選出一位最好的漁夫，授予他釣魚大師的稱號！  在下午2點到4點之間，大群的可口魚會出現在荊棘谷海岸。如果你的浮標落在可口魚魚群中，你肯定能釣上一些的，這比在荊棘谷一般的海域垂釣要有效得多。"] = "5776ad2ab96a8574ffb8006cc2353824",
            ["釣魚大賽的贏家已經出爐了，但是賈恩願意收購你們釣到的可口魚！  每週日都會有一場釣魚大賽，你盡可展示自己的釣魚技能！"] = "e7cede3a6a5c6bfa97691dd12ed05122",
        },
        [15078] = {
            ["釣魚大師巴斯貝特已經在這片水域中放入了美味的可口魚，釣魚比賽可以開始啦。  一旦勝出，我會按五條可口魚換一銀幣的價格進行交換！"] = "ecb584ae4efebbbfe24eb728f55f4ace",
        },
        [15080] = {
            ["贊達拉食人妖長途跋涉、歷經艱險才來到此地，但是這一切卻招致我們的厄運……"] = "e0da321d08e8706f432c7322309f11f8",
        },
        [15102] = {
            ["$C，我們感到非常慚愧，戰歌峽谷一役迫切需要增援。如果你願意助我們一臂之力的話，你將獲得前所未有的榮譽。銀翼哨兵對你的所做所為表示敬意。我帶你去戰場軍官那兒，好嗎？"] = "8c59b436d4f8db5f6a0c712f93e98b11",
            ["四季輪迴變幻，但是你年紀尚輕。當你經歷更多之後再來找我們吧，$c。"] = "142259b01ef398530e6a98ed1a7c183f",
        },
        [15103] = {
            ["$N，現在，奧特蘭克山谷的雷矛衛兵需要你助戰，共同打敗霜狼氏族。這是個獲得榮譽、提升聲望的大好機會！你需要知道戰場軍官在哪裡，好讓他們送你一程嗎？"] = "1bda910e93a73611cc7b700da4c7cb86",
            ["我怕你在奧特蘭克山谷活不了多久，$c。等你強壯點再回到我們這兒來吧。"] = "7482b5799dee6ec1e4b78aa8db8bdd98",
        },
        [15105] = {
            ["$C，我們需要你的幫助來在戰歌峽谷對抗銀翼哨兵。在那裡你可以獲取無上的榮耀！你是否有勇氣去和我們的戰場軍官對話呢？"] = "94e10ef8ca4f4ba7b2ed059da3d417e8",
            ["很不幸，你還太弱小，無法在戰歌峽谷存活，$c。"] = "f24e4a79c576d78e3b220d459097ffb8",
        },
        [15106] = {
            ["你需要變得更強大才能幫助我們在奧特蘭克山谷作戰，$c。"] = "f4899549736f46c15cd46831ff21c964",
            ["向你致敬，$c。現在奧特蘭克山谷急需援助，這是獲得榮譽、提升聲望的大好機會。$N，你必須找到戰場軍官，加入對抗雷矛衛兵的英勇戰鬥中。"] = "99f6365eca208317d557bba2b924e015",
        },
        [15116] = {
            ["嗨！嗨！嗨！如果你想要試試自己的釣魚技能，那麼你來對地方啦！本週日荊棘谷將舉辦一場釣魚大賽！"] = "99cd56092bd54c1d0a5b2852b38b9e5a",
            ["嘿嘿嘿！我在這裡是為了推廣荊棘谷的超級無敵釣魚錦標賽的。不過你首先得有足夠的生存能力在這裡活下去，然後還需要足夠在這裡釣魚的精湛技巧。$B$B當你更符合以上條件的時候再回到這裡來吧！"] = "06c7b60c6b427e9bed25fe5bb168ab7a",
        },
        [15119] = {
            ["你好！我在這裡是為了推廣荊棘谷的超級無敵釣魚錦標賽的。不過你首先得有足夠的生存能力在這裡活下去，然後還需要足夠在這裡釣魚的精湛技巧。$B$B當你更符合以上條件的時候再回到這裡來吧！"] = "3f6b8f110896d04e7a6ad663cef0e70d",
            ["很高興遇到你，漁夫！如果你想要在釣魚好手中一展自己的釣魚技能，那麼就聽好了！在本週日，荊棘谷將舉辦一場釣魚大賽，選出一名釣魚大師！"] = "999cf7c2621e41f28cf2b13cc9d97ede",
        },
        [15126] = {
            ["我是駐紮在阿拉希盆地的污染者物資供應商盧瑟弗·圖恩。隨著你在污染者的聲望的提升，我可以出售給你一些非常有用的物品。如果你需要修理裝備，我也樂意為你服務。"] = "8240b8eb0361e85e9da92de68294dca1",
        },
        [15127] = {
            ["我是駐紮在阿拉希盆地的阿拉索聯軍物資供應商薩繆爾·霍克。隨著你在阿拉索聯軍的聲望的提升，我可以出售給你一些非常有用的物品。如果你需要修理裝備，我也樂意為你服務。"] = "2b18d0f222c8e7658616bae3c1e5d0a2",
        },
        [15169] = {
            ["上古的力量被數千年來從未活動過的蟲子所震撼。世界在哭泣，$r。也許一次新的災變正在開始。其中孕育的是痛苦……$B$B那些可惡的傢伙開始滲透入我們的土地。噩夢來自於睡眠。噩夢開始在我們醒著的時候糾纏我們……"] = "b046831149354fece411cd5757825f3a",
            ["他們說我被祝福了：新世紀需要被聆聽的傳訊者。"] = "2e00e741fec447902b6e157a134f4866",
            ["你好，旅行者。大約1000年前，其拉蟲人開始了對卡裏姆多大陸的戰爭。$B$B在那場戰爭中損失了數以千記的生命，大多數都是在戰爭爆發初期喪身在這片該死的沙漠中的。$B$B我是少數倖存下來的人，我連接了過去和現在。我不知道我為什麼還留在這裏，但是我知道我必須這樣做。"] = "0b0c533904f5ec72051ce930ebe18a3a",
            ["我被殺死過無數次。我總是發現我會在這裏醒來。有些人說我遭受了詛咒，還有些人……"] = "06b81739f0bafcfd039de7bee1020205",
        },
        [15170] = {
            ["你最好坐下，這是個很長的故事。$B$B當我們第一次來到希利蘇斯時，瑪爾利斯女士是塞納里奧城堡中第一位加入遠征隊的夜精靈。我們的行程沒有什麼特別的：組隊進入蟲巢探險，尋找失落的神器。"] = "443b87cdae07e4c1b2c9da0ebeb77760",
            ["你聾了嗎？我還能指誰？當然是瑪爾利斯女士。無論如何，她已經回來了，但是她的心情似乎不太好。她需要我們幫個忙。"] = "226398c6e0111e0a06eca54612ddddec",
            ["你認為我說的什麼意思？她變得十分瘋狂！那個女孩就在我們面前變瘋了。一般來說我不會動手，但是當我從震驚中清醒過來的時候，我變得非常氣憤。布拉恩，魯特加爾，我，當然還有猴子，一起向她撲去！我們能擋開她真是一個奇跡。她好像完全被佔據了！"] = "9192ce03c16bdad9e3e38652c3d3ce23",
            ["她要我們立即返回雷戈蟲巢！布拉恩拒絕了她。他認為我們在沒有軍隊支援的情況下是無法進入蟲巢的。那樣太危險了。跟我們首次進入蟲巢相比，這些蟲子的數量似乎膨脹了3倍。$B$B娜塔莉亞就是在那時得了失心瘋的！"] = "4a04ba2b3a44d86c49e14414d314fd81",
            ["很明顯！蟲巢中住著各種不歡迎我們到來的異種蟲。$B$B一切進展順利，直到我們在雷戈蟲巢中發現了一塊雕文水晶。她像飛蛾撲火一般往水晶靠過去！她把可愛的臉頰湊上去，精神也變得恍惚起來。隊友們都很擔心她。我們以最快的速度將她帶出了蟲巢！"] = "81794f3c4756bdfd389fa69ab46e362c",
            ["我們把她交給了指揮官，希望議會的德魯伊能醫好她。我們相信德魯伊們能讓她清醒過來。我們跟議會之間已經兩清，該回去做自己的事情了。$B$B過了好幾週，一切看來進展順利。布拉恩仍然四處奔波，我們也正常地工作著。有一天，她突然出現在我們的營地裏。"] = "9e37db370c5a046827955e725e64bdd6",
            ["誰知道呢？無論如何，那是我最後一次見到她。或許法蘭克爾能告訴你更多資訊。$B$B別轉移話題，我想指揮官給你的工作相當重要吧，但是我們也是來執行重要任務的！鐵爐堡對我們請求軍隊增援的要求置若罔聞。很明顯，以我們的力量難以保護這片土地。一旦你將報告交還給指揮官，就跟你的朋友一同回到這兒來。我們需要你的幫助！"] = "dea537ea78bde91b9c77ce8d552d9bb7",
            ["銅鬚再次失蹤了！那傢伙跟他的兄弟不一樣，一點判斷力都沒有。"] = "2e9da6b3338a01eeae4e67b707bbd7e8",
        },
        [15171] = {
            ["仰望天空吧，$C。這片區域已經有一千年沒有見過龍族了！我就知道，那些其拉蟲人在策劃著什麼陰謀！"] = "af0fd13734bbd749a52d7d45abe934d3",
            ["你想問什麼？牠就是一隻猴子，你這個瘋狂的笨蛋。所以，反正就是，當那隻猴子看到老布拉恩忽然臉朝下地撲倒在地時，就變得狂暴了。那個夜精靈做不到的事情就是阻止格里布持續重擊她的頭。"] = "4419b499451d23fb555f4bbd5d1f3c98",
            ["哦，就是這樣了……先找個椅子，$g小夥子:小姑娘;。$B$B我肯定魯特加爾已經告訴你一些事情了，因此我將省略一些細節，讓你直奔主題。"] = "8b65201c7f8e4fca254e87dde37a2d5b",
            ["好吧！她從蟲巢回來過，但是布拉恩一點都沒有察覺到！混戰之前，她開始跟什麼人交談起來。奇怪的是，她用了一種我們從未聽過的語言談話。"] = "385c489f30a4498700047ccea1cf59cc",
            ["我會告訴你的。她直直地往巢穴跑去。你知道有多瘋狂嗎? 竟然沒有一隻該死的蟲擋住她的路或是試圖阻止她。她用跑的穿過它們就像她跟它們當了好幾百年的朋友一般。"] = "c0ef1cc2e7bf63b3d68034c42fac68b9",
            ["沒錯。"] = "bdd49ea534b3881187f934c773214283",
            ["聽著$g小子:小姑娘;，我要讓你知道無論是什麼攻擊我們，她都不是隨便一個不知名的女祭司！她的眼裡發出邪惡的光芒，而且她真的口吐白沫！她靠過來，發出了某種瘋狂的尖嘯使得我們全都往不同的方向逃走，然後開始一個接一個地鞭笞我們的心靈。我聽到黑暗的文字在我的腦海中迴盪，眼前忽明忽暗。我瘋了！如果沒有那隻該死的猴子，我們可能已經玩完了。"] = "0c9010e208fa0e5318f1df6b031376d3",
            ["那還用說！布拉恩、魯特加爾、猴子和我都對此感到陌生，我們懂38種語言，還略懂一點泰坦語——連瓦尼爾和艾斯爾都不例外。$B$B總之，她嘴裏嘰裏咕嚕說的話沒人能懂。「禮物」？她點點頭，就開始攻擊我們！直接攻擊我們！"] = "86d25b257a6e22384810cb2de77de42a",
        },
        [15174] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "3334d2c3be49af24ec80966cd3044afb",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "90657c7dd9fc98c4960a8c613e7e0841",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "f3dc300ddc1883b724afefb742b27c54",
            ["你好，旅行者。只要你待在塞納里奧城堡的城牆裏，就可以免受一切傷害。$B$B當你離開城堡的保護之後要特別小心，異種生物在這片土地上橫行。"] = "aa4d909db480c4f692905dd5b95a455a",
            ["你是個皮革商吧？我對獸皮的味道再熟悉不過了。$B$B我的父親過去常常跟我談起數世紀前一位居住在南風村的著名工匠。很遺憾，那兒已是一片廢墟了。"] = "ad265e60289c8468af0f3ee773f50f34",
            ["你有興趣探索這些地下城中的一個嗎？"] = "f70c987e98c43a9ac4f1ef6eb271008a",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "25a80704f18ee56676b132bdded0fe94",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "9cdbd4512dccbc458675c5216058ddcd",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "bbbb6f1884cdacec9af6cb67e3e1abd4",
            ["厄運之槌位於菲拉斯的中部。"] = "89054fe6fb8e52df563c9e80702c264a",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "d34171a9fbd911b8f1bf818f71cc3f32",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "4b24ea6b391a2efd0be7d84cc947d159",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "310fe6a22db0bf2928c1ff8e5c70cd20",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "5d076554d313584aa1c5611cf0129a23",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "24cd799771f287be14f8060e5444dfa5",
            ["奧達曼位於荒蕪之地最北端。"] = "36de161eff379c5060e7c2e31cdc975a",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "cac489d41abedaef7c5d7041fd7492e3",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "136e146f620b6e7197755a682b68ce84",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "6f1db228470e4b9d299edd3c7168c063",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "7bef92afa79765ff95f06d3660786a79",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "530c2f46cebb57733cec5f86ad8383d3",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "8d0c3e032d49fe079017a90965f53922",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "fd70ec87881856186158a19c159addb7",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "94fa40981e2a4d5c4b4b0b68b37f782c",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8f49377bcf39a38a76d2cf7cbacbefb0",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4352ca0c9a3782df4f9b0a23c9c7f9d7",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "c14eefa9bf01ea21ee6c512a62f5270c",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "e33d4e6573f24d17efcc2b0ecf76516d",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "6679f691680afda8b76a2dd04f2e7144",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "1d59940e7ccbee60370a304b33835f99",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "b19764fa4b6d3a891fa5f750b3dd2517",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "f9432ed28b2dabcd595eddb702af9ca1",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "10e3746148a7f37b2c1af2d199833368",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "927f2bfc50de1f03c38ac6ec3198f4a7",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "78e6008fbf1d737dce7812540853511c",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "54bd2c1a937b1392327adbdf92ce5e6d",
            ["諾姆瑞根在丹莫洛的西邊。"] = "a4f613548f3f5a63415a978d891ce475",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "3b08e6def8fe2881c84a302e3f4c7fea",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "03ee214820f246ccc4e751c56c822ace",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "7eddf733901dbca29a5a21752dd1ceb4",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "0e3148ee13bdc4aad5af84663b24d1ce",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "aab40b74860886caa96dcfdaf979e180",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "9c2b22f32a137854d984166b2aaded4b",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "8f57f5e81f55defd22e287d36b233496",
        },
        [15175] = {
            ["我向城堡提供各種施法所需的碎片和其他煉金材料。"] = "3407714a9aac3f0bbd78877a9a9f2f09",
        },
        [15176] = {
            ["一股強大的邪惡力量正在蠢蠢欲動，$R。你感覺到了沒？$B$B啊！當然你無法感覺到。把你的護甲和武器給我吧，我會讓它們恢復活力。"] = "8df70dd608a3c4cf651cb64b15114023",
        },
        [15177] = {
            ["你想要飛往什麼地方？"] = "8ee9e2b8b1fbeba82851331d36cb251c",
        },
        [15178] = {
            ["你想要飛往什麼地方？"] = "008491a7c8f31e3556f00e8c3fdc3190",
        },
        [15179] = {
            ["唉，我現在的補給品儲量已經非常少了！是什麼耽擱了那個該死的地精那麼長時間？"] = "adf109156d6688b93880917b0f179b65",
        },
        [15180] = {
            ["看看你身後，$R。蟲巢中的異動使我們周圍的土地震動起來。$B$B現在是我們實現一千年前許下的諾言的時候了。沙土飛揚，似乎其拉蟲人是在計畫開戰了。"] = "07d02c622457ae7e03cc05e5aefbc6e6",
        },
        [15181] = {
            ["為什麼是現在，$R？我不明白。要做的事情還有很多……"] = "45ecbb32f065f665b991c1a4db9e7395",
        },
        [15182] = {
            ["你是在獵殺死亡彎鉤吧，$N？我記得很清楚。這週我手下的兩個傢夥就是被她殺死的。希望你的運氣比他們好。"] = "a8ee595039d5f688ef88300a94ae9a8a",
            ["指揮官最近一直心不在焉。他的妻子在最近的一次南部沙漠考古挖掘中失蹤了——一下子消失地蹤影全無！真的非常奇怪。$B$B我想你是不是想要找份工作？我是不是可以給你一些提示？"] = "b60ac134e16be202debcce1733994a3f",
        },
        [15183] = {
            ["你可以聽到嗎，陌生人？嗡嗡的聲音一天比一天響。這些水晶一定是把那些蟲子逼瘋的元兇。"] = "923b9f247d112d5c467bec4f859d29b2",
        },
        [15190] = {
            ["你是誰？我在哪兒？我感到……非常虛弱……"] = "4769fa7dbee7d466df239c3fdc15ce4d",
            ["嗨！謝謝你手下留情，沒有懲罰我！我想我得躺一會兒恢復體力。"] = "0e9b47815086b6b0100592326be61808",
        },
        [15191] = {
            ["你好，$c。歡迎來到塞納里奧城堡。我們在這個異種生物最強盛的地方對抗他們。我希望你可以助我們一臂之力。"] = "602ace4ed716eca72ea8d2e7882f4a76",
            ["我很高興再見到你，$n。你的幫助為我們保證了補給線的安全。我希望你可以理解在如此一場大戰中，物資補給的重要性。"] = "83301b049e11b44cec8144e74a752623",
        },
        [15194] = {
            ["你已經回來了！現在，我能為你做什麼呢？"] = "48165a36b82154ca1c0e0b8bcd69e4a2",
            ["快點離開，陌生人！我和你沒什麼好說的。"] = "e79d5d1fab3e655e71f596369ca816fa",
        },
        [15197] = {
            ["歡迎來到稻草人慶典，$c！$B$B為了慶祝萬鬼節，被遺忘者焚燒稻草人來彰顯其榮耀，最為尊崇的場合。就是這一天，女妖之王帶著我們逃出了巫妖王與天譴軍的魔爪，從此以後我們得到了自由。我們對那些造成我們墮落之人的仇恨將會全額奉還！$B$B稻草人將會在下午8:00開始焚燒！"] = "ade7be73d65eb161512d4630be4b5df0",
        },
        [15199] = {
            ["你！你看起來身體強健……南海鎮需要你的幫助！$B$B萬聖節到了，那些受詛咒的被遺忘者蠢蠢欲動。他們把所謂的慶典開到我們家門口來了。如果你有時間的話，我們真的需要你的幫助！"] = "aa29eb4cc989127d57a7bf2186381767",
        },
        [15270] = {
            ["希利蘇斯的靈魂召喚我們，$N。土地在哭泣，它有個悲慘的故事要告訴我們……"] = "81fa3f4ee4a97d65004b878d5bb8a931",
        },
        [15282] = {
            ["塞納里奧議會是睿智的，他們發現了很多有關大地的秘密。願意聆聽這些德魯伊的教誨的工匠總是會得到許多寶貴的知識。"] = "43c3056caad01325e42ca64695ace0f9",
        },
        [15303] = {
            ["嗯，很簡單的！這東西的使用方法和你以前用過的那些東西沒什麼兩樣。別擔心，我會負責點火。當你升空之後，你會發現自己正「飄浮」在空中，但是這種情況不會持續很久。你將被發射到湖邊的一個目標那裏去。只要記得在適當的時候將你的「翅膀」分離，就可以安全地掉入湖中了！不然的話，嗯，我不負責出售人身保險。"] = "f2c53cf52adbcab179b2f133e834e2bd",
            ["歡迎！上前來，不要害羞。這是我最自豪的發明……衝擊者5000型超級大炮！她難道不漂亮嗎？她實在就是很漂亮啊！看起來對於炮管的中段來說，你的體型稍微大了一點，但是我想這不是什麼大問題。飛行充滿了樂趣，你想要學學嗎？"] = "938e293af4976c65a3bacb0ee9a2b2a3",
        },
        [15306] = {
            ["我們在希利蘇斯有一個以上的敵人，$n。$B$B當所有人的目光都注視著希利蘇斯時，我大哥跟我一直密切注意著暮光之錘的瘋子。"] = "811433ddcfe17faa04dd7e7c06eddfcb",
        },
        [15350] = {
            ["戰爭即將來臨，$n。每個部落成員都要響應號召，並肩擊潰懦弱的聯盟。"] = "500674c7da105457382c51908165838f",
        },
        [15351] = {
            ["與部落之間的戰爭已經到了白熱化的階段，$n。聯盟需要大量的物資，我們應竭盡所能，提供幫助。"] = "59639744f57566c294774d64cbef1436",
        },
        [15353] = {
            ["怎麼玩？！$B$B世界各地的旅店老闆都會將糖果分發給孩子們，許多城鎮都將裝飾一新，歡度節日！此外，南海鎮的哈特曼中士需要幫助，他想要攻擊那些被遺忘者，破壞他們的稻草人慶典。$B$B對了，我聽說暴風城孤兒院裏有個生病的小男孩，他想找人陪他玩要糖果的惡作劇遊戲……或許你能幫幫他？"] = "413f1f49e910de4126637d428d95ef9c",
            ["萬鬼節快樂！你喜歡我的面具嗎？嚇人吧！"] = "3bc518d31131ac14baee97e92ff44f6e",
        },
        [15354] = {
            ["怎麼玩？！$B$B世界各地的旅店老闆都會將糖果分發給孩子們，許多城鎮都將裝飾一新，歡度節日！此外，幽暗城外還會在夜間舉辦稻草人慶典。$B$B對了，我聽說奧格瑪孤兒院裏有個生病的小女孩，她想找人陪她玩要糖果的惡作劇遊戲……或許你能幫幫她？"] = "0381c9c7c5dfb5651cd61f8b8f45938b",
            ["萬鬼節快樂！你喜歡我的面具嗎？嚇人吧！"] = "947ed96708cb7e54b6840b95cfc92d0b",
        },
        [15378] = {
            ["一群英雄？一定要驅逐克蘇恩，我們會幫助你，人類！"] = "551053135aaeda0cc02c093df00e1973",
            ["英雄，在這受咒的寺廟裡所發生的事情都會被發現。它會被記載於史書中－故事以傳說描述艾澤拉斯遠至虛空本身！"] = "27a21efbb42166d015d42aea8c63230d",
        },
        [15379] = {
            ["即使你不知道為何沒有擊敗克蘇恩而設法解救我們，我們仍會集中所有的力量將野獸驅回牠原本的地獄－不惜任何代價。"] = "febc6c6f0212bb59db53fa246e390a6c",
            ["若克蘇恩還活著，我們的自由就根本不算什麼。你真是一位預言勇士。"] = "4a3616c5c52ca099ad816dfc278bf7a9",
        },
        [15380] = {
            ["我目睹站在我眼前的奇蹟！經過了一千年的囚禁，我還沒見過一件活的樣品－除了那些邪惡的其拉和異種蠍－進入密室。"] = "fbec45aaafa3ad165557bf6abbdc4ac2",
            ["這個世界很感激你和你的盟友，$n。"] = "fd10ddbf850f23ec3e5ca81dbb183556",
        },
        [15443] = {
            ["嗨，$c。鐵爐堡軍團被部署在這裡監視佐拉蟲巢。塞納里奧議會的德魯伊一直以來都在監控異種活動，他們預期在這兒會有重大的事情發生。"] = "cea4e3e3ab05b82e1f49619ce41d48d8",
        },
        [15458] = {
            ["你好，$r， $c。我是指揮官漢默·石錘，也是代表聯盟的大使。如果你對於聯盟收集作戰物資有任何問題$g 小伙子 : 小姑娘;,不要猶豫儘管問吧。"] = "f07f5e6d40044eae745e47cfd0b2ac14",
            ["我們團結一致，$r。一個古老的惡魔威脅要毀滅卡林多上的所有生命，並以它邪惡的力量摧毀世界……它是所有仇恨事物的締造者：永恆的泰坦。$B$B我們是唯一能與克蘇恩軍隊抗衡的軍隊。如果我們不繼續向前攻打我們的敵人， 我們的敵人絕對會摧毀我們。$B$B戰備需要你！"] = "ea8c9e4b80c9fb807cffa1aa88bd86b7",
        },
        [15471] = {
            ["< 安多洛夫冷酷地看著你。>$B$B如果它會流血，我們就能殺了它。"] = "cbb32bb2891d6e835c05709df5717dc5",
        },
        [15498] = {
            ["我們能從容穩固的對其拉發起戰鬥攻勢，都要歸功於整個卡林多的全力相助。$B$B你打仗需要的不只是士兵而已，$n。商人和工匠也是戰爭裡的無名英雄，他們能補給戰爭所需要的所有物資。"] = "b3799b82bc9ff1942e4ac19ba2d4c105",
        },
        [15499] = {
            ["當戰爭開打時，我就像其他人一樣，是來這裡幫助我的夥伴德魯伊們。$B$B現在安其拉之門已經開啟，我知道還有很多工作需要完成。我已決定要待在希利蘇斯，並盡全力協助達成目標，$n。"] = "5ad93a4745aa099f6c0236880ca96ae9",
        },
        [15500] = {
            ["這戰爭還沒結束，才剛開始而已！我們日夜都有勇猛的戰士對抗安其拉裡的敵人， $N。不久之後其拉城就會淪陷。"] = "814445cc1ab4e2c8f95a5e1a409c5970",
        },
        [15502] = {
            ["奧羅被殺後通往最後房間的路就顯而易見了。如果你想的話，我可以將你傳送到那裡。"] = "2e604774c5428e55d30448b3f9443e9b",
            ["當心點，凡人。那些強大的生物就是在此地葬生的。"] = "01a72b8a9ee3737b37605b3e99d6402a",
            ["雙子帝王被殺之後，神廟裡的魔法防護阻礙傳送就大幅衰弱。如果你想的話，我可以將你傳送到帝王的巢穴。"] = "e3ba53c521b1009ced105bc09ff00136",
        },
        [15503] = {
            ["一千年前，流沙之戰結束，在安納克羅斯和鹿盔封住安其拉大門時，我們的三位族人犧牲了自己，將其拉蟲人禁錮在這些大牆內。$B$B我們曾立下誓言，一旦甲蟲之牆開啟，就要找到麥琳瑟拉、亞雷戈斯和凱雷斯特拉茲。$B$B而它真的發生了...因此我們來了。"] = "60e14cbaa8435b4075f83aeb3e80dcff",
        },
        [15504] = {
            ["凡人，這兒充斥著一種難以形容的恐怖。克蘇恩和他的追隨者們不僅公然藐視自然的力量，他們的存在更預言著艾澤拉斯的毀滅。$B$B一千年前，麥琳瑟拉、凱雷斯特拉茲和亞雷戈斯都犧牲了自己以保全這個世界。我們來這裡不僅僅是要報仇，還因為我們必須阻止克蘇恩！"] = "0256593f191b79bf991a495678be7dce",
        },
        [15539] = {
            ["我們和聯盟站在同一陣線，$r。一個惡魔，古老到世界已經遺忘了它，想要吞沒我們；先是卡林多，再來就是整個艾澤拉斯。它被一個偉大變形者所創的仇恨而驅使：永恆的泰坦。$B$B我們全都阻擋著克蘇恩的軍隊。我們會先進攻並拿下安其拉的軍隊。讓整個艾澤拉斯因為部落和聯盟的力量結合而震動。$B$B戰爭需要你！"] = "867569b880563887beb157cd19a1f51b",
            ["為了部落， $r。我是部落大使，佐格將軍。我是來向你通報部落關於安其拉之戰的準備工作進度的。你想知道什麼？"] = "d2747cbf9e92ad97f5c16f908b596c77",
        },
        [15540] = {
            ["既然戰火蔓延已達巔峰，到目前為止，部落與聯盟的強壯戰士都沒有短缺。$B$B但願我們能將他們趕盡殺絕……"] = "d3444f4b56739837e99b8054c798a837",
        },
        [15549] = {
            ["新的一年來臨了，月光灑滿大地。$B$B這是屬於我們的日子……遠古的生命甦醒了。"] = "98f6f474b4727ae3900b6c9cf1de0ff7",
            ["鐵環長者住在灼熱峽谷的黑炭谷。"] = "6954eeb9a527a8cef8cc62722874280a",
        },
        [15556] = {
