            ["新的一年來臨了，月光灑滿大地。$B$B這是屬於我們的日子……遠古的生命甦醒了。"] = "98f6f474b4727ae3900b6c9cf1de0ff7",
            ["迷霧行者長者喜歡在菲拉斯觀賞厄運之槌的鬥爭。"] = "318ed0e744f88da539e3c51bc4697212",
        },
        [15557] = {
            ["你可以在暴風城裡找到錘嘯長者。"] = "24e765cdee4370c4b56804eb47e7701f",
            ["你可以在燃燒平原的烈焰峰找到晨行者長者。"] = "a82acbf9cc59e1d9b14eec0cc0cef377",
            ["冰蹄？我聽說他住在藏寶海灣那裡。"] = "37a1c67b2928272c30a2e3b3821eadc1",
            ["新的一年來臨了，月光灑滿大地。$B$B這是屬於我們的日子……遠古的生命甦醒了。"] = "98f6f474b4727ae3900b6c9cf1de0ff7",
            ["雷眉長者通常都在艾爾文森林的閃金鎮裡。"] = "0ef3a4daeaac64acf2ca98fcf3350b69",
        },
        [15558] = {
            ["新的一年來臨了，月光灑滿大地。$B$B這是屬於我們的日子……遠古的生命甦醒了。"] = "98f6f474b4727ae3900b6c9cf1de0ff7",
            ["金井長者都在丹莫洛的卡拉諾斯消磨時間。"] = "11ccf478d11d91ad3de1ce0965dd1e7c",
