        [15561] = {
            ["你可以在西瘟疫之地的通靈學院找到月擊長者。"] = "969acaf245ed6f2b05bdbb672a4a18c9",
            ["墓生長者都在提里斯法林地的布瑞爾附近。"] = "8aa7da319f4642917680c8b017576c28",
            ["峰頂長者就在市中心附近的山丘上守望辛特蘭。"] = "caf07620c72127b10e1729b5a72eef6b",
