        },
        [15562] = {
            ["你可以在銅鬚的故鄉，鐵爐堡，找到銅鬚長者。"] = "f65717b9ef7e2cce484130fee81dd53a",
            ["劍捷長者都在泰達希爾上的達納蘇斯小徑閒晃。"] = "7b97edf23dc2c013612ec1169de003d7",
