        [15609] = {
            ["我們很快就能擺脫艾澤拉斯上可恨的異種了。他們潛在的毀滅性比你所親眼見過的任何東西還要強大，$n。更強大、更黑暗的力量就藏在他們的活動背後。"] = "c6416a9b2460c2bc035acaa57091b218",
        },
        [15613] = {
            ["異種蠍看來會令人致命，但牠們卻比其拉統治者更為溫馴。"] = "d1ec54aff7b3d41b9cf78637de55db9c",
        },
        [15634] = {
            ["伊露恩與你同在，$c。"] = "9f0b1ccaf183a8e36a2849671ae33e26",
            ["泰蘭妲傳來她的禱告。月亮之母祝福我們。"] = "48d8bbdc83acab937796721b3e4db3ab",
            ["願月神與你同在，$c。"] = "9f0b1ccaf183a8e36a2849671ae33e26",
            ["高階牧師不能離開達納蘇斯。范達爾心情很惡劣。"] = "0f9c37eaa94c5a6409966d96d4a92fe8",
        },
        [15694] = {
            ["你好啊，朋友！"] = "5b93963bfae198a2a8e568d7c9b0aa31",
            ["別忘了觀看下一場煙火表演！每天下午6點開始，每小時整點都會有一次！"] = "4617036e771dca54c5b409aa97055eaf",
            ["我不知道他們給那些酒桶裏放了什麼，但聞起來很香甜！"] = "8698393913c403f236550da9075dd3d5",
            ["煙火表演之後，他們會拿出高腳杯，我們就可以喝酒慶祝啦！"] = "89e415bdb73fd26d1d58ccc6394eccff",
            ["要是有人給我個吻就好了，你知道我在哪裡可以找到一個吻嗎？"] = "b818b18848af77ff95b946be1fadd22d",
        },
        [15700] = {
            ["你好，部落的$C，以你為榮！我是部落作戰指揮官，督軍格爾庫克。我們將面臨一連串艱難的考驗，我們會戰勝一切的，一如往常。$B$B如果你有問題，可以問問他們。"] = "ff1113878810a7326aec257f03be15c6",
            ["我們和聯盟站在同一陣線，$r。一個惡魔，古老到世界已經遺忘了它，想要吞沒我們；先是卡林多，再來就是整個艾澤拉斯。它被一個偉大變形者所創的仇恨而驅使：永恆的泰坦。$B$B我們全都阻擋著克蘇恩的軍隊。我們會先進攻並拿下安其拉的軍隊。讓整個艾澤拉斯因為部落和聯盟的力量結合而震動。$B$B戰爭需要你！"] = "867569b880563887beb157cd19a1f51b",
        },
        [15701] = {
            ["你好，$c。我是這裡指揮作戰的戰場元帥落雪。我們還有一段辛苦的路要走，$g 小夥子 : 小姑娘;，所以如果你能幫忙，那是再好不過。請任意發問。"] = "ac0a0b581e16d91b9d2a09b564f6d6c3",
            ["我們團結一致，$r。一個古老的惡魔威脅要毀滅卡林多上的所有生命，並以它邪惡的力量摧毀世界……它是所有仇恨事物的締造者：永恆的泰坦。$B$B我們是唯一能與克蘇恩軍隊抗衡的軍隊。如果我們不繼續向前攻打我們的敵人， 我們的敵人絕對會摧毀我們。$B$B戰備需要你！"] = "ea8c9e4b80c9fb807cffa1aa88bd86b7",
        },
        [15702] = {
            ["嗨，$c。我相信你是來這裡詢問安其拉之戰的事。我們需要極大的協助。$B$B這是場聯盟和部落結合起來準備對抗安其拉異種和主使者的大戰。在奧格瑪的精神谷，我們正在收集大量的物品來製造作戰物資，而這些收集的任務正需要你的幫忙。$B$B我能請你去和我們的指揮官談談嗎？"] = "228c7995c13842a05cb0db6e14827e56",
        },
        [15703] = {
