        [15723] = {
            ["哇！這酒真夠勁！我快要撐不住了！"] = "de8c431728ce950f950d89ba7cdef31d",
            ["哈哈！開始慶祝吧！"] = "44787eb1940b1a80ea948150559d9522",
            ["晚上會有煙火表演，從下午6點直到第二天早上，藏寶海灣的天空將會綻開無數絢麗的花朵！"] = "fa57939560f4cbefcc06bc3981b280fc",
            ["煙火表演之後不要走開！拿起高腳杯和你的好朋友一起慶祝吧！"] = "cd8d2f3f2d1e4fce86b7b1d0a1c196ce",
        },
        [15731] = {
