        },
        [15798] = {
            ["研究並瞭解這些巨像，可以讓我們更有把握打敗其拉蟲人！"] = "ca9c2a76280fa526355a744dfbdacd34",
        },
        [15799] = {
            ["我們要弄清楚其拉到底都餵那些怪物吃什麼！你看看他們有多巨大！"] = "392d38d469784b0930ac72d8954f8d8e",
        },
        [15864] = {
            ["年獸就睡在月神湖深處，但要在怒風獸穴附近的東南方岸邊召喚它。在那裡你可以找到很特別的煙花束發射器……$B$B在發射器那裡使用你的煙花，年獸的爪牙就會出現。發射更多的煙花，大約三十六組，或者朝它的爪牙投擲伊露恩的蠟燭，年獸就會醒來。"] = "8380da37ec60070f5cc0417fd12e3bc6",
            ["長者們的榮譽就是對你們文化和人民的榮譽，$c。這個時候，祖先的錢幣就是表揚那些選擇踏上可敬之路的人最有力的方法。$B$B在這次的新年慶典中，你有機會為許多長者爭光。如果你要這樣做，就需要祖先的錢幣。帶給我這些錢幣，我就會讓你選擇一個獨特的物品作為獎勵。"] = "5ff684abf73ab59dca0e0d04d8c6f804",
        },
        [15871] = {
            ["你可以在暴風城裡找到錘嘯長者。"] = "24e765cdee4370c4b56804eb47e7701f",
            ["劍捷長者都在泰達希爾上的達納蘇斯小徑閒晃。"] = "7b97edf23dc2c013612ec1169de003d7",
            ["新的一年來臨了，月光灑滿大地。$B$B這是屬於我們的日子……遠古的生命甦醒了。"] = "98f6f474b4727ae3900b6c9cf1de0ff7",
            ["金井長者都在丹莫洛的卡拉諾斯消磨時間。"] = "11ccf478d11d91ad3de1ce0965dd1e7c",
            ["鐵環長者住在灼熱峽谷的黑炭谷。"] = "6954eeb9a527a8cef8cc62722874280a",
        },
        [15895] = {
            ["你好，$N。我們從月光林地過來，散播新年慶典的精神至世界各地。$B$B你何不加入我們的慶祝活動？"] = "aa03e1f2960fa0bfc11594e3485ca65b",
        },
        [15900] = {
            ["你好，$N。我們從月光林地過來，散播新年慶典的精神至世界各地。$B$B你何不加入我們的慶祝活動？"] = "8c264afdfd859dd75aa92958ab0ec315",
        },
        [15903] = {
            ["「你的戰爭物資收集工作做的很好」他們說，「你一定會得到晉升的！」。他們真正的意思是，「你會和一群小不點的矮人一起被部署在希利蘇斯的某個蟲巢外面，卡恩斯！」$B$B謝謝你的提拔，中尉！"] = "668e49c17df4b9aa59370244f97c3f6a",
        },
        [15905] = {
