        },
        [15909] = {
            ["我，就像我的哥哥一樣，為那些替自己祖先爭光的人爭光。與新年慶典的信徒們分享我手工技藝的秘密帶給我很大的快樂！"] = "63da9bd89a3205deec3a0d71f3209f77",
        },
        [15917] = {
            ["他們擺出這些燈籠來慶祝即將到來的新年節慶。"] = "7e9c620ca526252a37ea37761109af3c",
            ["他們要施放整夜的煙火秀。月神湖的天空將從晚上6點閃耀到日出！"] = "3ebd4c9fbc15b539397a05f7c7e9bfb7",
            ["這是新年節慶的最後一夜。願好運與你同在！"] = "ea6aed234baf22eb98af03d184469b13",
            ["願你的長者保佑你，$n，帶給你來年的好運。"] = "5e8efcc987de096a86113fbf1f74025c",
        },
        [16012] = {
            ["索爾讓我進入他的聖殿領地是對我釋出相當大的善意。無論如何，我不求久留。給我們的領導者帶來任何麻煩都是極大的侮辱。"] = "b9ca2ade5c180a21e305ffe165d2771c",
        },
        [16013] = {
            ["試著別引來太多注目，我正等著國王覲見。我不介意等待，在這些魁梧的守衛旁邊我覺得相當有安全感。"] = "f555efebf575408048587026c0aa3577",
        },
        [16014] = {
            ["你好，朋友！想不想看一些精華電容器？或是精細的全方位鬼魂吸收器？"] = "2ee56c2d70a0c3bb5d140a53ddd3fa45",
        },
        [16031] = {
            ["我現在很好，別擔心我。等我在這房間裡進行一些淨化儀式後就會想辦法出去。邪惡的魔法污染了這個地方，$n。"] = "79424cf61ac27a09aeb2a6d5ab3cbd8e",
        },
        [16032] = {
            ["什麼事？你沒看到我正在忙嗎？"] = "360a69edd614799c733b1184cf582009",
        },
        [16033] = {
            ["$N！你回來就是為了跟我聊聊嗎？好體貼啊，你今天穿的好美喔！$B$B你大概想不到見到你我有多開心。在這裡我好寂寞，都跟一堆忽視我的野人在一起。謝謝你為了我們所做的努力，我畢生難忘！$B$B謝謝你順道過來問候我們，別拘束，就當自己家吧。"] = "31cec36e221c24d2e395f87f8a13b7c7",
            ["<布德利懷疑地看著你，但仍繼續……>$B$B我們到了那裡，拿到了魔法書，而科爾莫克，我們的雙頭巨魔巫師，他的四隻眼睛裡流露出這個奇怪的眼神。那真的令人毛骨悚然，因為那第二對眼睛總是看起來死氣沉沉，像牛的眼睛一樣，你懂嗎？所以，突然間他就伸出手把瓦薩拉克所配戴的護符撕扯下來。$B$B公司裡剩下的人全瘋了；我們之中有一些人告訴其他人別去管那巫師，也有些人想將護符佔為己有。"] = "e4059edbada4f015b06e754a44f9b6c5",
            ["你能看到我？你知道就因為沒人能看到我，我在這上頭被忽略得有多慘嗎？有人跟我講話真是太開心了！$B$B啊，你一定是被我以前傭兵公司還活著的成員派來的，我說對了嗎？我當然對啊！$B$B不過不要再閒話家常了，如果你要把事情做好並交回瓦薩拉克的靈魂，那還有很多工作要做！"] = "d8a5cf6d252aa70c9685e327fb97066f",
            ["其實這很簡單，真的，$N。我的舊傭兵公司，隱刃，在錯的時候接下了錯的任務。$B$B我們被一個藏寶海灣的哥布林走私者僱用，一個叫格雷姆尼克的人，他覬覦瓦薩拉克的魔法書。或是說，可能在過去曾互相較勁？我想我們現在是不會知道的，因為格雷姆尼克不久前被瓦薩拉克的一群鬼魂刺客殺了。他們成群結隊時還真的很恐怖。$B$B我說到哪了？"] = "719549680790d3f20c149ecbf7c7c9a1",
            ["冷靜下來！$B$B<布德利低聲抱怨了一下生活的不耐煩>$B$B正如我所說的，從他的巫術中被召喚出來的瓦薩拉克靈魂和鬼魂刺客，開始對我們展開攻擊了。讓我告訴你，當時我們的狀態並不適合迎擊，所以只能跑。我還記得我們德魯伊中的一員，莫爾·灰蹄，在某處失足滑落塔的較低層。$B$B其他的就如同他們所說的，都是過去式了。"] = "6952da64d9a42837f0f8a0e8e30b1e67",
            ["哎呀，你不需乞求！總之，我已經快完成故事了。$B$B所以，整個公司就在那個巨大的房間中央為了那個護符爭吵，你知道這在那裡是如何產生回響的！最後它斷成三塊，然後我們擲骰子，讓它們分給不同的人或團體。$B$B剩下的就有點模糊不清了，因為那時候老瓦薩拉克的靈魂便決定製造一個入口，開始召喚所有的鬼魂刺客。"] = "58af390eae1d4f73c7b54ed1448a76db",
            ["喔，對，沒錯。$B$B所以，我們就在這裡入侵黑石塔上層，對抗他們的主人和領導者；這是在達基薩斯之前。如果你問我，我是覺得不太明智，但是我們的領導者，安希恩·哈莫，你見過他，他總是喜歡挑戰。$B$B令人驚訝的是，一切都如計畫中進行的一樣，直到我們從魔法書上扳開瓦薩拉克僵硬的手指。這就是一切不幸的開始。$B$B我要繼續嗎？你看起來眼神很呆滯。"] = "c5bc7008b7dc8feccc3dc8a43b1ab1a8",
            ["我們之後解散了，就是這麼一回事。有太多的仇恨，我想……這已經累積好一陣子了。而有著護符的那個東西就是弄傷科多獸背部的爛東西。$B$B從此以後瓦薩拉克的奴僕們就開始將我們一個個剷除掉。大部分的護符碎片持有者都死了，他們的靈魂都被禁錮其中的瓦薩拉克靈魂給污染了。$B$B這就是為什麼我這麼高興你在這裡的原因，$N。有你的幫助我們就能重新組合護符並將它還給瓦薩拉克！"] = "69ab7dc25b9198ce90439c7c1d193e0e",
        },
        [16070] = {
            ["你好，$C。看來你最近在進行一項秘密的收集工作？你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段代碼。把代碼告訴我，我就會給你一份特殊的獎勵作為回報。"] = "c5afae87abc614718a9d01193dc59430",
        },
        [16076] = {
            ["你好，$C。看來你最近在進行一項秘密的收集工作？你還是老樣子，但是這是個繁忙的城市。$B$B如果你參加了那場會議，你就該得到一段代碼。把代碼告訴我，我就會給你一份特殊的獎勵作為回報。"] = "28755471b38e6eb285e0d80db6c9498a",
        },
        [16091] = {
            ["來自莊園拉文霍德，冒險者的祝福與問候。"] = "a71a88515d6fa1bcf5501c0265097b6d",
        },
        [16112] = {
            ["什麼是聖光兄弟會？嗯…我們都是銀色黎明的核心成員，不受道德、過失和無用的人類情感所控制。我們十字軍的世界沒有愚蠢及盲目的狂熱行為，我們領導有方。$B$B別讓血色指揮官用別的方法說服你。$B$B也別讓泰羅索斯知道我說過這樣的話…如果爆發爭執，我會讓他殘廢，到時場面可就難看了。"] = "087fc685b3d3b988443256863a127d39",
            ["在飽受爭議的死亡事件之後，國王與戰士為了向他們倒下的英雄表示敬意，紛紛都穿起類似的戰袍。而莫格萊尼的死對科爾蘇加德是偉大的勝利，最後殉難的結果要一直到戰爭結束才知分曉。$B$B一王倒下，他強必崛起…"] = "338d2b414e7e0fbcec01d970b4aa4241",
            ["第一套無畏護甲是專為血色十字軍莫格萊尼公爵訂做的。完成時，公爵覺得自己活生生像是從冥府來的惡魔。$B$B沒錯，這的確是個絕佳機會親見莫格萊尼精神飽滿的率領血色十字軍，齊聲吶喊、高舉揮舞著灰燼之劍，眼看另一端敵軍於燃火飛塵之中在他的雙腳下慌張撤離。"] = "d0454cc1a7f4f7f1c3d786915dd2f879",
            ["這是很嚴肅的問題？你真的不知道？$B$B如果你是懦弱型的深怕髒了手，你可以在燃燒平原與灼熱峽谷，找找生物身上的黑鐵碎片。$B$B如果你是嗜血如命的冒險型，你到黑石塔和黑石深淵的地下城，會發現有數以萬計的黑鐵碎片等著你。"] = "0b31ddefd183ea40f98d3eae3fd516ca",
        },
        [16113] = {
            ["信仰…有些人失去了，有些人卻找到了。它不會被破壞，也不是所謂的建立。$B$B還是你談的是信仰外衣？我們的神父和虔誠戰士，在對抗天譴軍團的戰爭時所穿的護甲。沒錯，大部分都不見了…被納克薩瑪斯惡魔偷走了。"] = "573851fae77cd06367281ad5d921bf9b",
            ["巫妖王想讓自己名揚四海。絕不能讓他得逞。"] = "2546edb7adcfdf6f1c9a8e4e04303b07",
        },
        [16114] = {
            ["銀色黎明也許是個無力的理想主義者，他們有妄想傾向的領導者知道自己有優勢。我是血色十字軍派來的密使，也就是外交大使，如果你將…能不能削弱科爾蘇加德的軍隊都還是個問號－統一或獨立－我們如果能攔截他們的話就是奇蹟發生了。$B$B至於我呢？我將死在戰場上…$B$B<馬翰聳肩。>"] = "7dde9ae82fc3dac0e978a835607357c8",
        },
        [16115] = {
            ["小心，$r。提到正義的評定功過，聖光兄弟會可不像我們的同黨一樣寬大。$B$B 那些災難與不幸會激怒柯菲斯。$B$B好，如果你現在沒有其他事了，不管是跟我還是其他兄弟會成員，請離開，我們還要開會。"] = "ab082a0dacce89f2423a85518fe46a16",
            ["救贖護甲由我們最忠誠的騎士穿著－與光明使者自己等同地位的護甲！$B$B上千人戰死在最後的戰役；從屍體身上扒下的外衣，然後帶進恐怖的納克薩瑪斯之塔。$B$B謠傳納克薩瑪斯之死亡騎士收買了救贖護甲，供他們自己使用。$B$B如此的悲劇..."] = "413977ef54e229a5943c4a37c970e4e7",
        },
        [16116] = {
            ["<安吉拉點頭。>$B$B他們死後，六人決定最好的應變措施，就是藉由堅固的魔法屏障來隔離法杖，並且任命守護者︰法杖的守護者…而我就是那位守護者。"] = "c713a20e41938c73763a6be364694b66",
            ["啊，好問題。$B$B如果你愛在大戶外獵戰的話，告訴你幾個有元素的地方：瘟疫之地、艾薩拉、燃燒平原、費伍德、希利蘇斯、冬泉谷，甚至戈洛環形山。$B$B又或者，假如你笑談悠遊於危險之中，我聽說厄運之槌那有很多變形元素在牆裡。你也可到黑石深淵裡，好好找找黑鐵矮人使用的元素。"] = "2ab19e8f4975368b71069106f4f9e703",
            ["在卡拉贊倒下後，肯瑞托派了一群法師到哨塔搜索，並扣壓所有進口的物品...就為了「研究」的目的。就是那時候才發現了寓言中的法杖，並將它帶回達拉然。"] = "6122d26d8170dc3ccd4b9e61fb944a4a",
            ["在達拉然的倒下之後，我也離開肯瑞托。我花了好幾年觀察阿泰絲，在肯瑞托之中只有一個目的，就是拿回某次突擊中被奪走的東西。雖然會追尋一生，但是我一定要找到法杖。那就是為什麼我參加銀色黎明，還有我現在為什麼在這裡的原因。"] = "e31f9aa725b12b20135051ca058312a9",
            ["失敗巨人的腐敗，毀滅者的墮落。終究這法杖還是由仇恨的種子所鍛造。也就是說，這當然是我來這裡的主因…"] = "28cf85bb2ada6ed1f79286dd08cc5e99",
            ["我橫跨世界追蹤了各式各樣的法杖碎片，還因此發現科爾蘇加德改良法杖的計畫。他目前收集一些法杖碎片，並且由他最信賴的中尉保管著。$B$B努力讓守衛者的大法杖遠離科爾蘇加德的控制，這重要性可是非比尋常。坦白說，除了史詩部分的大災難外，我不知道結果將如何。"] = "cbfe4959c0dccd84f4f0f7ec31d8ebe2",
            ["我跟科爾蘇加德一樣都曾經是肯瑞托的法師，我們也都在遍尋傳說中的守護者的大法杖，阿泰絲。我們的命運是如此糾纏著，$c。"] = "2e1a14887634a9235eb8a2b52a40e043",
            ["所跟隨的是一連串的悲劇，以致每位只要接觸阿泰絲的肯瑞托法師都會死亡。$B$B你看，這是有知覺的神器，是薩格拉斯賦予它的…"] = "260835e952147cbb7a876af4c9aa6cac",
            ["沒什麼好說的。達拉然幾乎全被阿克蒙德破壞，法杖遺失了，可能遭到故障防護裝置機所粉碎了。$B$B 有些人相信就是因為法杖，所以引起阿克蒙德的報復。"] = "24abd0790e880086be8e9845c402ee7c",
            ["聽說科爾蘇加德在尋找充滿傳奇的阿泰絲，偉大的守護者。$B$B對，麥迪文下的非常人物。"] = "971c7add47ebb151a9436fa9054b5e73",
            ["艾格文的後裔，他會成為提里斯法最後一位守護者…麥迪文。"] = "93c3d0734d2464cd5730f70b6d5bebdd",
            ["這是一個傳奇，這也是個我沒時間和意願重述的故事，只要知道麥迪文是最後一位守護者。阿泰絲大法杖是權力的核心，也是墮落的極點。"] = "8a3e84c175ab25c48b49ca17b0135721",
        },
        [16123] = {
            ["談談錯誤的投資！$B$B瓦薩拉克的黑暗魔法書在黑市賣了一筆好價錢。他對財產遭到偷竊反應如此激烈真是太可惜了。那個可惡的傢伙在死後幾個月還來向我們討回公道！"] = "7851f71608300be24d2a60246c177a38",
        },
        [16131] = {
            ["你是笨蛋嗎？遺失了你回程時那堆散亂路旁的骨骷顱生物？＜洛漢嘆氣。＞$B$B如果你是戶外型的人，你可在東、西瘟疫之地找到骨骷顱生物。相信我，你不能搞丟牠們－如果他們可以的話，他們一定不會放過你。倘若你是地下城冒險型，斯坦索姆和通靈學院正是尋找為骨頭碎片的地方。"] = "13a767725c325fa51d467e80639b5c7b",
            ["只准會員，臭小子！"] = "e9681ae779f33089e0a1a4491af83568",
            ["啊，如同頭銜寫著我是血色十字軍的刺客。我白天花在時間消滅首要目標，夜晚則在加基森迪斯可。跳舞才是我內心真實的呼喚。刺殺行動不過是糊口而已。"] = "512f340d076023b4c9448a6a0aa5f962",
            ["好問題，$r。我年輕時是個狂放不羈、對世事冷眼旁觀的人。那些日子，我就在暴風城理髮店裡表演四重唱，團名叫Four Dons。那是我學會製作骨鐮護甲的地方。"] = "c5eeeaf1edcbad1bef6a552484b6b991",
            ["我和下一個人一樣頭腦清醒，$g 老兄︰女士；。相信你將相信的，我現在確實可以鑄好護甲。如果你感興趣，或許我們能做一筆交易。越快擺脫暗殺工作越好。"] = "f58bd8742f434e11faf30ac0397cb63c",
            ["是的，骨鐮。你知道的，這是我們的男中音，名為胡力歐的頑固人，他找我一起開始整件計畫。在他穿越羅德隆的旅途中，胡力歐學會很多有趣的技能，其中一種技能能利用倒下的天譴軍團的骨頭，做成致命的皮甲－非常適合給刺客。"] = "d6ee820d31d12325db3bb0117d5ad5ed",
            ["頭銜是騙人的。你了解我後，你就知道我是個好人。"] = "7d3224526057b707f3979b7b1671e479",
        },
        [16132] = {
            ["他們都派了我的兄弟，洛克希，到這個集會。他連他的獵犬都顧不好了，更別說有資格代表血色十字軍。"] = "55bee4d94fe2ec071c1f49801c48e21a",
            ["在我的同業裡，常有人研究跟吹噓地穴惡魔獵殺敵人的超自然力量。至於我自己，則是在十字軍中為了驅趕天譴軍團殺了很多野獸。$B$B但是我痛恨的是地穴惡魔殘酷的天性，這是一定要欽佩的能力。它有一定的地位和作用，而且實行的非常好。"] = "1bb2d36c1471ccc6854f72988e3b2362",
            ["我發現地穴惡魔的甲殼有一種功用。我可以發明一種極輕巧又致命的護甲套裝，只要組合一些納克薩瑪斯裡被褻瀆的魔法護甲碎片。$B$B幫我把需要的物品帶來，我就會為你製作一套世界前所未有的護甲！"] = "c3277c86a4fa82a1bddd12127f42cee9",
            ["那些污穢的野獸充斥此地。$B$B如果你喜歡在戶外狩獵的話，你可以在病木林跟恐懼谷尋獲牠們大部分的蹤跡，也請特別留意惡蛛隧道。牠們也可能出沒在東瘟疫之地的天譴軍團紮營處。$B$B假如你熱衷於地下城副本，你在斯坦索姆會發現更多牠們的蹤影，另外，在通靈學院可以找到一些通靈魔。"] = "86a91c29a823bc19ba74c174cebf69ae",
        },
        [16133] = {
            ["你要什麼，鼠輩？知道為什麼大家都叫我施怒者？在我證明之前，你趕快給我滾。"] = "46c26045969305b4f1afa87dc761ac0c",
            ["我不會裝模作樣，蛆蟲。這種黑暗物品所支配的力量可以把我們兩個都摧毀。這就是為什麼價格如此高昂的原因。如果我就要死了，也會是個富翁。$B$B你死了我也不會對你吐一口豺狼人的口水，照我的話做就對了。把我要的東西帶來，我們就能雙方受惠 - 或者死；我已經解釋過了...."] = "c3138924933336621f5295591b7152ae",
            ["這就是權力，低能兒。＜麥特斯眼眸加深。＞$B$B這些傻瓜派了像你這樣的白痴到納克薩瑪斯，取回玷污的護甲以便淨化它，重組零件恢復昔日光采。$B$B＜麥特斯啐了一口。＞就是這種愚蠢至極的想法讓我反胃想吐。$B$B我也去尋找護甲，我要找玷汙以及被褻瀆最深的護甲。"] = "c943281a6d8472a873a6c97a00f1de85",
        },
        [16134] = {
            ["我一直在期…$B$B＜林布拉特咳嗽。＞$B$B不好意思，老毛病。我是陶土議會的林布拉特。"] = "2c121d996480b972ca128fe4dd17568b",
            ["我是年輕牛頭人，勉強算是正值青春期。不過，我知道那些為我們自由而英勇奮戰的人，都庇護在與我同名的外衣下。"] = "102e0b4ad57167106f63887340efcdd5",
            ["我的家族數百年都以粉碎大地為名。就像我父親和曾祖父繼承權利一樣，我也能創造一件以我為名的外衣。"] = "261c833a674804c528c3991040fe6265",
            ["牛頭人在最後一場戰爭勇猛奮戰。薩滿負責抵禦天譴軍團的入侵。大多數的士兵都戰死沙場。還有很多人則是被五馬分屍，在那受詛咒的城堡裡，他們殘斷的屍塊、肢體被拿來執行卑鄙的實驗。我對於他們的犧牲感到無比悲慟，卻也打從心裡對他們的英勇深感驕傲。"] = "65e7b100fb21e8d6d72f6a72a8e28b8f",
        },
        [16135] = {
            ["哈囉，$c。抱歉我在跟林布拉特談話。他深信這塊土地還沒復元。"] = "f7cb5d818b4259306750c7395a10a00f",
            ["如果你對外面世界的獵戰比較有興趣的話，那費伍德樹人與安戈洛鞭笞者就是你很好的樹葉資源。$B$B若你是位更熱愛挑戰的勇者，厄運之槌的東、西雙翼能補給你取之不盡、用之不竭的原始樹葉。"] = "ca612f9695245d53b26272938714b047",
            ["我不認為。林布拉特證明了分裂的土地一樣可以孕育新生命。現在我們必須找到再生和更重要的持續成長。$B$B我在這裡幫忙那些進入納克薩瑪斯的冒險者。"] = "2c8bea531a145f78fd5e857b6b8fabd4",
            ["我們因為不同原因被吸引到此，$c。$B$B <瑞恩微笑。>我在這裡遇到這枚陶土議會的林布拉特。他說了些關於淨化土地的有趣言論。"] = "32fb9a5f34cae334b11ddc1ef3aaafda",
            ["我是個有名望的工匠，$c。只要有適當材料，我能鑄造著名的夢行者護甲。德魯伊－甚至某些薩滿－由於它的魔法特性而深受吸引。你有興趣嗎？"] = "182a2f807168b02644f4daff8caa6b4b",
        },
        [16212] = {
            ["我沒那時間跟你玩猜謎遊戲，$r。講正事，然後消失在我眼前吧，還有我也不想嗅到你的氣味，所以麻煩你徹徹底底的消失。"] = "b5c51729cbfc4944277ef2a9a1158a7e",
        },
        [16226] = {
            ["別怕劍，一點點地啃。這是要給你的羊肉。"] = "aa468b41ee1967bb79c4f9ff0c0d575f",
        },
        [16227] = {
            ["你想要飛往什麼地方？"] = "8d5a94fecd48af8f93d9d75d365ea743",
        },
        [16230] = {
            ["這名祭司處於深沉的昏睡狀態..."] = "73f0462573697c404b28308bec6f882a",
        },
        [16254] = {
            ["＜大元帥錢柏咆哮。＞$B$B所以，你是迪笛兒底下負責整套補給的廢渣？其他人呢？我知道這裡一定還有很多人吧。像你這樣的鼠輩大部分都一起遊盪無所事事。$B$B呸！快給我那要命的文件，我趕緊簽完。"] = "51a682137b7a6db94a26971a20130651",
        },
        [16256] = {
            ["不，我沒有。但其他人都想談戀愛。你應該跟我買些愛之硬幣，噴些古龍水或香水，發給大家！"] = "54899ff43d9fa3680bd5231fd54eae44",
            ["位於丹莫洛的科技奇跡城市諾姆瑞根世代以來都是地精的主城。最近，一群邪惡的變異食鄂怪侵入了包括地精主城在內的多處丹莫洛地區。為了做出殊死一搏來幹掉入侵的食齶怪，大工匠梅卡托克命令打開城市中的緊急輻射水箱。地精在等待那些食齶怪死亡或者逃跑的同時也在尋找躲避輻射的方法。不幸的是，雖然食齶怪在經過輻射之後感染了毒性——但是它們的攻擊沒有停止，也沒有絲毫的減弱。那些沒有被輻射殺死的注入被迫逃離，他們在附近的矮人城市鐵爐堡找到了安身之處。大工匠梅卡托克組建了一個智囊團來商議重新奪回他們摯愛的城市的計畫。"] = "6cc5772934f51d4bcf44e66f9cb19266",
            ["位於梣谷左拉姆海岸的黑暗深淵曾經是為供奉夜精靈月神艾露尼爾建造的。然而，在大爆炸中，神廟受到極大的衝擊然後沉入了海中。它一直保持著原樣——直到，其蘊含的古老的力量吸引來了納迦和薩特。傳說，古代怪獸阿庫麥爾就居住在神廟遺跡中。作為古代之神最喜歡的寵物之一，阿庫麥爾就一直生活在這個地區進行捕食。在阿庫麥爾的吸引下，一群被稱作幕光之錘的教徒也聚集在這裡從事邪惡的勾當。"] = "639f5e4137099522e1302487ff27f679",
            ["你有興趣探索這些地下城中的一個嗎？"] = "9211a5a83384bc6bf667f9e87661f2b5",
            ["剃刀沼澤位於貧瘠之地最南端的大路西邊。"] = "4855c8dab63ff7e92429d6df87b7b3cd",
            ["剃刀高地位於貧瘠之地最南端的大路東邊。"] = "ae45cd449d9b601c1faa2ad7d470e04a",
            ["剃刀高地和剃刀沼澤一樣由巨大的藤蔓組成，剃刀高地是野豬人的傳統都城。在那錯綜複雜的荊棘迷宮中居住著大群忠誠的野豬人軍隊以及他們的高階牧師——亡首部族。然而最近，一股陰影力量籠罩了這個原始的洞穴。天譴軍團的人在巫妖寒冰之王亞門納爾的帶領下控制了野豬部族並將荊棘迷宮變成了亡靈力量的堡壘。現在野豬人正奮力戰鬥來重新奪回他們的城市，並阻止亞門納爾繼續控制貧瘠之地。"] = "ae6bac71d95fa9cc576583cb12b00b0a",
            ["厄運之槌位於菲拉斯的中部。"] = "863a0466292f35423e25fb6b1e18e872",
            ["哀嚎洞穴的入口位於貧瘠之地十字路口西南邊甜水綠洲。"] = "58d9f5adb0c15d9e359abb8b40a54a91",
            ["在一千年之前，強大的古拉巴什王國被一次大型內部戰爭所毀滅。一部份被稱為阿塔萊的食人妖牧師試圖將古代血神哈卡靈魂掠奪者帶回這個世界。雖然這些牧師被擊敗並最終被流放，這個偉大的王國變得四分五裂。流放的牧師逃到了北面的悲傷沼澤。他們為哈卡建立了一座偉大的神廟——在那裡他們期望能夠把哈卡重新帶回世間。偉大的守護神龍伊瑟拉瞭解了阿塔萊的計畫並將神廟摧毀沉入沼澤之中。在今天，神廟沉沒的遺跡被綠龍所守衛並阻止任何人進入或者出去。"] = "7dc247370c0f46388922e4ad2824f973",
            ["在一萬年前的古代戰爭中，萬能的半神阿迦瑪甘和燃燒軍團進行了激戰。雖然這頭巨大的豬在戰鬥中倒下了，但是他的努力最終拯救了艾澤拉斯大陸免遭塗炭。雖然已經過去了很久，但是在它血液流淌的地方巨大的荊棘藤蔓生長出來。那些被認為是半神後代的野豬人佔領了這些地區並將其奉為聖地。這些荊棘地的中心被稱為剃刀嶺。而巨大的剃刀沼澤則被一個老醜婆卡爾加·刺肋所佔據。在她的統治下，信奉薩滿教的野豬人和別的部族以及部落為敵。有些人甚至猜測卡爾加還在和天譴軍團的有來往——她想要聯合天譴軍團來達到一些不可告人的險惡目的。"] = "13d77ffe00e095b4ad42eef5a8aaebfb",
            ["在第三次大戰中，奇靈托的法師和天譴軍團進行了殊死的戰鬥。當達拉然的法師最終在戰鬥中戰死之後，他們的意志轉移到了復甦的天譴軍團身上，然後重生了。由於對於緩慢的進展感到失望（並且對他的手下的建議不予理會）大法師阿魯高選擇召喚異次沅空間的生物來壯大達拉然日漸消失的力量。阿魯高的召喚將貪婪的狼人帶到了艾澤拉斯大陸。這些狂暴的狼型生物不僅屠殺了天譴軍團的人，而且迅速將目標轉向那些法師。那些狼人開始圍攻席瓦萊恩男爵的城堡。這座位於焚木村的城堡不久之後變成了黑暗勢力的聚集地並從此荒廢。因為對於自己罪過的愧疚，阿魯高將那些狼人當作自己的孩子並隱居在「影牙城堡」中。"] = "b69ededa6dbdfe26a15fda5121e90a20",
            ["埃德薩拉斯古城是在一萬二千年前由當時的一批夜精靈法師秘密地建造的，它被用於保護艾莎拉皇后最寶貴的奧法秘密。雖然受到了世界大震動的影響，這座偉大的城市基本屹立在那裡，現在其被稱為厄運之槌。這座遺跡城市分為三個部分，分別被不同的生物所佔據——包括幽靈般的高等精靈，邪惡的薩特和魯莽的巨魔。"] = "97a393e1ef12dc1fe4a4b55e63c2c620",
            ["奧達曼位於荒蕪之地最北端。"] = "4324821d63a3f73937dd5abffe6fdf7f",
            ["奧達曼是古代泰坦創世之時所留下的深埋於地下的城市。矮人探險隊最近發覺到了這塊被遺忘的城市，將泰坦一款失敗的創造物：食齶怪喚醒了。傳說泰坦是從石頭中創造了食齶怪。當執行證明這次試驗很失敗的時候，泰坦把食齶怪鎖了起來並進行了第二次的嘗試——最終創造了矮人這個種族。矮人創造的秘密被記錄在精密的白金圓盤中——那是位於古代城市最底部的大型泰坦遺跡。"] = "a25c5d7842af31618a063b3d3ce15fed",
            ["如果你噴點古龍水或香水，你就會發現某個人正含情脈脈的示意。他們專收愛之硬幣……然後再回送你禮物。$B$B請記住：給別人硬幣時，你也要聞起來香香的才行！男人喜歡香水的味道，而女人則偏愛古龍水的香味。"] = "8e4dcb74091e2e615d506f3ec7d147ca",
            ["影牙城堡位於南部銀松森林，就在焚木村的北面。"] = "17d13be0366794572061fb3fbb409ee6",
            ["怒焰裂谷位於奧格瑪中心的暗影裂口。"] = "b960d46bc6e1afd8a8048e75631efeb5",
            ["怒焰裂谷是由許多火山洞穴所組成的，它位於部落的新都城奧格瑪中。最近，有傳言說一群忠於陰影教會的教徒佔據了那個地方。這群被稱為火刃得教徒威脅了杜洛塔的安寧。許多人相信獸人酋長索爾已經意識到了火刃的存在，他並不想著急於摧毀他們，因為索爾希望這個教會能夠將他帶往陰影教會。"] = "4a0636d96305a16097c01ed6971f7971",
            ["愛之硬幣就是愛的小訊息，你可以給熱情的城鄉人們。他們會回送你象徵愛意的禮物。$B$B或者說，有人愛慕或崇拜你，他們也會給你友誼之禮。"] = "cd40129110d4c4917a537fef57180329",
            ["斯坦索姆位於東部瘟疫之地瘟疫林的北部。"] = "d9516bdeb534c80940a3be1f4600bf04",
            ["斯坦索姆曾經是羅德隆北部一顆璀璨的明珠，但是就是在這座城市阿薩斯王子背叛了他的導師烏瑟，並屠殺了數百個被認為感染了可怕瘟疫的臣民。阿薩斯不久之後就向巫妖王臣服。這個破碎的城市也被巫妖科爾蘇拉德領導的天譴軍團所佔據。而一直由大十字軍戰士達索漢領導的血色十字軍分遣隊也佔據了這個城市的一部分。這兩方力量在城市中進行著激烈的戰鬥。"] = "4bcf2a35fd98e48b3cd346ec97dccde8",
            ["日光暴曬下的這座城市是沙怒食人妖的家園，他們一向以來都以其無情和黑暗魔法而聞名。食人妖傳說中有一把強大的名叫鞭笞者蘇薩斯的武器能夠讓最弱小的人可以擊敗最強大的敵人。很久以前，這把武器被分成了兩半。然而，有傳言說這兩半可以在祖爾法拉克任何地方找到。"] = "0f7f53045dc845e1ab759203cc598d30",
            ["暴風城監獄位於暴風城靠近法師區附近。"] = "8b063ee787233090be02c8d7fc8e58a7",
            ["最近一個名叫納拉雷克斯的夜精靈德魯伊在貧瘠之地中的地下發現了一個錯綜複雜的洞穴網。這個被稱作「哀嚎洞穴」的地方有很多的蒸汽縫隙，所以當蒸氣噴射的時候發出的聲音就猶如哀嚎一般，其因此而得名。納拉雷克斯可以利用洞穴中的溫泉來恢復貧瘠之地的生態，讓這裡重新獲得生機——但是這樣做需要吸收傳說中的翡翠夢境的能量。一旦和翡翠夢境相連接，德魯伊的視線中就變成了一場噩夢。不久之後，哀嚎洞穴開始變化——洞中的水開始腐化——曾經溫順的生物開始變成狂暴，致命的捕食者。據說納拉雷克斯自己還居住在這個迷宮的最深處，他被翡翠夢境的邊緣所困擾著。即使他以前的隨從也被他們的主人所經歷的噩夢所腐化——他們都變成了邪惡的尖牙德魯伊。"] = "4d1835c423b0ee4a6773a1481ea2d03e",
            ["歡迎光臨聖光之願禮拜堂，陌生人。"] = "62d77d311ff95b739586b58c132d853b",
            ["死亡礦坑位於西部荒野月溪鎮的地下。"] = "cce75935af7718f82fcb4c3d13f23020",
            ["沉沒的神廟位於悲傷沼澤東部的一個大湖的中心。"] = "75ed2903e0af8abe0c91025f4d1a631e",
            ["瑪拉頓位於淒涼之地西部中間的長矛谷中。"] = "b32b2b77a0839ff8c1415be4d2623dd9",
            ["瑪拉頓被狂暴的瑪拉頓半人馬所保護，那是淒涼之地最神聖的地方。瑪拉頓是札爾塔的偉大神廟，札爾塔使半神塞納留斯不朽的兒子之一。傳說札爾塔和瑟萊德絲大地元素公主的私生子成為了半人馬種族。據說半人馬這個野蠻的種族在其出生了之後就開始轉向他們的父親並將其殺死。有些人則相信瑟萊德絲在悲傷中將札爾塔的靈魂困了起來，並將其藏在洞中——利用它的能量來達到一些不可告人的目的。"] = "44f65d16974643e3b29f727a67787ad0",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B丘比特就在伯瓦爾，麥格尼和泰蘭妲附近。"] = "0838f3fe0e3c17a16a7ff7d504eec929",
            ["當你將愛之硬幣給人民，你將收到他們不同的禮物作為回禮。有些禮物你會想留著自己用，但其他的就可以收集在一起送給你最喜歡的英雄！拜訪丘比特·傳播者把禮物交給他。$B$B傳播者就在凱恩，希瓦娜斯和索爾附近。"] = "9f470e7a9c62fa04faeb58fd3b1d6de9",
            ["監獄是位於暴風城運河區戒備森原的牢房。那裡由典獄官塞爾沃特看守著，監獄是那些小偷，政治犯，謀殺者和許多最危險的罪犯的家園。最近，異常暴動導致了監獄的混亂——所有的守衛都被趕了出來，裡面的罪犯可以自由的活動。"] = "9f8d7c84b3cbfc322f53a0a242de804e",
            ["祖爾法拉克遺跡位於塔納利斯沙漠最西北角。"] = "5521f2e5d2e37d7012ea87b75badcb01",
            ["血色修道院位於提里斯法林地東北部的山坡上。"] = "fe604977d24d31743e5481d5dcda2e88",
            ["血色修道院曾經是羅德隆王國牧師的榮耀之地——那裡是學習聖光知識和膜拜的中心。隨著在第三次大戰中天譴軍團的崛起，寧靜的修道院成為了瘋狂的血色十字軍的要塞。十字軍對於所有非人類都有著偏激的態度，無論他們是自己的盟友還是對手。他們相信所有任何外來者都帶著亡靈的瘟疫——他們必須被摧毀。"] = "2da51ca0be53ce695776bbe3e3eea8c7",
            ["諾姆瑞根在丹莫洛的西邊。"] = "1e16c8ae0545b101ebc5ad4d9c69c248",
            ["這裡曾經是人類最主要的產金地，希望礦坑在部落第一次大戰期間席捲暴風城的時候被廢棄。現在迪菲亞兄弟會的人佔據了那裡並將這個黑暗的通道轉變成他們的避難所。據說那些盜賊已經勸說了聰明的哥布林幫助他們在礦坑的深處建造一些可怕的東西——但是沒有人知道這是真的還是假的。有傳言說，死亡礦坑的入口在安寧的月溪鎮中。"] = "e118425d7cca455fae7064446900535b",
            ["通靈學院位於凱爾達隆廢棄的城堡中的地下室中。那裡曾經是高貴的巴羅夫家族的，但是在第二次大戰中凱爾達隆變成了一塊廢墟。法師科爾蘇加德經常向他的詛咒神教信徒承諾可以用對於巫妖王的效忠來換取永恆的生命。巴羅克家族受到科爾蘇加德的魅惑而將城堡和其地下室獻給了天譴軍團。那些信徒然後將巴羅夫家族的人殺死並把地下室變成了通靈學院。雖然科爾蘇加德不再住在這個地下室中，但是狂熱的信徒和講師都還留在那裡。"] = "44fdd52098e4ecaeddc946e101d7c60f",
            ["通靈學院這個學習亡靈術的學校位於西瘟疫之地的凱爾達隆那個廢棄的小島上。"] = "4414ebedf67147d4801e58071b11c237",
            ["黑暗深淵位於梣谷海岸左拉姆海岸的最北部。"] = "2d41c6e84da0f60aa520a4acc8919f87",
            ["黑石山脈位於灼熱峽谷和燃燒平原的中間。"] = "7beb3ee244d9c85c277537d4ba4a2fe1",
            ["黑石深淵曾經是黑鐵矮人的偉大都城，這個火山中的迷宮現在成為拉格納羅斯火焰領主的王座所在地。拉格納羅斯找到了使用石頭和設計圖來創造一支無敵石頭人均對來幫助它征服黑石深淵。即使是需要打敗奈法利安和他的龍子龍孫，拉格納羅斯會不惜一切代價來達到最後的勝利。"] = "e4835262a6e71a36692d90aedbb66c42",
            ["黑石深淵深處的巨大堡壘是由矮人建築大師弗蘭克羅恩·鑄鐵所設計的。這個堡壘是矮人力量的象徵並被邪惡的黑鐵矮人佔據了數個世紀。然而，奈法利安——死亡之翼狡猾的兒子——對這個巨大的堡壘別有意圖。他和他的黑龍軍團佔據了上層黑石塔並向佔據著黑石深淵的黑鐵矮人宣戰。奈法利安知道矮人是由強大的火元素拉格納羅斯所領導的，所以他立志要摧毀他的敵人並將黑石深淵全被占為己有。"] = "3644fa36f35ecdc5947046c71b54837a",
        },
        [16283] = {
            ["我們的商隊大約一天出隊2次，萬一天譴軍團又去阻止迪笛兒，還有要送往前線的那些騾，那到時我就會被指責。這還是我前所未見最瘋狂的事情。但願我們有英勇的冒險精神能保護這運送過程…"] = "b4e6217834a34f95034b22e071d3a451",
        },
        [16284] = {
            ["我事情太多，時間根本不夠用，$r！拜託，別擋我路。"] = "f21ac82310364bee548aaa65db9ae740",
            ["我事情太多，時間根本不夠用，$r！拜託，別擋我路。$B$B萬一你被巨蛆跟腐爛食屍鬼感染的話，我有能力治療各種疾病。"] = "69087ca98832c4d531ebd24380d184e3",
        },
        [16376] = {
            ["在某個夜裡工匠大師歐瑪利安突然消失了。就像風中的號角聲...咻！消失了！呸，現在只剩下我一個人幫前線的戰士們鑄造東西了。"] = "9cb182e6099250bd1e21445a5a8a786a",
        },
        [16381] = {
            ["<塔希斯傷的很重。>"] = "f9da3b9d9bfb527b32aa364ef806b9b5",
        },
        [16384] = {
            ["我們對抗天譴軍團的第一步進行的很好。我們有了一些成就，希望我們的協助能幫你們獲得未來的勝利。"] = "0973188afdf5745ee7a53c42da926c63",
            ["我們贏得了戰役。就目前看來，天譴軍團的威脅已被擊退。我們的資源可以引導來協助你們，作為感謝並為將來做準備。"] = "ebde1b78097e360ae80271b45ac8ec9b",
            ["戰役進行的很順利。天譴軍團的軍隊看來比較衰弱了。我相信把他們趕出我們的海岸只是早晚的事了。我會提供我的魔法幫助你們打贏這場仗。"] = "4d4e9052d3c36392e6211cb442ea3b1e",
        },
        [16395] = {
