        [169294] = {
            ["燃燒平原 - 七賢石板"] = "d53d78383a00e34fee253b35f4822f53",
            ["石板上的符號被小心翼翼地拓了下來……"] = "1441f593f536c438e86c832a3994399f",
        },
        [173265] = {
            ["啊，沒問題，$N！對不起……我還以為你已經搞定了。"] = "927e8ff519d8ba1f7268782502991891",
            ["有人嗎？"] = "f1066af8c8e6467a6ae99ec3559a06c9",
        },
        [174848] = {
            ["當你靠近時，那些液體和混合物劇烈地翻騰起來。設備旁邊是一把巨大的鉗子，似乎很適合用來夾起淤泥樣本。$B$B還有安全齒輪裝備，但是上面佈滿灰塵，似乎很久沒有使用過了。$B$B你覺得什麼東西都碰為好。"] = "4443edbe9f8e5b3bb25037cef6a76549",
        },
        [175265] = {
            ["當你靠近時，那些液體和混合物劇烈地翻騰起來。設備旁邊是一把巨大的鉗子，似乎很適合用來夾起淤泥樣本。$B$B還有安全齒輪裝備，但是上面佈滿灰塵，似乎很久沒有使用過了。$B$B你覺得什麼東西都碰為好。"] = "4443edbe9f8e5b3bb25037cef6a76549",
        },
        [175926] = {
            ["一本打開的日記放在你的面前，發黃的書頁上寫著如下的文字：$B$B「哈洛德變成了這個樣子，我不知道接下來會發生什麼事。把他拖進我能找到的唯一可以關住他的地方之後，我已經心力憔悴了。我把鑰匙藏在身上，祈禱能渡過這個難關……$B$B我希望能離開這裡，但我需要錢。我想我們的東西都在那個櫃櫥裡……現在我想起來了，哈樂德是不是把櫃櫥的鑰匙藏在自己身上了？$B$B我要先休息一下，現在我實在是太疲倦了。」"] = "717e4452946d86f15f58fb9bae10c1b8",
            ["這本書的標題是手寫體：莫琳·達爾松的日記。"] = "7ee3700cb7019901b220464a5ab94655",
        },
        [175927] = {
            ["人類和天譴軍團所知的最好的肉類防腐劑——萊斯·霜語的防腐液。這種防腐劑只能在一個地方找到，人們認為這東西得名於巫妖，要去那種地方一定不是件容易的事兒。$B$B但是……如果這正是你想要的東西，就去通靈學院吧……"] = "bc097c6ccf37ea8c37e08bf804253ff4",
            ["巴羅夫家族將通靈學院所在的土地給了科爾蘇加德。作為交換這塊詛咒神教可以研究天譴軍團墮落法術的地方，科爾蘇加德讓巴羅夫家族以亡靈的形式獲得永生。$B$B在陰影拱頂房間中，你能找到暗影之皮及其擁有者伊露希亞·巴羅夫。$B$B你無法找到比暗影之皮更好反射虛無和死亡的鏡子了。"] = "33f4d18ce0ab409c37b0395f421b1056",
            ["瑟銀兄弟會。$B$B祕法水晶是從富瑟銀礦脈中採集的。通過強大的煉金師的威力，奧金誕生了。$B$B找出一個礦工，如果你不是的話……還有找到一個出色的煉金術士！你兩樣都會需要的。"] = "d46d54093f1260912aed6c305f8d3ca6",
            ["瑟銀兄弟會的目錄：$B$B你可以從中找到所有你冒險必需的最強裝備！我們還將告訴你到哪兒去收集這些材料。"] = "76853600f17808d27848257e7a687168",
            ["要是你想要磨損的憎惡縫合線，你就得長途跋涉去斯坦索姆。$B$B以前那兒是光明使者的家園，現在被科爾蘇加德的僕從們侵佔了。$B$B解除這燃燒的城市的危機，擊敗那些強大的憎惡吧！從他們那兒奪取磨損的憎惡縫合線！"] = "3f424f4d79a0f2e7f08530b667b2e442",
            ["那些瘋狂的信徒的最後一處聖地。他們在那製作紅色制服，使用的就是魔化紅線！$B$B冒險家們，向斯坦索姆城前進！"] = "a1ab5bb20b1a4b85596ee4b43ec71cb8",
        },
        [176192] = {
            ["書中說很多條龍聯合起來對付一條極其強大的、名為死亡之翼的龍。按照我們掌握的資訊，多彩龍人差不多全部釋放。守護者已經準備就緒。"] = "a39f45feb88e61fcb589760afd9818ef",
        },
        [177226] = {
            ["這本秘典的內容就像潮水不斷流出。你覺得好像你腦中的思緒被榨乾並被這本書消化掉。"] = "91179f4a7cd672e7c6902020e8567c29",
        },
        [177490] = {
            ["那個堅固的箱子在木材廠中間，周圍推滿了殘骸和血色十字軍的狂熱信徒。"] = "c6e0746701f75c4143389544cdc0709b",
        },
        [177787] = {
            ["在龍蝦人的進攻後，我們知道下一次豪俠是無法倖免於難的。於是我和幾個倖存的水手棄船逃生。$B$B我們現在上岸了並很快就會向尼耶爾前哨站遊去，但是在到達避難所之前我們還有很多危險，而且我害怕淒涼之地會吞噬我們。$B$B我現在寫下這些是希望有人能知道我們的困境，有一天能把那些帶給我們滅頂之災的水中魔鬼殺死為我們報仇。"] = "b7584554dd225ef7e529ef1bd508f29b",
            ["我是奧塞斯·拉克摩爾，豪俠輪船的船長。這是最近幾天輪船的航行日誌。$B$B我們的船隻滿載貨物駛向羽月要塞，納迦襲擊了船隻一側。我們趕走了他們，但是我們知道他們會回來的。我擔心納迦會毀掉我最寶貴的財物，因此我將豪俠駛向遠離淒涼之地的一座小島，島上全是古老的夜精靈建築廢墟。我將自己的寶箱放在了島上。"] = "c59de48f730da3b5d7c895e1e6639450",
            ["我的箱子設計獨特，需要兩把鑰匙來開鎖，一把金鑰匙和一把銀鑰匙。我將銀鑰匙給了我的大副，自己保留了金鑰匙。$B$B但是我們註定會失去它們。在一次納迦發動的襲擊中，我丟了鑰匙；而後，龍蝦人攻擊了我們，將大副推入了深淵。$B$B我想鑰匙一定在納迦和龍蝦人那兒。還好這兩方是敵人，不會共用鑰匙的。"] = "4737220be29ed0b0905a27df23942c8f",
        },
        [178526] = {
            ["日誌中似乎記載了關於貿易、買主和其他商業事件的資訊。"] = "b452639355066c08bc2c04d51231d65d",
        },
        [179544] = {
