        },
        [180461] = {
            ["你這渺小的蟲子，你竟敢跟議會公爵交談！"] = "d39f90b279f06892c664f53d9d8191a0",
            ["從石頭中傳來清晰的聲音……$B$B你帶著你的頭銜來找我們，我們將會聆聽，但是不要試圖考驗我們的耐心，$c。議會沒有時間來和你這樣的凡人閒聊。"] = "37d313298adafe97bca139d3d41d6c87",
