        },
        [180466] = {
            ["從石頭中傳來雷霆般的聲音……$B$B我感覺到你攜帶著身份勳章，教徒，但是你沒有貴族之戒？你是不是真的是暮光之錘的指揮官，或者你只是一個跑腿的？"] = "e9af3f58bfcd009f6ff72f930ea3882f",
            ["從石頭中傳來雷霆般的聲音……$B$B這是什麼？我感覺到一個小小的信徒在竄來竄去！快點走開，苦力，否則你將面對議會領主的憤怒！"] = "5fb610919b3f9ee9e77b9a37bbabaaea",
            ["從石頭中傳來雷鳴般的聲音……$B$B你好，指揮官。你從希利蘇斯給議會領主帶來了什麼消息？"] = "9e096eb8c378bcc66b01591b1b44e830",
