            ["從石頭中傳來雷鳴般的聲音……$B$B你好，指揮官。你從希利蘇斯給議會領主帶來了什麼消息？"] = "9e096eb8c378bcc66b01591b1b44e830",
            ["議會領主面前出現了一隻蟲子？沒錯，無疑是一隻想要被碾碎的蟲子！"] = "9f2e8057a4162af2cc00fd83ab0ece74",
        },
        [180564] = {
            ["受死吧，異教徒！願深淵的力量毀滅你！"] = "01594454427de3b4452e20be980b7818",
            ["從石頭中傳來很輕的聲音……$B$B你好，渺小的凡人。你為聖殿騎士帶來了什麼消息？"] = "66471c117f9a9c8fb2c8bcbff27683fb",
        },
        [180574] = {
            ["燃燒稻草人產生的灰燼散發出了魔法的力量。"] = "28dd5a31538999b63e73fb2d316c92e0",
            ["燃燒稻草人產生的灰燼散發出了魔法的力量。你把這些灰燼抹在了臉上。"] = "9fde842505ae51e2e9603bb246e83c36",
        },
