        [180794] = {
            ["詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個某種製作背包的裁縫術語。以你對裁縫的了解還無法讓你破解這術語。"] = "ac3bf49b09e574e839ef683378f6e79d",
            ["詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個製作惡魔布包的裁縫術語。這背包是給術士裝靈魂碎片用的，你能複製這術語記在你的日記本裡嗎？"] = "2e4d9884e93c29c98746aa5d29d39c35",
            ["詹迪斯·巴羅夫的日記寫滿了不死族誇大的豪言壯語。翻到書的最後一頁，似乎出現一個製作惡魔布包的裁縫術語。這背包是給術士裝靈魂碎片的用，你已經知道要如何做出這種袋子。"] = "36abb8fc0a6fcba22ad534dedab0826c",
        },
